R2_FC8 = _env("R2_FC8", False, bool)
RECORD_FC8 = "R2_FC8" in os.environ
if R2_FC8 and not (R2_MLP == "fused8" and R2_MLP_FP8 == "both" and R2_MLP_PRECAST and R2_DW8 and not DW8_MLP):
    raise ValueError("R2_FC8 (switch 67) puts the dense MLPs' c_fc weight gradient on switch 9k's kernel under switch "
                     "9f's pre-cast: it needs R2_MLP=fused8, R2_MLP_FP8=both, R2_MLP_PRECAST=1 and R2_DW8=1 without "
                     "mlp or mlpfc in R2_DW8_SET")
