# -----------------------------------------------------------------------------
# Device / distributed setup

def neuron_available() -> bool:
    try:
        torch.device("neuron")
        return True
    except Exception:
        return False


def detect_device_type(requested: str = "") -> str:
    if requested:
        return requested
    if torch.cuda.is_available():
        return "cuda"
    if neuron_available():
        return "neuron"
    return "cpu"


def init_runtime(device_type: str):
    assert device_type in {"cpu", "cuda", "neuron"}
    torch.manual_seed(R2_SEED)
    ddp, rank, local_rank, world_size = get_dist_info()
    if ddp and device_type == "cuda":
        device = torch.device("cuda", local_rank)
        torch.cuda.set_device(device)
        dist.init_process_group("nccl", device_id=device)
    elif ddp and device_type == "neuron":
        dist.init_process_group("neuron")
        device = torch.device("neuron")
    elif ddp:
        dist.init_process_group("gloo")
        device = torch.device("cpu")
    else:
        device = torch.device(device_type)
    if dist.is_available() and dist.is_initialized():
        dist.barrier()
    return ddp, rank, local_rank, world_size, device


def cleanup_runtime() -> None:
    if dist.is_available() and dist.is_initialized():
        dist.destroy_process_group()


def synchronize(device: torch.device) -> None:
    if device.type == "cuda":
        torch.cuda.synchronize()
    elif device.type == "neuron" and hasattr(torch, "neuron"):
        torch.neuron.synchronize()


def compute_dtype_for(device: torch.device) -> torch.dtype:
    if device.type == "cuda" and torch.cuda.is_bf16_supported():
        return torch.bfloat16
    if device.type == "neuron":
        return torch.bfloat16
    return torch.float32


# -----------------------------------------------------------------------------
# Model

@dataclass
class GPTConfig:
    sequence_len: int
    vocab_size: int
    n_layer: int
    n_head: int
    n_embd: int
    # Recipe switches that change the forward (switches 12, 13 and the bundle's
    # attention scale, 14). Each default is the kit's model; model_config_dict()
    # leaves a field out of the checkpoint while it holds its default.
    unet: bool = False
    value_embeds: int = 0
    qk_scale: float = 0.0
    # Switch 17: the n-gram orders (empty: off), each table's rows and width, the
    # projection form and the hash tables' seed.
    ngram_orders: tuple = ()
    ngram_rows: int = 0
    ngram_dim: int = 0
    ngram_proj: str = ""
    ngram_seed: int = 0
    # Lane TABLE2: 1 or 4 when the saved table is switch 17's packed view at that many bits (ngram_table uint8
    # [rows, ngram_dim x bits / 8], ngram_scale its bf16 row scales); 0 (the default, left out of model_config) the
    # bf16 or int8 rows.
    ngram_bits: int = 0
    # Switch 18: a head-wise sigmoid gate on every layer's attention output.
    head_gate: bool = False
    # Switch 48: the layers whose MLP hidden activation is gated by a token-indexed table (empty: off).
    stem_layers: tuple = ()
    # Switch 47 (lane WIN; lane BAND's port): the short layers' window in tokens (0: every layer causal) and the long
    # layers (sorted); model_config_dict leaves both out while they hold their defaults.
    attn_window: int = 0
    attn_long: tuple = ()
    # Switch 59: the output-site one-shot table (0 rows: off): its rows and width, the key's length, the hash and
    # codebook seeds, the BOS id a key stops at, the readout (a0 in the table's units, the threshold, beta, the linear
    # gain) and the gate (its window, h0 and slope). Every value is hand-set; none is learned.
    os1_rows: int = 0
    os1_dim: int = 0
    os1_order: int = 0
    os1_seed: int = 0
    os1_code_seed: int = 0
    os1_bos: int = -1
    os1_a0: float = 0.0
    os1_thr: float = 0.0
    os1_beta: float = 0.0
    os1_glin: float = 0.0
    os1_gate_w: int = 0
    os1_gate_h0: float = 0.0
    os1_gate_slope: float = 0.0
    # Lane TABXB: 1 when the saved table is the packed 1-bit view (os1_table uint8 [rows, os1_dim / 8], os1_scale the
    # view's bf16 row scales); 0 (the default, left out of model_config) the int8 rows and their scales.
    os1_bits: int = 0
    # Switch 55: the mixture-of-experts layout (no blocks: off): the MoE blocks, the experts, the top-k, the
    # capacity a sequence, the experts' and the shared half's widths, the dispatch form, the shared half's route.
    moe_layers: tuple = ()
    moe_experts: int = 0
    moe_topk: int = 0
    moe_capacity: int = 0
    moe_hidden: int = 0
    moe_shared: int = 0
    moe_dispatch: str = ""
    moe_shared_mlp: str = ""
    # Switch 66 (lane THR13): 1 when the routed experts trained on switch 9f's fp8 route, so scoring runs them on
    # switch 9c's op pair (the same outputs); 0 (the default, left out of model_config) switch 55's bf16 experts.
    moe_expert8: int = 0
    # Lane EMA31 (R2_EMA): a saved average of the masters: the schedule fraction its samples start at and their period;
    # 0 and 0 (the defaults, left out of model_config) the last iterate. The forward does not read them.
    ema_from: float = 0.0
    ema_every: int = 0


def model_config_dict(config: GPTConfig) -> dict:
    """asdict(config) without the recipe fields that hold their defaults: the
    kit's keys for the kit's model, and every field load_for_eval needs."""
    out = asdict(config)
    for f in fields(GPTConfig):
        if f.default is not MISSING and out[f.name] == f.default:
            del out[f.name]
    return out


def value_embed_layers(n_layer: int, n_tables: int) -> list[int]:
    """The n alternating layers that end at the last layer (switch 13)."""
    if n_tables > (n_layer + 1) // 2:
        raise ValueError(f"value_embeds={n_tables}: at most {(n_layer + 1) // 2} alternating layers at depth {n_layer}")
    return [n_layer - 1 - 2 * j for j in range(n_tables)][::-1]


def ngram_hash_tables(seed: int, n_tables: int, size: int) -> torch.Tensor:
    """Switch 17: the hash's tabulation tables, [n_tables, size] int32 of NGRAM_HASH_BITS-bit values, from seed's
    splitmix64 stream (each output's top bits), computed with Python integers: the same values on every platform."""
    m64 = (1 << 64) - 1
    x = seed & m64
    out = []
    for _ in range(n_tables * size):
        x = (x + 0x9E3779B97F4A7C15) & m64
        z = ((x ^ (x >> 30)) * 0xBF58476D1CE4E5B9) & m64
        z = ((z ^ (z >> 27)) * 0x94D049BB133111EB) & m64
        out.append((z ^ (z >> 31)) >> (64 - NGRAM_HASH_BITS))
    return torch.tensor(out, dtype=torch.int32).view(n_tables, size)


def ngram_hash_ids(idx: torch.Tensor, hash_tab: torch.Tensor, orders: tuple, rows: int) -> list[torch.Tensor]:
    """Switch 17: for each order n, the table row of the n-gram ending at every position of idx [b, t]: the sum of
    hash_tab[r + k][id at t - k] over k < n, masked to rows (a power of two), int32 [b, t]. A position before the
    window's first has the pad id hash_tab.size(1) - 1. Every operation is int32: each partial sum is masked to
    NGRAM_HASH_BITS (30) bits, so a sum of a partial sum and a value stays below 2^31; rows divides 2^30, so the
    row is the full sum's low bits."""
    z = idx.to(torch.int32)
    b, t = z.shape
    pad = hash_tab.size(1) - 1
    shifted = [z]
    for k in range(1, max(orders)):
        fill = torch.full((b, k), pad, dtype=torch.int32, device=z.device)
        shifted.append(torch.cat([fill, z], dim=1)[:, :t])
    out = []
    r = 0
    for n in orders:
        h = hash_tab[r][shifted[0]]
        for k in range(1, n):
            h = torch.bitwise_and(h + hash_tab[r + k][shifted[k]], NGRAM_HASH_MASK)
        out.append(torch.bitwise_and(h, rows - 1))
        r += n
    return out


def ngram_hash_tables31(seed: int, base: torch.Tensor) -> torch.Tensor:
    """Lane EMA31 (R2_NGRAM_ROWS=2^31): the 31-bit hash's tabulation tables, int64 of base's shape [n_tables, size]:
    each value is ngram_hash_tables' 30-bit value (bits 34 to 63 of the same splitmix64 output) with that output's bit
    33 as bit 30, computed with Python integers (the same values on every platform). base: ngram_hash_tables(seed,
    n_tables, size) as the table object holds it; its values must be the low 30 bits of the result (checked)."""
    n_tables, size = base.shape
    m64 = (1 << 64) - 1
    x = seed & m64
    out = []
    for _ in range(n_tables * size):
        x = (x + 0x9E3779B97F4A7C15) & m64
        z = ((x ^ (x >> 30)) * 0xBF58476D1CE4E5B9) & m64
        z = ((z ^ (z >> 27)) * 0x94D049BB133111EB) & m64
        z ^= z >> 31
        out.append((z >> (64 - NGRAM_HASH_BITS)) | (((z >> (63 - NGRAM_HASH_BITS)) & 1) << NGRAM_HASH_BITS))
    tab = torch.tensor(out, dtype=torch.int64).view(n_tables, size)
    if not torch.equal(torch.bitwise_and(tab, NGRAM_HASH_MASK), base.to(torch.int64)):
        raise RuntimeError("lane EMA31: the 31-bit hash's tables do not hold the base's 30-bit values")
    return tab


def ngram_hash_ids31(idx: torch.Tensor, tab31: torch.Tensor, orders: tuple, rows: int) -> list[torch.Tensor]:
    """Lane EMA31 (R2_NGRAM_ROWS=2^31): ngram_hash_ids above 2^30 rows: the same sums of the same shifted ids (the pad
    id before the window) over ngram_hash_tables31's values, in int64, each partial sum masked to 31 bits (two 31-bit
    terms stay below 2^32: no overflow), the row the full sum masked to rows - 1, returned as int32 (below 2^31). The
    low 30 bits of every sum are the base's 30-bit sum, so a key's row is its 2^30 row or that row plus 2^30."""
    z = idx.to(torch.int64)
    b, t = z.shape
    pad = tab31.size(1) - 1
    shifted = [z]
    for k in range(1, max(orders)):
        fill = torch.full((b, k), pad, dtype=torch.int64, device=z.device)
        shifted.append(torch.cat([fill, z], dim=1)[:, :t])
    out = []
    r = 0
    for n in orders:
        h = tab31[r][shifted[0]]
        for k in range(1, n):
            h = torch.bitwise_and(h + tab31[r + k][shifted[k]], NGRAM_HASH_MASK31)
        out.append(torch.bitwise_and(h, rows - 1).to(torch.int32))
        r += n
    return out


def ngram_bf16_round_up(x: torch.Tensor) -> torch.Tensor:
    """Switch 17, int8 save: FP32 x >= 0 rounded up to the next bf16 value (its FP32 bits truncated to bf16, one bf16
    step added when that dropped anything), so a scale never quantises a value beyond [-127, 127]."""
    bits = x.contiguous().view(torch.int32)
    trunc = torch.bitwise_and(bits, -65536)
    return torch.where(bits != trunc, trunc + 65536, trunc).view(torch.float32)


def ngram_round_bf16(x: torch.Tensor, noise: torch.Tensor) -> torch.Tensor:
    """Switch 17: FP32 x stochastically rounded to bf16 (PR #854's rounding): a uniform 16-bit integer (noise, int32
    of x's shape) is added to each FP32 bit pattern and the low 16 bits are cleared, so the rounding is unbiased and a
    decay smaller than half a bf16 step still acts on average."""
    return ((x.contiguous().view(torch.int32) + noise) & -65536).view(torch.float32).to(torch.bfloat16)


def ngram_view_scale(m: torch.Tensor) -> torch.Tensor:
    """Lane TABLE2 (R2_NGRAM_BITS=1): the 1-bit view's scale of bf16 rows m [n, dim], bf16 [n]: each row's mean |value|,
    summed in float64 by numpy along the row's contiguous values (one fixed pairwise order a row, whatever n), divided
    by the width, rounded to float32 and then to bf16 (round to nearest even). A zero row gets 0."""
    import numpy as np
    a = np.abs(m.contiguous().float().numpy().astype(np.float64)).sum(axis=1) / m.size(1)
    return torch.from_numpy(a.astype(np.float32)).to(torch.bfloat16)


def ngram_view4(m: torch.Tensor):
    """Lane TABLE2 (R2_NGRAM_BITS=4): the 4-bit view of bf16 rows m [n, dim]: q int8 [n, dim] in [-7, 7] and the row
    steps s bf16 [n]: s = max |m| / 7 rounded up to bf16 (switch 17's int8 save rule at 7 levels, so no value leaves
    [-7, 7]), q = round(m / s) (half to even). A zero row gets s = 0 and q = 0. max is exact and every operation is a
    row's own elementwise one, so q and s do not depend on how many rows are viewed together."""
    x = m.float()
    s = ngram_bf16_round_up(x.abs().amax(1) / 7.0)
    safe = torch.where(s > 0, s, torch.ones_like(s))
    q = torch.round(x / safe.unsqueeze(1)).clamp_(-7, 7).to(torch.int8)
    return q, s.to(torch.bfloat16)


def ngram_view4_rows(q: torch.Tensor, s: torch.Tensor) -> torch.Tensor:
    """Lane TABLE2: the 4-bit view's rows, bf16 [n, dim]: q x s in FP32, rounded once to bf16."""
    return (q.to(torch.float32) * s.to(torch.float32).unsqueeze(1)).to(torch.bfloat16)


def ngram_pack4(q: torch.Tensor) -> torch.Tensor:
    """Lane TABLE2: int8 q [n, dim] in [-7, 7] two to a byte along the width, uint8 [n, dim / 2]: column 2 j in the low
    nibble of byte j, column 2 j + 1 in the high nibble, each as 4-bit two's complement."""
    u = q.to(torch.int16) & 15
    return (u[:, 0::2] | (u[:, 1::2] << 4)).to(torch.uint8)


def ngram_unpack4(pk: torch.Tensor, dim: int) -> torch.Tensor:
    """Lane TABLE2: ngram_pack4's inverse, int8 [n, dim]."""
    b = pk.to(torch.int16)
    v = torch.stack([b & 15, (b >> 4) & 15], dim=2).reshape(pk.size(0), dim)
    return torch.where(v >= 8, v - 16, v).to(torch.int8)


def host_meminfo(key: str) -> int:
    """A /proc/meminfo field in bytes (0 if unreadable)."""
    try:
        with open("/proc/meminfo") as fh:
            for ln in fh:
                if ln.startswith(key + ":"):
                    return int(ln.split()[1]) * 1024
    except (OSError, ValueError, IndexError):
        pass
    return 0


class MemPath(type(Path())):
    """A host table's file as rank 0's memfd: its path /proc/<pid>/fd/<n> opens it on every rank of the host; name,
    suffix and parent are the logical file's; unlink() closes rank 0's descriptor (the memory goes with the last
    mapping, as an unlinked tmpfs file's; no use by path after it: the number may be reused)."""

    def with_segments(self, *args):
        return Path(*args)              # a path made from this one (resolve, joins) is a plain path

    @property
    def name(self) -> str:
        return self.__dict__.get("_logical") or super().name

    @property
    def suffix(self) -> str:
        return Path(self.name).suffix

    @property
    def parent(self) -> Path:
        return Path("memfd")            # Os1ShmWatch then reads the host's Shmem (no folder to measure)

    def exists(self, *args, **kwargs) -> bool:
        return True

    def unlink(self, missing_ok: bool = False) -> None:
        fd = self.__dict__.get("_fd")
        self._fd = None
        if fd is not None:
            try:
                os.close(fd)
            except OSError:
                pass


def memfd_files(base_name: str, names: dict, rank: int, world: int, group) -> list:
    """Collective on group: rank 0 makes the memfds (zeros at their sizes) and sends their paths to every rank; every
    rank opens each once, so a refusal raises on every rank before training."""
    import numpy as np
    got, fds = [None], []
    if rank == 0:
        try:
            for k, (dt, shape) in names.items():
                fds.append(os.memfd_create(f"{base_name}.{k}", os.MFD_CLOEXEC))
                os.ftruncate(fds[-1], np.dtype(dt).itemsize * math.prod(shape))
            got[0] = [(f"/proc/{os.getpid()}/fd/{fd}", f"{base_name}.{k}") for fd, k in zip(fds, names)]
        except Exception as e:  # noqa: BLE001 (sent to every rank, raised below on all of them)
            got[0] = f"rank 0 could not make the memfds: {e!r}"
    if world > 1:
        dist.broadcast_object_list(got, src=0, group=group)
    err = got[0] if isinstance(got[0], str) else ""
    for p, _logical in [] if err else got[0]:
        try:
            os.close(os.open(p, os.O_RDWR))
        except OSError as e:
            err = f"rank {rank} cannot open {p}: {e!r}"
            break
    bad = torch.tensor([int(bool(err))], dtype=torch.int64)
    if world > 1:
        dist.all_reduce(bad, group=group)
    if int(bad):
        for fd in fds:
            os.close(fd)
        raise RuntimeError(f"the host tables' memfds failed on {int(bad)} of {world} ranks "
                           f"({err or 'this rank opened them'})")
    out = []
    for i, (p, logical) in enumerate(got[0]):
        m = MemPath(p)
        m._logical, m._fd = logical, (fds[i] if rank == 0 else None)
        out.append(m)
    return out


class NgramHostTable:
    """Switch 17: the n-gram table in host memory, the hash and gather, and the row-wise RMSprop with its exchange.

    table [rows, dim] bf16 and acc [rows] FP32 (the RMSprop accumulator, one per row). With `path`, both are files
    under it (one name per run, `tag`) that every rank of the host maps: rank 0 deletes any stale files of that name,
    creates them zero-filled, and the other ranks map them after a barrier; staging files carry each step's rows and
    gradients between ranks. Without a path (one process) they are private tensors. ids() hashes host token ids to
    rows [b, t, orders]; gather() reads those rows; step() applies one optimizer step's update. read_only() wraps a
    loaded checkpoint's table (bf16, or int8 with a per-row scale) for load_for_eval."""

    def __init__(self, rows: int, dim: int, orders: tuple, seed: int, vocab_pad: int, *, path: str = "", tag: str = "",
                 rank: int = 0, world: int = 1, group=None, max_rows: int = 0, beta: float = 0.99, eps: float = 1e-8,
                 decay: float = 1e-3, quant: bool = False):
        import numpy as np
        self.rows, self.dim, self.orders = rows, dim, tuple(orders)
        self.rank, self.world, self.group = rank, world, group
        self.beta, self.eps, self.decay, self.seed = beta, eps, decay, seed
        self.hash_tab = ngram_hash_tables(seed, sum(self.orders), vocab_pad + 1)
        # Lane EMA31 (R2_NGRAM_ROWS): above 2^30 rows the 31-bit hash's tables (their low 30 bits the base's,
        # checked); None at the base's counts (the base's hash)
        self.hash_tab31 = ngram_hash_tables31(seed, self.hash_tab) if rows > 1 << NGRAM_HASH_BITS else None
        # Switch 17, int8 save: the int8 table and its bf16 row scales (filled at the save, quantize_for_save).
        self.q8 = self.qs = None
        self._mapd = {}
        self.scale = None
        # Lane TABLE2 (R2_NGRAM_BITS): every read takes the rows' packed view; packed once the save has written it.
        self.bits, self.packed = R2_NGRAM_BITS, False
        self.files, self._maps = [], []
        self.stats = {"steps": 0, "rows_updated": 0, "skipped": 0, "host_seconds": 0.0}
        # The stochastic rounding's noise: one buffer of uniform 16-bit integers drawn once from the seed, read at an
        # offset set by the step and the rank (a fresh draw every step took a large share of the update's host time).
        self.noise_buf = torch.randint(0, 1 << 16, (1 << 23,), generator=torch.Generator().manual_seed(seed),
                                       dtype=torch.int32)
        if not path:
            if world > 1:
                raise ValueError("switch 17 on more than one rank needs R2_NGRAM_PATH (the shared table's folder)")
            self.table = torch.zeros(rows, dim, dtype=torch.bfloat16)
            self.acc = torch.zeros(rows, dtype=torch.float32)
            return
        base = Path(path) / f"r2_ngram_{tag}"
        names = {"table": (np.int16, (rows, dim)), "acc": (np.float32, (rows,))}
        if world > 1:
            names.update(st_counts=(np.int64, (world, world)), st_ids=(np.int64, (world, max_rows)),
                         st_grads=(np.float32, (world, max_rows, dim)))
        if quant:
            # Switch 17, int8 save: written at the save only (a tmpfs file takes memory as it is written).
            names.update(q8=(np.int8, (rows, dim)), qs=(np.int16, (rows,)))
        if quant and self.bits:
            # Lane TABLE2: the save writes the packed view in place of the int8 rows: its values (the q8 file, uint8
            # [rows, dim x bits / 8]) and its scales (the qs file, bf16 [rows], as the int8 rows' scales).
            names.update(q8=(np.uint8, (rows, dim * self.bits // 8)))
        self.files = [Path(f"{base}.{k}") for k in names]
        if path == "memfd":                 # lane SHMFIT: no file under a folder (memfd_files below makes them)
            self.files = []
        if rank == 0:
            for f in self.files:
                if f.exists():
                    f.unlink()
            for f, (dt, shape) in zip(self.files, names.values()):
                np.memmap(f, dtype=dt, mode="w+", shape=shape).flush()     # a new file reads as zeros
        if path == "memfd":                 # lane SHMFIT: rank 0's memfds, their paths sent to every rank
            self.files = memfd_files(f"r2_ngram_{tag}", names, rank, world, self.group)
        self.barrier()
        maps = {k: np.memmap(f, dtype=dt, mode="r+", shape=shape) for f, (k, (dt, shape)) in zip(self.files, names.items())}
        self._maps = list(maps.values())
        self._mapd = maps
        if quant:
            self.q8 = torch.from_numpy(maps["q8"])
            self.qs = torch.from_numpy(maps["qs"]).view(torch.bfloat16)
        self.table = torch.from_numpy(maps["table"]).view(torch.bfloat16)
        self.acc = torch.from_numpy(maps["acc"])
        if world > 1:
            self.st_counts = torch.from_numpy(maps["st_counts"])
            self.st_ids = torch.from_numpy(maps["st_ids"])
            self.st_grads = torch.from_numpy(maps["st_grads"])

    @classmethod
    def read_only(cls, table: torch.Tensor, scale, orders: tuple, seed: int, vocab_pad: int) -> "NgramHostTable":
        self = cls.__new__(cls)
        self.rows, self.dim, self.orders = table.size(0), table.size(1), tuple(orders)
        self.rank, self.world, self.group = 0, 1, None
        self.hash_tab = ngram_hash_tables(seed, sum(self.orders), vocab_pad + 1)
        self.hash_tab31 = (ngram_hash_tables31(seed, self.hash_tab) if self.rows > 1 << NGRAM_HASH_BITS
                           else None)     # lane EMA31 (R2_NGRAM_ROWS): a 2^31-row checkpoint's 31-bit hash
        self.table, self.scale, self.acc = table, scale, None
        self.files, self._maps = [], []
        self.q8 = self.qs = None
        self._mapd = {}
        self.bits, self.packed = 0, False      # lane TABLE2: GPT.attach_ngram_table marks a packed table
        return self

    def barrier(self) -> None:
        if self.world > 1:
            dist.barrier(group=self.group)

    def ids(self, tokens: torch.Tensor) -> torch.Tensor:
        """The rows [b, t, orders] (int32) of host token ids [b, t]."""
        if self.rows > 1 << NGRAM_HASH_BITS:      # lane EMA31 (R2_NGRAM_ROWS): the 31-bit hash at 2^31 rows
            return torch.stack(ngram_hash_ids31(tokens, self.hash_tab31, self.orders, self.rows), dim=-1)
        return torch.stack(ngram_hash_ids(tokens, self.hash_tab, self.orders, self.rows), dim=-1)

    def gather(self, ids: torch.Tensor) -> torch.Tensor:
        """The table's rows for ids [..., orders], bf16 [..., orders, dim] (an int8 table dequantised by its row
        scales)."""
        if self.bits:
            # Lane TABLE2 (R2_NGRAM_BITS): the rows' packed view, from the bf16 master in training, from the packed
            # values and the saved scales after the save and in load_for_eval (pack_for_save writes them by the
            # same functions).
            flat = ids.reshape(-1).long()
            if self.bits == 4:
                if self.packed:
                    q, s = ngram_unpack4(self.table.index_select(0, flat), self.dim), self.scale.index_select(0, flat)
                else:
                    q, s = ngram_view4(self.table.index_select(0, flat))
                return ngram_view4_rows(q, s).view(*ids.shape, self.dim)
            if self.packed:
                neg, s = os1_unpack_bits(self.table.index_select(0, flat), self.dim), self.scale.index_select(0, flat)
            else:
                m = self.table.index_select(0, flat)
                neg, s = m < 0, ngram_view_scale(m)
            return os1_view_rows(neg, s).view(*ids.shape, self.dim)
        flat = ids.reshape(-1).long()
        rows = self.table.index_select(0, flat)
        if self.scale is not None:
            rows = (rows.float() * self.scale.index_select(0, flat).float().unsqueeze(1)).to(torch.bfloat16)
        return rows.view(*ids.shape, self.dim)

    def _exchange(self, ids: torch.Tensor, grads: torch.Tensor):
        """This rank's rows and gradients, split by owner (row mod world) into its staging slot; after a barrier, the
        rows this rank owns from every rank, in rank order and each rank's loader order."""
        W, r, n = self.world, self.rank, ids.numel()
        owner = ids % W
        order = torch.argsort(owner, stable=True)
        self.st_counts[r].copy_(torch.bincount(owner, minlength=W))
        self.st_ids[r, :n].copy_(ids.index_select(0, order))
        self.st_grads[r, :n].copy_(grads.index_select(0, order))
        self.barrier()
        if R2_OS1:
            # Lane OS1D (C1, switch 59 on only; unset, the loop below runs as in a1d1d1d1): the same entries in the
            # same order by one flat gather per staging file (os1_owner_index), without the loop's 128 int() reads.
            flat = os1_owner_index(self.st_counts.numpy(), r, self.st_ids.size(1))
            return self.st_ids.view(-1).index_select(0, flat), self.st_grads.view(-1, self.dim).index_select(0, flat)
        counts = self.st_counts.clone()
        starts = torch.cumsum(counts, dim=1) - counts
        pieces_i, pieces_g = [], []
        for s in range(W):
            a, c = int(starts[s, r]), int(counts[s, r])
            pieces_i.append(self.st_ids[s, a:a + c])
            pieces_g.append(self.st_grads[s, a:a + c])
        return torch.cat(pieces_i), torch.cat(pieces_g)

    @torch.no_grad()
    def step(self, ids: torch.Tensor, grads: torch.Tensor, lr: float, step: int) -> None:
        """One optimizer step: ids [N] this rank's rows for the step, grads [N, dim] the gradient of its mean loss
        with respect to those gathered rows (FP32, loader order). Every rank calls it; on return every rank's
        update is in the table."""
        t0 = time.perf_counter()
        ids = ids.reshape(-1).long()
        grads = grads.reshape(-1, self.dim).float()
        own_ids, own_grads = (ids, grads) if self.world == 1 else self._exchange(ids, grads)
        if own_ids.numel() and bool(torch.isfinite(own_grads).all()):
            uniq, inv = torch.unique(own_ids, sorted=True, return_inverse=True)
            g = torch.zeros(uniq.numel(), self.dim, dtype=torch.float32).index_add_(0, inv, own_grads)
            if self.world > 1:
                g.div_(self.world)
            acc = self.acc.index_select(0, uniq).mul_(self.beta).add_(g.square().mean(1), alpha=1.0 - self.beta)
            self.acc.index_copy_(0, uniq, acc)
            x = self.table.index_select(0, uniq).float().mul_(1.0 - self.decay)
            x.sub_(g.mul_((lr / (acc.sqrt() + self.eps)).unsqueeze(1)))
            self.table.index_copy_(0, uniq, ngram_round_bf16(x, self.noise(x.numel(), step).view(x.shape)))
            self.stats["rows_updated"] += uniq.numel()
        elif own_ids.numel():
            self.stats["skipped"] += 1
        self.barrier()
        self.stats["steps"] += 1
        self.stats["host_seconds"] += time.perf_counter() - t0

    @torch.no_grad()
    def prefault(self) -> float:
        """Switch 21 (collective): every page of the shared files populated before training. Rank r reads one byte of
        every 4 KiB page of its 1/W slice of each file (on tmpfs a read allocates the page: no two ranks allocate the
        same one), then, after a barrier, one byte of every page of the table and the accumulator, starting at its own
        slice and wrapping around (mapping them into its own page tables; once the pages exist, the kernel maps their
        neighbours too). Values are only read. Returns the seconds taken."""
        t0 = time.perf_counter()
        W, r = self.world, self.rank
        views = [t.view(torch.uint8).reshape(-1) for t in (self.table, self.acc) if t is not None]
        views += [getattr(self, k).view(torch.uint8).reshape(-1) for k in ("st_counts", "st_ids", "st_grads")
                  if getattr(self, k, None) is not None]
        for b in views:
            pages = b.numel() // 4096
            lo, hi = pages * r // W, pages * (r + 1) // W
            if hi > lo:
                b[lo * 4096:hi * 4096:4096].sum()
        self.barrier()
        for b in views[:2]:
            pages = b.numel() // 4096
            start = (pages * r // W) * 4096
            b[start::4096].sum()
            if start:
                b[:start:4096].sum()
        self.barrier()
        return time.perf_counter() - t0

    def noise(self, n: int, step: int) -> torch.Tensor:
        """n of the buffer's integers from offset (step x 2,654,435,761 + rank x 40,503 + 12,345) mod its length,
        wrapping around its end."""
        buf = self.noise_buf
        size = buf.numel()
        o = (step * 2654435761 + self.rank * 40503 + 12345) % size
        if o + n <= size:
            return buf[o:o + n]
        if n <= size:
            return torch.cat([buf[o:], buf[:o + n - size]])
        return buf.repeat((o + n) // size + 1)[o:o + n]

    def state_for_checkpoint(self, save_dtype: str) -> dict:
        """The table for final.pt's model_state: bf16 as trained, or (after quantize_for_save on every rank) int8
        with a bf16 scale per row."""
        if save_dtype == "bf16":
            return {"ngram_table": self.table}
        if self.q8 is None or self.scale is None:
            raise RuntimeError("switch 17: the int8 save needs quantize_for_save on every rank first")
        return {"ngram_table": self.q8, "ngram_scale": self.qs}

    @torch.no_grad()
    def quantize_for_save(self) -> None:
        """Switch 17, int8 save (collective). Every rank quantises its share of the rows, rows R r / W to
        R (r + 1) / W, into the int8 table and its bf16 row scales: s = max|x| / 127 rounded up to bf16 (so no value
        leaves [-127, 127]), q = round(x / s) (a zero row: s = 0, q = 0). Then the table is served from the int8
        copy (gather dequantises, as load_for_eval's does), the rows with accumulator state are counted, and the
        training state (the bf16 table, the accumulator, the staging) is let go by every rank and its files
        removed (rank 0), so the host frees that memory before the checkpoint is written."""
        if self.bits:
            # Lane TABLE2 (R2_NGRAM_BITS): the packed view in place of the int8 rows.
            return self.pack_for_save()
        import gc
        t0 = time.perf_counter()
        R, W, r = self.rows, self.world, self.rank
        lo, hi = R * r // W, R * (r + 1) // W
        if self.q8 is None:
            self.q8 = torch.zeros(R, self.dim, dtype=torch.int8)
            self.qs = torch.zeros(R, dtype=torch.bfloat16)
        with_state = 0
        for a in range(lo, hi, 1 << 18):
            b = min(hi, a + (1 << 18))
            x = self.table[a:b].float()
            s = ngram_bf16_round_up(x.abs().amax(1) / 127.0)
            safe = torch.where(s > 0, s, torch.ones_like(s))
            self.q8[a:b] = torch.round(x / safe.unsqueeze(1)).clamp_(-127, 127).to(torch.int8)
            self.qs[a:b] = s.to(torch.bfloat16)
            with_state += int((self.acc[a:b] > 0).sum())
        counted = torch.tensor([with_state], dtype=torch.int64)
        if self.world > 1:
            dist.all_reduce(counted, group=self.group)
        self.stats["rows_with_state"] = int(counted.item())
        self.barrier()
        self.table, self.scale = self.q8, self.qs
        self.acc = None
        for k in ("st_counts", "st_ids", "st_grads"):
            if hasattr(self, k):
                setattr(self, k, None)
        for k in ("table", "acc", "st_counts", "st_ids", "st_grads"):
            self._mapd.pop(k, None)
        self._maps = list(self._mapd.values())
        gc.collect()
        self.barrier()
        if self.rank == 0:
            for f in self.files:
                if f.suffix not in (".q8", ".qs"):
                    try:
                        f.unlink()
                    except OSError:
                        pass
        self.stats["quantize_seconds"] = time.perf_counter() - t0

    @torch.no_grad()
    def pack_for_save(self) -> None:
        """Lane TABLE2 (R2_NGRAM_BITS), the save (collective; quantize_for_save calls it): every rank packs its share of
        the rows, rows R r / W to R (r + 1) / W in 2^18-row chunks, into the view's values (the q8 file, uint8 [rows,
        dim x bits / 8]: os1_pack_bits of m < 0 at 1 bit, ngram_pack4 of ngram_view4's q at 4) and its scales (the qs
        file, bf16 [rows]), the functions training's gather reads, so the saved view is the trained table's view bit
        for bit. Then the table is served from the packed view, the rows with accumulator state are counted, and the
        training state is let go and its files removed, as quantize_for_save does for the int8 rows."""
        import gc
        t0 = time.perf_counter()
        R, W, r = self.rows, self.world, self.rank
        lo, hi = R * r // W, R * (r + 1) // W
        if self.q8 is None:
            self.q8 = torch.zeros(R, self.dim * self.bits // 8, dtype=torch.uint8)
            self.qs = torch.zeros(R, dtype=torch.bfloat16)
        with_state = 0
        for a in range(lo, hi, 1 << 18):
            b = min(hi, a + (1 << 18))
            m = self.table[a:b]
            if self.bits == 4:
                q, s = ngram_view4(m)
                self.q8[a:b] = ngram_pack4(q)
                self.qs[a:b] = s
            else:
                self.q8[a:b] = os1_pack_bits(m < 0)
                self.qs[a:b] = ngram_view_scale(m)
            with_state += int((self.acc[a:b] > 0).sum())
        counted = torch.tensor([with_state], dtype=torch.int64)
        if self.world > 1:
            dist.all_reduce(counted, group=self.group)
        self.stats["rows_with_state"] = int(counted.item())
        self.barrier()
        self.table, self.scale, self.packed = self.q8, self.qs, True
        self.acc = None
        for k in ("st_counts", "st_ids", "st_grads"):
            if hasattr(self, k):
                setattr(self, k, None)
        for k in ("table", "acc", "st_counts", "st_ids", "st_grads"):
            self._mapd.pop(k, None)
        self._maps = list(self._mapd.values())
        gc.collect()
        self.barrier()
        if self.rank == 0:
            for f in self.files:
                if f.suffix not in (".q8", ".qs"):
                    try:
                        f.unlink()
                    except OSError:
                        pass
        self.stats["quantize_seconds"] = time.perf_counter() - t0

    def close(self, remove: bool) -> None:
        """With remove (rank 0 at the end of a run, after the checkpoint holds the table), delete the files. The
        mappings stay until the process exits (an unlinked file under /dev/shm stays readable while mapped, so the
        model can still be called), then the host frees the memory."""
        if remove:
            for f in self.files:
                try:
                    f.unlink()
                except OSError:
                    pass


class Os1ShmWatch:
    """Lane TABXB: rank 0's sampler of the tables' file system through the save (switch 59's pack, then switch 17's
    quantise): its used bytes every 0.2 s on a daemon thread and at the marks; stop() ends it and returns the os1_shm
    line (the start, the peak, the marks, the seconds). Information only: nothing the run computes reads it."""

    def __init__(self, path):
        import threading
        self.path, self.t0, self.marks = str(path), time.perf_counter(), []
        self.start_b = self.peak_b = self._used()
        self._halt = threading.Event()
        self._th = threading.Thread(target=self._run, name="r2-os1-shm", daemon=True)
        self._th.start()

    def _used(self) -> int:
        if self.path == "memfd":            # lane SHMFIT: the host's shared memory in use (the memfds count there)
            return host_meminfo("Shmem")
        try:
            st = os.statvfs(self.path)
            return (st.f_blocks - st.f_bfree) * st.f_frsize
        except (OSError, AttributeError):
            return 0

    def _run(self) -> None:
        while not self._halt.wait(0.2):
            self.peak_b = max(self.peak_b, self._used())

    def mark(self, name: str) -> None:
        u = self._used()
        self.peak_b = max(self.peak_b, u)
        self.marks.append((name, u, time.perf_counter() - self.t0))

    def stop(self) -> str:
        self._halt.set()
        self._th.join()
        self.mark("end")
        return (f"os1_shm: path={self.path} start_GB={self.start_b / 1e9:.1f} peak_GB={self.peak_b / 1e9:.1f} "
                + " ".join(f"{n}_GB={u / 1e9:.1f} {n}_s={s:.1f}" for n, u, s in self.marks)
                + f" seconds={time.perf_counter() - self.t0:.1f} order=os1_pack_first,ngram_quantize")


class Os1Record:
    """Switch 59: one step's (or one scorer call's) keys on this rank, flattened in loader order: row (int64, -1 where
    no key exists), signs (int8 [n, dim]), y (the step's targets, cloned, or None at the scorers), nxt (each position's
    next input token, rank 0's diagnostics only, or None), its windows and their length."""

    __slots__ = ("row", "signs", "y", "nxt", "n_win", "seq")

    def sliced(self, k: int) -> "Os1Record":
        """The first k windows (S5: the step's trained ones)."""
        if k >= self.n_win:
            return self
        out = Os1Record()
        n = k * self.seq
        out.row, out.signs = self.row[:n], self.signs[:n]
        out.y = None if self.y is None else self.y[:n]
        out.nxt = None if self.nxt is None else self.nxt[:n]
        out.n_win, out.seq = k, self.seq
        return out


class Os1HostTable:
    """Switch 59: the output-site one-shot table in host memory (work/p2/os1b/NOTES.md).

    table [rows, dim] bf16, zero at the start; q8 [rows, dim] int8 and qs [rows] bf16, written at the save. With `path`
    each is a file that every rank of the host maps (named from `tag`; rank 0 creates them zero-filled), with staging
    files that carry each step's entries between ranks by owner (row mod world, switch 17's scheme); without a path (one
    process) private tensors. record() hashes a step's keys; gather_u() reads and unbinds its rows; job() applies one
    step's gradient update (every rank together); quantize_for_save() reports and quantises (every rank); read_only()
    wraps a checkpoint's table for load_for_eval. Nothing here counts the data: the only write to a row is the
    optimizer's os1_row_step on the training loss's gradient."""

    def __init__(self, rows: int, dim: int, order: int, seed: int, code_seed: int, bos: int, vocab_pad: int, *,
                 path: str = "", tag: str = "", rank: int = 0, world: int = 1, group=None, max_rows: int = 0,
                 lr: float = 0.125, eps: float = 0.0, cap: float = 4.0, a0: float = 1.0, thr: float = 0.7,
                 gate_w: int = 32, gate_h0: float = 0.3, gate_slope: float = 30.0, diag: bool = False,
                 bits: int = 0):
        import numpy as np
        self.rows, self.dim, self.order, self.seed, self.code_seed, self.bos = rows, dim, order, seed, code_seed, bos
        self.bits, self.packed = bits, False     # lane TABXB: R2_OS1_BITS; True once the packed view serves the reads
        self.noise_step = 0                      # lane TABXB: set by job() before each update (the rounding noise)
        self.rank, self.world, self.group, self.max_rows = rank, world, group, max_rows
        self.lr, self.eps, self.cap, self.a0, self.thr = lr, eps, cap, a0, thr
        self.gate_w, self.gate_h0, self.gate_slope, self.diag = gate_w, gate_h0, gate_slope, diag
        self.tabs = os1_hash_tables(seed, order, vocab_pad + 1)
        # The codebook on the host: rank 0's diagnostic reads only (the device has its own copy, scaled by 1 / a0).
        self.code = os1_codebook(vocab_pad, dim, code_seed) if diag else None
        self.first = None
        self.scale = None
        self.stats = {"update_steps": 0, "update_s": 0.0, "gather_s": 0.0, "gathers": 0, "entries": 0,
                      "updated_rows": 0, "capped": 0, "skipped": 0, "quantize_s": 0.0}
        self.mix = self._mix_zero()
        self.record_dict = {"rows": rows, "dim": dim, "order": order, "lr": lr, "eps": eps, "cap": cap, "a0": a0,
                            "thr": thr, "gate_w": gate_w, "gate_h0": gate_h0, "gate_slope": gate_slope,
                            "hash_seed": seed, "code_seed": code_seed, "bos": bos, "rule": "normalized step + budget",
                            "counts": "none"}
        names = {"table": (np.int16, (rows, dim)), "q8": (np.int8, (rows, dim)), "qs": (np.int16, (rows,))}
        if bits:
            # Lane TABXB: the int8 master and its bf16 row scales (the training state), then the packed view's bits and
            # scales (written at the save only: a tmpfs file takes memory as it is written).
            if dim % 8:
                raise ValueError(f"switch 59, R2_OS1_BITS=1: a width that is a multiple of 8 (got {dim})")
            names = {"table": (np.int8, (rows, dim)), "ms": (np.int16, (rows,)), "pk": (np.uint8, (rows, dim // 8)),
                     "vs": (np.int16, (rows,))}
            self.record_dict.update(bits=1, master="int8 rows, bf16 row scales (max|x| / 127 rounded up)",
                                    view="sign(m) x mean|m| (bf16), sign(0) = +1", rounding="stochastic, 16-bit",
                                    save="sign bits packed 8 a byte along the width + bf16 view scales")
        if bits and R2_OS1_MBITS == 4:
            # Lane TABLE3: the master at 4 bits, two values to a byte (os1_unpack4, os1_requant4); the same scales.
            names["table"] = (np.uint8, (rows, dim // 2))
            self.mbits = 4
            self.record_dict.update(master="4-bit rows two to a byte (ngram_pack4), bf16 row scales (max|x| / 7 "
                                    "rounded up)", master_bits=4)
        if world > 1:
            names.update(st_counts=(np.int64, (world, world)), st_ids=(np.int64, (world, max_rows)),
                         st_grads=(np.float32, (world, max_rows, dim)))
        self.files, self._mapd = [], {}
        if not path:
            if world > 1:
                raise ValueError("switch 59 on more than one rank needs R2_NGRAM_PATH (the shared table's folder)")
            maps = {k: torch.from_numpy(np.zeros(shape, dtype=dt)) for k, (dt, shape) in names.items()}
        else:
            base = Path(path) / f"r2_ngram_{tag}"
            self.files = [Path(f"{base}.{k}") for k in names]
            if path == "memfd":             # lane SHMFIT: as switch 17's table
                self.files = []
            if rank == 0:
                for f in self.files:
                    if f.exists():
                        f.unlink()
                for f, (dt, shape) in zip(self.files, names.values()):
                    np.memmap(f, dtype=dt, mode="w+", shape=shape).flush()     # a new file reads as zeros
            if path == "memfd":             # lane SHMFIT: rank 0's memfds, their paths sent to every rank
                self.files = memfd_files(f"r2_ngram_{tag}", names, rank, world, self.group)
            self.barrier()
            self._mapd = {k: np.memmap(f, dtype=dt, mode="r+", shape=shape)
                          for f, (k, (dt, shape)) in zip(self.files, names.items())}
            maps = {k: torch.from_numpy(v) for k, v in self._mapd.items()}
        if bits:
            # Lane TABXB: the master (int8) and its scales, the packed view's files, and the rounding noise (switch 17's
            # scheme: one buffer of uniform 16-bit integers drawn once from a seed, read at an offset set by the step
            # and the rank).
            self.table, self.mscale = maps["table"], maps["ms"].view(torch.bfloat16)
            self.pk, self.vs = maps["pk"], maps["vs"].view(torch.bfloat16)
            self.q8 = self.qs = None
            self.noise_buf = torch.randint(0, 1 << 16, (1 << 23,), generator=torch.Generator().manual_seed(seed + 1),
                                           dtype=torch.int32)
        else:
            self.table = maps["table"].view(torch.bfloat16)
            self.q8, self.qs = maps["q8"], maps["qs"].view(torch.bfloat16)
        for k in ("st_counts", "st_ids", "st_grads"):
            setattr(self, k, maps.get(k))

    @classmethod
    def read_only(cls, table: torch.Tensor, scale: torch.Tensor, config, vocab_pad: int) -> "Os1HostTable":
        """load_for_eval's table: a checkpoint's int8 rows and bf16 row scales (lookups only)."""
        self = cls.__new__(cls)
        self.rows, self.dim, self.order = table.size(0), table.size(1), config.os1_order
        self.seed, self.code_seed, self.bos = config.os1_seed, config.os1_code_seed, config.os1_bos
        self.rank, self.world, self.group = 0, 1, None
        self.tabs = os1_hash_tables(config.os1_seed, config.os1_order, vocab_pad + 1)
        self.code, self.diag = None, False
        self.table, self.scale = table, scale
        self.bits, self.packed = int(getattr(config, "os1_bits", 0) or 0), False
        if self.bits:
            # Lane TABXB: a checkpoint's packed view, its sign bits uint8 [rows, dim / 8] and view scales bf16 [rows].
            self.dim, self.pk, self.vs, self.packed = config.os1_dim, table, scale, True
            self.table = self.scale = None
        self.files, self._mapd = [], {}
        self.stats = {"gather_s": 0.0, "gathers": 0}
        self.mix = cls._mix_zero()
        return self

    def barrier(self) -> None:
        if self.world > 1:
            dist.barrier(group=self.group)

    def record(self, x: torch.Tensor, y) -> Os1Record:
        """The keys of host token ids x [b, t] and (training) a clone of the targets y."""
        b, t = x.shape
        row, hs = os1_keys(x, self.tabs, self.order, self.bos, self.rows)
        rec = Os1Record()
        rec.row = row.reshape(-1)
        rec.signs = os1_signs(hs.reshape(-1), self.dim)
        rec.y = None if y is None else y.reshape(-1).to(torch.int64).clone()
        rec.nxt = None
        if self.diag and y is not None:
            z = x.to(torch.int64)
            nx = torch.full_like(z, self.bos)
            nx[:, :-1] = z[:, 1:]
            rec.nxt = nx.reshape(-1)
        rec.n_win, rec.seq = b, t
        return rec

    def first_record(self, x: torch.Tensor, y: torch.Tensor) -> None:
        """The first step's record (its rows, gathered before the loop, read zeros: the table starts at zero)."""
        self.first = self.record(x, y)

    def gather_u(self, rec: Os1Record) -> torch.Tensor:
        """A record's unbound rows, bf16 [n_win, seq, dim]: signs x row where a key exists, 0 elsewhere (exact: the
        signs are +-1). An int8 table is dequantised by its row scales."""
        t0 = time.perf_counter()
        valid = rec.row >= 0
        idx = rec.row.clamp(min=0)
        if self.bits:
            # Lane TABXB: the 1-bit view's bits and scales (training and every lookup read the same ones), unbound in
            # integer operations (os1_unbind_bits: bit for bit view x signs x valid).
            u = os1_unbind_bits(*self.view_bits(idx), rec.signs, valid)
        else:
            r = self.table.index_select(0, idx)
            if self.scale is not None:
                r = (r.float() * self.scale.index_select(0, idx).float().unsqueeze(1)).to(torch.bfloat16)
            u = r * rec.signs.to(torch.bfloat16) * valid.unsqueeze(1).to(torch.bfloat16)
        if self.diag and rec.y is not None and rec.nxt is not None:
            self._mix_add(u, rec)
        self.stats["gather_s"] += time.perf_counter() - t0
        self.stats["gathers"] += 1
        return u.view(rec.n_win, rec.seq, self.dim)

    def view_bits(self, idx: torch.Tensor):
        """Lane TABXB (R2_OS1_BITS=1): the 1-bit view at idx, its sign bits (bool [n, dim]) and scales (bf16 [n]): in
        training from the int8 master (its values' signs and os1_view_scale of its rows), after the save and in
        load_for_eval from the packed bits and the saved view scales (pack_for_save writes those from the master)."""
        if self.packed:
            return os1_unpack_bits(self.pk.index_select(0, idx), self.dim), self.vs.index_select(0, idx)
        q = self.table.index_select(0, idx)
        if getattr(self, "mbits", 8) == 4:
            q = os1_unpack4(q, self.dim)            # lane TABLE3: the 4-bit master's values (the same view of them)
        return q < 0, os1_view_scale(q, self.mscale.index_select(0, idx))

    def view_rows(self, idx: torch.Tensor) -> torch.Tensor:
        """Lane TABXB: the 1-bit view's rows at idx, bf16 [n, dim] (os1_view_rows of view_bits; the save's checks and
        the tests read it; the gather unbinds the same bits directly)."""
        return os1_view_rows(*self.view_bits(idx))

    def lookup_u(self, idx: torch.Tensor) -> torch.Tensor:
        """The scorers' slot for host token ids idx [b, t]: the unbound rows, bf16 [b, t, dim]."""
        return self.gather_u(self.record(idx, None))

    @staticmethod
    def _mix_zero() -> dict:
        return {"n": 0, "read_sum": 0.0, "hit": 0, "gate": 0, "gate_hit": 0}

    def _mix_add(self, u: torch.Tensor, rec: Os1Record) -> None:
        """Rank 0's diagnostics on its training gathers (information only; nothing the run computes reads them): at
        positions with a key and a token target, the read of the target, s_y = (u . C_y) / a0, how often it clears
        the threshold, and the host's copy of the device's gate (the same formula from the same rows) above 0.5."""
        uu = u.float()
        sel = (rec.row >= 0) & (rec.y >= 0)
        sy = (uu * self.code.index_select(0, rec.y.clamp(min=0))).sum(1) / self.a0
        z = (uu * self.code.index_select(0, rec.nxt)).sum(1) / self.a0
        z = torch.where(rec.nxt == self.bos, torch.zeros_like(z), z).view(rec.n_win, rec.seq)
        cz = torch.cumsum(z, dim=1)
        ex = torch.cat([torch.zeros(rec.n_win, 1), cz[:, :-1]], dim=1)
        t = torch.arange(rec.seq)
        lo = torch.clamp(t - self.gate_w, min=0)
        h = (ex - ex[:, lo]) / torch.clamp(t - lo, min=1).to(torch.float32)
        g = torch.sigmoid(self.gate_slope * (h - self.gate_h0)).reshape(-1)
        m = self.mix
        m["n"] += int(sel.sum())
        m["read_sum"] += float(sy[sel].sum())
        m["hit"] += int((sy[sel] > self.thr).sum())
        m["gate"] += int((g[sel] > 0.5).sum())
        m["gate_hit"] += int(((g[sel] > 0.5) & (sy[sel] > self.thr)).sum())

    def _exchange(self, ids: torch.Tensor, grads: torch.Tensor):
        """This rank's entries, split by owner (row mod world) into its staging slot; after a barrier, the entries this
        rank owns from every rank, in rank order and each rank's loader order (switch 17's exchange). Lane OS1D (C1):
        the owner's share read by one flat gather of each staging file at os1_owner_index's positions (the same
        entries in the same order as 0fd43a66's 64-owner loop of 128 int() reads, 128 slices and two torch.cat)."""
        W, r, n = self.world, self.rank, ids.numel()
        if n > self.max_rows:
            raise RuntimeError(f"switch 59: {n} entries for a staging slot of {self.max_rows}")
        owner = ids % W
        order = torch.argsort(owner, stable=True)
        self.st_counts[r].copy_(torch.bincount(owner, minlength=W))
        self.st_ids[r, :n].copy_(ids.index_select(0, order))
        self.st_grads[r, :n].copy_(grads.index_select(0, order))
        self.barrier()
        flat = os1_owner_index(self.st_counts.numpy(), r, self.st_ids.size(1))
        return self.st_ids.view(-1).index_select(0, flat), self.st_grads.view(-1, self.dim).index_select(0, flat)

    def job(self, rec: Os1Record, grads: torch.Tensor, step: int) -> None:
        """One trained step's update (every rank together); then, every OS1_LINE_EVERY steps and after the first
        update, rank 0's diagnostic line."""
        self.noise_step = step      # lane TABXB: the step whose slice of the rounding noise update_job takes (bits 1)
        self.update_job(rec, grads)
        if step % OS1_LINE_EVERY == 0 or self.stats["update_steps"] == 1:
            self.line(step)

    @torch.no_grad()
    def update_job(self, rec: Os1Record, gu: torch.Tensor) -> None:
        """The step's gradient of the unbound rows gu [k, seq, dim] (the device's): the rows' gradient signs * gu at the
        positions with a key and a nonzero gradient; the owner sums its rows' entries over the ranks, averages them
        (switch 17's convention) and applies os1_row_step (the normalized step and the update budget), stored bf16
        (round to nearest). A step whose gradient is not finite on an owner leaves its rows unchanged."""
        if getattr(self, "mbits", 8) == 4:
            return self.update_job4(rec, gu)        # lane TABLE3: the 4-bit master's update
        t0 = time.perf_counter()
        gu = gu.reshape(-1, self.dim).float()
        nz = (rec.row >= 0) & (gu != 0).any(1)
        ids = rec.row[nz]
        gr = gu[nz] * rec.signs[nz].to(torch.float32)
        own_ids, own_g = (ids, gr) if self.world == 1 else self._exchange(ids, gr)
        if own_ids.numel() and bool(torch.isfinite(own_g).all()):
            uniq, inv = torch.unique(own_ids, sorted=True, return_inverse=True)
            g = torch.zeros(uniq.numel(), self.dim, dtype=torch.float32).index_add_(0, inv, own_g)
            if self.world > 1:
                g.div_(self.world)
            if self.bits:
                # Lane TABXB: the master's rows dequantised, the same rule and budget, then requantised by stochastic
                # rounding with this step's slice of the noise buffer (int8 rows and new bf16 scales).
                x = self.table.index_select(0, uniq).float() * self.mscale.index_select(0, uniq).float().unsqueeze(1)
                self.stats["capped"] += os1_row_step(x, g, self.lr, self.eps, self.cap)
                q, s = os1_requant(x, self.noise(x.numel(), self.noise_step).view(x.shape))
                self.table.index_copy_(0, uniq, q)
                self.mscale.index_copy_(0, uniq, s)
            else:
                x = self.table.index_select(0, uniq).float()
                self.stats["capped"] += os1_row_step(x, g, self.lr, self.eps, self.cap)
                self.table.index_copy_(0, uniq, x.to(torch.bfloat16))
            self.stats["updated_rows"] += int(uniq.numel())
            self.stats["entries"] += int(own_ids.numel())
        elif own_ids.numel():
            self.stats["skipped"] += 1
        self.barrier()
        self.stats["update_steps"] += 1
        self.stats["update_s"] += time.perf_counter() - t0

    def noise(self, n: int, step: int) -> torch.Tensor:
        """Lane TABXB: n of the rounding buffer's integers from switch 17's offset (step x 2,654,435,761 + rank x
        40,503 + 12,345) mod its length, wrapping around its end (NgramHostTable.noise's rule)."""
        buf = self.noise_buf
        size = buf.numel()
        o = (step * 2654435761 + self.rank * 40503 + 12345) % size
        if o + n <= size:
            return buf[o:o + n]
        if n <= size:
            return torch.cat([buf[o:], buf[:o + n - size]])
        return buf.repeat((o + n) // size + 1)[o:o + n]

    @torch.no_grad()
    def update_job4(self, rec: Os1Record, gu: torch.Tensor) -> None:
        """Lane TABLE3 (R2_OS1_MBITS=4): update_job on the 4-bit master, line for line update_job's packed-form branch
        but for two lines: the touched rows unpacked (os1_unpack4) before the dequantisation, and requantised at 7
        levels into nibbles (os1_requant4) with the same slice of the rounding noise. The exchange, the averaging,
        os1_row_step, the scales' write, the counts and the barrier are update_job's."""
        t0 = time.perf_counter()
        gu = gu.reshape(-1, self.dim).float()
        nz = (rec.row >= 0) & (gu != 0).any(1)
        ids = rec.row[nz]
        gr = gu[nz] * rec.signs[nz].to(torch.float32)
        own_ids, own_g = (ids, gr) if self.world == 1 else self._exchange(ids, gr)
        if own_ids.numel() and bool(torch.isfinite(own_g).all()):
            uniq, inv = torch.unique(own_ids, sorted=True, return_inverse=True)
            g = torch.zeros(uniq.numel(), self.dim, dtype=torch.float32).index_add_(0, inv, own_g)
            if self.world > 1:
                g.div_(self.world)
            x = (os1_unpack4(self.table.index_select(0, uniq), self.dim).float()
                 * self.mscale.index_select(0, uniq).float().unsqueeze(1))
            self.stats["capped"] += os1_row_step(x, g, self.lr, self.eps, self.cap)
            q, s = os1_requant4(x, self.noise(x.numel(), self.noise_step).view(x.shape))
            self.table.index_copy_(0, uniq, q)
            self.mscale.index_copy_(0, uniq, s)
            self.stats["updated_rows"] += int(uniq.numel())
            self.stats["entries"] += int(own_ids.numel())
        elif own_ids.numel():
            self.stats["skipped"] += 1
        self.barrier()
        self.stats["update_steps"] += 1
        self.stats["update_s"] += time.perf_counter() - t0

    def line(self, step: int) -> None:
        """Rank 0's diagnostic line (no collective): its owner share's update counts and its gathers' reads."""
        if self.rank != 0:
            return
        m, s = self.mix, self.stats
        n = max(1, m["n"])
        print(f"os1 step {step}: rows={self.rows} update_steps={s['update_steps']} entries_rank0={s['entries']} "
              f"updated_rows_rank0={s['updated_rows']} capped_rank0={s['capped']} skipped_rank0={s['skipped']} "
              f"mix_n={m['n']} read_mean={m['read_sum'] / n:.6f} read_hit={m['hit'] / n:.6f} "
              f"gate_open={m['gate'] / n:.6f} gate_hit={m['gate_hit'] / n:.6f} "
              f"update_ms={1000 * s['update_s'] / max(1, s['update_steps']):.2f} "
              f"gather_ms={1000 * s['gather_s'] / max(1, s['gathers']):.2f}", flush=True)
        self.mix = self._mix_zero()

    def split_pending(self, pending: tuple, prefetch):
        """Switch 21's pending update of the step just taken, split: switch 17's (its orders' slots of the gradient,
        and S11's event when present) and this table's job (the step's record cut to the trained windows, with its
        slot of the same gradient)."""
        ids, grads, lr, step = pending[:4]
        n1 = ids.shape[-1]
        rec = prefetch.recs[prefetch.cur].sliced(ids.shape[0])
        k = self.dim // grads.size(-1)        # lane TABXB: the table's slots (one unless R2_OS1_DIM is a multiple)
        g1 = grads[:, :, n1] if k == 1 else grads[:, :, n1:n1 + k].view(*grads.shape[:2], self.dim)
        return (ids, grads[:, :, :n1], lr, step) + tuple(pending[4:]), (rec, g1, step)

    @torch.no_grad()
    def quantize_for_save(self) -> None:
        """The save (every rank; called from switch 17's quantize_for_save): every rank's share of the rows quantised
        by switch 17's rule (int8, a bf16 scale per row), the rows written (any nonzero value), their mean RMS and the
        rows at the budget measured on the way (log statistics of the table, not of the data); then the table is
        served from the int8 copy, the training state let go and the other files removed (rank 0)."""
        if self.bits:
            self.pack_for_save()            # lane TABXB: the packed 1-bit view instead
            return
        import gc
        t0 = time.perf_counter()
        R, W, r = self.rows, self.world, self.rank
        lo, hi = R * r // W, R * (r + 1) // W
        written, at_cap, rms_sum = 0, 0, 0.0
        bound = 0.999 * self.cap * self.lr
        for a in range(lo, hi, 1 << 18):
            b = min(hi, a + (1 << 18))
            x = self.table[a:b].float()
            amax = x.abs().amax(1)
            s = ngram_bf16_round_up(amax / 127.0)
            safe = torch.where(s > 0, s, torch.ones_like(s))
            self.q8[a:b] = torch.round(x / safe.unsqueeze(1)).clamp_(-127, 127).to(torch.int8)
            self.qs[a:b] = s.to(torch.bfloat16)
            rms = x.square().mean(1).sqrt()
            nzr = amax > 0
            written += int(nzr.sum())
            at_cap += int((rms >= bound).sum())
            rms_sum += float(rms[nzr].double().sum())
        tot = torch.tensor([written, at_cap, self.stats["updated_rows"], self.stats["capped"],
                            self.stats["skipped"]], dtype=torch.int64)
        rs = torch.tensor([rms_sum], dtype=torch.float64)
        if W > 1:
            dist.all_reduce(tot, group=self.group)
            dist.all_reduce(rs, group=self.group)
        self.barrier()
        self.table, self.scale = self.q8, self.qs
        for k in ("st_counts", "st_ids", "st_grads"):
            setattr(self, k, None)
        for k in ("table", "st_counts", "st_ids", "st_grads"):
            self._mapd.pop(k, None)
        gc.collect()
        self.barrier()
        if self.rank == 0:
            for f in self.files:
                if f.suffix not in (".q8", ".qs"):
                    try:
                        f.unlink()
                    except OSError:
                        pass
        self.stats["quantize_s"] = time.perf_counter() - t0
        written, at_cap, updated, capped, skipped = tot.tolist()
        mean_rms = float(rs[0]) / max(1, written)
        self.record_dict.update(written=written, written_frac=written / R, at_cap=at_cap,
                                mean_rms_over_lr=mean_rms / self.lr, updated_row_steps=updated,
                                capped_row_steps=capped, skipped_updates=skipped,
                                update_steps=self.stats["update_steps"],
                                quantize_seconds=round(self.stats["quantize_s"], 1))
        if self.rank == 0:
            print(f"os1_save: rows={R} written={written} written_frac={written / R:.6f} at_cap={at_cap} "
                  f"mean_rms_over_lr={mean_rms / self.lr:.4f} updated_row_steps={updated} capped_row_steps={capped} "
                  f"skipped_updates={skipped} update_steps={self.stats['update_steps']} "
                  f"quantize_s={self.stats['quantize_s']:.1f}", flush=True)

    @torch.no_grad()
    def pack_for_save(self) -> None:
        """Lane TABXB (R2_OS1_BITS=1), the save (every rank; first: patch_base's quantize_for_save calls it before
        switch 17 quantises). Every rank packs its share of the rows (R r / W to R (r + 1) / W) in 2^18-row chunks: the
        1-bit view's sign bits (os1_pack_bits of the master's signs) and scales (os1_view_scale), the very bits and
        scales training's gather read; the rows written (any nonzero value), their mean RMS and the rows at the budget
        measured from the master on the way (log statistics of the table, not of the data). Behind each chunk the
        master's pages and its scales' are given back (os1_punch), so the file system shrinks as the packed view
        grows. Then the table is served from the packed view (the same rows), the training state let go and the
        other files removed (rank 0)."""
        import gc
        t0 = time.perf_counter()
        R, W, r, d = self.rows, self.world, self.rank, self.dim
        if getattr(self, "mbits", 8) == 4:
            d = self.dim // 2                       # lane TABLE3: the 4-bit master's bytes a row (the punches' ranges)
        lo, hi = R * r // W, R * (r + 1) // W
        written, at_cap, rms_sum, punched, chunks = 0, 0, 0.0, 0, 0
        bound = 0.999 * self.cap * self.lr
        if R2_SAVE_PREL:
            save_prel_clear(self, (("table", d), ("ms", 2)))   # lane SAVE: clear this rank's mapping outside its share
        fds = [os.open(f, os.O_RDWR) for f in self.files if f.suffix in (".table", ".ms")]
        try:
            for a in range(lo, hi, 1 << 18):
                b = min(hi, a + (1 << 18))
                q, ms = self.table[a:b], self.mscale[a:b]
                if getattr(self, "mbits", 8) == 4:
                    q = os1_unpack4(q, self.dim)    # lane TABLE3: the 4-bit master's values (the same view of them)
                self.pk[a:b] = os1_pack_bits(q < 0)
                self.vs[a:b] = os1_view_scale(q, ms)
                rms = q.to(torch.float32).square().mean(1).sqrt() * ms.to(torch.float32)
                nzr = (q != 0).any(1)
                written += int(nzr.sum())
                at_cap += int((rms >= bound).sum())
                rms_sum += float(rms[nzr].double().sum())
                chunks += 1
                if len(fds) == 2:
                    punched += int(os1_punch(fds[0], a * d, (b - a) * d) and os1_punch(fds[1], 2 * a, 2 * (b - a)))
        finally:
            for fd in fds:
                os.close(fd)
        tot = torch.tensor([written, at_cap, self.stats["updated_rows"], self.stats["capped"],
                            self.stats["skipped"], punched, chunks], dtype=torch.int64)
        rs = torch.tensor([rms_sum], dtype=torch.float64)
        if W > 1:
            dist.all_reduce(tot, group=self.group)
            dist.all_reduce(rs, group=self.group)
        self.barrier()
        self.table = self.mscale = None
        self.packed = True
        for k in ("st_counts", "st_ids", "st_grads"):
            setattr(self, k, None)
        for k in ("table", "ms", "st_counts", "st_ids", "st_grads"):
            self._mapd.pop(k, None)
        gc.collect()
        self.barrier()
        if self.rank == 0:
            for f in self.files:
                if f.suffix not in (".pk", ".vs"):
                    try:
                        f.unlink()
                    except OSError:
                        pass
        self.stats["quantize_s"] = time.perf_counter() - t0
        written, at_cap, updated, capped, skipped, punched, chunks = tot.tolist()
        mean_rms = float(rs[0]) / max(1, written)
        self.record_dict.update(written=written, written_frac=written / R, at_cap=at_cap,
                                mean_rms_over_lr=mean_rms / self.lr, updated_row_steps=updated,
                                capped_row_steps=capped, skipped_updates=skipped,
                                update_steps=self.stats["update_steps"],
                                quantize_seconds=round(self.stats["quantize_s"], 1), chunks=chunks,
                                punched_chunks=punched)
        if self.rank == 0:
            print(f"os1_save: rows={R} written={written} written_frac={written / R:.6f} at_cap={at_cap} "
                  f"mean_rms_over_lr={mean_rms / self.lr:.4f} updated_row_steps={updated} capped_row_steps={capped} "
                  f"skipped_updates={skipped} update_steps={self.stats['update_steps']} "
                  f"quantize_s={self.stats['quantize_s']:.1f} packed=1bit chunks={chunks} punched_chunks={punched}",
                  flush=True)

    def state_for_checkpoint(self) -> dict:
        """The table for final.pt's model_state (after quantize_for_save on every rank): int8 rows, bf16 scales."""
        if self.bits:
            # Lane TABXB: the packed view (its sign bits and view scales), after pack_for_save on every rank.
            if not self.packed:
                raise RuntimeError("switch 59: the save needs pack_for_save on every rank first")
            return {"os1_table": self.pk, "os1_scale": self.vs}
        if self.scale is None:
            raise RuntimeError("switch 59: the save needs quantize_for_save on every rank first")
        return {"os1_table": self.table, "os1_scale": self.scale}

    @torch.no_grad()
    def prefault(self) -> float:
        """Switch 21's prefault on this table's files (collective): rank r reads one byte of every page of its 1/W of
        the table and the staging, then, after a barrier, one byte of every page of the table from its own offset on,
        wrapping around. Values are only read; q8 and qs are left for the save. Returns the seconds taken."""
        t0 = time.perf_counter()
        W, r = self.world, self.rank
        views = [self.table.view(torch.uint8).reshape(-1)]
        if self.bits:
            views.append(self.mscale.view(torch.uint8).reshape(-1))     # lane TABXB: the master's scales
        views += [getattr(self, k).view(torch.uint8).reshape(-1) for k in ("st_counts", "st_ids", "st_grads")
                  if getattr(self, k, None) is not None]
        for b in views:
            pages = b.numel() // 4096
            lo, hi = pages * r // W, pages * (r + 1) // W
            if hi > lo:
                b[lo * 4096:hi * 4096:4096].sum()
        self.barrier()
        b = views[0]
        pages = b.numel() // 4096
        start = (pages * r // W) * 4096
        b[start::4096].sum()
        if start:
            b[:start:4096].sum()
        if self.bits:
            b = views[1]                  # lane TABXB: the master's scales, mapped by every rank as the master is
            pages = b.numel() // 4096
            start = (pages * r // W) * 4096
            b[start::4096].sum()
            if start:
                b[:start:4096].sum()
        self.barrier()
        return time.perf_counter() - t0

    def close(self, remove: bool) -> None:
        """With remove (rank 0 at the end of a run, after the checkpoint holds the table), delete the files."""
        if remove:
            for f in self.files:
                try:
                    f.unlink()
                except OSError:
                    pass

    def patch_base(self, ngram) -> None:
        """Switch 17's table object's prefault, quantize_for_save, state_for_checkpoint and close made to cover this
        table too, so main()'s calls of them (the rescue path's included) do both (switch 57's pattern)."""
        p, q, s, c = ngram.prefault, ngram.quantize_for_save, ngram.state_for_checkpoint, ngram.close

        def prefault():
            return p() + self.prefault()

        def quantize_for_save():
            if self.bits:
                # Lane TABXB (TABX section 2.3): switch 59 packs first, freeing its master as it goes, then switch 17
                # quantises; rank 0 samples the tables' file system through both and prints the peak (os1_shm line).
                watch = Os1ShmWatch(self.files[0].parent) if self.rank == 0 and self.files else None
                try:
                    self.quantize_for_save()
                    if watch is not None:
                        watch.mark("packed")
                    q()
                finally:
                    if watch is not None:
                        print(watch.stop(), flush=True)
                return
            q()
            self.quantize_for_save()

        def state_for_checkpoint(save_dtype):
            out = dict(s(save_dtype))
            out.update(self.state_for_checkpoint())
            return out

        def close(remove):
            c(remove)
            self.close(remove)

        ngram.prefault, ngram.quantize_for_save = prefault, quantize_for_save
        ngram.state_for_checkpoint, ngram.close = state_for_checkpoint, close

    def setup_line(self, reserve_s: float, typ: float) -> str:
        R, d, W = self.rows, self.dim, self.world
        staging = (W * W * 8 + W * self.max_rows * (8 + 4 * d)) / 1e9 if W > 1 else 0.0
        tgb = (R * (d + 2) if self.bits else R * d * 2) / 1e9          # lane TABXB: the int8 master and its scales
        sgb = (R * (d // 8 + 2) if self.bits else R * (d + 2)) / 1e9   # lane TABXB: the packed view and its scales
        return (f"os1: rows={R} dim={d} order={self.order} lr={self.lr:g} a0={self.a0:g} thr={self.thr:g} "
                f"beta={R2_OS1_BETA:g} glin={R2_OS1_GLIN:g} gate_w={self.gate_w} gate_h0={self.gate_h0:g} "
                f"gate_slope={self.gate_slope:g} cap={self.cap:g} eps_rel={R2_OS1_EPS_REL:g} eps={self.eps:.6e} "
                f"typ={typ:.6e} rule=normalized_step+budget counts=none init=zero thread={R2_OS1_THREAD} "
                f"hash_seed={self.seed} "
                f"code_seed={self.code_seed} bos={self.bos} table_GB={tgb:.3f} "
                f"staging_GB={staging:.3f} save_GB={sgb:.3f} reserve_s={reserve_s:g} "
                f"rows_per_rank_step={self.max_rows} line_every={OS1_LINE_EVERY} host_cuts=C1,C2,C3 "
                f"ngram_exchange=flat"
                + (" bits=1 master=int8+bf16_scale view=sign_x_mean_abs save=packed_1bit+bf16_view_scale "
                   "save_order=os1_first_chunked" if self.bits else ""))

    def end_line(self, timing: dict) -> str:
        s = self.stats
        n = max(1, s["update_steps"])
        return (f"os1_host rank {self.rank}: update_steps={s['update_steps']} "
                f"update_ms={1000 * s['update_s'] / n:.2f} gather_ms={1000 * s['gather_s'] / max(1, s['gathers']):.2f} "
                f"worker_job_ms={1000 * timing.get('os1_job', 0.0) / n:.2f} "
                f"worker_gather_ms={1000 * timing.get('os1_gather', 0.0) / n:.2f} "
                f"worker_wait_ms={1000 * timing.get('os1_wait', 0.0) / n:.2f} entries={s['entries']} "
                f"updated_rows={s['updated_rows']} capped={s['capped']} skipped={s['skipped']} "
                f"quantize_s={s['quantize_s']:.1f}")


# >>> lane SAVE block (R2_SAVE_PREL; work/p2/save/NOTES.md): switch 59's pack with its master cleared in parallel first
def save_prel_clear(tab, parts) -> None:
    """Lane SAVE (R2_SAVE_PREL=1; every rank, collective): before switch 59's pack walks this rank's share (rows
    R r / W to R (r + 1) / W), the rank clears its own mapping of the master's files (parts: (file key, bytes a row))
    outside that share: madvise DONTNEED (saveov2_dontneed) in SAVE_PREL_CHUNK-row pieces, from the piece after its
    share on, around the file, so the ranks clear different pages at once; then the table's barrier, so every rank's
    mapping is clear before any punch. The file keeps its pages (a shared file mapping's entries go, its data does
    not), so the pack reads the same bytes and each of its punches finds this rank's entries only; a piece a share
    covers only in part stays mapped (a punch there finds two mappings). Without files (one process, no path) nothing
    is cleared. Prints this rank's line."""
    t0 = time.perf_counter()
    R, W, r = tab.rows, tab.world, tab.rank
    lo, hi = R * r // W, R * (r + 1) // W
    asked = cleared = 0
    for key, row_bytes in parts:
        mp = tab._mapd.get(key)
        if mp is None or not any(x.suffix == "." + key for x in tab.files):
            continue
        addr, nbytes, step = int(mp.ctypes.data), int(mp.nbytes), SAVE_PREL_CHUNK * int(row_bytes)
        n = (nbytes + step - 1) // step
        k_lo, k_hi = lo * row_bytes // step, (hi * row_bytes + step - 1) // step   # the share's pieces stay mapped
        for jj in range(n):
            k = (k_hi + jj) % n
            if k_lo <= k < k_hi:
                continue
            asked += 1
            cleared += int(saveov2_dontneed(addr + k * step, min(step, nbytes - k * step)))
    t1 = time.perf_counter()
    tab.barrier()
    print(f"save_prel rank {r}: os1 cleared={cleared}/{asked} clear_s={t1 - t0:.1f} "
          f"barrier_s={time.perf_counter() - t1:.1f}", flush=True)


def save_prel_setup(rank: int, world: int, overlap) -> None:
    """Lane SAVE (every rank, once switch 64's object is final and before the tables exist): R2_SAVE_PREL's launch
    refusal (switch 64's overlap packs by its own walk) and rank 0's line."""
    if overlap is not None:
        raise ValueError("lane SAVE: R2_SAVE_PREL=1 and switch 64's overlap (R2_SAVEOV=1 on the clock schedule) "
                         "are two save paths: set one")
    if not rank:
        print(f"save_prel: on (lane SAVE) world={world} os1_rows={R2_OS1_ROWS} piece_rows={SAVE_PREL_CHUNK} "
              f"clear=dontneed_outside_share_staggered_then_barrier pack=base", flush=True)
# <<< lane SAVE block end


COMPUTE_DTYPE: torch.dtype = torch.bfloat16


def norm(x: torch.Tensor) -> torch.Tensor:
    return F.rms_norm(x, (x.size(-1),))


# -----------------------------------------------------------------------------
# Example: a custom NKI kernel (optional, default OFF)
#
# This is an ILLUSTRATION to get you started writing your own Trainium kernels.
# It implements the MLP activation `relu(x)**2` as a fused NKI kernel. The eager
# baseline does not use it; enable it with `--nki-relu2` (Neuron only).
#
# Three things worth copying from this example:
#   1. The kernel body: load a tile from HBM into SBUF, compute, store back.
#   2. Tiling over the 128-partition limit: a NeuronCore processes at most 128
#      rows (the "partition" dim) at once, so we loop over chunks of 128 rows.
#   3. Autograd: a raw NKI kernel is NOT differentiable. To use one inside the
#      training forward pass you must wrap it in a torch.autograd.Function and
#      provide the backward yourself, or gradients silently stop flowing.
#
# To write your own: change the per-tile math in `_relu_sq_fwd` (and the matching
# derivative in `_relu_sq_bwd`), or fuse a different elementwise op.

_NKI_PARTITION = 128  # NeuronCore SBUF partition limit (== nki.language.tile_size.pmax)

try:
    import nki
    import nki.language as nl
    import nki.isa as nisa

    @nki.jit
    def _relu_sq_fwd(x):
        """Fused y = relu(x)**2 for a 2-D [M, N] tensor, tiled over rows."""
        M, N = x.shape
        out = nl.ndarray((M, N), dtype=x.dtype, buffer=nl.shared_hbm)
        for t in nl.affine_range((M + _NKI_PARTITION - 1) // _NKI_PARTITION):
            rows = nl.ds(t * _NKI_PARTITION, _NKI_PARTITION)
            xb = nl.ndarray((_NKI_PARTITION, N), dtype=x.dtype, buffer=nl.sbuf)
            nisa.dma_copy(dst=xb, src=x[rows])
            rb = nl.ndarray((_NKI_PARTITION, N), dtype=x.dtype, buffer=nl.sbuf)
            nisa.tensor_scalar(dst=rb, data=xb, op0=nl.maximum, operand0=0.0)  # relu
            yb = nl.ndarray((_NKI_PARTITION, N), dtype=x.dtype, buffer=nl.sbuf)
            nisa.tensor_tensor(dst=yb, data1=rb, data2=rb, op=nl.multiply)     # square
            nisa.dma_copy(dst=out[rows], src=yb)
        return out

    @nki.jit
    def _relu_sq_bwd(x, grad_out):
        """Backward of relu(x)**2: grad_in = grad_out * 2 * relu(x)."""
        M, N = x.shape
        out = nl.ndarray((M, N), dtype=x.dtype, buffer=nl.shared_hbm)
        for t in nl.affine_range((M + _NKI_PARTITION - 1) // _NKI_PARTITION):
            rows = nl.ds(t * _NKI_PARTITION, _NKI_PARTITION)
            xb = nl.ndarray((_NKI_PARTITION, N), dtype=x.dtype, buffer=nl.sbuf)
            nisa.dma_copy(dst=xb, src=x[rows])
            gb = nl.ndarray((_NKI_PARTITION, N), dtype=x.dtype, buffer=nl.sbuf)
            nisa.dma_copy(dst=gb, src=grad_out[rows])
            rb = nl.ndarray((_NKI_PARTITION, N), dtype=x.dtype, buffer=nl.sbuf)
            nisa.tensor_scalar(dst=rb, data=xb, op0=nl.maximum, operand0=0.0)   # relu(x)
            two_r = nl.ndarray((_NKI_PARTITION, N), dtype=x.dtype, buffer=nl.sbuf)
            nisa.tensor_scalar(dst=two_r, data=rb, op0=nl.multiply, operand0=2.0)
            yb = nl.ndarray((_NKI_PARTITION, N), dtype=x.dtype, buffer=nl.sbuf)
            nisa.tensor_tensor(dst=yb, data1=two_r, data2=gb, op=nl.multiply)
            nisa.dma_copy(dst=out[rows], src=yb)
        return out

    class _ReluSquaredNKI(torch.autograd.Function):
        """Makes the NKI relu**2 kernel differentiable so it can train."""

        @staticmethod
        def forward(ctx, x):
            y = _relu_sq_fwd(x.reshape(-1, x.shape[-1])).reshape(x.shape)
            ctx.save_for_backward(x)
            return y

        @staticmethod
        def backward(ctx, grad_out):
            (x,) = ctx.saved_tensors
            flat_x = x.reshape(-1, x.shape[-1])
            flat_g = grad_out.reshape(-1, x.shape[-1]).contiguous()
            return _relu_sq_bwd(flat_x, flat_g).reshape(x.shape)

    _HAS_NKI = True
except Exception:  # nki unavailable (e.g. CPU/GPU dev box) — eager path still works
    _HAS_NKI = False

# Toggled by the --nki-relu2 flag in main(). Default OFF: the shipped baseline is
# numerically identical to the plain eager `relu(x)**2`.
USE_NKI_RELU2 = False


def relu_squared(x: torch.Tensor) -> torch.Tensor:
    """relu(x)**2, via the example NKI kernel when enabled, else eager."""
    # The example kernel tiles rows in blocks of 128, so it needs a row count that
    # is a multiple of 128 (true for the baseline: B*T = 1*1024). Otherwise fall
    # back to eager so the knob is always safe to flip.
    if USE_NKI_RELU2 and _HAS_NKI and x.device.type == "neuron" and (x.numel() // x.shape[-1]) % _NKI_PARTITION == 0:
        return _ReluSquaredNKI.apply(x)
    return F.relu(x).square()


class Linear(nn.Linear):
    """Linear without bias that casts weight to input dtype (allows bf16 input with f32 weight)."""

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return F.linear(x, self.weight.to(dtype=x.dtype), None)


class GradFoldIn(torch.autograd.Function):
    """Switch 9h: the identity on a weight w in the forward; in the backward its gradient g goes into acc, the
    weight's view of the lean optimizer's Muon slab, in place: acc <- g where flag is True (a step's first
    micro-step: S2's copy) and acc + g where it is False (S2's add: one rounding, in the slab's dtype), and no
    gradient reaches w (its .grad stays None). acc and flag ride on ctx as attributes, not as saved tensors: the
    views share the slab's version counter, so a saved view would fail autograd's version check once another view
    of the slab had been written."""

    @staticmethod
    def forward(ctx, w, acc, flag):
        ctx.acc = acc
        ctx.flag = flag
        return w.view_as(w)

    @staticmethod
    def backward(ctx, g):
        acc = ctx.acc
        acc.copy_(torch.where(ctx.flag, g, acc + g))
        return None, None, None


def fold_in_weight(lin: nn.Module, dtype: torch.dtype) -> torch.Tensor:
    """Switch 9h: lin.weight.to(dtype) for a forward; when the lean optimizer gave lin its slab view and the flag
    (enable_fold_in) and gradients are on, the weight passes GradFoldIn first. Unset: lin.weight.to(dtype)."""
    acc = getattr(lin, "r2_fold_in", None) if R2_GRAD_FOLD_IN else None
    if acc is None or not torch.is_grad_enabled():
        return lin.weight.to(dtype=dtype)
    return GradFoldIn.apply(lin.weight, acc, lin.r2_fold_flag).to(dtype=dtype)


def fold_in_modules(model: nn.Module) -> list:
    """Switch 9h: the Linear layers whose forward takes its weight through fold_in_weight: c_q, c_k and c_v on switch
    9d's QKV route, the attention's c_proj on its c_proj route, c_fc and the MLP's c_proj under switch 9c. Only these
    may get slab views: a weight whose forward bypassed fold_in_weight would get a .grad that no fold reads (the
    optimizer refuses that after a step's first micro-step)."""
    out = []
    # Lane STACK4: switch 48's gated layers run their MLP through mlp_stem8, which reads c_fc and c_proj without
    # fold_in_weight, so those two weights are not listed (their .grad goes to S2's fold). No gated layer: as before.
    gated = set(getattr(model.config, "stem_layers", ()) or ())
    for i, blk in enumerate(model.transformer.h):
        if ATTN8_QKV:
            out += [blk.attn.c_q, blk.attn.c_k, blk.attn.c_v]
        if ATTN8_PROJ:
            out.append(blk.attn.c_proj)
        if R2_MLP == "fused8" and i not in gated:
            out += [blk.mlp.c_fc, blk.mlp.c_proj]
    return out


def apply_rotary_emb(x: torch.Tensor, cos: torch.Tensor, sin: torch.Tensor) -> torch.Tensor:
    d = x.shape[-1] // 2
    x1, x2 = x[..., :d], x[..., d:]
    y1 = x1 * cos + x2 * sin
    y2 = x1 * (-sin) + x2 * cos
    return torch.cat((y1, y2), dim=-1)


def head_gated(y: torch.Tensor, x: torch.Tensor, w: torch.Tensor) -> torch.Tensor:
    """Switch 18: the attention output y [b, t, n_head, head_dim] with each head times its gate sigmoid(x @ w), for
    the attention's input x [b, t, n_embd] and w [n_embd, n_head] cast to x's dtype. Both routes call it."""
    return y * torch.sigmoid(x @ w.to(dtype=x.dtype)).unsqueeze(-1)


def attn_band_mask(t: int, nw: int) -> torch.Tensor:
    """Switch 47: [t, t] bool, True where a short layer attends: key k <= query q and k // 128 > q // 128 - nw (the key
    tiles q // 128 - nw + 1 to q // 128, the diagonal tile causal). Built on the host in int64; the mask for t tokens is
    the top-left corner of the mask for more."""
    i = torch.arange(t, dtype=torch.int64)
    return (i[None, :] <= i[:, None]) & (i[None, :] // 128 > i[:, None] // 128 - nw)


def attn_layer_nw(config, layer: int) -> int:
    """Switch 47: the layer's band in key tiles of 128 (0: the full causal attention), from model_config's fields."""
    if not config.attn_window or layer in config.attn_long:
        return 0
    return config.attn_window // 128


def attn_window_check(config) -> None:
    """Switch 47: model_config's window and long layers, checked wherever a model with a window is built."""
    long_ok = all(isinstance(i, int) and 0 <= i < config.n_layer for i in config.attn_long)
    if (config.attn_window < 128 or config.attn_window % 128 or not config.attn_long or not long_ok
            or len(set(config.attn_long)) != len(config.attn_long)):
        raise ValueError(f"switch 47: attn_window={config.attn_window} attn_long={config.attn_long} at "
                         f"n_layer={config.n_layer}")


def attn_band_attach(model) -> int:
    """Switch 47: the band mask [T, T] bool (attn_band_mask at the declared length, made on the host and moved to the
    model's device) as the non-persistent buffer attn_band of every short layer's attention, one tensor for all of
    them, where SDPA runs the short layers (load_for_eval; a process off the band pair's route). Never saved; the
    kernel's route never reads it. Returns the number of layers given it."""
    cfg = model.config
    if not cfg.attn_window:
        return 0
    mask = attn_band_mask(cfg.sequence_len, cfg.attn_window // 128).to(model.cos.device)
    n = 0
    for blk in model.transformer.h:                                     # switch 47
        if blk.attn.attn_nw:
            blk.attn.register_buffer("attn_band", mask, persistent=False)
            n += 1
    return n


# -----------------------------------------------------------------------------
# Switch 6: the fused attention kernel; switch 7: the route it runs on

ATTN_KERNEL_FILE = "nki_attn.py"
ATTN_KERNEL_MD5 = "d635d2352c5569ff29a23ecd99cba3e4"
