# Route R2 (R2_ATTN_BAND_V8=1): kernels/nki_attn_band2.py, md5-pinned (work/p2/band/kernels/build_attn_band_r2.py).
ATTN_BAND2_KERNEL_FILE = "nki_attn_band2.py"
ATTN_BAND2_KERNEL_MD5 = "5d8aebaf3e79c9030273184ff0a405be"
# Lane BANDPRO (R2_ATTN_PRO=1 beside the window): the band module with lane ATTR's PRO rider, kernels/
# nki_attn_bandpro.py in mlp_kernel_dir(), md5-pinned (its build: work/p2/bandpro/tools/build_bandpro_kernel.py).
ATTN_BANDPRO_KERNEL_FILE = "nki_attn_bandpro.py"
ATTN_BANDPRO_KERNEL_MD5 = "7d70140abe5c67740cf5299023450939"
ATTN_BAND_OPS: dict = {}
ATTN_BAND_COUNTS = {"fwd_op_bodies": 0, "bwd_op_bodies": 0}
ATTN_BAND_STATUS = {"ops": ""}
# Candidate 33's knobs, as the H5 bench ran the kernel; the module reads its R1_* variables once, at import.
ATTN_KERNEL_KNOBS = {
    "R1_NKI_ATTN": "1", "R1_NKI_ATTN_ROPE": "1", "R1_NKI_ATTN_BWD_GROUP": "4", "R1_NKI_ATTN_KCHUNK": "4",
    "R1_NKI_ATTN_V81": "1", "R1_NKI_ATTN_QKN_DT": "bf16", "R1_NKI_ATTN_ROPE_VT": "pe",
}
ATTN_HEAD_DIM = 128
ATTN_SCALE = 1.0 / math.sqrt(ATTN_HEAD_DIM)  # scaled_dot_product_attention's default at head_dim 128

