ATTN_OPS: dict = {}
ATTN_SHIFT = 0.0
ATTN_QK_SCALE = 0.0            # switch 14's qk_scale on the kernel route, and the kernel's fixed shift for it
ATTN_QK_SHIFT = 0.0
ATTN_COUNTS = {"eager_calls": 0, "fwd_op_bodies": 0, "bwd_op_bodies": 0}


def attn_kernel_dir() -> Path:
    """The folder of ATTN_KERNEL_FILE: S2_KERNEL_DIR if set, else _c26_stage two levels above this file's folder
    (~/work/p2/s2_attn/ -> ~/work/_c26_stage/ on the server, the folder the H5 bench imported it from)."""
    if os.environ.get("S2_KERNEL_DIR"):
        return Path(os.environ["S2_KERNEL_DIR"])
    return Path(__file__).resolve().parent.parent.parent / "_c26_stage"


def load_attn_kernel_module():
    """Import ATTN_KERNEL_FILE after checking its md5, with ATTN_KERNEL_KNOBS as the only R1_* variables while it
    imports; the environment is restored afterwards. Returns (module, path)."""
    if R2_ATTN_V8:
        # Switch 9n: the v8 module (candidate 33's kernels byte for byte plus the v8 backward), md5-pinned; the base
        # module is not loaded.
        path = mlp_kernel_dir() / ATTN_V8_KERNEL_FILE
        want = ATTN_V8_KERNEL_MD5
    else:
        path = attn_kernel_dir() / ATTN_KERNEL_FILE
        want = ATTN_KERNEL_MD5
    if ATTN_ATTR_ON:
        # Lane ATTR: the riders' module (nki_attn_v8.py's kernels byte for byte plus the riders) in place of v8's.
        path = mlp_kernel_dir() / ATTN_ATTR_KERNEL_FILE
        want = ATTN_ATTR_KERNEL_MD5
    if R2_ATTN_WINDOW:
        # Switch 47 (lane BAND): the band module in place of candidate 33's or switch 9n's (it holds both backwards and
        # the tile-band pair; route R2's also the v8 band backward; md5-pinned).
        path = mlp_kernel_dir() / (ATTN_BAND2_KERNEL_FILE if R2_ATTN_BAND_V8 else ATTN_BAND_KERNEL_FILE)
        want = ATTN_BAND2_KERNEL_MD5 if R2_ATTN_BAND_V8 else ATTN_BAND_KERNEL_MD5
    if ATTN_BANDPRO:
        # Lane BANDPRO: the band module with lane ATTR's PRO rider in place of the band module (R1_NKI_ATTN_PRO=1 is set
        # below while it imports, under R2_ATTN_PRO, as for lane ATTR's module).
        path = mlp_kernel_dir() / ATTN_BANDPRO_KERNEL_FILE
        want = ATTN_BANDPRO_KERNEL_MD5
    digest = hashlib.md5(path.read_bytes()).hexdigest()
    if digest != want:
        raise RuntimeError(f"{path} has md5 {digest}, expected {want}")
    saved = {k: v for k, v in os.environ.items() if k.startswith("R1_")}
    for k in saved:
        del os.environ[k]
    os.environ.update(ATTN_KERNEL_KNOBS)
    if R2_ATTN_PRO:
        os.environ["R1_NKI_ATTN_PRO"] = "1"  # lane ATTR: the module's forward DMA forms, read once at import
    try:
        spec = importlib.util.spec_from_file_location("s2_nki_attn", path)
        module = importlib.util.module_from_spec(spec)
        sys.modules[spec.name] = module
        spec.loader.exec_module(module)
    finally:
        for k in ATTN_KERNEL_KNOBS:
            os.environ.pop(k, None)
        os.environ.pop("R1_NKI_ATTN_PRO", None)  # lane ATTR
        os.environ.update(saved)
    return module, path


def attn_kernel_applies(x: torch.Tensor, head_dim: int) -> bool:
    """Switch 6: where the kernel runs. The route is set up, the block's input is bf16 on a Neuron device,
    head_dim is 128 and the sequence length a multiple of 128 up to 4,096."""
    t = x.size(1)
    return (ATTN_READY and x.device.type == "neuron" and x.dtype == torch.bfloat16
            and head_dim == ATTN_HEAD_DIM and t % 128 == 0 and t <= 4096)


def fused_rope_attention(qkv: torch.Tensor, cos: torch.Tensor, sin: torch.Tensor, n_head: int,
                         qk_scale: float = 0.0) -> torch.Tensor:
    """Switch 6: the kernel on the projection output qkv [b, t, 3 * n_embd]: RoPE and the QK norm on q and k, then
    causal attention; [b, t, n_head, head_dim] out. Switch 7 decides how the kernel is called. A qk_scale above 0
    (switch 14) replaces the kit's 1/sqrt(head_dim) softmax scale, with the kernel's fixed shift for it."""
    b, t, _ = qkv.shape
    if R2_ROUTE == "eager":
        ATTN_COUNTS["eager_calls"] += 1
        if qk_scale > 0.0:
            y = ATTN_MODULE.nki_rope_attention(qkv, cos, sin, n_head, scale=qk_scale)
        else:
            y = ATTN_MODULE.nki_rope_attention(qkv, cos, sin, n_head)
        if y is None:
            raise RuntimeError(f"the attention kernel module declined qkv {list(qkv.shape)} {qkv.dtype}")
        return y
    if qk_scale > 0.0:
        # Switch 14, qk_scale: the bundle's scale and the shift setup_attn_kernel made for it.
        if qk_scale != ATTN_QK_SCALE:
            raise RuntimeError(f"qk_scale {qk_scale} on the kernel route, whose shift was set up for {ATTN_QK_SCALE}")
        scale, shift = ATTN_QK_SCALE, ATTN_QK_SHIFT
    else:
        scale, shift = ATTN_SCALE, ATTN_SHIFT
    cos2 = cos.reshape(t, ATTN_HEAD_DIM // 2)
    sin2 = sin.reshape(t, ATTN_HEAD_DIM // 2)
    if ATTN_PL_FWD and (b * n_head) % (2 if ATTN_MODULE._LNC == 2 else 1):
        # Lane ATTR, switch 9o: each program of the pipelined forward runs B x H / programs pairs (a fixed trip count).
        raise RuntimeError(f"R2_ATTN_PL (switch 9o): {b} x {n_head} (batch, head) pairs is not a multiple of the "
                           f"launch's programs (LNC {ATTN_MODULE._LNC})")
    if R2_CUSTOMOP_FORM == "nki_hop":
        o3 = FusedRopeAttention.apply(qkv, cos2, sin2, scale, shift)
    else:
        o3 = ATTN_OPS["fwd"](qkv, cos2, sin2, scale, shift)[0]
    return o3.view(b, t, n_head, ATTN_HEAD_DIM)


def fused_rope_attention_band(qkv: torch.Tensor, cos: torch.Tensor, sin: torch.Tensor, n_head: int,
                              qk_scale: float, nw: int) -> torch.Tensor:
    """Switch 47: fused_rope_attention's compiled custom-op route on the tile-band pair (ATTN_BAND_OPS, registered at
    nw = R2_ATTN_WINDOW / 128): the same scale, shift and tables; the pair's autograd runs the band backward."""
    b, t, _ = qkv.shape                                                 # switch 47
    if nw != ATTN_BAND_OPS.get("nw"):
        raise RuntimeError(f"switch 47: a band of {nw} key tiles, but the band pair was registered at "
                           f"{ATTN_BAND_OPS.get('nw')}")
    if qk_scale > 0.0:                                                  # switch 47
        if qk_scale != ATTN_QK_SCALE:                                   # switch 47
            raise RuntimeError(f"switch 47: qk_scale {qk_scale} on the band pair, whose shift was set up for "
                               f"{ATTN_QK_SCALE}")
        scale, shift = ATTN_QK_SCALE, ATTN_QK_SHIFT                     # switch 47
    else:
        scale, shift = ATTN_SCALE, ATTN_SHIFT                           # switch 47
    cos2 = cos.reshape(t, ATTN_HEAD_DIM // 2)                           # switch 47
    sin2 = sin.reshape(t, ATTN_HEAD_DIM // 2)                           # switch 47
    o3 = ATTN_BAND_OPS["fwd"](qkv, cos2, sin2, scale, shift)[0]
    return o3.view(b, t, n_head, ATTN_HEAD_DIM)                      # switch 47


class FusedRopeAttention(torch.autograd.Function):
    """Switch 7, form "nki_hop": the kernel's two launches as NKI's higher-order-operator calls (ATTN_OPS, made by
    setup_attn_kernel outside any trace), with the backward written out."""

    @staticmethod
    def forward(ctx, qkv, cos2, sin2, scale, shift):
        o3, lse3, r5, inv3 = ATTN_OPS["fwd"](qkv, cos2, sin2, scale, shift)
        ctx.save_for_backward(qkv, cos2, sin2, o3, lse3, r5, inv3)
        ctx.scale = scale
        return o3

    @staticmethod
    def backward(ctx, d_o3):
        qkv, cos2, sin2, o3, lse3, r5, inv3 = ctx.saved_tensors
        dqkv = ATTN_OPS["bwd"](qkv, r5, inv3, o3, d_o3.contiguous(), lse3, cos2, sin2, ctx.scale)
        return dqkv, None, None, None, None


def register_attn_ops(module) -> str:
    """Switch 7, "compiled_customop": the kernel's forward and backward as ATTN_OPS["fwd"] / ATTN_OPS["bwd"],
    registered the R2_CUSTOMOP_FORM way, the forward with the backward as its autograd formula. The kernels are
    taken at the module's launch width (kernel[2] under LNC 2) here, outside any trace. Returns how."""
    global ATTN_OPS
    fwd_kernel = module._launch(module._attn_rope_fwd_kernel)
    if ATTN_PL_FWD:
        # Lane ATTR, switch 9o: lane A9M's pipelined forward binds the forward op; the backward stays v8's.
        fwd_kernel = module._launch(module._attn_rope_fwd_kernel_pl)
    # Switch 9n: the v8 backward in place of candidate 33's; the forward kernel is the same either way.
    bwd_kernel = module._launch(module._attn_rope_bwd_kernel_v8 if R2_ATTN_V8 else module._attn_rope_bwd_kernel)
    if R2_CUSTOMOP_FORM == "nki_hop":
        from nki.compiler.frontend import ParserFrontend
        from nki.framework.kernel import wrap_nki_to_torch_hop
        ATTN_OPS = {"fwd": wrap_nki_to_torch_hop(fwd_kernel, _frontend_cls=ParserFrontend),
                    "bwd": wrap_nki_to_torch_hop(bwd_kernel, _frontend_cls=ParserFrontend)}
        return "NKI's higher-order operator (nki.framework.kernel.wrap_nki_to_torch_hop) in an autograd.Function"
    if R2_CUSTOMOP_FORM == "nki_op":
        from torch_neuronx import nki_op as make_op
    elif R2_CUSTOMOP_FORM == "torch_library":
        make_op = torch.library.custom_op
    else:
        raise ValueError(f"unknown R2_CUSTOMOP_FORM {R2_CUSTOMOP_FORM!r}")

    @make_op("s2attn::rope_attn_fwd", mutates_args=())
    def rope_attn_fwd(qkv: torch.Tensor, cos2: torch.Tensor, sin2: torch.Tensor, scale: float,
                      shift: float) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
        ATTN_COUNTS["fwd_op_bodies"] += 1
        o3, lse3, r5, inv3 = fwd_kernel(qkv, cos2, sin2, scale, shift)
        return o3, lse3, r5, inv3

    @make_op("s2attn::rope_attn_bwd", mutates_args=())
    def rope_attn_bwd(qkv: torch.Tensor, r5: torch.Tensor, inv3: torch.Tensor, o3: torch.Tensor,
                      do3: torch.Tensor, lse3: torch.Tensor, cos2: torch.Tensor, sin2: torch.Tensor,
                      scale: float) -> torch.Tensor:
        ATTN_COUNTS["bwd_op_bodies"] += 1
        return bwd_kernel(qkv, r5, inv3, o3, do3, lse3, cos2, sin2, scale)

    def rope_attn_fwd_fake(qkv, cos2, sin2, scale, shift):
        # The kernel's own allocations: o3 [b, t, c], lse3 [b*h, 128, g] fp32, r5 [2, b, h, t, 128],
        # inv3 [b*h, 128, g, 2, 1] fp32.
        b, t, c3 = qkv.shape
        h, g = c3 // 3 // ATTN_HEAD_DIM, t // 128
        return (qkv.new_empty(b, t, c3 // 3), qkv.new_empty(b * h, 128, g, dtype=torch.float32),
                qkv.new_empty(2, b, h, t, ATTN_HEAD_DIM), qkv.new_empty(b * h, 128, g, 2, 1, dtype=torch.float32))

    def rope_attn_bwd_fake(qkv, r5, inv3, o3, do3, lse3, cos2, sin2, scale):
        return torch.empty_like(qkv)

    # Ours are the kernel's allocations exactly; a decorator that keeps its own (registration refused) keeps it.
    fakes = []
    for name, fake in (("s2attn::rope_attn_fwd", rope_attn_fwd_fake), ("s2attn::rope_attn_bwd", rope_attn_bwd_fake)):
        try:
            torch.library.register_fake(name)(fake)
            fakes.append("ours")
        except Exception as err:
            fakes.append(f"the decorator's ({type(err).__name__})")

    def setup_context(ctx, inputs, output):
        qkv, cos2, sin2, scale, _shift = inputs
        o3, lse3, r5, inv3 = output
        ctx.save_for_backward(qkv, cos2, sin2, o3, lse3, r5, inv3)
        ctx.scale = scale
        ctx.mark_non_differentiable(lse3, r5, inv3)
        ctx.set_materialize_grads(False)  # no zero tensors for the three outputs that carry no gradient

    def backward(ctx, d_o3, _d_lse3, _d_r5, _d_inv3):
        qkv, cos2, sin2, o3, lse3, r5, inv3 = ctx.saved_tensors
        dqkv = rope_attn_bwd(qkv, r5, inv3, o3, d_o3.contiguous(), lse3, cos2, sin2, ctx.scale)
        return dqkv, None, None, None, None

    torch.library.register_autograd("s2attn::rope_attn_fwd", backward, setup_context=setup_context)
    ATTN_OPS = {"fwd": rope_attn_fwd, "bwd": rope_attn_bwd}
    if R2_ATTN_WINDOW:
        # Switch 47: the tile-band pair beside the full pair (the same fakes and autograd form).
        ATTN_BAND_STATUS["ops"] = register_attn_band_ops(module, make_op, rope_attn_fwd_fake, rope_attn_bwd_fake)
    return (f"custom ops s2attn::rope_attn_fwd / rope_attn_bwd by {R2_CUSTOMOP_FORM}, fake impls "
            f"{fakes[0]} / {fakes[1]}, autograd by torch.library.register_autograd")


def register_attn_band_ops(module, make_op, fwd_fake, bwd_fake) -> str:
    """Switch 47: s2attn::rope_attn_fwd_band / rope_attn_bwd_band, the module's tile-band kernels at its launch width
    (kernel[2] under LNC 2), with nw = R2_ATTN_WINDOW / 128 a constant of the pair handed to each kernel as a Python int
    (switch 9b hands its tile width the same way); the full pair's signatures, fakes and autograd form (lane WIN's
    registration, line for line). Returns the registration line."""
    global ATTN_BAND_OPS
    nw = R2_ATTN_WINDOW // 128
    fwd_kernel = module._launch(module._attn_rope_fwd_kernel_band)
    # Route R2 (R2_ATTN_BAND_V8=1): the v8 band backward; route R1: lane WIN's band backward.
    bwd_kernel = module._launch(module._attn_rope_bwd_kernel_v8_band if R2_ATTN_BAND_V8
                                else module._attn_rope_bwd_kernel_band)

    @make_op("s2attn::rope_attn_fwd_band", mutates_args=())
    def band_fwd(qkv: torch.Tensor, cos2: torch.Tensor, sin2: torch.Tensor, scale: float,
                 shift: float) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
        ATTN_BAND_COUNTS["fwd_op_bodies"] += 1
        o3, lse3, r5, inv3 = fwd_kernel(qkv, cos2, sin2, scale, shift, nw)
        return o3, lse3, r5, inv3                                  # switch 47

    @make_op("s2attn::rope_attn_bwd_band", mutates_args=())
    def band_bwd(qkv: torch.Tensor, r5: torch.Tensor, inv3: torch.Tensor, o3: torch.Tensor,
                 do3: torch.Tensor, lse3: torch.Tensor, cos2: torch.Tensor, sin2: torch.Tensor,
                 scale: float) -> torch.Tensor:
        ATTN_BAND_COUNTS["bwd_op_bodies"] += 1
        return bwd_kernel(qkv, r5, inv3, o3, do3, lse3, cos2, sin2, scale, nw)

    fakes = []
    for name, fake in (("s2attn::rope_attn_fwd_band", fwd_fake), ("s2attn::rope_attn_bwd_band", bwd_fake)):
        try:
            torch.library.register_fake(name)(fake)
            fakes.append("ours")
        except Exception as err:
            fakes.append(f"the decorator's ({type(err).__name__})")

    def setup_context(ctx, inputs, output):
        qkv, cos2, sin2, scale, _shift = inputs                         # switch 47
        o3, lse3, r5, inv3 = output                                     # switch 47
        ctx.save_for_backward(qkv, cos2, sin2, o3, lse3, r5, inv3)
        ctx.scale = scale
        ctx.mark_non_differentiable(lse3, r5, inv3)                     # switch 47
        ctx.set_materialize_grads(False)                           # switch 47

    def backward(ctx, d_o3, _d_lse3, _d_r5, _d_inv3):                   # switch 47
        qkv, cos2, sin2, o3, lse3, r5, inv3 = ctx.saved_tensors
        dqkv = band_bwd(qkv, r5, inv3, o3, d_o3.contiguous(), lse3, cos2, sin2, ctx.scale)
        return dqkv, None, None, None, None

    torch.library.register_autograd("s2attn::rope_attn_fwd_band", backward, setup_context=setup_context)
    ATTN_BAND_OPS = {"fwd": band_fwd, "bwd": band_bwd, "nw": nw}
    return (f"s2attn::rope_attn_fwd_band / rope_attn_bwd_band at nw {nw} by {R2_CUSTOMOP_FORM}, backward "
            f"{'v8 band (route R2)' if R2_ATTN_BAND_V8 else 'band (route R1)'}, fake impls {fakes[0]} / {fakes[1]}")


def setup_attn_kernel() -> str:
    """Switches 6 and 7: load the kernel module and prepare the route, before torch.compile and the first forward.
    Returns a status line for the log."""
    global ATTN_READY, ATTN_MODULE, ATTN_SHIFT, ATTN_QK_SCALE, ATTN_QK_SHIFT
    if not R2_ATTN_KERNEL:
        return "off"
    module, path = load_attn_kernel_module()
    knobs = (f"BWD_GROUP {module._BWD_GROUP} KCHUNK {module._KCHUNK} V81 {module._V81} QKN_DT {module._QKN_DT} "
             f"ROPE_VT {module._ROPE_VT} ROPE_SAVE {module._ROPE_SAVE} LNC {module._LNC}")
    where = f"{path} md5 {ATTN_V8_KERNEL_MD5 if R2_ATTN_V8 else ATTN_KERNEL_MD5}, {knobs}"
    if ATTN_ATTR_ON:
        where = f"{path} md5 {ATTN_ATTR_KERNEL_MD5}, {knobs}"  # lane ATTR: the riders' module, its own md5
    if R2_ATTN_WINDOW:
        # Switch 47: the band module and its own md5 (route R2's under R2_ATTN_BAND_V8).
        where = f"{path} md5 {ATTN_BAND2_KERNEL_MD5 if R2_ATTN_BAND_V8 else ATTN_BAND_KERNEL_MD5}, {knobs}"
    if ATTN_BANDPRO:
        where = f"{path} md5 {ATTN_BANDPRO_KERNEL_MD5}, {knobs}"  # lane BANDPRO: the merged module, its own md5
    if not module._HAS_NKI:
        return f"unavailable (nki does not import here), the kit's attention throughout; {where}"
    if not (module.USE_NKI_ATTN and module.USE_NKI_ATTN_ROPE) or module._ROPE_SAVE != "r" or module._BWD_GROUP < 2:
        raise RuntimeError(f"the attention kernel module did not take candidate 33's knobs: {knobs}")
    if R2_ATTN_V8:
        # Switch 9n: the v8 backward needs the v8.1 placement and groups that start on chunk boundaries, and runs as a
        # custom op (the module's own autograd.Function on the eager route takes candidate 33's backward).
        if R2_ROUTE != "compiled_customop":
            raise ValueError(f"R2_ATTN_V8 (switch 9n) runs on the compiled custom-op route, not {R2_ROUTE!r}")
        if not module._V81 or module._BWD_GROUP % module._KCHUNK != 0:
            raise RuntimeError(f"R2_ATTN_V8 (switch 9n) needs V81 and BWD_GROUP a multiple of KCHUNK: {knobs}")
        if not hasattr(module, "_attn_rope_bwd_kernel_v8"):
            raise RuntimeError(f"{path} has no _attn_rope_bwd_kernel_v8")
        where += "; attn_v8=1 (the v8 backward: dQ, dV, dK accumulated transposed with 512-wide moving operands)"
    if ATTN_ATTR_ON:
        # Lane ATTR: the riders' module must carry v8.1's placement and saved RoPE rows (both forwards' prologue), take
        # R1_NKI_ATTN_PRO as R2_ATTN_PRO set it, and hold the pipelined forward.
        pro = getattr(module, "_PRO", None)
        if not module._V81 or module._ROPE_SAVE != "r" or pro is None or bool(pro) != R2_ATTN_PRO:
            raise RuntimeError(f"lane ATTR's module did not take its knobs: {knobs} PRO {pro}")
        if not hasattr(module, "_attn_rope_fwd_kernel_pl"):
            raise RuntimeError(f"{path} has no _attn_rope_fwd_kernel_pl")
        where += (f"; attr: PRO {int(module._PRO)} pro={int(R2_ATTN_PRO)} pl={R2_ATTN_PL} "
                  f"(forward {'pipelined' if ATTN_PL_FWD else 'base'}, one V load and one output store a pair: "
                  f"{'yes' if R2_ATTN_PRO else 'no'})")
    if R2_ATTN_WINDOW:
        # Switch 47: the band pair beside switch 6's (and 9n's) kernels, on the compiled custom-op route in form nki_op
        # or torch_library (the eager route and nki_hop never run the band).
        if R2_ROUTE != "compiled_customop" or R2_CUSTOMOP_FORM not in ("nki_op", "torch_library"):
            raise ValueError(f"switch 47 runs on the compiled custom-op route, form nki_op or torch_library, not "
                             f"{R2_ROUTE} / {R2_CUSTOMOP_FORM}")
        if not (hasattr(module, "_attn_rope_fwd_kernel_band") and hasattr(module, "_attn_rope_bwd_kernel_band")):
            raise RuntimeError(f"switch 47: {path} has no tile-band pair")
        if R2_ATTN_BAND_V8 and not hasattr(module, "_attn_rope_bwd_kernel_v8_band"):
            raise RuntimeError(f"switch 47 route R2: {path} has no _attn_rope_bwd_kernel_v8_band")
        where += (f"; switch 47: band pair at nw {R2_ATTN_WINDOW // 128} (window {R2_ATTN_WINDOW}), long layers "
                  f"{','.join(str(i) for i in sorted(R2_ATTN_WIN_LAYERS))}, short layers' backward "
                  f"{'v8 band (route R2)' if R2_ATTN_BAND_V8 else 'band (route R1)'}")
    if ATTN_BANDPRO:
        # Lane BANDPRO: the merged module must carry v8.1's placement and saved RoPE rows (the PRO forwards' prologue as
        # lane ATTR's), have taken R1_NKI_ATTN_PRO=1, and hold both PRO forwards beside the band pair.
        bp_pro = getattr(module, "_PRO", None)
        if not module._V81 or module._ROPE_SAVE != "r" or not bp_pro or not hasattr(module, "_pro_ostore"):
            raise RuntimeError(f"lane BANDPRO's module did not take its knobs: {knobs} PRO {bp_pro}")
        where += (f"; bandpro: PRO {int(bp_pro)} pro={int(R2_ATTN_PRO)} (lane ATTR's rider in the full and the band "
                  f"forward: one V load and one output store a pair, on the Act queue's hardware DGE)")
    ATTN_SHIFT = module.fixed_shift(ATTN_SCALE, ATTN_HEAD_DIM)
    if "qk_scale" in BUNDLE_ITEMS:
        # Switch 14, qk_scale: the bundle's scale and the kernel's fixed shift for it (the bound scale * head_dim on
        # the scaled scores after the QK norm, plus the module's margin), as the module's own wrapper computes it.
        ATTN_QK_SCALE = R2_QK_SCALE
        ATTN_QK_SHIFT = module.fixed_shift(R2_QK_SCALE, ATTN_HEAD_DIM)
        where += f"; qk_scale {ATTN_QK_SCALE:g} shift {ATTN_QK_SHIFT:.6g}"
    if R2_ROUTE == "eager":
        how = "the module's nki_rope_attention (its autograd.Function)"
    elif R2_ROUTE == "compiled_customop":
        how = register_attn_ops(module)
    else:
        raise ValueError(f"unknown R2_ROUTE {R2_ROUTE!r}")
    ATTN_MODULE = module
    ATTN_READY = True
    return f"on, route {R2_ROUTE}: {how}; {where}"


def attn_kernel_summary() -> str:
    """Switch 6: the end-of-run line. eager_calls counts the eager route's kernel calls; the op bodies run when
    the custom ops execute outside a compiled graph (or are traced by the decorator)."""
    if not ATTN_READY:
        return "off"
    disabled = ATTN_MODULE._LAST_KERNEL_ERROR if ATTN_MODULE._KERNEL_DISABLED else None
    form = R2_CUSTOMOP_FORM if R2_ROUTE == "compiled_customop" else "-"
    return (f"route={R2_ROUTE} form={form} eager_calls={ATTN_COUNTS['eager_calls']} "
            f"fwd_op_bodies={ATTN_COUNTS['fwd_op_bodies']} bwd_op_bodies={ATTN_COUNTS['bwd_op_bodies']} "
            f"disabled={disabled}" + (f" v8={int(R2_ATTN_V8)}" if RECORD_ATTN_V8 else ""))


# -----------------------------------------------------------------------------
# Switches 8 to 10: three more NKI kernels, inlined. Each is the reviewed source the H5 bench ran on the chip,
# taken verbatim by kernels_extract.py (comments and docstrings removed, the source's import-time knobs resolved at
# the bench's values, module names prefixed): the chunked loss head (W2's prototype,
# work/agents/p2_kernels/nki_loss_head_chunk_proto.py, md5 831a6fe0), the fp8 GEMM and its weight quantiser
# (candidate 33's work/_c26_stage/nki_gemm_fp8_nn.py, md5 b0fb16e2) and the embedding backward (candidate 33's
# work/_c26_stage/nki_embedding.py, md5 1365cbc7). Every launch is kernel[2], the launch command's LNC 2.

_LH_VCHUNK = 8192              # loss head: vocabulary entries per chunk (32,768 = 4 chunks of the Phase 1 tile shape)
_LH_NBUF = 2                   # loss head: chunk tiles double-buffered
_F8_P = 128                    # fp8 GEMM: SBUF partitions
_F8_CH = 512                   # fp8 GEMM: output columns per PSUM bank (the output width must be a multiple)
_F8_KS = 256                   # fp8 GEMM: contraction per double-row matmul (the contraction must be a multiple)
_F8_J = 2
_EB_P = 128                    # embedding backward: tokens per tile
_EB_VPP = 2                    # embedding backward: vocabulary tiles of 128 per pass
_EB_NBUF = 4                   # embedding backward: gradient tiles in flight
_EB_MOVING = 352               # embedding backward: columns per matmul (1,408 = 4 x 352)
_EB_ONEZERO = False
_EB_W = 256                    # embedding backward: one-hot columns per pass
_OS1_VCHUNK = 4096             # lane OS1A2: the fused readout's loss head pair, vocabulary entries per chunk
_OS1_MM = 512                  # lane OS1A2: the read term's matmul columns (one FP32 PSUM bank)

try:
    import nki
    import nki.language as nl
    import nki.isa as nisa

    _LH_VEC = nisa.engine.vector
    _F8_PM = nisa.matmul_perf_mode.double_row

    # ---- begin extracted kernels (kernels_extract.py) ----
    def _lh_shard():
        if nl.program_ndim() > 0:
            return nl.program_id(0), nl.num_programs(0)
        return 0, 1

    def _lh_tile_range(NT):
        pid, nprg = _lh_shard()
        per, rem = NT // nprg, NT % nprg
        i0 = pid * per + min(pid, rem)
        n = per + (1 if pid < rem else 0)
        return i0, i0 + n

    def _lh_pair(shape, dtype):
        return (nl.ndarray(shape, dtype=dtype, buffer=nl.sbuf), nl.ndarray(shape, dtype=dtype, buffer=nl.sbuf))

    @nki.jit
    def _lh_fwd_kernel(x3, tl3, rwc4, softcap):
        P, NT, V = x3.shape
        K = tl3.shape[0]
        NC = V // _LH_VCHUNK
        f32 = nl.float32
        loss2 = nl.ndarray((P, NT), dtype=f32, buffer=nl.shared_hbm)
        lz2 = nl.ndarray((P, NT), dtype=f32, buffer=nl.shared_hbm)
        i0, i1 = _lh_tile_range(NT)
        n = i1 - i0
        if n > 0:
            zc = nl.ndarray((P, n, NC), dtype=f32, buffer=nl.sbuf)
            tgl = nl.ndarray((P, K, n), dtype=nl.uint32, buffer=nl.sbuf)
            xtb = nl.ndarray((P, K, NC, n), dtype=x3.dtype, buffer=nl.sbuf)
            for k in range(K):
                nisa.dma_copy(dst=tgl[:, k, :], src=tl3[k, :, i0:i1])
            xbs = _lh_pair((P, _LH_VCHUNK), x3.dtype)
            ts = _lh_pair((P, _LH_VCHUNK), f32)
            es = _lh_pair((P, _LH_VCHUNK), f32)
            steps = n * NC
            nisa.dma_copy(dst=xbs[0], src=x3[:, i0, 0:_LH_VCHUNK])
            for s in range(steps):
                j = s // NC
                c = s % NC
                xb, t, e = xbs[s % _LH_NBUF], ts[s % _LH_NBUF], es[s % _LH_NBUF]
                sn = s + 1
                if sn < steps:
                    jn = sn // NC
                    cn = sn % NC
                    nisa.dma_copy(dst=xbs[sn % _LH_NBUF], src=x3[:, i0 + jn, cn * _LH_VCHUNK:(cn + 1) * _LH_VCHUNK])
                nisa.activation(dst=t, op=nl.tanh, data=xb, scale=1.0 / softcap)
                nisa.activation_reduce(dst=e, op=nl.exp, data=t, reduce_op=nl.add, reduce_res=zc[:, j, c:c + 1],
                                       scale=softcap, bias=-softcap)
                for k in range(K):
                    nisa.nc_n_gather(dst=xtb[:, k, c, j:j + 1], data=xb, indices=tgl[:, k, j:j + 1])
            zb = nl.ndarray((P, n), dtype=f32, buffer=nl.sbuf)
            nisa.tensor_reduce(dst=zb, op=nl.add, data=zc, axis=2)
            lzb = nl.ndarray((P, n), dtype=f32, buffer=nl.sbuf)
            nisa.activation(dst=lzb, op=nl.log, data=zb)
            nisa.dma_copy(dst=lz2[:, i0:i1], src=lzb)
            lzc = nl.ndarray((P, n), dtype=f32, buffer=nl.sbuf)
            nisa.tensor_scalar(dst=lzc, data=lzb, op0=nl.add, operand0=softcap)
            rwb = nl.ndarray((P, n), dtype=f32, buffer=nl.sbuf)
            tb = nl.ndarray((P, n), dtype=f32, buffer=nl.sbuf)
            nll = nl.ndarray((P, n), dtype=f32, buffer=nl.sbuf)
            acc = nl.ndarray((P, n), dtype=f32, buffer=nl.sbuf)
            for k in range(K):
                for c in range(NC):
                    nisa.dma_copy(dst=rwb, src=rwc4[k, c, :, i0:i1])
                    nisa.activation(dst=tb, op=nl.tanh, data=xtb[:, k, c, :], scale=1.0 / softcap)
                    nisa.scalar_tensor_tensor(dst=nll, data=tb, op0=nl.multiply, operand0=-softcap, op1=nl.add, operand1=lzc)
                    if k == 0 and c == 0:
                        nisa.tensor_tensor(dst=acc, data1=nll, data2=rwb, op=nl.multiply, engine=_LH_VEC)
                    else:
                        nisa.tensor_tensor(dst=nll, data1=nll, data2=rwb, op=nl.multiply, engine=_LH_VEC)
                        nisa.tensor_tensor(dst=acc, data1=acc, data2=nll, op=nl.add, engine=_LH_VEC)
            nisa.dma_copy(dst=loss2[:, i0:i1], src=acc)
        return loss2, lz2

    @nki.jit
    def _lh_bwd_kernel(x3, tg3, rwc4, lz2, g2, softcap):
        P, NT, V = x3.shape
        K = tg3.shape[0]
        NC = V // _LH_VCHUNK
        f32 = nl.float32
        d3 = nl.ndarray((P, NT, V), dtype=x3.dtype, buffer=nl.shared_hbm)
        i0, i1 = _lh_tile_range(NT)
        n = i1 - i0
        if n > 0:
            tgs = nl.ndarray((P, K, NC, n), dtype=f32, buffer=nl.sbuf)
            rwb = nl.ndarray((P, K, n), dtype=f32, buffer=nl.sbuf)
            tmp = nl.ndarray((P, n), dtype=f32, buffer=nl.sbuf)
            for k in range(K):
                nisa.dma_copy(dst=tgs[:, k, 0, :], src=tg3[k, :, i0:i1])
                for c in range(1, NC):
                    nisa.tensor_scalar(dst=tgs[:, k, c, :], data=tgs[:, k, 0, :], op0=nl.add, operand0=-float(c * _LH_VCHUNK))
                nisa.dma_copy(dst=rwb[:, k, :], src=rwc4[k, 0, :, i0:i1])
                for c in range(1, NC):
                    nisa.dma_copy(dst=tmp, src=rwc4[k, c, :, i0:i1])
                    nisa.tensor_tensor(dst=rwb[:, k, :], data1=rwb[:, k, :], data2=tmp, op=nl.add, engine=_LH_VEC)
            nb = nl.ndarray((P, n), dtype=f32, buffer=nl.sbuf)
            nisa.dma_copy(dst=nb, src=lz2[:, i0:i1])
            ab = nl.ndarray((P, n), dtype=f32, buffer=nl.sbuf)
            nisa.dma_copy(dst=ab, src=g2[:, i0:i1])
            nisa.tensor_tensor(dst=ab, data1=ab, data2=rwb[:, 0, :], op=nl.multiply, engine=_LH_VEC)
            sq = nl.ndarray((P, n), dtype=f32, buffer=nl.sbuf)
            nisa.activation(dst=sq, op=nl.sqrt, data=ab)
            nisa.tensor_scalar(dst=nb, data=nb, op0=nl.multiply, operand0=-1.0, op1=nl.add, operand1=-softcap)
            if K > 1:
                nisa.reciprocal(dst=rwb[:, 0, :], data=rwb[:, 0, :])
                for k in range(1, K):
                    nisa.tensor_tensor(dst=rwb[:, k, :], data1=rwb[:, k, :], data2=rwb[:, 0, :], op=nl.multiply, engine=_LH_VEC)
                wb = nl.ndarray((P, n), dtype=f32, buffer=nl.sbuf)
                nisa.tensor_scalar(dst=wb, data=rwb[:, 1, :], op0=nl.add, operand0=1.0)
                for k in range(2, K):
                    nisa.tensor_tensor(dst=wb, data1=wb, data2=rwb[:, k, :], op=nl.add, engine=_LH_VEC)
                nisa.activation(dst=wb, op=nl.log, data=wb)
                nisa.tensor_tensor(dst=nb, data1=nb, data2=wb, op=nl.add, engine=_LH_VEC)
            io = nl.ndarray((P, _LH_VCHUNK), dtype=f32, buffer=nl.sbuf)
            nisa.iota(dst=io, pattern=[[1, _LH_VCHUNK]], offset=0, channel_multiplier=0)
            xbs = _lh_pair((P, _LH_VCHUNK), x3.dtype)
            ts = _lh_pair((P, _LH_VCHUNK), f32)
            qs = _lh_pair((P, _LH_VCHUNK), f32)
            steps = n * NC
            nisa.dma_copy(dst=xbs[0], src=x3[:, i0, 0:_LH_VCHUNK])
            for s in range(steps):
                j = s // NC
                c = s % NC
                i = i0 + j
                xb, t, q = xbs[s % _LH_NBUF], ts[s % _LH_NBUF], qs[s % _LH_NBUF]
                sn = s + 1
                if sn < steps:
                    jn = sn // NC
                    cn = sn % NC
                    nisa.dma_copy(dst=xbs[sn % _LH_NBUF], src=x3[:, i0 + jn, cn * _LH_VCHUNK:(cn + 1) * _LH_VCHUNK])
                nisa.activation(dst=t, op=nl.tanh, data=xb, scale=1.0 / softcap)
                nisa.activation(dst=q, op=nl.exp, data=t, scale=softcap, bias=nb[:, j:j + 1])
                nisa.scalar_tensor_tensor(dst=q, data=io, op0=nl.equal, operand0=tgs[:, 0, c, j:j + 1],
                                          op1=nl.subtract, operand1=q)
                for k in range(1, K):
                    nisa.tensor_scalar(dst=xb, data=io, op0=nl.equal, operand0=tgs[:, k, c, j:j + 1])
                    nisa.scalar_tensor_tensor(dst=q, data=xb, op0=nl.multiply, operand0=rwb[:, k, j:j + 1],
                                              op1=nl.add, operand1=q)
                nisa.activation(dst=t, op=nl.square, data=t, scale=sq[:, j:j + 1])
                nisa.scalar_tensor_tensor(dst=xb, data=t, op0=nl.subtract, operand0=ab[:, j:j + 1],
                                          op1=nl.multiply, operand1=q)
                nisa.dma_copy(dst=d3[:, i, c * _LH_VCHUNK:(c + 1) * _LH_VCHUNK], src=xb)
        return d3

    def _f8_dtype(fmt):
        if fmt == 1:
            return nl.float8_e5m2
        return nl.float8_e4m3

    def _f8_shard():
        if nl.program_ndim() > 0:
            return nl.program_id(0), nl.num_programs(0)
        return 0, 1

    def _f8_span(n, pid, nprg):
        per = n // nprg
        rem = n - per * nprg
        i0 = pid * per
        if pid < rem:
            i0 = i0 + pid
        else:
            i0 = i0 + rem
        cnt = per
        if pid < rem:
            cnt = cnt + 1
        return i0, i0 + cnt

    def _f8_ceil_div(a, b):
        return (a + b - 1) // b

    def _f8_ptiles(n, shape, dtype, buf):
        t0 = nl.ndarray(shape, dtype=dtype, buffer=buf)
        if n == 1:
            return (t0,)
        t1 = nl.ndarray(shape, dtype=dtype, buffer=buf)
        if n == 2:
            return (t0, t1)
        t2 = nl.ndarray(shape, dtype=dtype, buffer=buf)
        if n == 3:
            return (t0, t1, t2)
        t3 = nl.ndarray(shape, dtype=dtype, buffer=buf)
        if n == 4:
            return (t0, t1, t2, t3)
        t4 = nl.ndarray(shape, dtype=dtype, buffer=buf)
        if n == 5:
            return (t0, t1, t2, t3, t4)
        t5 = nl.ndarray(shape, dtype=dtype, buffer=buf)
        if n == 6:
            return (t0, t1, t2, t3, t4, t5)
        t6 = nl.ndarray(shape, dtype=dtype, buffer=buf)
        if n == 7:
            return (t0, t1, t2, t3, t4, t5, t6)
        t7 = nl.ndarray(shape, dtype=dtype, buffer=buf)
        return (t0, t1, t2, t3, t4, t5, t6, t7)

    def _f8_load_at_hwt(a2, K, NKB, row0, ntok, dt):
        at = nl.ndarray((_F8_P, NKB, ntok), dtype=dt, buffer=nl.sbuf)
        for s in range(ntok // 16):
            nisa.dma_transpose(dst=at.ap([[NKB * ntok, _F8_P], [ntok, NKB], [1, 1], [1, 16]], offset=s * 16),
                               src=a2.ap([[K, 16], [_F8_P, NKB], [1, 1], [1, _F8_P]], offset=(row0 + s * 16) * K),
                               dge_mode=nisa.dge_mode.hwdge)
        return at

    def _f8_load_at_pre(a2t, K, NKB, row0, ntok, dt):
        at = nl.ndarray((_F8_P, NKB, ntok), dtype=dt, buffer=nl.sbuf)
        for kk in range(NKB):
            nisa.dma_copy(dst=at[:, kk, :], src=a2t[kk * _F8_P:(kk + 1) * _F8_P, row0:row0 + ntok])
        return at

    def _f8_quantise_block(at, NKD, ntok, scale, aq, bound, hi, fmt):
        a_f8 = nl.ndarray((_F8_P, NKD, _F8_J, ntok), dtype=_f8_dtype(fmt), buffer=nl.sbuf)
        for kd in range(NKD):
            for j in range(_F8_J):
                kk = kd * _F8_J + j
                if aq == 1:
                    nisa.tensor_scalar(dst=a_f8[:, kd, j, :], data=at[:, kk, :],
                                       op0=nl.multiply, operand0=scale,
                                       op1=nl.minimum, operand1=hi, engine=nisa.engine.vector)
                elif aq == 2:
                    nisa.tensor_scalar(dst=a_f8[:, kd, j, :], data=at[:, kk, :],
                                       op0=nl.minimum, operand0=hi,
                                       op1=nl.maximum, operand1=-hi, engine=nisa.engine.vector)
                else:
                    nisa.tensor_scalar(dst=at[:, kk, :], data=at[:, kk, :],
                                       op0=nl.minimum, operand0=bound,
                                       op1=nl.maximum, operand1=-bound, engine=nisa.engine.vector)
                    nisa.activation(dst=a_f8[:, kd, j, :], op=nl.copy, data=at[:, kk, :], scale=scale)
        return a_f8

    def _f8_load_w_chunks(w_u8, K, N, NKD, NC):
        w_sb = nl.ndarray((_F8_P, NKD * NC, _F8_J, _F8_CH), dtype=nl.uint8, buffer=nl.sbuf)
        for kd in range(NKD):
            for c in range(NC):
                for j in range(_F8_J):
                    r0 = kd * _F8_KS + j * _F8_P
                    nisa.dma_copy(dst=w_sb[:, kd * NC + c, j, :], src=w_u8[r0:r0 + _F8_P, c * _F8_CH:(c + 1) * _F8_CH])
        return w_sb.view(nl.float8_e4m3)

    def _f8_evac_scaled(dst, src, k, evac, inv_scale):
        if evac == 1:
            nisa.activation(dst=dst, op=nl.copy, data=src, scale=inv_scale)
        elif evac == 2:
            nisa.tensor_scalar(dst=dst, data=src, op0=nl.multiply, operand0=inv_scale,
                               engine=nisa.engine.vector)
        elif k % 2 == 0:
            nisa.activation(dst=dst, op=nl.copy, data=src, scale=inv_scale)
        else:
            nisa.tensor_scalar(dst=dst, data=src, op0=nl.multiply, operand0=inv_scale,
                               engine=nisa.engine.vector)

    def _f8_mm_tile(a_f8, w_f8, out, ti, bt0, N, NKD, NC, npass, group, evac, inv_scale, dt, f32):
        row0 = (bt0 + ti) * _F8_P
        ost = nl.ndarray((_F8_P, N), dtype=dt, buffer=nl.sbuf)
        for p in range(npass):
            c0 = p * group
            g = NC - c0
            if g > group:
                g = group
            pss = _f8_ptiles(g, (_F8_P, _F8_CH), f32, nl.psum)
            for kd in range(NKD):
                st = a_f8[:, kd, :, ti * _F8_P:(ti + 1) * _F8_P]
                for j in range(g):
                    nisa.nc_matmul(dst=pss[j], stationary=st, moving=w_f8[:, kd * NC + c0 + j, :, :],
                                   accumulate=(kd > 0), perf_mode=_F8_PM)
            for j in range(g):
                c = c0 + j
                _f8_evac_scaled(ost[:, c * _F8_CH:(c + 1) * _F8_CH], pss[j], c, evac, inv_scale)
        nisa.dma_copy(dst=out[row0:row0 + _F8_P, :], src=ost)

    @nki.jit
    def _f8_mm_kernel(a2, w_u8, xt_mode, tb, group, evac, aq, loop, afmt,
                          a_scale, a_bound, a_hi, inv_scale):
        if xt_mode == 2:
            K = a2.shape[0]
            M = a2.shape[1]
        else:
            M = a2.shape[0]
            K = a2.shape[1]
        N = w_u8.shape[1]
        dt = a2.dtype
        f32 = nl.float32
        out = nl.ndarray((M, N), dtype=dt, buffer=nl.shared_hbm)
        NKD = K // _F8_KS
        NKB = K // _F8_P
        NC = N // _F8_CH
        npass = _f8_ceil_div(NC, group)
        pid, nprg = _f8_shard()
        t0, t1 = _f8_span(M // _F8_P, pid, nprg)
        w_f8 = _f8_load_w_chunks(w_u8, K, N, NKD, NC)
        ntb = tb // _F8_P
        nblk = _f8_ceil_div(t1 - t0, ntb)
        for b in range(nblk):
            bt0 = t0 + b * ntb
            bt1 = bt0 + ntb
            if bt1 > t1:
                bt1 = t1
            nt = bt1 - bt0
            if xt_mode == 2:
                at = _f8_load_at_pre(a2, K, NKB, bt0 * _F8_P, nt * _F8_P, dt)
            else:
                at = _f8_load_at_hwt(a2, K, NKB, bt0 * _F8_P, nt * _F8_P, dt)
            a_f8 = _f8_quantise_block(at, NKD, nt * _F8_P, a_scale, aq, a_bound, a_hi, afmt)
            if loop == 1:
                for ti in nl.affine_range(nt):
                    _f8_mm_tile(a_f8, w_f8, out, ti, bt0, N, NKD, NC, npass, group, evac, inv_scale, dt, f32)
            else:
                for ti in range(nt):
                    _f8_mm_tile(a_f8, w_f8, out, ti, bt0, N, NKD, NC, npass, group, evac, inv_scale, dt, f32)
        return out

    @nki.jit
    def _f8_quant_w_kernel(w, scale, clip, bound):
        K = w.shape[0]
        N = w.shape[1]
        out = nl.ndarray((K, N), dtype=nl.uint8, buffer=nl.shared_hbm)
        pid, nprg = _f8_shard()
        r0, r1 = _f8_span(K // _F8_P, pid, nprg)
        for i in range(r1 - r0):
            k0 = (r0 + i) * _F8_P
            stage = nl.ndarray((_F8_P, N), dtype=w.dtype, buffer=nl.sbuf)
            nisa.dma_copy(dst=stage, src=w[k0:k0 + _F8_P, :])
            if clip == 1:
                nisa.tensor_scalar(dst=stage, data=stage, op0=nl.minimum, operand0=bound,
                                   op1=nl.maximum, operand1=-bound, engine=nisa.engine.vector)
            q_u8 = nl.ndarray((_F8_P, N), dtype=nl.uint8, buffer=nl.sbuf)
            nisa.activation(dst=q_u8.view(nl.float8_e4m3), op=nl.copy, data=stage, scale=scale)
            nisa.dma_copy(dst=out[k0:k0 + _F8_P, :], src=q_u8)
        return out

    def _eb_dma(dst, src):
        nisa.dma_copy(dst=dst, src=src)

    def _eb_shard():
        if nl.program_ndim() > 0:
            return nl.program_id(0), nl.num_programs(0)
        return 0, 1

    def _eb_iota_row(P, W):
        io = nl.ndarray((P, W), dtype=nl.float32, buffer=nl.sbuf)
        nisa.iota(dst=io, pattern=[[1, W]], offset=0, channel_multiplier=0)
        return io

    def _eb_idx_src(idx3):
        if len(idx3.shape) == 3:
            return idx3[:, :, 0]
        return idx3

    def _eb_tiles(n, shape, dtype, buf):
        if n == 1:
            return (nl.ndarray(shape, dtype=dtype, buffer=buf),)
        if n == 2:
            return (nl.ndarray(shape, dtype=dtype, buffer=buf), nl.ndarray(shape, dtype=dtype, buffer=buf))
        if n == 3:
            return (nl.ndarray(shape, dtype=dtype, buffer=buf), nl.ndarray(shape, dtype=dtype, buffer=buf),
                    nl.ndarray(shape, dtype=dtype, buffer=buf))
        if n == 4:
            return (nl.ndarray(shape, dtype=dtype, buffer=buf), nl.ndarray(shape, dtype=dtype, buffer=buf),
                    nl.ndarray(shape, dtype=dtype, buffer=buf), nl.ndarray(shape, dtype=dtype, buffer=buf))
        return (nl.ndarray(shape, dtype=dtype, buffer=buf), nl.ndarray(shape, dtype=dtype, buffer=buf),
                nl.ndarray(shape, dtype=dtype, buffer=buf), nl.ndarray(shape, dtype=dtype, buffer=buf),
                nl.ndarray(shape, dtype=dtype, buffer=buf), nl.ndarray(shape, dtype=dtype, buffer=buf),
                nl.ndarray(shape, dtype=dtype, buffer=buf), nl.ndarray(shape, dtype=dtype, buffer=buf))

    def _eb_onehot(oh, io, idxb, ids, t, v0):
        nisa.tensor_scalar(dst=oh, data=io, op0=nl.equal, operand0=ids[:, t:t + 1])

    def _eb_matmuls(accs, oh, dyb, CC, acc_flag):
        for v in range(_EB_VPP):
            for c in range(CC):
                nisa.nc_matmul(dst=accs[v * CC + c], stationary=oh[:, v * _EB_P:(v + 1) * _EB_P],
                               moving=dyb[:, c * _EB_MOVING:(c + 1) * _EB_MOVING], accumulate=acc_flag,
                               is_stationary_onezero=_EB_ONEZERO)

    def _eb_acc_flag(first):
        return first

    def _eb_store_psum(dw, accs, CC, C, v0):
        for v in range(_EB_VPP):
            ob = nl.ndarray((_EB_P, C), dtype=nl.float32, buffer=nl.sbuf)
            for c in range(CC):
                nisa.tensor_copy(dst=ob[:, c * _EB_MOVING:(c + 1) * _EB_MOVING], src=accs[v * CC + c])
            _eb_dma(dst=dw[v0 + v * _EB_P:v0 + (v + 1) * _EB_P, :], src=ob)

    @nki.jit
    def _eb_bwd_kernel(idx3, dy3, V):
        P, NT, C = dy3.shape
        f32, bf16 = nl.float32, nl.bfloat16
        dw = nl.ndarray((V, C), dtype=f32, buffer=nl.shared_hbm)
        pid, nprg = _eb_shard()
        VTp = (V // P) // nprg
        NPASS = VTp // _EB_VPP
        CC = C // _EB_MOVING
        NACC = _EB_VPP * CC
        io = _eb_iota_row(P, _EB_W)
        idxb = nl.ndarray((P, NT), dtype=f32, buffer=nl.sbuf)
        _eb_dma(dst=idxb, src=_eb_idx_src(idx3))
        for ps in range(NPASS):
            v0 = (pid * VTp + ps * _EB_VPP) * P
            ids = nl.ndarray((P, NT), dtype=f32, buffer=nl.sbuf)
            nisa.tensor_scalar(dst=ids, data=idxb, op0=nl.subtract, operand0=v0 * 1.0)
            accs = _eb_tiles(NACC, (P, _EB_MOVING), f32, nl.psum)
            dybs = _eb_tiles(_EB_NBUF, (P, C), dy3.dtype, nl.sbuf)
            ohs = _eb_tiles(2, (P, _EB_W), bf16, nl.sbuf)
            for t in range(min(_EB_NBUF - 1, NT)):
                _eb_dma(dst=dybs[t % _EB_NBUF], src=dy3[:, t, :])
            for t in range(NT):
                tn = t + _EB_NBUF - 1
                if tn < NT and _EB_NBUF > 1:
                    _eb_dma(dst=dybs[tn % _EB_NBUF], src=dy3[:, tn, :])
                if _EB_NBUF == 1:
                    _eb_dma(dst=dybs[0], src=dy3[:, t, :])
                oh = ohs[t % 2]
                _eb_onehot(oh, io, idxb, ids, t, v0)
                _eb_matmuls(accs, oh, dybs[t % _EB_NBUF], CC, _eb_acc_flag(t > 0))
            _eb_store_psum(dw, accs, CC, C, v0)
        return dw
    # ---- end extracted kernels ----

    # T1: switch 10's embedding backward with the matmul tile width a parameter: `mov` columns per matmul and per
    # PSUM accumulator (mov * 4 bytes, within one 2 KB PSUM bank). At mov = _EB_MOVING it issues _eb_bwd_kernel's
    # instructions; T1 launches it at _EB_MOVING_W = 384 for width 1,536 (4 x 384).
    def _eb_matmuls_w(accs, oh, dyb, CC, acc_flag, mov):
        for v in range(_EB_VPP):
            for c in range(CC):
                nisa.nc_matmul(dst=accs[v * CC + c], stationary=oh[:, v * _EB_P:(v + 1) * _EB_P],
                               moving=dyb[:, c * mov:(c + 1) * mov], accumulate=acc_flag,
                               is_stationary_onezero=_EB_ONEZERO)

    def _eb_store_psum_w(dw, accs, CC, C, v0, mov):
        for v in range(_EB_VPP):
            ob = nl.ndarray((_EB_P, C), dtype=nl.float32, buffer=nl.sbuf)
            for c in range(CC):
                nisa.tensor_copy(dst=ob[:, c * mov:(c + 1) * mov], src=accs[v * CC + c])
            _eb_dma(dst=dw[v0 + v * _EB_P:v0 + (v + 1) * _EB_P, :], src=ob)

    @nki.jit
    def _eb_bwd_w_kernel(idx3, dy3, V, mov):
        P, NT, C = dy3.shape
        f32, bf16 = nl.float32, nl.bfloat16
        dw = nl.ndarray((V, C), dtype=f32, buffer=nl.shared_hbm)
        pid, nprg = _eb_shard()
        VTp = (V // P) // nprg
        NPASS = VTp // _EB_VPP
        CC = C // mov
        NACC = _EB_VPP * CC
        io = _eb_iota_row(P, _EB_W)
        idxb = nl.ndarray((P, NT), dtype=f32, buffer=nl.sbuf)
        _eb_dma(dst=idxb, src=_eb_idx_src(idx3))
        for ps in range(NPASS):
            v0 = (pid * VTp + ps * _EB_VPP) * P
            ids = nl.ndarray((P, NT), dtype=f32, buffer=nl.sbuf)
            nisa.tensor_scalar(dst=ids, data=idxb, op0=nl.subtract, operand0=v0 * 1.0)
            accs = _eb_tiles(NACC, (P, mov), f32, nl.psum)
            dybs = _eb_tiles(_EB_NBUF, (P, C), dy3.dtype, nl.sbuf)
            ohs = _eb_tiles(2, (P, _EB_W), bf16, nl.sbuf)
            for t in range(min(_EB_NBUF - 1, NT)):
                _eb_dma(dst=dybs[t % _EB_NBUF], src=dy3[:, t, :])
            for t in range(NT):
                tn = t + _EB_NBUF - 1
                if tn < NT and _EB_NBUF > 1:
                    _eb_dma(dst=dybs[tn % _EB_NBUF], src=dy3[:, tn, :])
                if _EB_NBUF == 1:
                    _eb_dma(dst=dybs[0], src=dy3[:, t, :])
                oh = ohs[t % 2]
                _eb_onehot(oh, io, idxb, ids, t, v0)
                _eb_matmuls_w(accs, oh, dybs[t % _EB_NBUF], CC, _eb_acc_flag(t > 0), mov)
            _eb_store_psum_w(dw, accs, CC, C, v0, mov)
        return dw

    # Switch 26: the loss head pair with label smoothing eps (R2_LABEL_SMOOTH), derived from switch 8's kernels
    # above by work/p2/s2c_ls/proofs/make_kernels_piece.py. Forward: each chunk's tanh also sums its values into
    # sc (activation_reduce, the same ScalarEngine instruction); the row's loss is
    # lse - eps (softcap / V) sum_v tanh(x_v / softcap) - (1 - eps) z_target, with mean_coef = -eps softcap / V and
    # tgt_coef = -(1 - eps) softcap from the op; lz2 is the plain log-sum-exp less softcap, as switch 8's.
    @nki.jit
    def _lh_fwd_ls_kernel(x3, tl3, rwc4, softcap, tgt_coef, mean_coef):
        P, NT, V = x3.shape
        K = tl3.shape[0]
        NC = V // _LH_VCHUNK
        f32 = nl.float32
        loss2 = nl.ndarray((P, NT), dtype=f32, buffer=nl.shared_hbm)
        lz2 = nl.ndarray((P, NT), dtype=f32, buffer=nl.shared_hbm)
        i0, i1 = _lh_tile_range(NT)
        n = i1 - i0
        if n > 0:
            zc = nl.ndarray((P, n, NC), dtype=f32, buffer=nl.sbuf)
            sc = nl.ndarray((P, n, NC), dtype=f32, buffer=nl.sbuf)
            tgl = nl.ndarray((P, K, n), dtype=nl.uint32, buffer=nl.sbuf)
            xtb = nl.ndarray((P, K, NC, n), dtype=x3.dtype, buffer=nl.sbuf)
            for k in range(K):
                nisa.dma_copy(dst=tgl[:, k, :], src=tl3[k, :, i0:i1])
            xbs = _lh_pair((P, _LH_VCHUNK), x3.dtype)
            ts = _lh_pair((P, _LH_VCHUNK), f32)
            es = _lh_pair((P, _LH_VCHUNK), f32)
            steps = n * NC
            nisa.dma_copy(dst=xbs[0], src=x3[:, i0, 0:_LH_VCHUNK])
            for s in range(steps):
                j = s // NC
                c = s % NC
                xb, t, e = xbs[s % _LH_NBUF], ts[s % _LH_NBUF], es[s % _LH_NBUF]
                sn = s + 1
                if sn < steps:
                    jn = sn // NC
                    cn = sn % NC
                    nisa.dma_copy(dst=xbs[sn % _LH_NBUF], src=x3[:, i0 + jn, cn * _LH_VCHUNK:(cn + 1) * _LH_VCHUNK])
                nisa.activation_reduce(dst=t, op=nl.tanh, data=xb, reduce_op=nl.add, reduce_res=sc[:, j, c:c + 1],
                                       scale=1.0 / softcap)
                nisa.activation_reduce(dst=e, op=nl.exp, data=t, reduce_op=nl.add, reduce_res=zc[:, j, c:c + 1],
                                       scale=softcap, bias=-softcap)
                for k in range(K):
                    nisa.nc_n_gather(dst=xtb[:, k, c, j:j + 1], data=xb, indices=tgl[:, k, j:j + 1])
            zb = nl.ndarray((P, n), dtype=f32, buffer=nl.sbuf)
            nisa.tensor_reduce(dst=zb, op=nl.add, data=zc, axis=2)
            lzb = nl.ndarray((P, n), dtype=f32, buffer=nl.sbuf)
            nisa.activation(dst=lzb, op=nl.log, data=zb)
            nisa.dma_copy(dst=lz2[:, i0:i1], src=lzb)
            lzc = nl.ndarray((P, n), dtype=f32, buffer=nl.sbuf)
            nisa.tensor_scalar(dst=lzc, data=lzb, op0=nl.add, operand0=softcap)
            sb = nl.ndarray((P, n), dtype=f32, buffer=nl.sbuf)
            nisa.tensor_reduce(dst=sb, op=nl.add, data=sc, axis=2)
            lzs = nl.ndarray((P, n), dtype=f32, buffer=nl.sbuf)
            nisa.scalar_tensor_tensor(dst=lzs, data=sb, op0=nl.multiply, operand0=mean_coef, op1=nl.add, operand1=lzc)
            rwb = nl.ndarray((P, n), dtype=f32, buffer=nl.sbuf)
            tb = nl.ndarray((P, n), dtype=f32, buffer=nl.sbuf)
            nll = nl.ndarray((P, n), dtype=f32, buffer=nl.sbuf)
            acc = nl.ndarray((P, n), dtype=f32, buffer=nl.sbuf)
            for k in range(K):
                for c in range(NC):
                    nisa.dma_copy(dst=rwb, src=rwc4[k, c, :, i0:i1])
                    nisa.activation(dst=tb, op=nl.tanh, data=xtb[:, k, c, :], scale=1.0 / softcap)
                    nisa.scalar_tensor_tensor(dst=nll, data=tb, op0=nl.multiply, operand0=tgt_coef, op1=nl.add, operand1=lzs)
                    if k == 0 and c == 0:
                        nisa.tensor_tensor(dst=acc, data1=nll, data2=rwb, op=nl.multiply, engine=_LH_VEC)
                    else:
                        nisa.tensor_tensor(dst=nll, data1=nll, data2=rwb, op=nl.multiply, engine=_LH_VEC)
                        nisa.tensor_tensor(dst=acc, data1=acc, data2=nll, op=nl.add, engine=_LH_VEC)
            nisa.dma_copy(dst=loss2[:, i0:i1], src=acc)
        return loss2, lz2

    # Switch 26, backward, for K = 1 (chunked_loss_mean's layout): the row scale ab = (1 - eps) g w (keep =
    # 1 - eps), the exponential's bias -lse - log(keep) (nb_add = -softcap - log(keep)), so q = softmax / keep,
    # then q += q_add (q_add = -eps / (V keep)), one VectorEngine pass per chunk; then switch 8's two steps:
    # d = (ab t^2 - ab) (onehot - q) = g w (1 - t^2) (softmax - (1 - eps) onehot - eps / V). No new tile (the
    # backward's SBUF is about 192 of 224 KiB a partition); the constants come from the op.
    @nki.jit
    def _lh_bwd_ls_kernel(x3, tg3, rwc4, lz2, g2, softcap, keep, nb_add, q_add):
        P, NT, V = x3.shape
        K = tg3.shape[0]
        NC = V // _LH_VCHUNK
        f32 = nl.float32
        d3 = nl.ndarray((P, NT, V), dtype=x3.dtype, buffer=nl.shared_hbm)
        i0, i1 = _lh_tile_range(NT)
        n = i1 - i0
        if n > 0:
            tgs = nl.ndarray((P, K, NC, n), dtype=f32, buffer=nl.sbuf)
            rwb = nl.ndarray((P, K, n), dtype=f32, buffer=nl.sbuf)
            tmp = nl.ndarray((P, n), dtype=f32, buffer=nl.sbuf)
            for k in range(K):
                nisa.dma_copy(dst=tgs[:, k, 0, :], src=tg3[k, :, i0:i1])
                for c in range(1, NC):
                    nisa.tensor_scalar(dst=tgs[:, k, c, :], data=tgs[:, k, 0, :], op0=nl.add, operand0=-float(c * _LH_VCHUNK))
                nisa.dma_copy(dst=rwb[:, k, :], src=rwc4[k, 0, :, i0:i1])
                for c in range(1, NC):
                    nisa.dma_copy(dst=tmp, src=rwc4[k, c, :, i0:i1])
                    nisa.tensor_tensor(dst=rwb[:, k, :], data1=rwb[:, k, :], data2=tmp, op=nl.add, engine=_LH_VEC)
            nb = nl.ndarray((P, n), dtype=f32, buffer=nl.sbuf)
            nisa.dma_copy(dst=nb, src=lz2[:, i0:i1])
            ab = nl.ndarray((P, n), dtype=f32, buffer=nl.sbuf)
            nisa.dma_copy(dst=ab, src=g2[:, i0:i1])
            nisa.tensor_tensor(dst=ab, data1=ab, data2=rwb[:, 0, :], op=nl.multiply, engine=_LH_VEC)
            nisa.tensor_scalar(dst=ab, data=ab, op0=nl.multiply, operand0=keep)
            sq = nl.ndarray((P, n), dtype=f32, buffer=nl.sbuf)
            nisa.activation(dst=sq, op=nl.sqrt, data=ab)
            nisa.tensor_scalar(dst=nb, data=nb, op0=nl.multiply, operand0=-1.0, op1=nl.add, operand1=nb_add)
            io = nl.ndarray((P, _LH_VCHUNK), dtype=f32, buffer=nl.sbuf)
            nisa.iota(dst=io, pattern=[[1, _LH_VCHUNK]], offset=0, channel_multiplier=0)
            xbs = _lh_pair((P, _LH_VCHUNK), x3.dtype)
            ts = _lh_pair((P, _LH_VCHUNK), f32)
            qs = _lh_pair((P, _LH_VCHUNK), f32)
            steps = n * NC
            nisa.dma_copy(dst=xbs[0], src=x3[:, i0, 0:_LH_VCHUNK])
            for s in range(steps):
                j = s // NC
                c = s % NC
                i = i0 + j
                xb, t, q = xbs[s % _LH_NBUF], ts[s % _LH_NBUF], qs[s % _LH_NBUF]
                sn = s + 1
                if sn < steps:
                    jn = sn // NC
                    cn = sn % NC
                    nisa.dma_copy(dst=xbs[sn % _LH_NBUF], src=x3[:, i0 + jn, cn * _LH_VCHUNK:(cn + 1) * _LH_VCHUNK])
                nisa.activation(dst=t, op=nl.tanh, data=xb, scale=1.0 / softcap)
                nisa.activation(dst=q, op=nl.exp, data=t, scale=softcap, bias=nb[:, j:j + 1])
                nisa.tensor_scalar(dst=q, data=q, op0=nl.add, operand0=q_add, engine=_LH_VEC)
                nisa.scalar_tensor_tensor(dst=q, data=io, op0=nl.equal, operand0=tgs[:, 0, c, j:j + 1],
                                          op1=nl.subtract, operand1=q)
                nisa.activation(dst=t, op=nl.square, data=t, scale=sq[:, j:j + 1])
                nisa.scalar_tensor_tensor(dst=xb, data=t, op0=nl.subtract, operand0=ab[:, j:j + 1],
                                          op1=nl.multiply, operand1=q)
                nisa.dma_copy(dst=d3[:, i, c * _LH_VCHUNK:(c + 1) * _LH_VCHUNK], src=xb)
        return d3
    # ---- begin OS1A2 kernels (lane OS1A2, work/p2/os1a2/NOTES.md) ----
    # R2_OS1_FUSED: switch 59's readout inside switch 8's loss head pair, at a vocabulary chunk of _OS1_VCHUNK
    # (4,096) entries. x3 is lin, the folded head GEMM's output [x | u] [W | glin C / a0]^T (the readout's linear
    # term inside it), in the [128, rows / 128, V] layout; xu3 the GEMM's input [x | u] in the same layout (u its
    # last D columns, from col0); ct2 the codebook C / a0 transposed, [D, V] bf16; cg2 the read's scale c G_t per
    # row (c = beta / (1 - thr)), FP32 [128, rows / 128]. Per 128-row tile and chunk: s = u C^T on TensorE (one PSUM
    # bank a 512 columns), r = relu(s - thr) out of PSUM and head = r cg + lin on VectorE in FP32 (os1_bias's order;
    # two instruction forms switch 8's pair and the fused MLP run on the chip), then switch 8's softcap and
    # log-sum-exp on the head. The backward recomputes the head with the same instructions; the read is a
    # stop-gradient term, so its output d3 is d(lin), and the head GEMM's backward gives d(x) and d(u) in one product.
    def _os1_code_tiles(ct2):
        D, V = ct2.shape
        NC = V // _OS1_VCHUNK
        ct = nl.ndarray((D, V), dtype=ct2.dtype, buffer=nl.sbuf)
        for c in range(NC):
            v0 = c * _OS1_VCHUNK
            v1 = v0 + _OS1_VCHUNK
            nisa.dma_copy(dst=ct[:, v0:v1], src=ct2[:, v0:v1])
        return ct

    def _os1_u_tiles(xu3, i0, n, col0, D):
        P = xu3.shape[0]
        c1 = col0 + D
        ut = nl.ndarray((D, n, P), dtype=xu3.dtype, buffer=nl.sbuf)
        for j in range(n):
            i = i0 + j
            ub = nl.ndarray((P, D), dtype=xu3.dtype, buffer=nl.sbuf)
            nisa.dma_copy(dst=ub, src=xu3[:, i, col0:c1])
            pt = nl.ndarray((D, P), dtype=xu3.dtype, buffer=nl.psum)
            nisa.nc_transpose(dst=pt, data=ub)
            nisa.tensor_copy(dst=ut[:, j, :], src=pt, engine=_LH_VEC)
        return ut

    def _os1_gate(cg2, i0, i1):
        P = cg2.shape[0]
        n = i1 - i0
        cgb = nl.ndarray((P, n), dtype=nl.float32, buffer=nl.sbuf)
        nisa.dma_copy(dst=cgb, src=cg2[:, i0:i1])
        return cgb

    def _os1_read(hd, rr, xb, ut, ct, cgb, thr, j, c):
        P = hd.shape[0]
        NM = _OS1_VCHUNK // _OS1_MM
        j1 = j + 1
        cgj = cgb[:, j:j1]
        base = c * _OS1_VCHUNK
        for m in range(NM):
            q0 = m * _OS1_MM
            q1 = q0 + _OS1_MM
            v0 = base + q0
            v1 = v0 + _OS1_MM
            ps = nl.ndarray((P, _OS1_MM), dtype=nl.float32, buffer=nl.psum)
            nisa.nc_matmul(dst=ps, stationary=ut[:, j, :], moving=ct[:, v0:v1], accumulate=False)
            nisa.tensor_scalar(dst=rr[:, q0:q1], data=ps, op0=nl.subtract, operand0=thr, op1=nl.maximum,
                               operand1=0.0, engine=_LH_VEC)
        nisa.scalar_tensor_tensor(dst=hd, data=rr, op0=nl.multiply, operand0=cgj, op1=nl.add, operand1=xb)

    @nki.jit
    def _lh_os1_fwd_kernel(x3, tl3, rwc4, xu3, ct2, cg2, softcap, thr, col0):
        P, NT, V = x3.shape
        K = tl3.shape[0]
        D = ct2.shape[0]
        NC = V // _OS1_VCHUNK
        f32 = nl.float32
        loss2 = nl.ndarray((P, NT), dtype=f32, buffer=nl.shared_hbm)
        lz2 = nl.ndarray((P, NT), dtype=f32, buffer=nl.shared_hbm)
        i0, i1 = _lh_tile_range(NT)
        n = i1 - i0
        if n > 0:
            ct = _os1_code_tiles(ct2)
            ut = _os1_u_tiles(xu3, i0, n, col0, D)
            cgb = _os1_gate(cg2, i0, i1)
            zc = nl.ndarray((P, n, NC), dtype=f32, buffer=nl.sbuf)
            tgl = nl.ndarray((P, K, n), dtype=nl.uint32, buffer=nl.sbuf)
            xtb = nl.ndarray((P, K, NC, n), dtype=f32, buffer=nl.sbuf)
            for k in range(K):
                nisa.dma_copy(dst=tgl[:, k, :], src=tl3[k, :, i0:i1])
            xbs = _lh_pair((P, _OS1_VCHUNK), x3.dtype)
            hds = _lh_pair((P, _OS1_VCHUNK), f32)
            es = _lh_pair((P, _OS1_VCHUNK), f32)
            steps = n * NC
            x0 = xbs[0]
            nisa.dma_copy(dst=x0, src=x3[:, i0, 0:_OS1_VCHUNK])
            for s in range(steps):
                j = s // NC
                c = s % NC
                b = s % _LH_NBUF
                xb = xbs[b]
                hd = hds[b]
                e = es[b]
                sn = s + 1
                if sn < steps:
                    jn = sn // NC
                    cn = sn % NC
                    bn = sn % _LH_NBUF
                    inx = i0 + jn
                    w0 = cn * _OS1_VCHUNK
                    w1 = w0 + _OS1_VCHUNK
                    xn = xbs[bn]
                    nisa.dma_copy(dst=xn, src=x3[:, inx, w0:w1])
                _os1_read(e, hd, xb, ut, ct, cgb, thr, j, c)
                j1 = j + 1
                c1 = c + 1
                for k in range(K):
                    nisa.nc_n_gather(dst=xtb[:, k, c, j:j1], data=e, indices=tgl[:, k, j:j1])
                nisa.activation(dst=hd, op=nl.tanh, data=e, scale=1.0 / softcap)
                nisa.activation_reduce(dst=hd, op=nl.exp, data=hd, reduce_op=nl.add, reduce_res=zc[:, j, c:c1],
                                       scale=softcap, bias=-softcap)
            zb = nl.ndarray((P, n), dtype=f32, buffer=nl.sbuf)
            nisa.tensor_reduce(dst=zb, op=nl.add, data=zc, axis=2)
            lzb = nl.ndarray((P, n), dtype=f32, buffer=nl.sbuf)
            nisa.activation(dst=lzb, op=nl.log, data=zb)
            nisa.dma_copy(dst=lz2[:, i0:i1], src=lzb)
            lzc = nl.ndarray((P, n), dtype=f32, buffer=nl.sbuf)
            nisa.tensor_scalar(dst=lzc, data=lzb, op0=nl.add, operand0=softcap)
            rwb = nl.ndarray((P, n), dtype=f32, buffer=nl.sbuf)
            tb = nl.ndarray((P, n), dtype=f32, buffer=nl.sbuf)
            nll = nl.ndarray((P, n), dtype=f32, buffer=nl.sbuf)
            acc = nl.ndarray((P, n), dtype=f32, buffer=nl.sbuf)
            for k in range(K):
                for c in range(NC):
                    nisa.dma_copy(dst=rwb, src=rwc4[k, c, :, i0:i1])
                    nisa.activation(dst=tb, op=nl.tanh, data=xtb[:, k, c, :], scale=1.0 / softcap)
                    nisa.scalar_tensor_tensor(dst=nll, data=tb, op0=nl.multiply, operand0=-softcap, op1=nl.add,
                                              operand1=lzc)
                    if k == 0 and c == 0:
                        nisa.tensor_tensor(dst=acc, data1=nll, data2=rwb, op=nl.multiply, engine=_LH_VEC)
                    else:
                        nisa.tensor_tensor(dst=nll, data1=nll, data2=rwb, op=nl.multiply, engine=_LH_VEC)
                        nisa.tensor_tensor(dst=acc, data1=acc, data2=nll, op=nl.add, engine=_LH_VEC)
            nisa.dma_copy(dst=loss2[:, i0:i1], src=acc)
        return loss2, lz2

    @nki.jit
    def _lh_os1_bwd_kernel(x3, tg3, rwc4, lz2, g2, xu3, ct2, cg2, softcap, thr, col0):
        P, NT, V = x3.shape
        K = tg3.shape[0]
        D = ct2.shape[0]
        NC = V // _OS1_VCHUNK
        f32 = nl.float32
        d3 = nl.ndarray((P, NT, V), dtype=x3.dtype, buffer=nl.shared_hbm)
        i0, i1 = _lh_tile_range(NT)
        n = i1 - i0
        if n > 0:
            ct = _os1_code_tiles(ct2)
            ut = _os1_u_tiles(xu3, i0, n, col0, D)
            cgb = _os1_gate(cg2, i0, i1)
            tgs = nl.ndarray((P, K, NC, n), dtype=f32, buffer=nl.sbuf)
            rwb = nl.ndarray((P, K, n), dtype=f32, buffer=nl.sbuf)
            tmp = nl.ndarray((P, n), dtype=f32, buffer=nl.sbuf)
            for k in range(K):
                nisa.dma_copy(dst=tgs[:, k, 0, :], src=tg3[k, :, i0:i1])
                for c in range(1, NC):
                    off = -float(c * _OS1_VCHUNK)
                    nisa.tensor_scalar(dst=tgs[:, k, c, :], data=tgs[:, k, 0, :], op0=nl.add, operand0=off)
                nisa.dma_copy(dst=rwb[:, k, :], src=rwc4[k, 0, :, i0:i1])
                for c in range(1, NC):
                    nisa.dma_copy(dst=tmp, src=rwc4[k, c, :, i0:i1])
                    nisa.tensor_tensor(dst=rwb[:, k, :], data1=rwb[:, k, :], data2=tmp, op=nl.add, engine=_LH_VEC)
            nb = nl.ndarray((P, n), dtype=f32, buffer=nl.sbuf)
            nisa.dma_copy(dst=nb, src=lz2[:, i0:i1])
            ab = nl.ndarray((P, n), dtype=f32, buffer=nl.sbuf)
            nisa.dma_copy(dst=ab, src=g2[:, i0:i1])
            nisa.tensor_tensor(dst=ab, data1=ab, data2=rwb[:, 0, :], op=nl.multiply, engine=_LH_VEC)
            sq = nl.ndarray((P, n), dtype=f32, buffer=nl.sbuf)
            nisa.activation(dst=sq, op=nl.sqrt, data=ab)
            nisa.tensor_scalar(dst=nb, data=nb, op0=nl.multiply, operand0=-1.0, op1=nl.add, operand1=-softcap)
            if K > 1:
                nisa.reciprocal(dst=rwb[:, 0, :], data=rwb[:, 0, :])
                for k in range(1, K):
                    nisa.tensor_tensor(dst=rwb[:, k, :], data1=rwb[:, k, :], data2=rwb[:, 0, :], op=nl.multiply,
                                       engine=_LH_VEC)
                wb = nl.ndarray((P, n), dtype=f32, buffer=nl.sbuf)
                nisa.tensor_scalar(dst=wb, data=rwb[:, 1, :], op0=nl.add, operand0=1.0)
                for k in range(2, K):
                    nisa.tensor_tensor(dst=wb, data1=wb, data2=rwb[:, k, :], op=nl.add, engine=_LH_VEC)
                nisa.activation(dst=wb, op=nl.log, data=wb)
                nisa.tensor_tensor(dst=nb, data1=nb, data2=wb, op=nl.add, engine=_LH_VEC)
            io = nl.ndarray((P, _OS1_VCHUNK), dtype=f32, buffer=nl.sbuf)
            nisa.iota(dst=io, pattern=[[1, _OS1_VCHUNK]], offset=0, channel_multiplier=0)
            xbs = _lh_pair((P, _OS1_VCHUNK), x3.dtype)
            ts = _lh_pair((P, _OS1_VCHUNK), f32)
            qs = _lh_pair((P, _OS1_VCHUNK), f32)
            steps = n * NC
            x0 = xbs[0]
            nisa.dma_copy(dst=x0, src=x3[:, i0, 0:_OS1_VCHUNK])
            for s in range(steps):
                j = s // NC
                c = s % NC
                i = i0 + j
                b = s % _LH_NBUF
                xb = xbs[b]
                t = ts[b]
                q = qs[b]
                sn = s + 1
                if sn < steps:
                    jn = sn // NC
                    cn = sn % NC
                    bn = sn % _LH_NBUF
                    inx = i0 + jn
                    w0 = cn * _OS1_VCHUNK
                    w1 = w0 + _OS1_VCHUNK
                    xn = xbs[bn]
                    nisa.dma_copy(dst=xn, src=x3[:, inx, w0:w1])
                _os1_read(q, t, xb, ut, ct, cgb, thr, j, c)
                j1 = j + 1
                nisa.activation(dst=t, op=nl.tanh, data=q, scale=1.0 / softcap)
                nisa.activation(dst=q, op=nl.exp, data=t, scale=softcap, bias=nb[:, j:j1])
                nisa.scalar_tensor_tensor(dst=q, data=io, op0=nl.equal, operand0=tgs[:, 0, c, j:j1],
                                          op1=nl.subtract, operand1=q)
                for k in range(1, K):
                    nisa.tensor_scalar(dst=xb, data=io, op0=nl.equal, operand0=tgs[:, k, c, j:j1])
                    nisa.scalar_tensor_tensor(dst=q, data=xb, op0=nl.multiply, operand0=rwb[:, k, j:j1],
                                              op1=nl.add, operand1=q)
                nisa.activation(dst=t, op=nl.square, data=t, scale=sq[:, j:j1])
                nisa.scalar_tensor_tensor(dst=xb, data=t, op0=nl.subtract, operand0=ab[:, j:j1],
                                          op1=nl.multiply, operand1=q)
                w0 = c * _OS1_VCHUNK
                w1 = w0 + _OS1_VCHUNK
                nisa.dma_copy(dst=d3[:, i, w0:w1], src=xb)
        return d3
    # ---- end OS1A2 kernels ----
    S2B_HAS_NKI = True
    S2B_NKI_ERROR = ""
except Exception as exc:  # as the kit's own NKI import: switches 8 to 10 then take their torch routes off the device
    S2B_HAS_NKI = False
    S2B_NKI_ERROR = f"{type(exc).__name__}: {exc}"

# Switch 9's fixed scales (powers of two; proofs/calib_fp8.py read them off the S1 rehearsal's final weights, and its
# activations and gradients on training sequences, H7_s1_full: the end of a full-length run).
FP8_H_SCALE = 1.0 / 128        # row 2's h = relu(pre)^2, e4m3, non-negative, for a model shape without a table below:
                               # saturates at 30,720 (S1's largest h, layer 3's: 10,328)
# Row 2's h scale per layer for the calibrated shape (depth, width): the largest power of two leaving at least 2x
# headroom over the layer's largest h on 80 training sequences (Phase 1's h margin, per tensor), and 4x where that
# largest h is a tail value, at least 1.5x the median sequence's (layers 5 to 19: such maxima keep growing with
# the sequences read); proofs/calib_fp8.py. One scale for every layer (1/128, set by layers 1 to 4's large
# activations) leaves the other layers' h far below e4m3's normal range.
FP8_H_SCALES = {
    (22, 1408): tuple(2.0 ** e for e in (-2, -5, -6, -7, -5, -2, -2, -2, -2, -2, -2, -2, -2, -2, -2, -1, -2, -2,
                                         -2, -2, -2, -3)),
}
FP8_W_SCALE_PROJ = 32.0        # row 2's weight, c_proj, e4m3: S1's largest |w| 1.238 leaves 6.1x headroom under 240
FP8_W_SCALE_FC = 64.0          # row 3's weight, c_fc, e4m3: S1's largest |w| 0.673 leaves 5.6x headroom
FP8_G_SCALE = 2.0 ** 24        # row 3's gradient d(pre), e5m2: S1's largest |g| 1.16e-4 at 1,951 of 57,344 (29x)
FP8_TB = 256                   # tokens per transposed operand block (the planned form of rows 2 and 3)
FP8_GROUP = 2                  # output chunks per stationary pass
FP8_EVAC = 2                   # PSUM evacuated on VectorE (candidate 33's setting)
FP8_LOOP = 0                   # token-tile loop unrolled
FP8_E4M3, FP8_E5M2 = 0, 1
FP8_E4M3_MAX, FP8_E5M2_MAX = 240.0, 57344.0   # this chip's e4m3 is the legacy format: largest finite value 240


def fp8_clip_bound(scale: float, fmt: int = 0) -> float:
    """The clamp bound in the unscaled bf16 domain: the largest bf16 value b with b * scale within the format's
    largest finite value (nki_gemm_fp8_nn.clip_bound)."""
    hi = FP8_E5M2_MAX if fmt == 1 else FP8_E4M3_MAX
    b = torch.tensor(hi / scale, dtype=torch.float32).to(torch.bfloat16)
    for _ in range(4):
        if float(b) * scale <= hi:
            break
        b = torch.nextafter(b, torch.tensor(0.0, dtype=torch.bfloat16))
    return float(b)


FP8_H_BOUND = fp8_clip_bound(FP8_H_SCALE, FP8_E4M3)            # 30,720: where h saturates at the default scale
FP8_H_BOUNDS = {s: fp8_clip_bound(s, FP8_E4M3) for s in {FP8_H_SCALE, *(v for r in FP8_H_SCALES.values() for v in r)}}
FP8_G_BOUND = fp8_clip_bound(FP8_G_SCALE, FP8_E5M2)
FP8_W_PROJ_BOUND = fp8_clip_bound(FP8_W_SCALE_PROJ, FP8_E4M3)
FP8_W_FC_BOUND = fp8_clip_bound(FP8_W_SCALE_FC, FP8_E4M3)


def fp8_h_scale(layer: int, n_layer: int, n_embd: int) -> float:
    """Switch 9: row 2's h scale for one layer: the calibrated table's for its model shape, FP8_H_SCALE otherwise."""
    table = FP8_H_SCALES.get((n_layer, n_embd))
    return table[layer] if table is not None else FP8_H_SCALE


def fp8_h_scales_line(n_layer: int, n_embd: int) -> str:
    """Switch 9: the log line naming the h scales in force."""
    if (n_layer, n_embd) in FP8_H_SCALES:
        return (f"per layer (calibrated for depth {n_layer}, width {n_embd}): "
                + " ".join(f"1/{round(1 / s)}" if s < 1 else f"{s:g}" for s in FP8_H_SCALES[(n_layer, n_embd)]))
    return f"1/{round(1 / FP8_H_SCALE)} in every layer (no table for depth {n_layer}, width {n_embd})"


# Switch 10: the compact vocabulary of one optimizer step's tokens on one rank (W2 F19: 4,071 distinct of 16,384 on
# average, 4,722 at most in 394 windows).
LE_COMPACT_V = 8192

# Set by setup_s2b_kernels().
S2B_READY = False
S2B_OPS: dict = {}
S2B_COUNTS = {"loss_head_fwd": 0, "loss_head_bwd": 0, "fp8_row2": 0, "fp8_row3": 0, "fp8_quant": 0,
              "lean_embed_bwd": 0, "lean_host_steps": 0}


def setup_s2b_kernels(device: torch.device) -> str:
    """Switches 8 to 10: register the kernels as custom ops the way switch 7 registers the attention kernel
    (R2_CUSTOMOP_FORM), with fake implementations for their shapes, outside any trace and once per process. On a
    Neuron device they are required. Returns a status line for the log."""
    global S2B_READY
    if not (R2_LOSS_HEAD_KERNEL or R2_FP8_ROWS or R2_LEAN_EMBED):
        return "off"
    if S2B_READY:
        return "on (registered earlier in this process)"
    if not S2B_HAS_NKI:
        if device.type == "neuron":
            raise RuntimeError(f"switches 8 to 10 need nki on a Neuron device ({S2B_NKI_ERROR})")
        return (f"unavailable (nki: {S2B_NKI_ERROR}): the kit's loss chain, the fp8 rows' torch emulation and the "
                "lean lookup's torch contraction")
    if R2_ROUTE != "compiled_customop" or R2_CUSTOMOP_FORM not in ("nki_op", "torch_library"):
        raise ValueError("switches 8 to 10 run on the compiled custom-op route, form nki_op or torch_library")
    if R2_CUSTOMOP_FORM == "nki_op":
        from torch_neuronx import nki_op as make_op
    else:
        make_op = torch.library.custom_op
    lh_fwd = _lh_fwd_kernel[2]
    lh_bwd = _lh_bwd_kernel[2]
    f8_mm = _f8_mm_kernel[2]
    f8_quant = _f8_quant_w_kernel[2]
    eb_bwd = _eb_bwd_kernel[2]

    @make_op("s2b::loss_head_fwd", mutates_args=())
    def loss_head_fwd(x3: torch.Tensor, tl3: torch.Tensor, rwc4: torch.Tensor,
                      softcap: float) -> tuple[torch.Tensor, torch.Tensor]:
        S2B_COUNTS["loss_head_fwd"] += 1
        loss2, lz2 = lh_fwd(x3, tl3, rwc4, softcap)
        return loss2, lz2

    @make_op("s2b::loss_head_bwd", mutates_args=())
    def loss_head_bwd(x3: torch.Tensor, tg3: torch.Tensor, rwc4: torch.Tensor, lz2: torch.Tensor,
                      g2: torch.Tensor, softcap: float) -> torch.Tensor:
        S2B_COUNTS["loss_head_bwd"] += 1
        return lh_bwd(x3, tg3, rwc4, lz2, g2, softcap)

    @make_op("s2b::fp8_row2", mutates_args=())
    def fp8_row2(h: torch.Tensor, wq: torch.Tensor, h_scale: float) -> torch.Tensor:
        S2B_COUNTS["fp8_row2"] += 1
        bound = FP8_H_BOUNDS[h_scale]
        return f8_mm(h, wq, 3, FP8_TB, FP8_GROUP, FP8_EVAC, 1, FP8_LOOP, FP8_E4M3, float(h_scale),
                     float(bound), float(bound * h_scale), float(1.0 / (h_scale * FP8_W_SCALE_PROJ)))

    @make_op("s2b::fp8_row3", mutates_args=())
    def fp8_row3(dpre: torch.Tensor, wq: torch.Tensor) -> torch.Tensor:
        S2B_COUNTS["fp8_row3"] += 1
        return f8_mm(dpre, wq, 3, FP8_TB, FP8_GROUP, FP8_EVAC, 0, FP8_LOOP, FP8_E5M2, float(FP8_G_SCALE),
                     float(FP8_G_BOUND), float(FP8_G_BOUND * FP8_G_SCALE), float(1.0 / (FP8_G_SCALE * FP8_W_SCALE_FC)))

    @make_op("s2b::fp8_quant_proj", mutates_args=())
    def fp8_quant_proj(w: torch.Tensor) -> torch.Tensor:
        S2B_COUNTS["fp8_quant"] += 1
        return f8_quant(w, float(FP8_W_SCALE_PROJ), 1, float(FP8_W_PROJ_BOUND))

    @make_op("s2b::fp8_quant_fc", mutates_args=())
    def fp8_quant_fc(w: torch.Tensor) -> torch.Tensor:
        S2B_COUNTS["fp8_quant"] += 1
        return f8_quant(w, float(FP8_W_SCALE_FC), 1, float(FP8_W_FC_BOUND))

    @make_op("s2b::lean_embed_bwd", mutates_args=())
    def lean_embed_bwd(cid2: torch.Tensor, dy3: torch.Tensor) -> torch.Tensor:
        S2B_COUNTS["lean_embed_bwd"] += 1
        return eb_bwd(cid2, dy3, LE_COMPACT_V)

    # The fake implementations are the kernels' own output allocations.
    fakes = {
        "s2b::loss_head_fwd": lambda x3, tl3, rwc4, softcap: (
            x3.new_empty((x3.shape[0], x3.shape[1]), dtype=torch.float32),
            x3.new_empty((x3.shape[0], x3.shape[1]), dtype=torch.float32)),
        "s2b::loss_head_bwd": lambda x3, tg3, rwc4, lz2, g2, softcap: torch.empty_like(x3),
        "s2b::fp8_row2": lambda h, wq, h_scale: h.new_empty((h.shape[0], wq.shape[1])),
        "s2b::fp8_row3": lambda dpre, wq: dpre.new_empty((dpre.shape[0], wq.shape[1])),
        "s2b::fp8_quant_proj": lambda w: w.new_empty(w.shape, dtype=torch.uint8),
        "s2b::fp8_quant_fc": lambda w: w.new_empty(w.shape, dtype=torch.uint8),
        "s2b::lean_embed_bwd": lambda cid2, dy3: dy3.new_empty((LE_COMPACT_V, dy3.shape[-1]), dtype=torch.float32),
    }
    kept = []
    for name, fake in fakes.items():
        try:
            torch.library.register_fake(name)(fake)
        except RuntimeError:
            kept.append(name)
    S2B_OPS.update(lh_fwd=loss_head_fwd, lh_bwd=loss_head_bwd, fp8_row2=fp8_row2, fp8_row3=fp8_row3,
                   fp8_quant_proj=fp8_quant_proj, fp8_quant_fc=fp8_quant_fc, lean_embed_bwd=lean_embed_bwd)
    if R2_LEAN_EMBED_1536 and R2_LEAN_EMBED:
        # T1: the embedding backward at a width the 352-column kernel does not tile (1,536), one launch as above.
        eb_bwd_w = _eb_bwd_w_kernel[2]

        @make_op("s2b::lean_embed_bwd_w", mutates_args=())
        def lean_embed_bwd_w(cid2: torch.Tensor, dy3: torch.Tensor) -> torch.Tensor:
            S2B_COUNTS["lean_embed_bwd"] += 1
            return eb_bwd_w(cid2, dy3, LE_COMPACT_V, lean_moving_width(dy3.shape[-1]))

        try:
            torch.library.register_fake("s2b::lean_embed_bwd_w")(
                lambda cid2, dy3: dy3.new_empty((LE_COMPACT_V, dy3.shape[-1]), dtype=torch.float32))
        except RuntimeError:
            kept.append("s2b::lean_embed_bwd_w")
        S2B_OPS["lean_embed_bwd_w"] = lean_embed_bwd_w
    if R2_LABEL_SMOOTH > 0.0 and R2_LOSS_HEAD_KERNEL:
        # Switch 26: the label-smoothed loss head pair, registered as switch 8's pair is; each op computes its
        # kernel's constants from softcap, eps and the vocabulary width in Python (no log or division inside the
        # kernels). They count under their own keys, which s2b_summary() prints only when they exist.
        lh_ls_fwd = _lh_fwd_ls_kernel[2]
        lh_ls_bwd = _lh_bwd_ls_kernel[2]
        S2B_COUNTS.setdefault("loss_head_ls_fwd", 0)
        S2B_COUNTS.setdefault("loss_head_ls_bwd", 0)

        @make_op("s2b::loss_head_ls_fwd", mutates_args=())
        def loss_head_ls_fwd(x3: torch.Tensor, tl3: torch.Tensor, rwc4: torch.Tensor, softcap: float,
                             eps: float) -> tuple[torch.Tensor, torch.Tensor]:
            S2B_COUNTS["loss_head_ls_fwd"] += 1
            v = int(x3.shape[2])
            loss2, lz2 = lh_ls_fwd(x3, tl3, rwc4, softcap, float(-(1.0 - eps) * softcap), float(-eps * softcap / v))
            return loss2, lz2

        @make_op("s2b::loss_head_ls_bwd", mutates_args=())
        def loss_head_ls_bwd(x3: torch.Tensor, tg3: torch.Tensor, rwc4: torch.Tensor, lz2: torch.Tensor,
                             g2: torch.Tensor, softcap: float, eps: float) -> torch.Tensor:
            S2B_COUNTS["loss_head_ls_bwd"] += 1
            keep = 1.0 - eps
            return lh_ls_bwd(x3, tg3, rwc4, lz2, g2, softcap, float(keep), float(-softcap - math.log(keep)),
                             float(-eps / (int(x3.shape[2]) * keep)))

        ls_fakes = {
            "s2b::loss_head_ls_fwd": lambda x3, tl3, rwc4, softcap, eps: (
                x3.new_empty((x3.shape[0], x3.shape[1]), dtype=torch.float32),
                x3.new_empty((x3.shape[0], x3.shape[1]), dtype=torch.float32)),
            "s2b::loss_head_ls_bwd": lambda x3, tg3, rwc4, lz2, g2, softcap, eps: torch.empty_like(x3),
        }
        for name, fake in ls_fakes.items():
            try:
                torch.library.register_fake(name)(fake)
            except RuntimeError:
                kept.append(name)
        S2B_OPS.update(lh_ls_fwd=loss_head_ls_fwd, lh_ls_bwd=loss_head_ls_bwd)
    if R2_OS1_FUSED and R2_LOSS_HEAD_KERNEL:
        # Lane OS1A2: switch 59's readout inside switch 8's pair, registered as switch 8's pair is; the column where u
        # starts in the GEMM's input rows (n_embd) is the rows' width less the codebook's, computed in the op body.
        # They count under their own keys, which s2b_summary() prints only when they exist.
        lh_os1_fwd = _lh_os1_fwd_kernel[2]
        lh_os1_bwd = _lh_os1_bwd_kernel[2]
        S2B_COUNTS.setdefault("loss_head_os1_fwd", 0)
        S2B_COUNTS.setdefault("loss_head_os1_bwd", 0)

        @make_op("s2b::loss_head_os1_fwd", mutates_args=())
        def loss_head_os1_fwd(x3: torch.Tensor, tl3: torch.Tensor, rwc4: torch.Tensor, xu3: torch.Tensor,
                              ct2: torch.Tensor, cg2: torch.Tensor, softcap: float,
                              thr: float) -> tuple[torch.Tensor, torch.Tensor]:
            S2B_COUNTS["loss_head_os1_fwd"] += 1
            col0 = int(xu3.shape[2]) - int(ct2.shape[0])
            loss2, lz2 = lh_os1_fwd(x3, tl3, rwc4, xu3, ct2, cg2, softcap, thr, col0)
            return loss2, lz2

        @make_op("s2b::loss_head_os1_bwd", mutates_args=())
        def loss_head_os1_bwd(x3: torch.Tensor, tg3: torch.Tensor, rwc4: torch.Tensor, lz2: torch.Tensor,
                              g2: torch.Tensor, xu3: torch.Tensor, ct2: torch.Tensor, cg2: torch.Tensor,
                              softcap: float, thr: float) -> torch.Tensor:
            S2B_COUNTS["loss_head_os1_bwd"] += 1
            col0 = int(xu3.shape[2]) - int(ct2.shape[0])
            return lh_os1_bwd(x3, tg3, rwc4, lz2, g2, xu3, ct2, cg2, softcap, thr, col0)

        os1_fakes = {
            "s2b::loss_head_os1_fwd": lambda x3, tl3, rwc4, xu3, ct2, cg2, softcap, thr: (
                torch.empty_like(x3[:, :, 0], dtype=torch.float32, memory_format=torch.contiguous_format),
                torch.empty_like(x3[:, :, 0], dtype=torch.float32, memory_format=torch.contiguous_format)),
            "s2b::loss_head_os1_bwd": lambda x3, tg3, rwc4, lz2, g2, xu3, ct2, cg2, softcap, thr: torch.empty_like(
                x3, memory_format=torch.contiguous_format),
        }
        for name, fake in os1_fakes.items():
            try:
                torch.library.register_fake(name)(fake)
            except RuntimeError:
                kept.append(name)
        S2B_OPS.update(lh_os1_fwd=loss_head_os1_fwd, lh_os1_bwd=loss_head_os1_bwd)
    S2B_READY = True
    return (f"on: custom ops s2b::loss_head_fwd/bwd, fp8_row2/row3, fp8_quant_proj/fc, lean_embed_bwd by "
            f"{R2_CUSTOMOP_FORM}; fake impls ours"
            + (f" except {kept} (the decorator's)" if kept else "")
            + f"; switches loss_head={R2_LOSS_HEAD_KERNEL} fp8_rows={R2_FP8_ROWS} lean_embed={R2_LEAN_EMBED}")


def s2b_kernel_device(device: torch.device) -> bool:
    """Switches 8 to 10: the kernels run on a Neuron device once setup_s2b_kernels() has registered them."""
    return S2B_READY and device.type == "neuron"


def s2b_summary() -> str:
    """Switches 8 to 10: the end-of-run line. The op bodies run when an op executes outside a compiled graph (or is
    traced by the decorator)."""
    if not S2B_READY:
        return "off" if not (R2_LOSS_HEAD_KERNEL or R2_FP8_ROWS or R2_LEAN_EMBED) else "not registered"
    return " ".join(f"{k}={v}" for k, v in S2B_COUNTS.items())


# ---- switch 8: the chunked loss head

def loss_head_applies(x: torch.Tensor, loss_reduction: str, vocab_size: int, padded_vocab: int) -> bool:
    """Switch 8: where the loss head kernel runs: the kernels' device, bf16, the mean reduction (training's), the
    vocabulary unpadded and a multiple of the chunk, and a multiple of 128 rows."""
    return (s2b_kernel_device(x.device) and x.dtype == torch.bfloat16 and loss_reduction == "mean"
            and vocab_size == padded_vocab and vocab_size % _LH_VCHUNK == 0 and (x.size(0) * x.size(1)) % 128 == 0)


class ChunkedLossHead(torch.autograd.Function):
    """Switch 8: the kernel pair over the logits laid out as [128, rows / 128, V] (row n = p * rows / 128 + i on
    partition p, tile i). The backward kernel recomputes d(logits) from the logits and the saved log-sum-exp; it
    needs a non-negative upstream gradient (training's is 1 / grad_accum_steps)."""

    @staticmethod
    def forward(ctx, x3, tg3, tl3, rwc4):
        loss2, lz2 = S2B_OPS["lh_fwd"](x3, tl3, rwc4, LOGIT_SOFTCAP)
        ctx.save_for_backward(x3, tg3, rwc4, lz2)
        return loss2

    @staticmethod
    def backward(ctx, d_loss2):
        x3, tg3, rwc4, lz2 = ctx.saved_tensors
        d3 = S2B_OPS["lh_bwd"](x3, tg3, rwc4, lz2, d_loss2.contiguous(), LOGIT_SOFTCAP)
        return d3, None, None, None


class ChunkedLossHeadLS(torch.autograd.Function):
    """Switch 26: ChunkedLossHead with label smoothing eps = R2_LABEL_SMOOTH, through the ops
    s2b::loss_head_ls_fwd/bwd (kernels _lh_fwd_ls_kernel and _lh_bwd_ls_kernel), on the same layout: each row's
    loss is w (lse - (1 - eps) z_target - eps mean_v z) and its d(logits) g w (1 - t^2) (softmax - (1 - eps) onehot -
    eps / V), t = tanh(logits / softcap); lz2 is the plain log-sum-exp less softcap. The upstream gradient must be
    non-negative, as for ChunkedLossHead."""

    @staticmethod
    def forward(ctx, x3, tg3, tl3, rwc4):
        loss2, lz2 = S2B_OPS["lh_ls_fwd"](x3, tl3, rwc4, LOGIT_SOFTCAP, R2_LABEL_SMOOTH)
        ctx.save_for_backward(x3, tg3, rwc4, lz2)
        return loss2

    @staticmethod
    def backward(ctx, d_loss2):
        x3, tg3, rwc4, lz2 = ctx.saved_tensors
        d3 = S2B_OPS["lh_ls_bwd"](x3, tg3, rwc4, lz2, d_loss2.contiguous(), LOGIT_SOFTCAP, R2_LABEL_SMOOTH)
        return d3, None, None, None


def chunked_loss_mean(logits: torch.Tensor, targets: torch.Tensor, smooth: bool = False,
                      tok_w: torch.Tensor | None = None) -> torch.Tensor:
    """Switch 8: the kit's F.cross_entropy(LOGIT_SOFTCAP * tanh(logits.float() / LOGIT_SOFTCAP), targets,
    ignore_index=-1, reduction="mean") through the kernels. The mean and the ignored targets are row weights:
    1 / (targets not ignored) per row, 0 for an ignored row, split per vocabulary chunk (the chunk that holds the
    row's target carries its weight, the kernel gathers the target's logit with its index inside the chunk)."""
    b, t, v = logits.shape
    n = b * t
    nt = n // 128
    nc = v // _LH_VCHUNK
    y = targets.reshape(n)
    valid = y >= 0
    w = valid.to(torch.float32) / valid.sum().clamp_min(1).to(torch.float32)
    if tok_w is not None:
        # Switch 29: each target's loss weight (R2_QA_ANSWER_WEIGHT where the loader marked it, 1 elsewhere) on its row.
        w = w * tok_w.reshape(n)
    tg = y.clamp(0, v - 1)
    chunk = torch.div(tg, _LH_VCHUNK, rounding_mode="floor")
    rwc = torch.stack([w * (chunk == c).to(torch.float32) for c in range(nc)])
    tl = tg - chunk * _LH_VCHUNK
    if smooth:
        # Switch 26: the label-smoothed pair (eps = R2_LABEL_SMOOTH) on the same layout.
        loss2 = ChunkedLossHeadLS.apply(logits.reshape(128, nt, v), tg.to(torch.int32).view(1, 128, nt),
                                        tl.to(torch.int32).view(1, 128, nt), rwc.view(1, nc, 128, nt))
    else:
        loss2 = ChunkedLossHead.apply(logits.reshape(128, nt, v), tg.to(torch.int32).view(1, 128, nt),
                                      tl.to(torch.int32).view(1, 128, nt), rwc.view(1, nc, 128, nt))
    return loss2.sum()


class Os1FoldHead(torch.autograd.Function):
    """Lane OS1A2 (R2_OS1_FUSED): the head GEMM with switch 59's linear term folded in, lin = xu [w | cw]^T on the
    rows xu = [x | u] (n_embd + D columns), w the head's weight and cw = glin C / a0 in the compute dtype (GPT's
    os1_codeg, a constant). The backward is the GEMM's own: d(xu) = d(lin) [w | cw] (d(x) and d(u) in one product on
    the base's d(head)) and d(w) = d(lin)^T x; cw takes none. The concatenated weight is formed again in the backward,
    not saved."""

    @staticmethod
    def forward(ctx, xu, w, cw):
        ctx.save_for_backward(xu, w, cw)
        return F.linear(xu, torch.cat([w, cw], dim=1))

    @staticmethod
    def backward(ctx, d_lin):
        xu, w, cw = ctx.saved_tensors
        d_xu = d_lin.matmul(torch.cat([w, cw], dim=1))
        d_w = d_lin.t().matmul(xu[:, :w.size(1)])
        return d_xu, d_w, None


class Os1FoldHeadR(torch.autograd.Function):
    """Lane OS1R (THR9's build 1, riders b and c): Os1FoldHead's GEMM, lin = xu [w | cw]^T, with the concatenated
    weight read from wcat (rider b: GPT's os1_wcat, written by fp8_refresh_weights after every optimizer step) when it
    is given, else formed by torch.cat as Os1FoldHead forms it, in the forward and again in the backward; and d(w) =
    d(lin)^T x2 from the head's own input rows x2 [rows, n_embd] (rider c) when given, else from xu[:, :n_embd] as
    Os1FoldHead takes it. The same operands, so the same values as Os1FoldHead; wcat and x2 take no gradient (x's
    gradient flows through xu)."""

    @staticmethod
    def forward(ctx, xu, w, cw, wcat, x2):
        wf = wcat if wcat is not None else torch.cat([w, cw], dim=1)
        ctx.wcat, ctx.x2, ctx.n_embd = wcat is not None, x2 is not None, w.size(1)
        ctx.save_for_backward(wf if ctx.wcat else w, cw, x2 if ctx.x2 else xu)
        return F.linear(xu, wf)

    @staticmethod
    def backward(ctx, d_lin):
        a, cw, xs = ctx.saved_tensors
        wf = a if ctx.wcat else torch.cat([a, cw], dim=1)
        d_xu = d_lin.matmul(wf)
        d_w = d_lin.t().matmul(xs if ctx.x2 else xs[:, :ctx.n_embd])
        return d_xu, d_w, None, None, None


OS1_WCAT_FN = None             # lane OS1R (rider b): the once-per-step weight function; main() compiles it in training


@torch.no_grad()
def os1_wcat_into(w: torch.Tensor, cg: torch.Tensor, out: torch.Tensor) -> None:
    """Lane OS1R (rider b), once per optimizer step: out <- [w | cg] in the compute dtype, in place: the fold's weight
    as os1_fused_loss forms it (w the head's weight, cg = glin C / a0); the graphs read the same tensor every step."""
    out.copy_(torch.cat([w.to(COMPUTE_DTYPE), cg], dim=1))


def set_os1_wcat_fn(fn) -> None:
    """Lane OS1R (rider b): main() hands over the compiled weight function (the model's backend)."""
    global OS1_WCAT_FN
    OS1_WCAT_FN = fn


def os1_wcat_refresh(model: nn.Module) -> None:
    """Lane OS1R (rider b): fp8_refresh_weights' share: GPT's os1_wcat from the head's current weight (compiled in
    training, eager in load_for_eval and off the compile: the same operations on the same values)."""
    fn = OS1_WCAT_FN or os1_wcat_into
    fn(model.lm_head.weight, model.os1_codeg, model.os1_wcat)


class ChunkedLossHeadOS1(torch.autograd.Function):
    """Lane OS1A2 (R2_OS1_FUSED): switch 8's ChunkedLossHead with switch 59's read term inside the kernels
    (s2b::loss_head_os1_fwd/bwd), on the same [128, rows / 128, V] layout at the vocabulary chunk _OS1_VCHUNK: x3 is
    lin (the folded GEMM's output), xu3 the GEMM's input rows, ct2 the codebook C / a0 transposed [D, V] and cg2 the
    read's scale c G_t per row; the backward's d3 is d(lin) (the read is a stop-gradient term: xu3, ct2 and cg2 take
    no gradient). The upstream gradient must be non-negative, as for ChunkedLossHead."""

    @staticmethod
    def forward(ctx, x3, tg3, tl3, rwc4, xu3, ct2, cg2, thr):
        loss2, lz2 = S2B_OPS["lh_os1_fwd"](x3, tl3, rwc4, xu3, ct2, cg2, LOGIT_SOFTCAP, thr)
        ctx.save_for_backward(x3, tg3, rwc4, lz2, xu3, ct2, cg2)
        ctx.thr = thr
        return loss2

    @staticmethod
    def backward(ctx, d_loss2):
        x3, tg3, rwc4, lz2, xu3, ct2, cg2 = ctx.saved_tensors
        d3 = S2B_OPS["lh_os1_bwd"](x3, tg3, rwc4, lz2, d_loss2.contiguous(), xu3, ct2, cg2, LOGIT_SOFTCAP, ctx.thr)
        return d3, None, None, None, None, None, None, None


def chunked_loss_mean_os1(lin: torch.Tensor, targets: torch.Tensor, xu: torch.Tensor, ct2: torch.Tensor,
                          cg: torch.Tensor, thr: float) -> torch.Tensor:
    """Lane OS1A2 (R2_OS1_FUSED): chunked_loss_mean's row weights and target indices at the chunk _OS1_VCHUNK, through
    ChunkedLossHeadOS1: lin [rows, V] (the folded head GEMM's output), xu [rows, n_embd + D] (its input, detached),
    ct2 [D, V], cg [rows] FP32. The kit's mean, over the targets that are not ignored, of the cross-entropy of the
    softcapped lin + cg relu(s - thr), s = u C^T / a0."""
    n, v = lin.shape
    nt = n // 128
    nc = v // _OS1_VCHUNK
    y = targets.reshape(n)
    valid = y >= 0
    w = valid.to(torch.float32) / valid.sum().clamp_min(1).to(torch.float32)
    tg = y.clamp(0, v - 1)
    chunk = torch.div(tg, _OS1_VCHUNK, rounding_mode="floor")
    rwc = torch.stack([w * (chunk == c).to(torch.float32) for c in range(nc)])
    tl = tg - chunk * _OS1_VCHUNK
    loss2 = ChunkedLossHeadOS1.apply(lin.view(128, nt, v), tg.to(torch.int32).view(1, 128, nt),
                                     tl.to(torch.int32).view(1, 128, nt), rwc.view(1, nc, 128, nt),
                                     xu.view(128, nt, xu.size(-1)), ct2, cg.reshape(128, nt), thr)
    return loss2.sum()


def qa_unmark(targets: torch.Tensor, vocab: int):
    """Switch 29: the targets the loader marked (target + vocabulary size) back to targets, and each target's loss
    weight: R2_QA_ANSWER_WEIGHT where marked, 1 elsewhere (an ignored target, -1, is never marked)."""
    marked = targets >= vocab
    weight = torch.ones(targets.shape, dtype=torch.float32, device=targets.device).masked_fill(marked,
                                                                                              R2_QA_ANSWER_WEIGHT)
    return torch.where(marked, targets - vocab, targets), weight


def qa_extra_loss(logits: torch.Tensor, targets: torch.Tensor, weight: torch.Tensor) -> torch.Tensor:
    """Switch 29 off the loss head kernel's route: the sum over the targets of (weight - 1) times their cross-entropy,
    over the count of targets not ignored. The kit's mean loss plus this is the weighted mean; at weight 1 every term
    is an exact zero, so the sum is the kit's loss bit for bit."""
    ce = F.cross_entropy(logits.reshape(-1, logits.size(-1)), targets.reshape(-1), ignore_index=-1, reduction="none")
    count = (targets >= 0).sum().clamp_min(1).to(ce.dtype)
    return ((weight.reshape(-1) - 1.0) * ce).sum() / count


# ---- switch 9: fp8 rows 2 and 3

def fp8_padded(n: int) -> int:
    """Switch 9: the output width the fp8 kernel computes for n columns (the next multiple of 512)."""
    return ((n + _F8_CH - 1) // _F8_CH) * _F8_CH


def fp8_kernel_applies(x2: torch.Tensor, hidden: int) -> bool:
    """Switch 9: where the fp8 kernel runs: the kernels' device, bf16 rows [M, n_embd] with M a multiple of 128 and at
    least 256, the hidden width a multiple of 256 (the kernel's double-row contraction)."""
    m = x2.size(0)
    return (s2b_kernel_device(x2.device) and x2.dtype == torch.bfloat16 and m % 128 == 0 and m >= 256
            and hidden % _F8_KS == 0)


def fp8_round(t: torch.Tensor, scale: float, fmt: int) -> torch.Tensor:
    """Switch 9's torch emulation of the kernels' conversion: from the operand's bf16 value (the kernels read bf16:
    h and d(pre) are bf16 on the chip, and the weights are cast to bf16 before the quantiser), scale, clamp at the
    format's largest finite value, round to the fp8 format, in fp32 (every e4m3 / e5m2 value is exact there)."""
    hi = FP8_E5M2_MAX if fmt == FP8_E5M2 else FP8_E4M3_MAX
    dt = torch.float8_e5m2 if fmt == FP8_E5M2 else torch.float8_e4m3fn
    return (t.to(torch.bfloat16).float() * scale).clamp(-hi, hi).to(dt).float()


def fp8_emulated_mm(a: torch.Tensor, w_kn: torch.Tensor, a_scale: float, a_fmt: int, w_scale: float) -> torch.Tensor:
    """Switch 9 off the kernels' device: a [M, K] @ w_kn [K, N] with both operands rounded as the kernel rounds them,
    accumulated in fp32, descaled, in a's dtype."""
    return ((fp8_round(a, a_scale, a_fmt) @ fp8_round(w_kn, w_scale, FP8_E4M3))
            * (1.0 / (a_scale * w_scale))).to(a.dtype)


def fp8_row2_mm(h: torch.Tensor, wq2: torch.Tensor, w_proj: torch.Tensor, kernel: bool, h_scale: float) -> torch.Tensor:
    """Switch 9, row 2: y = h @ c_proj.weight^T, h e4m3 at the layer's h scale (saturating at 240 / h_scale), the
    weight e4m3."""
    n = w_proj.size(0)
    if kernel:
        return S2B_OPS["fp8_row2"](h.contiguous(), wq2, h_scale)[:, :n]
    return fp8_emulated_mm(h, w_proj.t(), h_scale, FP8_E4M3, FP8_W_SCALE_PROJ)


def fp8_row3_mm(dpre: torch.Tensor, wq3: torch.Tensor, w_fc: torch.Tensor, kernel: bool) -> torch.Tensor:
    """Switch 9, row 3: d(x) = d(pre) @ c_fc.weight, d(pre) e5m2 at FP8_G_SCALE, the weight e4m3."""
    n = w_fc.size(1)
    if kernel:
        return S2B_OPS["fp8_row3"](dpre.contiguous(), wq3)[:, :n]
    return fp8_emulated_mm(dpre, w_fc, FP8_G_SCALE, FP8_E5M2, FP8_W_SCALE_FC)


class MlpFp8(torch.autograd.Function):
    """Switch 9: the kit's MLP, c_proj(relu(c_fc(x))^2), with row 2 (the c_proj forward) and row 3 (the c_fc input
    gradient) in fp8 and rows 1 and 4 to 6 (the c_fc forward, the c_proj input gradient and both weight gradients)
    in bf16 as the kit computes them; the gradients of both weights use the bf16 h and x, as Phase 1's rows did."""

    @staticmethod
    def forward(ctx, x2, w_fc, w_proj, wq2, wq3, kernel, h_scale):
        pre = F.linear(x2, w_fc)
        r = F.relu(pre)
        h = r.square()
        y = fp8_row2_mm(h, wq2, w_proj, kernel, h_scale)
        ctx.save_for_backward(x2, w_fc, w_proj, r, h, wq3)
        ctx.kernel = kernel
        return y

    @staticmethod
    def backward(ctx, dy):
        x2, w_fc, w_proj, r, h, wq3 = ctx.saved_tensors
        dh = dy.mm(w_proj)
        dw_proj = dy.t().mm(h)
        dpre = torch.ops.aten.threshold_backward(dh * (2 * r), r, 0)
        dx = fp8_row3_mm(dpre, wq3, w_fc, ctx.kernel)
        dw_fc = dpre.t().mm(x2)
        return dx, dw_fc, dw_proj, None, None, None, None


def mlp_fp8(mlp: nn.Module, x: torch.Tensor) -> torch.Tensor:
    """Switch 9: MLP.forward on [b, t, n_embd] through MlpFp8 (the kernel on its device, the emulation elsewhere)."""
    b, t, c = x.shape
    x2 = x.reshape(b * t, c)
    kernel = fp8_kernel_applies(x2, mlp.c_fc.weight.size(0))
    y = MlpFp8.apply(x2, mlp.c_fc.weight.to(dtype=x.dtype), mlp.c_proj.weight.to(dtype=x.dtype), mlp.fp8_wq2,
                     mlp.fp8_wq3, kernel, mlp.fp8_h_scale)
    return y.view(b, t, c)


@torch.no_grad()
def fp8_quantise_into(w_proj_list: list, w_fc_list: list, q2_list: list, q3_list: list) -> None:
    """Switch 9, once per optimizer step: the fp8 bytes of every layer's two weights in the kernel's [K, N] layout,
    padded with zero columns to the kernel's width (row 2's c_proj.weight^T and row 3's c_fc.weight), written into
    the MLPs' buffers in place, so the graphs read the same tensors every step."""
    for w, q in zip(w_proj_list, q2_list):
        q.copy_(S2B_OPS["fp8_quant_proj"](F.pad(w.to(torch.bfloat16).t(), (0, fp8_padded(w.size(0)) - w.size(0)))))
    for w, q in zip(w_fc_list, q3_list):
        q.copy_(S2B_OPS["fp8_quant_fc"](F.pad(w.to(torch.bfloat16), (0, fp8_padded(w.size(1)) - w.size(1)))))


def fp8_refresh_weights(model: nn.Module, quantise_fn=None) -> None:
    """Switch 9: after every optimizer step (and once after the optimizer is built, and in load_for_eval), the fp8
    weights the kernels read. Nothing to do where the emulation runs (it rounds the weights it is given)."""
    if getattr(model, "os1_wcat", None) is not None:
        os1_wcat_refresh(model)         # lane OS1R (rider b): the fold's weight for the next step's micro-steps
    if R2_MLP == "fused8":
        # Switch 9c: every layer's fp8 scale tile from its weights, on every device (the emulation reads the tiles as
        # the kernels do), at the same points: after each optimizer step, once before the first, in load_for_eval.
        mlp8_refresh_scales(model)
        if getattr(model, "stem_tables", None) is not None:
            # Switch 48 on the fp8 line: each gated layer's gate scales from its table, at the same points.
            stem8_refresh_gates(model)
    if ATTN8_ON:
        # Switch 9d: every layer's attention scale tile from its weights, at the same points as switch 9c's.
        attn8_refresh_scales(model)
        if R2_ATTN_PRECAST:
            # Switch 9g: the e4m3 bytes from the same weights and the scales just written.
            attn8_precast_refresh(model)
    if not (R2_FP8_ROWS and s2b_kernel_device(model.get_device())):
        return
    blocks = model.transformer.h
    quantise = quantise_fn or fp8_quantise_into
    quantise([blk.mlp.c_proj.weight for blk in blocks], [blk.mlp.c_fc.weight for blk in blocks],
             [blk.mlp.fp8_wq2 for blk in blocks], [blk.mlp.fp8_wq3 for blk in blocks])


# ---- switch 9b: the fused ReLU-squared MLP

MLP_KERNEL_FILE = "nki_mlp_fused.py"
MLP_KERNEL_MD5 = "c3209e4b1fd9f67d1da05711f804731e"
MLP_READY = False
MLP_MODULE = None
MLP_OPS: dict = {}
MLP_COUNTS = {"fwd_bodies": 0, "bwd_bodies": 0}      # op bodies only: nothing the compiled graph traces mutates it
MLP_DW_MODE = {"token": 0, "fmajor": 1}.get(R2_MLP_DW)
if MLP_DW_MODE is None:
    raise ValueError(f"R2_MLP_DW={R2_MLP_DW!r}: expected token or fmajor")
if DW8_MLP:
    # Switch 9k: the fp8 weight-gradient kernel reads token-major h and dpre: switch 9c's backward in its token mode.
    MLP_DW_MODE = 0
if R2_MLP_TB % 128 or not 0 < R2_MLP_TB <= 1024:
    raise ValueError(f"R2_MLP_TB={R2_MLP_TB}: a multiple of 128 up to 1024")


def mlp_kernel_dir() -> Path:
    """The folder of MLP_KERNEL_FILE: S2_MLP_KERNEL_DIR if set, else kernels/ beside this file."""
    if os.environ.get("S2_MLP_KERNEL_DIR"):
        return Path(os.environ["S2_MLP_KERNEL_DIR"])
    return Path(__file__).resolve().parent / "kernels"


def load_mlp_kernel_module():
    """Import MLP_KERNEL_FILE after checking its md5, with no R1_* variable set while it imports (its knobs are this
    file's R2_MLP_TB and R2_MLP_DW, passed as kernel arguments; the launch width is NEURON_LOGICAL_NC_CONFIG's).
    Returns (module, path)."""
    path = mlp_kernel_dir() / MLP_KERNEL_FILE
    digest = hashlib.md5(path.read_bytes()).hexdigest()
    if digest != MLP_KERNEL_MD5:
        raise RuntimeError(f"{path} has md5 {digest}, expected {MLP_KERNEL_MD5}")
    saved = {k: v for k, v in os.environ.items() if k.startswith("R1_")}
    for k in saved:
        del os.environ[k]
    try:
        spec = importlib.util.spec_from_file_location("s2_nki_mlp_fused", path)
        module = importlib.util.module_from_spec(spec)
        sys.modules[spec.name] = module
        spec.loader.exec_module(module)
    finally:
        os.environ.update(saved)
    return module, path


def register_mlp_ops(module) -> str:
    """Switch 9b: the kernels as MLP_OPS["fwd"] / ["bwd"], registered as switch 7 registers the attention pair
    (nki_op or torch_library), the forward with the backward as its autograd formula: the backward kernel, then the
    two weight gradients as the kit's matmul expressions on its h and dpre outputs."""
    global MLP_OPS
    if R2_ROUTE != "compiled_customop" or R2_CUSTOMOP_FORM not in ("nki_op", "torch_library"):
        raise ValueError("switch 9b runs on the compiled custom-op route, form nki_op or torch_library")
    if R2_CUSTOMOP_FORM == "nki_op":
        from torch_neuronx import nki_op as make_op
    else:
        make_op = torch.library.custom_op
    fwd_kernel = module._launch(module._mlp_fwd_kernel)
    bwd_kernel = module._launch(module._mlp_bwd_kernel)
    tb, dw_mode = R2_MLP_TB, MLP_DW_MODE

    @make_op("s2mlp::mlp_fwd", mutates_args=())
    def mlp_fwd(x2: torch.Tensor, w_fc: torch.Tensor, w_proj: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor]:
        MLP_COUNTS["fwd_bodies"] += 1
        y, rT = fwd_kernel(x2, w_fc, w_proj, tb)
        return y, rT

    @make_op("s2mlp::mlp_bwd", mutates_args=())
    def mlp_bwd(dy2: torch.Tensor, rT: torch.Tensor, w_fc: torch.Tensor,
                w_proj: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
        MLP_COUNTS["bwd_bodies"] += 1
        dx, h_out, dp_out = bwd_kernel(dy2, rT, w_fc, w_proj, tb, dw_mode)
        return dx, h_out, dp_out

    def mlp_fwd_fake(x2, w_fc, w_proj):
        # The kernel's own allocations: y [M, d], rT [F, M].
        return x2.new_empty(x2.shape[0], x2.shape[1]), x2.new_empty(w_fc.shape[0], x2.shape[0])

    def mlp_bwd_fake(dy2, rT, w_fc, w_proj):
        # dx [M, d]; h and dpre [M, F] token-major (dw_mode 0) or [F, M] (dw_mode 1).
        m, f = dy2.shape[0], rT.shape[0]
        big = (f, m) if dw_mode == 1 else (m, f)
        return dy2.new_empty(m, dy2.shape[1]), dy2.new_empty(*big), dy2.new_empty(*big)

    fakes = []
    for name, fake in (("s2mlp::mlp_fwd", mlp_fwd_fake), ("s2mlp::mlp_bwd", mlp_bwd_fake)):
        try:
            torch.library.register_fake(name)(fake)
            fakes.append("ours")
        except Exception as err:
            fakes.append(f"the decorator's ({type(err).__name__})")

    def setup_context(ctx, inputs, output):
        x2, w_fc, w_proj = inputs
        _y, rT = output
        ctx.save_for_backward(x2, rT, w_fc, w_proj)
        ctx.mark_non_differentiable(rT)
        ctx.set_materialize_grads(False)

    def backward(ctx, dy2, _d_rT):
        x2, rT, w_fc, w_proj = ctx.saved_tensors
        dy2 = dy2.contiguous()
        dx, h_out, dp_out = mlp_bwd(dy2, rT, w_fc, w_proj)
        dw_fc, dw_proj = module.weight_grads(dy2, x2, h_out, dp_out, dw_mode)
        return dx, dw_fc, dw_proj

    torch.library.register_autograd("s2mlp::mlp_fwd", backward, setup_context=setup_context)
    MLP_OPS = {"fwd": mlp_fwd, "bwd": mlp_bwd}
    return (f"custom ops s2mlp::mlp_fwd / mlp_bwd by {R2_CUSTOMOP_FORM}, fake impls {fakes[0]} / {fakes[1]}, "
            f"autograd by torch.library.register_autograd; tb={tb} dw={R2_MLP_DW}")


def setup_mlp_kernel(device: torch.device) -> str:
    """Switch 9b: load the kernel module and register its ops, once per process, before the model is built (main()
    and load_for_eval). Off a Neuron device the module's torch emulation runs instead. Returns the log line."""
    global MLP_READY, MLP_MODULE
    if R2_MLP != "fused":
        return "off"
    if MLP_MODULE is None:
        MLP_MODULE, path = load_mlp_kernel_module()
    else:
        path = mlp_kernel_dir() / MLP_KERNEL_FILE
    if device.type != "neuron":
        return f"emulation (not a Neuron device): {path} md5 {MLP_KERNEL_MD5}, tb={R2_MLP_TB} dw={R2_MLP_DW}"
    if not MLP_MODULE._HAS_NKI:
        raise RuntimeError(f"switch 9b needs nki on a Neuron device ({MLP_MODULE._NKI_ERROR})")
    if MLP_READY:
        return "on (registered earlier in this process)"
    how = register_mlp_ops(MLP_MODULE)
    MLP_READY = True
    return f"on: {how}; {path} md5 {MLP_KERNEL_MD5}"


def mlp_fused_applies(x2: torch.Tensor, hidden: int) -> bool:
    """Switch 9b: where the kernels run: registered, a Neuron device, bf16 rows, every shape a multiple of 128."""
    return (MLP_READY and x2.device.type == "neuron" and x2.dtype == torch.bfloat16
            and MLP_MODULE.shapes_apply(x2.size(0), x2.size(1), hidden, R2_MLP_TB))


def mlp_fused(mlp: nn.Module, x: torch.Tensor) -> torch.Tensor:
    """Switch 9b: MLP.forward on [b, t, n_embd]: the kernels where they apply, the module's emulation off a Neuron
    device (CPU proxies and proofs), the kit's expression for a shape the kernels do not take."""
    b, t, c = x.shape
    x2 = x.reshape(b * t, c).contiguous()
    w_fc = mlp.c_fc.weight.to(dtype=x.dtype)
    w_proj = mlp.c_proj.weight.to(dtype=x.dtype)
    # No counter here: this runs inside the compiled graph, and a mutated global is a guard that recompiles every step.
    if mlp_fused_applies(x2, w_fc.size(0)):
        y, _rT = MLP_OPS["fwd"](x2, w_fc, w_proj)
    elif x2.device.type != "neuron" and MLP_MODULE is not None:
        y = MLP_MODULE.EmulatedFusedMlp.apply(x2, w_fc, w_proj, MLP_DW_MODE)
    else:
        return mlp.c_proj(relu_squared(mlp.c_fc(x)))
    return y.view(b, t, c)


def mlp_summary() -> str:
    """Switch 9b: the end-of-run line: the op bodies' counts (they run when the decorator traces them or outside a
    compiled graph) and whether the ops were registered (on a Neuron device; off one the emulation ran)."""
    if R2_MLP != "fused":
        return "off"
    return " ".join(f"{k}={v}" for k, v in MLP_COUNTS.items()) + (" registered" if MLP_READY else " not registered")


# ---- switch 9c: the fp8 fused MLP

MLP8_KERNEL_FILE = "nki_mlp_fused8.py"
MLP8_KERNEL_MD5 = "18369d3831905542d1e0362789613321"
MLP8_NSC = 16                                  # the scale tile's columns (the module's NSC)
MLP8_READY = False
MLP8_MODULE = None
MLP8_OPS: dict = {}
MLP8_COUNTS = {"fwd_bodies": 0, "bwd_bodies": 0}    # op bodies only, as switch 9b's
MLP8_SCALE_FN = None                           # the per-step scale function; main() compiles it as the model is
MLP8_MODE = {"fwd": 1, "bwd": 2, "both": 3}[R2_MLP_FP8]


def load_mlp8_kernel_module():
    """Switch 9c: import MLP8_KERNEL_FILE (in mlp_kernel_dir(), beside switch 9b's) after checking its md5, with no R1_*
    variable set while it imports (its knobs are this file's, passed as kernel arguments). Returns (module, path)."""
    path = mlp_kernel_dir() / MLP8_KERNEL_FILE
    digest = hashlib.md5(path.read_bytes()).hexdigest()
    if digest != MLP8_KERNEL_MD5:
        raise RuntimeError(f"{path} has md5 {digest}, expected {MLP8_KERNEL_MD5}")
    saved = {k: v for k, v in os.environ.items() if k.startswith("R1_")}
    for k in saved:
        del os.environ[k]
    try:
        spec = importlib.util.spec_from_file_location("s2_nki_mlp_fused8", path)
        module = importlib.util.module_from_spec(spec)
        sys.modules[spec.name] = module
        spec.loader.exec_module(module)
    finally:
        os.environ.update(saved)
    if module.NSC != MLP8_NSC:
        raise RuntimeError(f"{path}: NSC {module.NSC}, expected {MLP8_NSC}")
    return module, path


def register_mlp8_ops(module) -> str:
    """Switch 9c: the forward as s2mlp8::fwd (the fp8 kernel, or under R2_MLP_FP8=bwd switch 9b's bf16 kernel) with
    its autograd formula: the backward op s2mlp8::bwd (the fp8 kernel with this call's dy scales computed in the
    backward graph, or under R2_MLP_FP8=fwd the bf16 kernel), then the two weight gradients as the kit's matmul
    expressions on its bf16 h and dpre. Registered as switch 9b registers its pair."""
    global MLP8_OPS
    if R2_ROUTE != "compiled_customop" or R2_CUSTOMOP_FORM not in ("nki_op", "torch_library"):
        raise ValueError("switch 9c runs on the compiled custom-op route, form nki_op or torch_library")
    if R2_CUSTOMOP_FORM == "nki_op":
        from torch_neuronx import nki_op as make_op
    else:
        make_op = torch.library.custom_op
    tb, dw_mode, forms, mode = R2_MLP_TB, MLP_DW_MODE, R2_MLP8_FORMS, MLP8_MODE
    fwd_kernel = module._launch(module._mlp8_fwd_kernel if mode & 1 else module._mlp_fwd_kernel)
    bwd_kernel = module._launch(module._mlp8_bwd_kernel if mode & 2 else module._mlp_bwd_kernel)

    @make_op("s2mlp8::fwd", mutates_args=())
    def mlp8_fwd(x2: torch.Tensor, w_fc: torch.Tensor, w_proj: torch.Tensor,
                 sc: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor]:
        MLP8_COUNTS["fwd_bodies"] += 1
        if mode & 1:
            y, rT = fwd_kernel(x2, w_fc, w_proj, sc, tb, forms)
        else:
            y, rT = fwd_kernel(x2, w_fc, w_proj, tb)
        return y, rT

    @make_op("s2mlp8::bwd", mutates_args=())
    def mlp8_bwd(dy2: torch.Tensor, rT: torch.Tensor, w_fc: torch.Tensor, w_proj: torch.Tensor,
                 sc: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
        MLP8_COUNTS["bwd_bodies"] += 1
        if mode & 2:
            dx, h_out, dp_out = bwd_kernel(dy2, rT, w_fc, w_proj, sc, tb, dw_mode, forms)
        else:
            dx, h_out, dp_out = bwd_kernel(dy2, rT, w_fc, w_proj, tb, dw_mode)
        return dx, h_out, dp_out

    def mlp8_fwd_fake(x2, w_fc, w_proj, sc):
        # The kernels' own allocations: y [M, d], rT [F, M].
        return x2.new_empty(x2.shape[0], x2.shape[1]), x2.new_empty(w_fc.shape[0], x2.shape[0])

    def mlp8_bwd_fake(dy2, rT, w_fc, w_proj, sc):
        # dx [M, d]; h and dpre [M, F] token-major (dw_mode 0) or [F, M] (dw_mode 1).
        m, f = dy2.shape[0], rT.shape[0]
        big = (f, m) if dw_mode == 1 else (m, f)
        return dy2.new_empty(m, dy2.shape[1]), dy2.new_empty(*big), dy2.new_empty(*big)

    fakes = []
    for name, fake in (("s2mlp8::fwd", mlp8_fwd_fake), ("s2mlp8::bwd", mlp8_bwd_fake)):
        try:
            torch.library.register_fake(name)(fake)
            fakes.append("ours")
        except Exception as err:
            fakes.append(f"the decorator's ({type(err).__name__})")

    def setup_context(ctx, inputs, output):
        x2, w_fc, w_proj, sc = inputs
        _y, rT = output
        ctx.save_for_backward(x2, rT, w_fc, w_proj, sc)
        ctx.mark_non_differentiable(rT)
        ctx.set_materialize_grads(False)

    def backward(ctx, dy2, _d_rT):
        x2, rT, w_fc, w_proj, sc = ctx.saved_tensors
        dy2 = dy2.contiguous()
        # The fp8 backward's scales: this call's dy amax and the dpre bound, in the backward graph (training only).
        sc_b = module.sc_tile(module.backward_scales(dy2, sc[0])) if mode & 2 else sc
        dx, h_out, dp_out = mlp8_bwd(dy2, rT, w_fc, w_proj, sc_b)
        dw_fc, dw_proj = mlp8_weight_grads(module, dy2, x2, h_out, dp_out, dw_mode, sc_b)     # (switch 9k's route)
        return dx, dw_fc, dw_proj, None

    torch.library.register_autograd("s2mlp8::fwd", backward, setup_context=setup_context)
    MLP8_OPS = {"fwd": mlp8_fwd, "bwd": mlp8_bwd}
    return (f"custom ops s2mlp8::fwd / bwd by {R2_CUSTOMOP_FORM}, fake impls {fakes[0]} / {fakes[1]}, "
            f"autograd by torch.library.register_autograd; fp8={R2_MLP_FP8} forms={forms} tb={tb} dw={R2_MLP_DW}")


def setup_mlp8_kernel(device: torch.device) -> str:
    """Switch 9c: load the fp8 kernel module and register its ops, once per process, before the model is built (main()
    and load_for_eval). Off a Neuron device the module's torch emulation runs instead. Returns the log line."""
    global MLP8_READY, MLP8_MODULE
    if R2_MLP != "fused8":
        return "off"
    if MLP8_MODULE is None:
        MLP8_MODULE, path = load_mlp8_kernel_module()
    else:
        path = mlp_kernel_dir() / MLP8_KERNEL_FILE
    tail = (f"{path} md5 {MLP8_KERNEL_MD5}, fp8={R2_MLP_FP8} forms={R2_MLP8_FORMS} tb={R2_MLP_TB} dw={R2_MLP_DW}")
    if device.type != "neuron":
        return f"emulation (not a Neuron device): {tail}"
    if not MLP8_MODULE._HAS_NKI:
        raise RuntimeError(f"switch 9c needs nki on a Neuron device ({MLP8_MODULE._NKI_ERROR})")
    if MLP8_READY:
        return "on (registered earlier in this process)"
    how = register_mlp8_ops(MLP8_MODULE)
    MLP8_READY = True
    return f"on: {how}; {tail}"


def mlp8_applies(x2: torch.Tensor, hidden: int) -> bool:
    """Switch 9c: where the kernels run: registered, a Neuron device, bf16 rows, n_embd and the hidden width multiples
    of 256 (the double-row pair); the row count is padded to a multiple of 128 by the caller."""
    return (MLP8_READY and x2.device.type == "neuron" and x2.dtype == torch.bfloat16
            and MLP8_MODULE.shapes_apply8(128, x2.size(1), hidden, R2_MLP_TB))


def mlp_fused8(mlp: nn.Module, x: torch.Tensor) -> torch.Tensor:
    """Switch 9c: MLP.forward on [b, t, n_embd]: the kernels on a Neuron device, the rows padded with zeros to a
    multiple of 128 (a zero row gives a zero output row and touches no other row: each output element's sum runs in
    the same order whatever the row count, so every real row's output is its unpadded value bit for bit); off a Neuron
    device the module's emulation. No bf16 MLP expression is reachable under this switch: a shape the kernels do not
    take on a Neuron device raises."""
    b, t, c = x.shape
    x2 = x.reshape(b * t, c).contiguous()
    # Switch 9h: fold_in_weight is weight.to(dtype) unless the lean optimizer gave the layer its slab view.
    w_fc = fold_in_weight(mlp.c_fc, x.dtype)
    w_proj = fold_in_weight(mlp.c_proj, x.dtype)
    m = x2.size(0)
    if mlp8_applies(x2, w_fc.size(0)):
        pad = (-m) % 128
        if pad:
            x2 = F.pad(x2, (0, 0, 0, pad))
        if R2_MOE_SHPC and MLP_L4_READY and isinstance(mlp, MoeShared):
            # Switch 55s: a shared half on switch 9f's op pair, on its own e4m3 bytes (9c's outputs bit for bit).
            y, _rT = MLP_L4_OPS["fwd"](x2, w_fc, w_proj, mlp.mlp8_sc, mlp.mlp8_w8)
            if pad:
                y = y[:m]
            return y.view(b, t, c)
        if FC8_READY and not isinstance(mlp, MoeShared):
            # Switch 67 (lane FP8MLP): a dense unit on its own op pair (switch 9f's kernel calls, the backward in token
            # mode, c_fc's weight gradient on switch 9k's kernel); the MoE blocks' shared halves keep s2mlp8l (above).
            y, _rT = FC8_OPS["fwd"](x2, w_fc, w_proj, mlp.mlp8_sc, mlp.mlp8_w8)
            if pad:
                y = y[:m]
            return y.view(b, t, c)
        if MLP_L4_READY and not isinstance(mlp, MoeShared):
            # Switches 9e, 9f: their op pair (switch 9c's arithmetic; under 9e the backward is the L4 kernel). Lane
            # STACK5: switch 55's shared halves hold no e4m3 bytes and keep switch 9c's pair (the MoE's measured route).
            y, _rT = MLP_L4_OPS["fwd"](x2, w_fc, w_proj, mlp.mlp8_sc, mlp.mlp8_w8)
        else:
            y, _rT = MLP8_OPS["fwd"](x2, w_fc, w_proj, mlp.mlp8_sc)
        if pad:
            y = y[:m]
    elif x2.device.type != "neuron" and MLP8_MODULE is not None:
        if R2_FC8 and not isinstance(mlp, MoeShared):
            # Switch 67 off a Neuron device: switch 9c's emulation in token mode, c_fc's weight gradient by switch 9k's.
            return EmulatedFusedMlp8FC8.apply(x2, w_fc, w_proj, mlp.mlp8_sc).view(b, t, c)
        if R2_MLP_L4:
            # Switch 9e off a Neuron device: switch 9c's emulation, the weight gradients as the L4 kernel forms them.
            y = EmulatedFusedMlp8L4.apply(x2, w_fc, w_proj, mlp.mlp8_sc, MLP8_MODE)
        elif DW8_MLP:
            # Switch 9k off a Neuron device: switch 9c's emulation, the weight gradients from the fp8 emulation.
            y = EmulatedFusedMlp8DW8.apply(x2, w_fc, w_proj, mlp.mlp8_sc, MLP8_MODE)
        else:
            y = MLP8_MODULE.EmulatedFusedMlp8.apply(x2, w_fc, w_proj, mlp.mlp8_sc, MLP8_MODE, MLP_DW_MODE)
    else:
        raise RuntimeError(f"switch 9c: the fp8 MLP kernels do not take rows {tuple(x2.shape)} {x2.dtype} with hidden "
                           f"width {w_fc.size(0)} (registered: {MLP8_READY}); no bf16 MLP runs under R2_MLP=fused8")
    return y.view(b, t, c)


@torch.no_grad()
def mlp8_scales_into(w_fc_list: list, w_proj_list: list, sc_list: list) -> None:
    """Switch 9c, once per optimizer step: every layer's scale tile from its two weights (the module's forward_scales:
    exact amax and powers of two), written into the MLPs' buffers in place, so the graphs read the same tensors every
    step and a new value never recompiles them."""
    for w_fc, w_proj, sc in zip(w_fc_list, w_proj_list, sc_list):
        sc.copy_(MLP8_MODULE.sc_tile(MLP8_MODULE.forward_scales(w_fc, w_proj)))


def set_mlp8_scale_fn(fn) -> None:
    """Switch 9c: main() hands over the compiled scale function (the model's backend)."""
    global MLP8_SCALE_FN
    MLP8_SCALE_FN = fn


def mlp8_refresh_scales(model: nn.Module) -> None:
    """Switch 9c: fp8_refresh_weights' share: every layer's scale tile from its current weights (compiled in training,
    eager in load_for_eval: the same operations on the same values)."""
    units = mlp8_units(model)     # switch 55: a MoE block's shared half (without it, every block's MLP)
    fn = MLP8_SCALE_FN or mlp8_scales_into
    fn([u.c_fc.weight for u in units], [u.c_proj.weight for u in units], [u.mlp8_sc for u in units])
    if R2_MLP_PRECAST:
        # Switch 9f: the e4m3 bytes from the same weights and the scales just written (compiled in training, eager in
        # load_for_eval: the same operations on the same values). Lane STACK5: switch 55's shared halves hold no e4m3
        # bytes and keep switch 9c's op pair (mlp_fused8), so the dense units alone (every unit without switch 55).
        dense = [u for u in units if not isinstance(u, MoeShared)]
        if R2_MOE_SHPC:
            dense = units       # switch 55s: the shared halves hold switch 9f's bytes too
        pfn = MLP8_PRECAST_FN or mlp8_precast_into
        pfn([u.c_fc.weight for u in dense], [u.c_proj.weight for u in dense],
            [u.mlp8_sc for u in dense], [u.mlp8_w8 for u in dense])
    moe8_refresh(model)     # switch 66 (lane THR13): the fp8 experts' tiles and bytes (nothing without them)


def mlp8_scales_line(model: nn.Module) -> str:
    """Switch 9c: the scales in force, one line: each layer's weight scales (log2 of W_fc's and W_proj's), log2 of
    s_h, W_fc's largest row norm, and the kernels' SBUF plan (KiB a partition, forward / backward) at this width."""
    units = mlp8_units(model)     # switch 55: a MoE block's shared half (without it, every block's MLP)
    rows = torch.stack([u.mlp8_sc[0].detach().float().cpu() for u in units])

    def log2s(col):
        return [int(v) for v in torch.log2(rows[:, col]).round().tolist()]

    rho = [round(v, 3) for v in rows[:, MLP8_MODULE.SC_RHO2].sqrt().tolist()]
    w = units[0].c_fc.weight
    kib = MLP8_MODULE.plan_kib8(w.shape[1], w.shape[0], R2_MLP_TB, R2_MLP8_FORMS)
    return (f"log2_s_wfc={log2s(MLP8_MODULE.SC_S_WFC)} log2_s_wproj={log2s(MLP8_MODULE.SC_S_WPROJ)} "
            f"log2_s_h={log2s(MLP8_MODULE.SC_S_H)} rho_fc={rho} sbuf_kib={kib[0]:.0f}/{kib[1]:.0f}")


def mlp8_summary() -> str:
    """Switch 9c: the end-of-run line: the op bodies' counts and whether the ops were registered."""
    if R2_MLP != "fused8":
        return "off"
    return " ".join(f"{k}={v}" for k, v in MLP8_COUNTS.items()) + (" registered" if MLP8_READY else " not registered")


# ---- switches 9e and 9f: the MLP weight gradients inside the fp8 backward kernel, the e4m3 weights pre-cast

MLP_L4_KERNEL_FILE = "nki_mlp_l4.py"
MLP_L4_KERNEL_MD5 = "6f712d967999e04f60567c95e6822969"
MLP_L4_GQ = 4                                   # hidden chunks of 128 a dW_proj store (the module's GQ)
MLP_L4_U8 = 1                                   # fp8 bytes cross HBM as uint8 viewed on chip (switch 9's device form)
MLP_L4_MODULE = None
MLP_L4_OPS: dict = {}
MLP_L4_READY = False
MLP_L4_COUNTS = {"fwd_bodies": 0, "bwd_bodies": 0, "precast_bodies": 0}   # op bodies only, as switch 9c's
MLP8_PRECAST_FN = None                          # the per-step pre-cast; main() compiles it as the scale function is


def load_mlp_l4_kernel_module():
    """Switches 9e, 9f: import MLP_L4_KERNEL_FILE (in mlp_kernel_dir(), beside switch 9c's) after checking its md5, with
    no R1_* variable set while it imports (its knobs are this file's, passed as kernel arguments). Returns
    (module, path)."""
    if R2_MLP_TT:
        return load_mlp_l4t_kernel_module()     # switch 9r: the same functions, the activation loads by TensorE
    path = mlp_kernel_dir() / MLP_L4_KERNEL_FILE
    digest = hashlib.md5(path.read_bytes()).hexdigest()
    if digest != MLP_L4_KERNEL_MD5:
        raise RuntimeError(f"{path} has md5 {digest}, expected {MLP_L4_KERNEL_MD5}")
    saved = {k: v for k, v in os.environ.items() if k.startswith("R1_")}
    for k in saved:
        del os.environ[k]
    try:
        spec = importlib.util.spec_from_file_location("s2_nki_mlp_l4", path)
        module = importlib.util.module_from_spec(spec)
        sys.modules[spec.name] = module
        spec.loader.exec_module(module)
    finally:
        os.environ.update(saved)
    if module.NSC != MLP8_NSC or module.GQ != MLP_L4_GQ:
        raise RuntimeError(f"{path}: NSC {module.NSC}, GQ {module.GQ}; expected {MLP8_NSC}, {MLP_L4_GQ}")
    return module, path


def register_mlp_l4_ops(module8, module) -> str:
    """Switches 9e, 9f: s2mlp8l::fwd (switch 9c's forward kernel, under 9f its pre-cast form, under R2_MLP_FP8=bwd
    switch 9b's bf16 kernel) with its autograd formula: the backward op s2mlp8l::bwd (under 9e the L4 kernel, which
    returns dx and both weight gradients; else switch 9c's backward kernel, under 9f in its pre-cast form, then the
    two weight gradients as switch 9c forms them), with this call's dy scales computed in the backward graph as
    switch 9c computes them; and s2mlp8l::precast (switch 9f: one layer's e4m3 bytes). Registered as switch 9c
    registers its pair."""
    global MLP_L4_OPS
    if R2_ROUTE != "compiled_customop" or R2_CUSTOMOP_FORM not in ("nki_op", "torch_library"):
        raise ValueError("switches 9e and 9f run on the compiled custom-op route, form nki_op or torch_library")
    if R2_CUSTOMOP_FORM == "nki_op":
        from torch_neuronx import nki_op as make_op
    else:
        make_op = torch.library.custom_op
    tb, dw_mode, forms, mode, gq, u8 = R2_MLP_TB, MLP_DW_MODE, R2_MLP8_FORMS, MLP8_MODE, MLP_L4_GQ, MLP_L4_U8
    l4, pc = int(R2_MLP_L4), int(R2_MLP_PRECAST)
    need = module.precast_need(mode)
    lnc = module8._LNC
    if mode & 1:
        fwd_kernel = module8._launch(module._mlp8_fwd_pc_kernel if pc else module8._mlp8_fwd_kernel)
    else:
        fwd_kernel = module8._launch(module8._mlp_fwd_kernel)
    if l4:
        bwd_kernel = module8._launch(module._mlp8_bwd_l4_kernel)
    elif mode & 2:
        bwd_kernel = module8._launch(module._mlp8_bwd_pc_kernel if pc else module8._mlp8_bwd_kernel)
    else:
        bwd_kernel = module8._launch(module8._mlp_bwd_kernel)
    pre_kernel = module8._launch(module._precast8_kernel)

    @make_op("s2mlp8l::fwd", mutates_args=())
    def mlp8l_fwd(x2: torch.Tensor, w_fc: torch.Tensor, w_proj: torch.Tensor, sc: torch.Tensor,
                  w8: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor]:
        MLP_L4_COUNTS["fwd_bodies"] += 1
        if mode & 1:
            if pc:
                y, rT = fwd_kernel(x2, w8, sc, tb, forms, u8)
            else:
                y, rT = fwd_kernel(x2, w_fc, w_proj, sc, tb, forms)
        else:
            y, rT = fwd_kernel(x2, w_fc, w_proj, tb)
        return y, rT

    @make_op("s2mlp8l::bwd", mutates_args=())
    def mlp8l_bwd(dy2: torch.Tensor, rT: torch.Tensor, x2: torch.Tensor, w_fc: torch.Tensor, w_proj: torch.Tensor,
                  sc: torch.Tensor, w8: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
        MLP_L4_COUNTS["bwd_bodies"] += 1
        if l4:
            dx, a, b, _dp8 = bwd_kernel(dy2, rT, x2, w_fc, w_proj, w8, sc, tb, gq, pc, forms, u8)
        elif mode & 2:
            if pc:
                dx, a, b = bwd_kernel(dy2, rT, w8, sc, tb, dw_mode, forms, u8)
            else:
                dx, a, b = bwd_kernel(dy2, rT, w_fc, w_proj, sc, tb, dw_mode, forms)
        else:
            dx, a, b = bwd_kernel(dy2, rT, w_fc, w_proj, tb, dw_mode)
        return dx, a, b

    @make_op("s2mlp8l::precast", mutates_args=())
    def mlp8l_precast(w_fc: torch.Tensor, w_proj: torch.Tensor, sc: torch.Tensor) -> torch.Tensor:
        MLP_L4_COUNTS["precast_bodies"] += 1
        return pre_kernel(w_fc, w_proj, sc, need, forms, u8)

    def mlp8l_fwd_fake(x2, w_fc, w_proj, sc, w8):
        # The kernels' own allocations: y [M, d], rT [F, M].
        return x2.new_empty(x2.shape[0], x2.shape[1]), x2.new_empty(w_fc.shape[0], x2.shape[0])

    def mlp8l_bwd_fake(dy2, rT, x2, w_fc, w_proj, sc, w8):
        # Under 9e: dx [M, d], dw_fc [F, d], dw_proj [d, F]; else as switch 9c's backward op.
        m, d, f = dy2.shape[0], dy2.shape[1], rT.shape[0]
        if l4:
            return dy2.new_empty(m, d), dy2.new_empty(f, d), dy2.new_empty(d, f)
        big = (f, m) if dw_mode == 1 else (m, f)
        return dy2.new_empty(m, d), dy2.new_empty(*big), dy2.new_empty(*big)

    def mlp8l_precast_fake(w_fc, w_proj, sc):
        # The kernel's allocation: [4, F x d] bytes.
        return w_fc.new_empty(4, w_fc.shape[0] * w_fc.shape[1], dtype=torch.uint8)

    fakes = []
    for name, fake in (("s2mlp8l::fwd", mlp8l_fwd_fake), ("s2mlp8l::bwd", mlp8l_bwd_fake),
                       ("s2mlp8l::precast", mlp8l_precast_fake)):
        try:
            torch.library.register_fake(name)(fake)
            fakes.append("ours")
        except Exception as err:
            fakes.append(f"the decorator's ({type(err).__name__})")

    def setup_context(ctx, inputs, output):
        x2, w_fc, w_proj, sc, w8 = inputs
        _y, rT = output
        ctx.save_for_backward(x2, rT, w_fc, w_proj, sc, w8)
        ctx.mark_non_differentiable(rT)
        ctx.set_materialize_grads(False)

    def backward(ctx, dy2, _d_rT):
        x2, rT, w_fc, w_proj, sc, w8 = ctx.saved_tensors
        dy2 = dy2.contiguous()
        if l4 and not module.shapes_apply_l4(dy2.shape[0], dy2.shape[1], rT.shape[0], tb, lnc, gq, pc, forms):
            raise RuntimeError(f"switch 9e: the L4 kernel does not take {tuple(dy2.shape)} with hidden width "
                               f"{rT.shape[0]} at tb {tb}, LNC {lnc} (module.shapes_apply_l4)")
        # The fp8 backward's scales: this call's dy amax and the dpre bound, in the backward graph (as switch 9c's).
        sc_b = module8.sc_tile(module8.backward_scales(dy2, sc[0])) if mode & 2 else sc
        dx, a, b = mlp8l_bwd(dy2, rT, x2, w_fc, w_proj, sc_b, w8)
        if l4:
            return dx, a, b, None, None
        dw_fc, dw_proj = mlp8_weight_grads(module8, dy2, x2, a, b, dw_mode, sc_b)     # (switch 9k's route)
        return dx, dw_fc, dw_proj, None, None

    torch.library.register_autograd("s2mlp8l::fwd", backward, setup_context=setup_context)
    MLP_L4_OPS = {"fwd": mlp8l_fwd, "bwd": mlp8l_bwd, "precast": mlp8l_precast}
    return (f"custom ops s2mlp8l::fwd / bwd / precast by {R2_CUSTOMOP_FORM}, fake impls {fakes[0]} / {fakes[1]} / "
            f"{fakes[2]}, autograd by torch.library.register_autograd; l4={l4} precast={pc} need={need} gq={gq} "
            f"u8={u8}")


def setup_mlp_l4_kernel(device: torch.device) -> str:
    """Switches 9e, 9f: load their module and register their ops, once per process, after switch 9c's (main() and
    load_for_eval). Off a Neuron device switch 9c's emulation runs, with 9e's weight-gradient arithmetic (and 9f's
    bytes from the module's reference). Returns the log line."""
    global MLP_L4_READY, MLP_L4_MODULE
    if not (R2_MLP_L4 or R2_MLP_PRECAST):
        return "off"
    if MLP_L4_MODULE is None:
        MLP_L4_MODULE, path = load_mlp_l4_kernel_module()
    else:
        path = mlp_kernel_dir() / MLP_L4_KERNEL_FILE
    tail = f"l4={int(R2_MLP_L4)} precast={int(R2_MLP_PRECAST)} gq={MLP_L4_GQ}; {path} md5 {MLP_L4_KERNEL_MD5}"
    if R2_MLP_TT:
        tail = (f"l4={int(R2_MLP_L4)} precast={int(R2_MLP_PRECAST)} gq={MLP_L4_GQ} tt=1; "
                f"{mlp_kernel_dir() / MLP_L4T_KERNEL_FILE} md5 {MLP_L4T_KERNEL_MD5}")    # switch 9r's module
    if device.type != "neuron":
        return f"emulation (not a Neuron device): {tail}"
    if not MLP_L4_MODULE._HAS_NKI:
        raise RuntimeError(f"switches 9e, 9f need nki on a Neuron device ({MLP_L4_MODULE._NKI_ERROR})")
    if R2_MLP_L4 and MLP8_MODULE._LNC != 2:
        raise RuntimeError("switch 9e (R2_MLP_L4) needs NEURON_LOGICAL_NC_CONFIG=2: the kernel's two programs each "
                           "form one weight gradient")
    if MLP_L4_READY:
        return "on (registered earlier in this process)"
    how = register_mlp_l4_ops(MLP8_MODULE, MLP_L4_MODULE)
    MLP_L4_READY = True
    return f"on: {how}; {tail}"


class EmulatedFusedMlp8L4(torch.autograd.Function):
    """Switch 9e off a Neuron device (CPU proxies and proofs): switch 9c's emulation (its forward, and its fp8
    backward with this call's dy scales) with the two weight gradients formed as the L4 kernel forms them, bf16 of
    fp32 sums of the backward's bf16 h^T and dpre^T against x and dy (the module's l4_weight_grads)."""

    @staticmethod
    def forward(ctx, x2, w_fc, w_proj, sc, mode):
        row = sc[0]
        if mode & 1:
            y, rT = MLP8_MODULE.emulate8_forward(x2, w_fc, w_proj, row)
        else:
            y, rT = MLP8_MODULE.emulate_forward(x2, w_fc, w_proj)
        ctx.save_for_backward(x2, rT, w_fc, w_proj, sc)
        return y

    @staticmethod
    def backward(ctx, dy2):
        x2, rT, w_fc, w_proj, sc = ctx.saved_tensors
        dy2 = dy2.contiguous()
        dx, hT, dpT = MLP8_MODULE.emulate8_backward(dy2, rT, w_fc, w_proj, MLP8_MODULE.backward_scales(dy2, sc[0]), 1)
        dw_fc, dw_proj = MLP_L4_MODULE.l4_weight_grads(dy2, x2, hT, dpT)
        return dx, dw_fc, dw_proj, None, None


@torch.no_grad()
def mlp8_precast_into(w_fc_list: list, w_proj_list: list, sc_list: list, w8_list: list) -> None:
    """Switch 9f, once per optimizer step after the scales: every layer's e4m3 bytes from its two weights and the scale
    tile just written (the module's kernel on a Neuron device, its byte reference elsewhere), into the MLPs' buffers
    in place, so the graphs read the same tensors every step and a new value never recompiles them."""
    need = MLP_L4_MODULE.precast_need(MLP8_MODE)
    for w_fc, w_proj, sc, w8 in zip(w_fc_list, w_proj_list, sc_list, w8_list):
        wf, wp = w_fc.to(torch.bfloat16), w_proj.to(torch.bfloat16)
        if MLP_L4_READY and w8.device.type == "neuron":
            w8.copy_(MLP_L4_OPS["precast"](wf, wp, sc))
        else:
            w8.copy_(MLP_L4_MODULE.precast_ref(wf, wp, sc[0].float(), need))


def set_mlp8_precast_fn(fn) -> None:
    """Switch 9f: main() hands over the compiled pre-cast function (the model's backend)."""
    global MLP8_PRECAST_FN
    MLP8_PRECAST_FN = fn


MOE8_SCALE_FN = None        # switch 66: main() compiles the experts' scale function as switch 9c's (its own graph)
MOE8_PRECAST_FN = None      # switch 66: and the experts' pre-cast as switch 9f's


@torch.no_grad()
def moe8_scales_into(w_fc_list: list, w_proj_list: list, sc_list: list) -> None:
    """Switch 66 (lane THR13): mlp8_scales_into on the experts' lists (its own compiled graph)."""
    mlp8_scales_into(w_fc_list, w_proj_list, sc_list)


@torch.no_grad()
def moe8_precast_into(w_fc_list: list, w_proj_list: list, sc_list: list, w8_list: list) -> None:
    """Switch 66 (lane THR13): mlp8_precast_into on the experts' lists (its own compiled graph)."""
    mlp8_precast_into(w_fc_list, w_proj_list, sc_list, w8_list)


def set_moe8_fns(scale_fn, precast_fn) -> None:
    """Switch 66: main() hands over the compiled scale and pre-cast functions (the model's backend)."""
    global MOE8_SCALE_FN, MOE8_PRECAST_FN
    MOE8_SCALE_FN, MOE8_PRECAST_FN = scale_fn, precast_fn


@torch.no_grad()
def moe8_refresh(model: nn.Module) -> None:
    """Switch 66 (lane THR13), fp8_refresh_weights' share for the routed experts (nothing where no block runs them):
    each expert held here gets its scale tile from its current weights (switch 9c's forward_scales, as every dense
    unit's); in training (one expert a rank) also its e4m3 bytes from the same weights and that tile (switch 9f's
    pre-cast). Compiled in training, eager in load_for_eval: the same operations on the same values."""
    units = [blk.mlp for blk in model.transformer.h if isinstance(blk.mlp, MoeMLP) and blk.mlp.e8]
    if not units:
        return
    ep = [u for u in units if u.ep]
    # host counts only (never in a traced function: a mutated global there is a guard that recompiles every call)
    MOE8_COUNTS.update(ep_blocks=len(ep), local_blocks=len(units) - len(ep), refreshes=MOE8_COUNTS["refreshes"] + 1)
    if ep:
        fn = MOE8_SCALE_FN or moe8_scales_into
        fn([u.w_fc[0] for u in ep], [u.w_proj[0] for u in ep], [u.exp8_sc for u in ep])
        pfn = MOE8_PRECAST_FN or moe8_precast_into
        pfn([u.w_fc[0] for u in ep], [u.w_proj[0] for u in ep], [u.exp8_sc for u in ep], [u.exp8_w8 for u in ep])
    for u in units:
        if not u.ep:
            for j in range(u.n_local):
                mlp8_scales_into([u.w_fc[j]], [u.w_proj[j]], [u.exp8_sc[j]])


def mlp_l4_summary() -> str:
    """Switches 9e, 9f: the end-of-run line: the op bodies' counts and whether the ops were registered."""
    if not (R2_MLP_L4 or R2_MLP_PRECAST):
        return "off"
    return (" ".join(f"{k}={v}" for k, v in MLP_L4_COUNTS.items())
            + (" registered" if MLP_L4_READY else " not registered")
            + f" l4={int(R2_MLP_L4)} precast={int(R2_MLP_PRECAST)}")


# ---- switch 9d: the fp8 attention projections

ATTN8_KERNEL_FILE = "nki_attn_proj8.py"
ATTN8_KERNEL_MD5 = "275376c2e8bac755fbea67809bf4e9a9"
ATTN8_NSC = 16                                 # the scale tile's columns (the module's NSC)
ATTN8_READY = False
ATTN8_MODULE = None
ATTN8_OPS: dict = {}
ATTN8_COUNTS = {"fwd_bodies": 0, "bwd_bodies": 0}   # op bodies only, as switch 9c's
ATTN8_SCALE_FN = None                          # the per-step scale function; main() compiles it as the model is
ATTN8_MODE = {"off": 0, "fwd": 1, "bwd": 2, "both": 3}[R2_ATTN_FP8]


def load_attn8_kernel_module():
    """Switch 9d: import ATTN8_KERNEL_FILE (in mlp_kernel_dir(), beside switch 9c's) after checking its md5, with no
    R1_* variable set while it imports. Returns (module, path)."""
    path = mlp_kernel_dir() / ATTN8_KERNEL_FILE
    digest = hashlib.md5(path.read_bytes()).hexdigest()
    if digest != ATTN8_KERNEL_MD5:
        raise RuntimeError(f"{path} has md5 {digest}, expected {ATTN8_KERNEL_MD5}")
    saved = {k: v for k, v in os.environ.items() if k.startswith("R1_")}
    for k in saved:
        del os.environ[k]
    try:
        spec = importlib.util.spec_from_file_location("s2_nki_attn_proj8", path)
        module = importlib.util.module_from_spec(spec)
        sys.modules[spec.name] = module
        spec.loader.exec_module(module)
    finally:
        os.environ.update(saved)
    if module.NSC != ATTN8_NSC:
        raise RuntimeError(f"{path}: NSC {module.NSC}, expected {ATTN8_NSC}")
    return module, path


def attn8_plan(k: int, n_rows: int, nw: int, fwd: bool) -> tuple:
    """Switch 9d: (tb, cwid) of one kernel call: the forward contracts K = k over k / 128 slabs into chunks of each
    weight's n_rows outputs; the backward contracts the nw x n_rows outputs into chunks of the k inputs."""
    if fwd:
        return ATTN8_MODULE.plan(k // 128, n_rows, R2_ATTN8_FORMS, R2_ATTN8_TB)
    return ATTN8_MODULE.plan(nw * n_rows // 128, k, R2_ATTN8_FORMS, R2_ATTN8_TB)


def register_attn8_ops(module) -> str:
    """Switch 9d: the module's four kernels as four custom ops (the QKV projection with its three weights, c_proj with
    its one; each forward and its input gradient), registered as switch 9c registers its pair (nki_op or
    torch_library), with fake implementations of the kernels' allocations. AttnProj8 carries the autograd formula."""
    global ATTN8_OPS
    if R2_ROUTE != "compiled_customop" or R2_CUSTOMOP_FORM not in ("nki_op", "torch_library"):
        raise ValueError("switch 9d runs on the compiled custom-op route, form nki_op or torch_library")
    if R2_CUSTOMOP_FORM == "nki_op":
        from torch_neuronx import nki_op as make_op
    else:
        make_op = torch.library.custom_op
    fwd_kernel = module._launch(module._proj8_fwd_kernel)
    bwd_kernel = module._launch(module._proj8_bwd_kernel)
    fwd1_kernel = module._launch(module._proj8_fwd1_kernel)
    bwd1_kernel = module._launch(module._proj8_bwd1_kernel)
    forms = R2_ATTN8_FORMS
    m = module

    @make_op("s2attn8::qkv_fwd", mutates_args=())
    def qkv_fwd(x2: torch.Tensor, wq: torch.Tensor, wk: torch.Tensor, wv: torch.Tensor,
                sc: torch.Tensor) -> torch.Tensor:
        ATTN8_COUNTS["fwd_bodies"] += 1
        tb, cwid = attn8_plan(x2.shape[1], wq.shape[0], 3, True)
        return fwd_kernel(x2, wq, wk, wv, sc, m.SC_S_X, m.SC_S_WQKV, m.SC_DQ_QKV, tb, cwid, forms)

    @make_op("s2attn8::qkv_bwd", mutates_args=())
    def qkv_bwd(g2: torch.Tensor, wq: torch.Tensor, wk: torch.Tensor, wv: torch.Tensor,
                bc: torch.Tensor) -> torch.Tensor:
        ATTN8_COUNTS["bwd_bodies"] += 1
        tb, cwid = attn8_plan(wq.shape[1], wq.shape[0], 3, False)
        return bwd_kernel(g2, wq, wk, wv, bc, m.BC_S_G, m.BC_S_W, m.BC_DQ, tb, cwid, forms)

    @make_op("s2attn8::proj_fwd", mutates_args=())
    def proj_fwd(y2: torch.Tensor, wp: torch.Tensor, sc: torch.Tensor) -> torch.Tensor:
        ATTN8_COUNTS["fwd_bodies"] += 1
        tb, cwid = attn8_plan(y2.shape[1], wp.shape[0], 1, True)
        return fwd1_kernel(y2, wp, sc, m.SC_S_Y, m.SC_S_WPROJ, m.SC_DQ_PROJ, tb, cwid, forms)

    @make_op("s2attn8::proj_bwd", mutates_args=())
    def proj_bwd(g2: torch.Tensor, wp: torch.Tensor, bc: torch.Tensor) -> torch.Tensor:
        ATTN8_COUNTS["bwd_bodies"] += 1
        tb, cwid = attn8_plan(wp.shape[1], wp.shape[0], 1, False)
        return bwd1_kernel(g2, wp, bc, m.BC_S_G, m.BC_S_W, m.BC_DQ, tb, cwid, forms)

    fakes_by_name = {
        # The kernels' own allocations: the forward [M, nw x rows], the input gradient [M, K].
        "s2attn8::qkv_fwd": lambda x2, wq, wk, wv, sc: x2.new_empty(x2.shape[0], 3 * wq.shape[0]),
        "s2attn8::qkv_bwd": lambda g2, wq, wk, wv, bc: g2.new_empty(g2.shape[0], wq.shape[1]),
        "s2attn8::proj_fwd": lambda y2, wp, sc: y2.new_empty(y2.shape[0], wp.shape[0]),
        "s2attn8::proj_bwd": lambda g2, wp, bc: g2.new_empty(g2.shape[0], wp.shape[1]),
    }
    fakes = []
    for name, fake in fakes_by_name.items():
        try:
            torch.library.register_fake(name)(fake)
            fakes.append("ours")
        except Exception as err:
            fakes.append(f"the decorator's ({type(err).__name__})")
    ATTN8_OPS = {"qkv_fwd": qkv_fwd, "qkv_bwd": qkv_bwd, "proj_fwd": proj_fwd, "proj_bwd": proj_bwd}
    return (f"custom ops s2attn8::qkv_fwd / qkv_bwd / proj_fwd / proj_bwd by {R2_CUSTOMOP_FORM}, fake impls "
            f"{'/'.join(fakes)}, autograd by AttnProj8; fp8={R2_ATTN_FP8} set={'+'.join(R2_ATTN8_SET)} forms={forms}")


def setup_attn8_kernel(device: torch.device) -> str:
    """Switch 9d: load the kernel module and register its ops, once per process, before the model is built (main()
    and load_for_eval). Off a Neuron device the module's torch emulation runs instead. Returns the log line."""
    global ATTN8_READY, ATTN8_MODULE
    if not ATTN8_ON:
        return "off"
    if ATTN8_MODULE is None:
        ATTN8_MODULE, path = load_attn8_kernel_module()
    else:
        path = mlp_kernel_dir() / ATTN8_KERNEL_FILE
    tail = (f"{path} md5 {ATTN8_KERNEL_MD5}, fp8={R2_ATTN_FP8} set={'+'.join(R2_ATTN8_SET)} forms={R2_ATTN8_FORMS} "
            f"tb_max={R2_ATTN8_TB}")
    if device.type != "neuron":
        return f"emulation (not a Neuron device): {tail}"
    if not ATTN8_MODULE._HAS_NKI:
        raise RuntimeError(f"switch 9d needs nki on a Neuron device ({ATTN8_MODULE._NKI_ERROR})")
    if ATTN8_READY:
        return "on (registered earlier in this process)"
    how = register_attn8_ops(ATTN8_MODULE)
    ATTN8_READY = True
    return f"on: {how}; {tail}"


def attn8_fwd_rows(a2: torch.Tensor, ws: tuple, sc: torch.Tensor, kind: int) -> torch.Tensor:
    """Switch 9d: one fp8 forward on rows a2 [M, K] (M a multiple of 128 on a Neuron device): the kernel's op there,
    the module's emulation elsewhere. kind 0: the QKV projection (ws = c_q, c_k, c_v), 1: c_proj (ws = its weight)."""
    m = ATTN8_MODULE
    if a2.device.type == "neuron":
        if kind == 0:
            return ATTN8_OPS["qkv_fwd"](a2, ws[0], ws[1], ws[2], sc)
        return ATTN8_OPS["proj_fwd"](a2, ws[0], sc)
    row = sc[0]
    w = torch.cat(ws) if kind == 0 else ws[0]
    if kind == 0:
        return m.emulate_fwd(a2, w, row[m.SC_S_X], row[m.SC_S_WQKV], row[m.SC_DQ_QKV])
    return m.emulate_fwd(a2, w, row[m.SC_S_Y], row[m.SC_S_WPROJ], row[m.SC_DQ_PROJ])


def attn8_bwd_rows(g2: torch.Tensor, ws: tuple, bc: torch.Tensor, kind: int) -> torch.Tensor:
    """Switch 9d: one fp8 input gradient on rows g2 [M, N] with the call's tile bc (backward_tile's)."""
    m = ATTN8_MODULE
    if g2.device.type == "neuron":
        if kind == 0:
            return ATTN8_OPS["qkv_bwd"](g2, ws[0], ws[1], ws[2], bc)
        return ATTN8_OPS["proj_bwd"](g2, ws[0], bc)
    w = torch.cat(ws) if kind == 0 else ws[0]
    row = bc[0]
    return m.emulate_bwd(g2, w, row[m.BC_S_G], row[m.BC_S_W], row[m.BC_DQ])


class AttnProj8(torch.autograd.Function):
    """Switch 9d: one projection out = a2 @ W^T, W = [w0; w1; w2] (kind 0, the QKV projection) or w0 (kind 1, c_proj):
    the forward in fp8 under R2_ATTN_FP8 fwd or both (bf16 F.linear under bwd); the input gradient in fp8 under bwd
    or both (the bf16 matmul under fwd), its scales from this call's gradient in the backward graph; the weight
    gradient g^T a2 in bf16, the compiler's GEMM, as the kit's."""

    @staticmethod
    def forward(ctx, a2, sc, kind, w0, w1, w2):
        ws = (w0, w1, w2) if kind == 0 else (w0,)
        if ATTN8_MODE & 1:
            out = attn8_fwd_rows(a2, ws, sc, kind)
        else:
            out = F.linear(a2, torch.cat(ws) if kind == 0 else w0)
        ctx.save_for_backward(a2, sc, *ws)
        ctx.kind = kind
        return out

    @staticmethod
    def backward(ctx, g):
        saved = ctx.saved_tensors
        a2, sc, ws = saved[0], saved[1], tuple(saved[2:])
        kind = ctx.kind
        m = ATTN8_MODULE
        g = g.contiguous()
        if ATTN8_MODE & 2:
            row = sc[0]
            if kind == 0:
                bc = m.backward_tile(g, row[m.SC_S_WQKV], row[m.SC_I_WQKV])
            else:
                bc = m.backward_tile(g, row[m.SC_S_WPROJ], row[m.SC_I_WPROJ])
            dx = attn8_bwd_rows(g, ws, bc, kind)
        else:
            dx = g.mm(torch.cat(ws) if kind == 0 else ws[0])
        # Switch 9k: the weight gradient in fp8 on its route, else the compiler's bf16 GEMM.
        dw = attn8_weight_grad(g, a2, sc, bc, kind) if (DW8_QKV if kind == 0 else DW8_PROJ) else g.t().mm(a2)
        if kind == 0:
            n = ws[0].shape[0]
            return dx, None, None, dw[:n], dw[n:2 * n], dw[2 * n:]
        return dx, None, None, dw, None, None


def attn8_project(a: torch.Tensor, sc: torch.Tensor, kind: int, ws: tuple) -> torch.Tensor:
    """Switch 9d: a [b, t, K] through AttnProj8 to [b, t, N]: on a Neuron device the rows padded with zeros to a
    multiple of 128 for the kernels (each output element's sum runs in the same order whatever the row count, so every
    real row's output is its unpadded value bit for bit) and a shape the kernels do not take raises; off one the
    module's emulation."""
    b, t, k = a.shape
    a2 = a.reshape(b * t, k).contiguous()
    m = a2.size(0)
    pad = 0
    if a2.device.type == "neuron":
        if not (ATTN8_READY and a2.dtype == torch.bfloat16 and ATTN8_MODULE.shapes_apply(m, k, ws[0].size(0))):
            raise RuntimeError(f"switch 9d: the fp8 projection kernels do not take rows {tuple(a2.shape)} {a2.dtype} "
                               f"with weights {tuple(ws[0].shape)} (registered: {ATTN8_READY})")
        pad = (-m) % 128
        if pad:
            a2 = F.pad(a2, (0, 0, 0, pad))
    elif ATTN8_MODULE is None:
        raise RuntimeError("switch 9d: the kernel module is not loaded (setup_attn8_kernel)")
    if kind == 0:
        out = AttnProj8.apply(a2, sc, 0, ws[0], ws[1], ws[2])
    else:
        out = AttnProj8.apply(a2, sc, 1, ws[0], None, None)
    if pad:
        out = out[:m]
    return out.view(b, t, out.size(-1))


def attn8_qkv(attn: nn.Module, x: torch.Tensor) -> torch.Tensor:
    """Switch 9d: [q | k | v] = the fp8 projection of x [b, t, n_embd] by c_q, c_k and c_v, [b, t, 3 n_embd]."""
    ws = tuple(fold_in_weight(lin, x.dtype) for lin in (attn.c_q, attn.c_k, attn.c_v))     # (switch 9h's route)
    if R2_ATTN_PRECAST:
        # Switch 9g: the same projection, the weights' e4m3 bytes read from the layer's pack.
        return attn8pc_project(x, attn.attn8_sc, 0, ws, attn.attn8_w8)
    return attn8_project(x, attn.attn8_sc, 0, ws)


def attn8_proj(attn: nn.Module, y: torch.Tensor) -> torch.Tensor:
    """Switch 9d: c_proj of the attention output y [b, t, n_embd] in fp8."""
    if R2_ATTN_PRECAST:
        # Switch 9g: the same projection, the weight's e4m3 bytes read from the layer's pack.
        return attn8pc_project(y, attn.attn8_sc, 1, (fold_in_weight(attn.c_proj, y.dtype),), attn.attn8_w8)
    return attn8_project(y, attn.attn8_sc, 1, (fold_in_weight(attn.c_proj, y.dtype),))


@torch.no_grad()
def attn8_scales_into(wq_list: list, wk_list: list, wv_list: list, wp_list: list, ve_list: list, lam_list: list,
                      sc_list: list) -> None:
    """Switch 9d, once per optimizer step: every layer's scale tile from its four weights and, on a value-embedding
    layer, |ve_lambda| x the table's amax (the module's forward_scales), written into the attention modules' buffers
    in place, so the graphs read the same tensors every step and a new value never recompiles them."""
    for wq, wk, wv, wp, ve, lam, sc in zip(wq_list, wk_list, wv_list, wp_list, ve_list, lam_list, sc_list):
        if ve is None:
            vb = torch.zeros((), dtype=torch.float32, device=wq.device)
        else:
            vb = lam.detach().float().abs().amax() * ve.detach().float().abs().amax()
        sc.copy_(ATTN8_MODULE.sc_tile(ATTN8_MODULE.forward_scales(wq, wk, wv, wp, vb)))


def set_attn8_scale_fn(fn) -> None:
    """Switch 9d: main() hands over the compiled scale function (the model's backend)."""
    global ATTN8_SCALE_FN
    ATTN8_SCALE_FN = fn


def attn8_refresh_scales(model: nn.Module) -> None:
    """Switch 9d: fp8_refresh_weights' share: every layer's scale tile from its current weights (compiled in training,
    eager in load_for_eval: the same operations on the same values)."""
    blocks = model.transformer.h
    tables = model.value_embeds
    ves = [tables[str(i)].weight if tables is not None and str(i) in tables else None for i in range(len(blocks))]
    fn = ATTN8_SCALE_FN or attn8_scales_into
    fn([blk.attn.c_q.weight for blk in blocks], [blk.attn.c_k.weight for blk in blocks],
       [blk.attn.c_v.weight for blk in blocks], [blk.attn.c_proj.weight for blk in blocks], ves,
       [blk.ve_lambda for blk in blocks], [blk.attn.attn8_sc for blk in blocks])


def attn8_scales_line(model: nn.Module) -> str:
    """Switch 9d: the scales in force, one line: log2 of each layer's QKV weight, y and c_proj weight multipliers, the
    y bound and its value-embedding term, and the kernels' plans (tb x cwid) at this width."""
    m = ATTN8_MODULE
    rows = torch.stack([blk.attn.attn8_sc[0].detach().float().cpu() for blk in model.transformer.h])

    def log2s(col):
        return [int(v) for v in torch.log2(rows[:, col]).round().tolist()]

    w = model.transformer.h[0].attn.c_q.weight
    k, n = w.shape[1], w.shape[0]
    parts = []
    for name, nw, fwd in (("qkv_fwd", 3, True), ("qkv_bwd", 3, False), ("proj_fwd", 1, True), ("proj_bwd", 1, False)):
        tb, cwid = attn8_plan(k, n, nw, fwd)
        parts.append(f"{name}:{tb}x{cwid}")
    b_y = [round(v, 2) for v in rows[:, m.SC_B_Y].tolist()]
    vb = [round(v, 3) for v in rows[:, m.SC_VB].tolist()]
    return (f"log2_s_wqkv={log2s(m.SC_S_WQKV)} log2_s_y={log2s(m.SC_S_Y)} log2_s_wproj={log2s(m.SC_S_WPROJ)} "
            f"b_y={b_y} vb={vb} plans={','.join(parts)}")


def attn8_summary() -> str:
    """Switch 9d: the end-of-run line: the op bodies' counts and whether the ops were registered."""
    if not ATTN8_ON:
        return "off"
    return " ".join(f"{k}={v}" for k, v in ATTN8_COUNTS.items()) + (" registered" if ATTN8_READY else " not registered")


# ---- switch 9g: the attention projections' e4m3 weights cast once an optimizer step

ATTN8PC_KERNEL_FILE = "nki_attn_pc8.py"
ATTN8PC_KERNEL_MD5 = "91c0a0875b2a829e50d36fa4525a39c8"
ATTN8TT_KERNEL_FILE = "nki_attn_tt8.py"         # switch 9j: switch 9g's module byte for byte plus its two kernels
ATTN8TT_KERNEL_MD5 = "32046b16f05b6df98877bacfe1a355c2"
ATTN8TTG_KERNEL_FILE = "nki_attn_tt8g.py"       # switch 9q: switch 9j's module with one cast a PSUM group
ATTN8TTG_KERNEL_MD5 = "2f0d0c02a376e16c64b332f46c9747ba"


def attn8pc_file() -> tuple:
    """Switches 9g and 9j: the module's file, md5 and import name (9j's module in place of 9g's when R2_ATTN_TT)."""
    if R2_ATTN_TTG:
        return ATTN8TTG_KERNEL_FILE, ATTN8TTG_KERNEL_MD5, "s2_nki_attn_tt8g"     # switch 9q (it needs 9j)
    if R2_ATTN_TT:
        return ATTN8TT_KERNEL_FILE, ATTN8TT_KERNEL_MD5, "s2_nki_attn_tt8"
    return ATTN8PC_KERNEL_FILE, ATTN8PC_KERNEL_MD5, "s2_nki_attn_pc8"
ATTN8PC_U8 = 1                                  # fp8 bytes cross HBM as uint8 viewed on chip (switch 9f's device form)
ATTN8PC_MODULE = None
ATTN8PC_OPS: dict = {}
ATTN8PC_READY = False
ATTN8PC_COUNTS = {"fwd_bodies": 0, "bwd_bodies": 0, "precast_bodies": 0}   # op bodies only, as switch 9d's
ATTN8_PRECAST_FN = None                         # the per-step pre-cast; main() compiles it as the scale function is


def load_attn8pc_kernel_module():
    """Switch 9g: import ATTN8PC_KERNEL_FILE (in mlp_kernel_dir(), beside switch 9d's) after checking its md5, with no
    R1_* variable set while it imports. Returns (module, path)."""
    kfile, kmd5, kname = attn8pc_file()          # switch 9j's module when R2_ATTN_TT
    path = mlp_kernel_dir() / kfile
    digest = hashlib.md5(path.read_bytes()).hexdigest()
    if digest != kmd5:
        raise RuntimeError(f"{path} has md5 {digest}, expected {kmd5}")
    saved = {k: v for k, v in os.environ.items() if k.startswith("R1_")}
    for k in saved:
        del os.environ[k]
    try:
        spec = importlib.util.spec_from_file_location(kname, path)
        module = importlib.util.module_from_spec(spec)
        sys.modules[spec.name] = module
        spec.loader.exec_module(module)
    finally:
        os.environ.update(saved)
    if module.NSC != ATTN8_NSC or module.PACK_ROWS != 8:
        raise RuntimeError(f"{path}: NSC {module.NSC}, PACK_ROWS {module.PACK_ROWS}; expected {ATTN8_NSC}, 8")
    return module, path


def attn8pc_plans(d: int) -> tuple:
    """Switch 9g: the chunk widths of switch 9d's four kernels at width d (its plans, so the pack's tiles are the
    tiles those kernels would load): the QKV forward's, c_proj's forward's, the QKV backward's, c_proj's backward's."""
    return (attn8_plan(d, d, 3, True)[1], attn8_plan(d, d, 1, True)[1], attn8_plan(d, d, 3, False)[1],
            attn8_plan(d, d, 1, False)[1])


def register_attn8pc_ops(module) -> str:
    """Switch 9g: the module's pre-cast forms of switch 9d's four kernels and its pre-cast kernel as five custom ops
    (registered as switch 9d registers its four), with fake implementations of the kernels' allocations."""
    global ATTN8PC_OPS
    if R2_ROUTE != "compiled_customop" or R2_CUSTOMOP_FORM not in ("nki_op", "torch_library"):
        raise ValueError("switch 9g runs on the compiled custom-op route, form nki_op or torch_library")
    if R2_CUSTOMOP_FORM == "nki_op":
        from torch_neuronx import nki_op as make_op
    else:
        make_op = torch.library.custom_op
    # Switch 9j: its module's tt kernels in place of the pc kernels (the same arguments, switch 9g's outputs).
    fwd_kernel = module._launch(module._proj8_fwd_tt_kernel if R2_ATTN_TT else module._proj8_fwd_pc_kernel)
    bwd_kernel = module._launch(module._proj8_bwd_tt_kernel if R2_ATTN_TT else module._proj8_bwd_pc_kernel)
    pre_kernel = module._launch(module._attn8_precast_kernel)
    forms, u8, need = R2_ATTN8_FORMS, ATTN8PC_U8, ATTN8_MODE
    m = module

    @make_op("s2attn8p::qkv_fwd", mutates_args=())
    def qkv_fwd(x2: torch.Tensor, w8: torch.Tensor, sc: torch.Tensor) -> torch.Tensor:
        ATTN8PC_COUNTS["fwd_bodies"] += 1
        tb, cwid = attn8_plan(x2.shape[1], x2.shape[1], 3, True)
        return fwd_kernel(x2, w8, sc, 3, m.PK_FQKV, m.SC_S_X, m.SC_DQ_QKV, tb, cwid, forms, u8)

    @make_op("s2attn8p::qkv_bwd", mutates_args=())
    def qkv_bwd(g2: torch.Tensor, w8: torch.Tensor, bc: torch.Tensor) -> torch.Tensor:
        ATTN8PC_COUNTS["bwd_bodies"] += 1
        d = g2.shape[1] // 3
        tb, cwid = attn8_plan(d, d, 3, False)
        return bwd_kernel(g2, w8, bc, 3, m.PK_BQKV, m.BC_S_G, m.BC_DQ, tb, cwid, forms, u8)

    @make_op("s2attn8p::proj_fwd", mutates_args=())
    def proj_fwd(y2: torch.Tensor, w8: torch.Tensor, sc: torch.Tensor) -> torch.Tensor:
        ATTN8PC_COUNTS["fwd_bodies"] += 1
        tb, cwid = attn8_plan(y2.shape[1], y2.shape[1], 1, True)
        return fwd_kernel(y2, w8, sc, 1, m.PK_FPROJ, m.SC_S_Y, m.SC_DQ_PROJ, tb, cwid, forms, u8)

    @make_op("s2attn8p::proj_bwd", mutates_args=())
    def proj_bwd(g2: torch.Tensor, w8: torch.Tensor, bc: torch.Tensor) -> torch.Tensor:
        ATTN8PC_COUNTS["bwd_bodies"] += 1
        tb, cwid = attn8_plan(g2.shape[1], g2.shape[1], 1, False)
        return bwd_kernel(g2, w8, bc, 1, m.PK_BPROJ, m.BC_S_G, m.BC_DQ, tb, cwid, forms, u8)

    @make_op("s2attn8p::precast", mutates_args=())
    def precast(wq: torch.Tensor, wk: torch.Tensor, wv: torch.Tensor, wp: torch.Tensor,
                sc: torch.Tensor) -> torch.Tensor:
        ATTN8PC_COUNTS["precast_bodies"] += 1
        cwf, cwp, cwb, cwbp = attn8pc_plans(wq.shape[1])
        return pre_kernel(wq, wk, wv, wp, sc, need, cwf, cwp, cwb, cwbp, forms, u8)

    fakes_by_name = {
        # The kernels' own allocations: the forward [M, nw d], the input gradient [M, d], the pack [8, d^2] bytes.
        "s2attn8p::qkv_fwd": lambda x2, w8, sc: x2.new_empty(x2.shape[0], 3 * x2.shape[1]),
        "s2attn8p::qkv_bwd": lambda g2, w8, bc: g2.new_empty(g2.shape[0], g2.shape[1] // 3),
        "s2attn8p::proj_fwd": lambda y2, w8, sc: y2.new_empty(y2.shape[0], y2.shape[1]),
        "s2attn8p::proj_bwd": lambda g2, w8, bc: g2.new_empty(g2.shape[0], g2.shape[1]),
        "s2attn8p::precast": lambda wq, wk, wv, wp, sc: wq.new_empty(8, wq.shape[1] * wq.shape[1],
                                                                     dtype=torch.uint8),
    }
    fakes = []
    for name, fake in fakes_by_name.items():
        try:
            torch.library.register_fake(name)(fake)
            fakes.append("ours")
        except Exception as err:
            fakes.append(f"the decorator's ({type(err).__name__})")
    ATTN8PC_OPS = {"qkv_fwd": qkv_fwd, "qkv_bwd": qkv_bwd, "proj_fwd": proj_fwd, "proj_bwd": proj_bwd,
                   "precast": precast}
    return (f"custom ops s2attn8p::qkv_fwd / qkv_bwd / proj_fwd / proj_bwd / precast by {R2_CUSTOMOP_FORM}, fake impls "
            f"{'/'.join(fakes)}, autograd by AttnProj8PC; need={need} forms={forms} u8={u8}")


def setup_attn8pc_kernel(device: torch.device) -> str:
    """Switch 9g: load its module and register its ops, once per process, after switch 9d's (main() and
    load_for_eval). Off a Neuron device the module's emulation reads the pack. Returns the log line."""
    global ATTN8PC_READY, ATTN8PC_MODULE
    if not R2_ATTN_PRECAST:
        return "off"
    if ATTN8PC_MODULE is None:
        ATTN8PC_MODULE, path = load_attn8pc_kernel_module()
    else:
        path = mlp_kernel_dir() / attn8pc_file()[0]
    tail = (f"precast=1 need={ATTN8_MODE} forms={R2_ATTN8_FORMS}"
            + (f" tt={int(R2_ATTN_TT)}" if RECORD_ATTN8_TT else "") + f"; {path} md5 {attn8pc_file()[1]}")
    if device.type != "neuron":
        return f"emulation (not a Neuron device): {tail}"
    if not ATTN8PC_MODULE._HAS_NKI:
        raise RuntimeError(f"switch 9g needs nki on a Neuron device ({ATTN8PC_MODULE._NKI_ERROR})")
    if ATTN8PC_READY:
        return "on (registered earlier in this process)"
    how = register_attn8pc_ops(ATTN8PC_MODULE)
    ATTN8PC_READY = True
    return f"on: {how}; {tail}"


def attn8pc_fwd_rows(a2: torch.Tensor, w8: torch.Tensor, sc: torch.Tensor, kind: int) -> torch.Tensor:
    """Switch 9g: attn8_fwd_rows with the weights' bytes from the pack: the kernel's op on a Neuron device, the
    module's emulation of the same bytes elsewhere (switch 9d's emulation bit for bit)."""
    if a2.device.type == "neuron":
        return ATTN8PC_OPS["qkv_fwd" if kind == 0 else "proj_fwd"](a2, w8, sc)
    p, row, d = ATTN8PC_MODULE, sc[0], a2.shape[1]
    cwf, cwp, _cwb, _cwbp = attn8pc_plans(d)
    if kind == 0:
        return p.emulate_fwd_pc(a2, w8, 0, row[p.SC_S_X], row[p.SC_DQ_QKV], cwf)
    return p.emulate_fwd_pc(a2, w8, 1, row[p.SC_S_Y], row[p.SC_DQ_PROJ], cwp)


def attn8pc_bwd_rows(g2: torch.Tensor, w8: torch.Tensor, bc: torch.Tensor, kind: int) -> torch.Tensor:
    """Switch 9g: attn8_bwd_rows with the weights' bytes from the pack."""
    if g2.device.type == "neuron":
        return ATTN8PC_OPS["qkv_bwd" if kind == 0 else "proj_bwd"](g2, w8, bc)
    p, row = ATTN8PC_MODULE, bc[0]
    d = g2.shape[1] // (3 if kind == 0 else 1)
    _cwf, _cwp, cwb, cwbp = attn8pc_plans(d)
    return p.emulate_bwd_pc(g2, w8, kind, row[p.BC_S_G], row[p.BC_DQ], cwb if kind == 0 else cwbp)


class AttnProj8PC(torch.autograd.Function):
    """Switch 9g: AttnProj8 with the fp8 forward and input gradient reading the layer's pre-cast bytes w8 (switch
    9d's arithmetic bit for bit); the bf16 paths (R2_ATTN_FP8 fwd or bwd) and the bf16 weight gradient as there."""

    @staticmethod
    def forward(ctx, a2, sc, w8, kind, w0, w1, w2):
        ws = (w0, w1, w2) if kind == 0 else (w0,)
        if ATTN8_MODE & 1:
            out = attn8pc_fwd_rows(a2, w8, sc, kind)
        else:
            out = F.linear(a2, torch.cat(ws) if kind == 0 else w0)
        ctx.save_for_backward(a2, sc, w8, *ws)
        ctx.kind = kind
        return out

    @staticmethod
    def backward(ctx, g):
        saved = ctx.saved_tensors
        a2, sc, w8, ws = saved[0], saved[1], saved[2], tuple(saved[3:])
        kind = ctx.kind
        m = ATTN8_MODULE
        g = g.contiguous()
        if ATTN8_MODE & 2:
            row = sc[0]
            if kind == 0:
                bc = m.backward_tile(g, row[m.SC_S_WQKV], row[m.SC_I_WQKV])
            else:
                bc = m.backward_tile(g, row[m.SC_S_WPROJ], row[m.SC_I_WPROJ])
            dx = attn8pc_bwd_rows(g, w8, bc, kind)
        else:
            dx = g.mm(torch.cat(ws) if kind == 0 else ws[0])
        # Switch 9k: the weight gradient in fp8 on its route, else the compiler's bf16 GEMM.
        dw = attn8_weight_grad(g, a2, sc, bc, kind) if (DW8_QKV if kind == 0 else DW8_PROJ) else g.t().mm(a2)
        if kind == 0:
            n = ws[0].shape[0]
            return dx, None, None, None, dw[:n], dw[n:2 * n], dw[2 * n:]
        return dx, None, None, None, dw, None, None


def attn8pc_project(a: torch.Tensor, sc: torch.Tensor, kind: int, ws: tuple, w8: torch.Tensor) -> torch.Tensor:
    """Switch 9g: attn8_project through AttnProj8PC (the same row padding on a Neuron device); square bf16 weights
    only (a shape or dtype the pre-cast path does not take raises, on every device)."""
    b, t, k = a.shape
    a2 = a.reshape(b * t, k).contiguous()
    m = a2.size(0)
    pad = 0
    if a2.dtype != torch.bfloat16 or ws[0].shape != (k, k):
        raise RuntimeError(f"switch 9g: the pre-cast projections take bf16 rows and square weights, not "
                           f"{tuple(a2.shape)} {a2.dtype} with {tuple(ws[0].shape)}")
    if a2.device.type == "neuron":
        if not (ATTN8PC_READY and ATTN8PC_MODULE.shapes_apply_pc(m + (-m) % 128, k)):
            raise RuntimeError(f"switch 9g: the pre-cast kernels do not take rows {tuple(a2.shape)} (registered: "
                               f"{ATTN8PC_READY})")
        pad = (-m) % 128
        if pad:
            a2 = F.pad(a2, (0, 0, 0, pad))
    elif ATTN8PC_MODULE is None or ATTN8_MODULE is None:
        raise RuntimeError("switch 9g: the kernel modules are not loaded (setup_attn8_kernel, setup_attn8pc_kernel)")
    if kind == 0:
        out = AttnProj8PC.apply(a2, sc, w8, 0, ws[0], ws[1], ws[2])
    else:
        out = AttnProj8PC.apply(a2, sc, w8, 1, ws[0], None, None)
    if pad:
        out = out[:m]
    return out.view(b, t, out.size(-1))


@torch.no_grad()
def attn8_precast_into(wq_list: list, wk_list: list, wv_list: list, wp_list: list, sc_list: list,
                       w8_list: list) -> None:
    """Switch 9g, once per optimizer step after switch 9d's scales: every layer's e4m3 bytes from its four weights
    (in bf16, as the kernels read them) and the scale tile just written (the module's kernel on a Neuron device, its
    byte reference elsewhere), into the attention modules' buffers in place, so the graphs read the same tensors
    every step and a new value never recompiles them."""
    for wq, wk, wv, wp, sc, w8 in zip(wq_list, wk_list, wv_list, wp_list, sc_list, w8_list):
        bf = [w.to(torch.bfloat16) for w in (wq, wk, wv, wp)]
        if ATTN8PC_READY and w8.device.type == "neuron":
            w8.copy_(ATTN8PC_OPS["precast"](bf[0], bf[1], bf[2], bf[3], sc))
        else:
            cwf, cwp, cwb, cwbp = attn8pc_plans(wq.shape[1])
            w8.copy_(ATTN8PC_MODULE.precast_ref(bf[0], bf[1], bf[2], bf[3], sc[0].float(), cwf, cwp, cwb, cwbp,
                                                ATTN8_MODE))


def set_attn8_precast_fn(fn) -> None:
    """Switch 9g: main() hands over the compiled pre-cast function (the model's backend)."""
    global ATTN8_PRECAST_FN
    ATTN8_PRECAST_FN = fn


def attn8_precast_refresh(model: nn.Module) -> None:
    """Switch 9g: fp8_refresh_weights' share, after switch 9d's scales (compiled in training, eager in load_for_eval:
    the same operations on the same values)."""
    blocks = model.transformer.h
    fn = ATTN8_PRECAST_FN or attn8_precast_into
    fn([blk.attn.c_q.weight for blk in blocks], [blk.attn.c_k.weight for blk in blocks],
       [blk.attn.c_v.weight for blk in blocks], [blk.attn.c_proj.weight for blk in blocks],
       [blk.attn.attn8_sc for blk in blocks], [blk.attn.attn8_w8 for blk in blocks])


# >>> switches 9r and 9s block begin (lane THR10 build 2, work/p2/thr10/NOTES.md; thr10/b2/tools/apply_b2.py)
MLP_L4T_KERNEL_FILE = "nki_mlp_l4t.py"          # switch 9r: switch 9f's module, the pc kernels' loads by TensorE
MLP_L4T_KERNEL_MD5 = "c36b697298a6b97896d93e468b25623b"
SCSTAT_KERNEL_FILE = "nki_scstat.py"            # switch 9s: the scale refresh's statistics kernels
SCSTAT_KERNEL_MD5 = "3e15eb18265e1eafff96c2100f7e4f69"
SCSTAT_MODULE = None
SCSTAT_OPS: dict = {}
SCSTAT_READY = False


def load_mlp_l4t_kernel_module():
    """Switch 9r: load_mlp_l4_kernel_module's import for MLP_L4T_KERNEL_FILE (md5-pinned, under its own name, with no
    R1_* variable set while it imports). Returns (module, path)."""
    path = mlp_kernel_dir() / MLP_L4T_KERNEL_FILE
    digest = hashlib.md5(path.read_bytes()).hexdigest()
    if digest != MLP_L4T_KERNEL_MD5:
        raise RuntimeError(f"{path} has md5 {digest}, expected {MLP_L4T_KERNEL_MD5}")
    saved = {k: v for k, v in os.environ.items() if k.startswith("R1_")}
    for k in saved:
        del os.environ[k]
    try:
        spec = importlib.util.spec_from_file_location("s2_nki_mlp_l4t", path)
        module = importlib.util.module_from_spec(spec)
        sys.modules[spec.name] = module
        spec.loader.exec_module(module)
    finally:
        os.environ.update(saved)
    if module.NSC != MLP8_NSC or module.GQ != MLP_L4_GQ:
        raise RuntimeError(f"{path}: NSC {module.NSC}, GQ {module.GQ}; expected {MLP8_NSC}, {MLP_L4_GQ}")
    return module, path


def load_scstat_kernel_module():
    """Switch 9s: import SCSTAT_KERNEL_FILE (in mlp_kernel_dir()) after checking its md5, with no R1_* variable set
    while it imports. Returns (module, path)."""
    path = mlp_kernel_dir() / SCSTAT_KERNEL_FILE
    digest = hashlib.md5(path.read_bytes()).hexdigest()
    if digest != SCSTAT_KERNEL_MD5:
        raise RuntimeError(f"{path} has md5 {digest}, expected {SCSTAT_KERNEL_MD5}")
    saved = {k: v for k, v in os.environ.items() if k.startswith("R1_")}
    for k in saved:
        del os.environ[k]
    try:
        spec = importlib.util.spec_from_file_location("s2_nki_scstat", path)
        module = importlib.util.module_from_spec(spec)
        sys.modules[spec.name] = module
        spec.loader.exec_module(module)
    finally:
        os.environ.update(saved)
    if (module.ST_MLP, module.ST_ATTN, module.ST_AMAX) != (8, 16, 2):
        raise RuntimeError(f"{path}: statistics widths {module.ST_MLP}, {module.ST_ATTN}, {module.ST_AMAX}")
    return module, path


def register_scstat_ops(module) -> str:
    """Switch 9s: the module's three statistics kernels as custom ops (registered as switch 9c registers its pair),
    with fake implementations of the kernels' allocations."""
    global SCSTAT_OPS
    if R2_ROUTE != "compiled_customop" or R2_CUSTOMOP_FORM not in ("nki_op", "torch_library"):
        raise ValueError("switch 9s runs on the compiled custom-op route, form nki_op or torch_library")
    if R2_CUSTOMOP_FORM == "nki_op":
        from torch_neuronx import nki_op as make_op
    else:
        make_op = torch.library.custom_op
    mlp_k = module._launch(module._mlp_stats_kernel)
    attn_k = module._launch(module._attn_stats_kernel)
    amax_k = module._launch(module._amax_stats_kernel)

    @make_op("s2st::mlp", mutates_args=())
    def st_mlp(w_fc: torch.Tensor, w_proj: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor]:
        st, cs = mlp_k(w_fc, w_proj)
        return st, cs

    @make_op("s2st::attn", mutates_args=())
    def st_attn(wq: torch.Tensor, wk: torch.Tensor, wv: torch.Tensor, wp: torch.Tensor) -> torch.Tensor:
        return attn_k(wq, wk, wv, wp)

    @make_op("s2st::amax", mutates_args=())
    def st_amax(t: torch.Tensor) -> torch.Tensor:
        return amax_k(t)

    def mlp_fake(w_fc, w_proj):
        # The kernel's allocations: st [programs() x 128, 8] (each program's own rows), cs [128, F] fp32.
        return (w_fc.new_empty(module.programs() * 128, module.ST_MLP, dtype=torch.float32),
                w_fc.new_empty(128, w_fc.shape[0], dtype=torch.float32))

    def attn_fake(wq, wk, wv, wp):
        return wq.new_empty(module.programs() * 128, module.ST_ATTN, dtype=torch.float32)

    def amax_fake(t):
        return t.new_empty(module.programs() * 128, module.ST_AMAX, dtype=torch.float32)

    fakes = []
    for name, fake in (("s2st::mlp", mlp_fake), ("s2st::attn", attn_fake), ("s2st::amax", amax_fake)):
        try:
            torch.library.register_fake(name)(fake)
            fakes.append("ours")
        except Exception as err:
            fakes.append(f"the decorator's ({type(err).__name__})")
    SCSTAT_OPS = {"mlp": st_mlp, "attn": st_attn, "amax": st_amax}
    return f"custom ops s2st::mlp / attn / amax by {R2_CUSTOMOP_FORM}, fake impls {'/'.join(fakes)}"


def setup_scstat_kernel(device: torch.device) -> str:
    """Switch 9s: load the statistics module and register its ops, once per process (main() only: load_for_eval keeps
    the torch scale functions). Off a Neuron device nothing registers and the torch functions stay."""
    global SCSTAT_READY, SCSTAT_MODULE
    if not R2_REFRESH_STATS:
        return "off"
    if SCSTAT_MODULE is None:
        SCSTAT_MODULE, path = load_scstat_kernel_module()
    else:
        path = mlp_kernel_dir() / SCSTAT_KERNEL_FILE
    tail = f"{path} md5 {SCSTAT_KERNEL_MD5}"
    if device.type != "neuron":
        return f"not a Neuron device (the torch scale functions stay): {tail}"
    if not SCSTAT_MODULE._HAS_NKI:
        raise RuntimeError(f"switch 9s needs nki on a Neuron device ({SCSTAT_MODULE._NKI_ERROR})")
    if SCSTAT_READY:
        return "on (registered earlier in this process)"
    how = register_scstat_ops(SCSTAT_MODULE)
    SCSTAT_READY = True
    return f"on: {how}; {tail}"


def scstat_shapes_ok(name: str, *ts) -> None:
    """Switch 9s: the statistics kernels' shape rule (nki_scstat.py's docstring), checked as a function traces: every
    operand 2-D with its row count a multiple of 128 and at least 256 (each program of a split gets a row tile)."""
    for t in ts:
        if t.dim() != 2 or t.shape[0] % 128 != 0 or t.shape[0] < 256:
            raise ValueError(f"switch 9s: {name} got a {tuple(t.shape)} operand (rows a multiple of 128, at least 256)")


@torch.no_grad()
def mlp8_scales_stats_into(w_fc_list: list, w_proj_list: list, sc_list: list) -> None:
    """Switch 9s: mlp8_scales_into's rows from one statistics call a unit (nki_scstat.mlp_row with switch 9c's module
    functions), written into the MLPs' buffers in place, as mlp8_scales_into writes them."""
    for w_fc, w_proj, sc in zip(w_fc_list, w_proj_list, sc_list):
        scstat_shapes_ok("mlp8_scales_stats_into", w_fc, w_proj)
        if tuple(w_proj.shape) != (w_fc.shape[1], w_fc.shape[0]):
            raise ValueError(f"switch 9s: W_proj {tuple(w_proj.shape)} is not W_fc {tuple(w_fc.shape)} transposed")
        st, cs = SCSTAT_OPS["mlp"](w_fc.to(torch.bfloat16), w_proj.to(torch.bfloat16))
        sc.copy_(MLP8_MODULE.sc_tile(SCSTAT_MODULE.mlp_row(MLP8_MODULE, st, cs, w_fc.shape[1])))


@torch.no_grad()
def attn8_scales_stats_into(wq_list: list, wk_list: list, wv_list: list, wp_list: list, ve_list: list,
                            lam_list: list, sc_list: list) -> None:
    """Switch 9s: attn8_scales_into's rows from one statistics call a layer (nki_scstat.attn_row with switch 9d's
    module functions) and, on a value-embedding layer, |ve_lambda| x the table's exact amax from one call on the
    table, written into the attention modules' buffers in place, as attn8_scales_into writes them."""
    for wq, wk, wv, wp, ve, lam, sc in zip(wq_list, wk_list, wv_list, wp_list, ve_list, lam_list, sc_list):
        scstat_shapes_ok("attn8_scales_stats_into", wq, wk, wv, wp)
        if not tuple(wq.shape) == tuple(wk.shape) == tuple(wv.shape) == tuple(wp.shape) == (wq.shape[1],) * 2:
            raise ValueError(f"switch 9s: the attention weights are not one [d, d] shape ({tuple(wq.shape)})")
        st = SCSTAT_OPS["attn"](wq.to(torch.bfloat16), wk.to(torch.bfloat16), wv.to(torch.bfloat16),
                                wp.to(torch.bfloat16))
        if ve is None:
            vb = torch.zeros((), dtype=torch.float32, device=wq.device)
        else:
            scstat_shapes_ok("attn8_scales_stats_into (the value-embedding table)", ve)
            vb = lam.detach().float().abs().amax() * SCSTAT_MODULE.table_amax(SCSTAT_OPS["amax"](ve.detach().float()))
        sc.copy_(ATTN8_MODULE.sc_tile(SCSTAT_MODULE.attn_row(ATTN8_MODULE, st, vb, wq.shape[1])))
# <<< switches 9r and 9s block end


def attn8pc_summary() -> str:
    """Switch 9g: the end-of-run line: the op bodies' counts and whether the ops were registered."""
    if not R2_ATTN_PRECAST:
        return "off"
    return (" ".join(f"{k}={v}" for k, v in ATTN8PC_COUNTS.items())
            + (" registered" if ATTN8PC_READY else " not registered") + f" precast=1 need={ATTN8_MODE}"
            + (f" tt={int(R2_ATTN_TT)}" if RECORD_ATTN8_TT else ""))


# ---- switch 9k: the weight gradients in fp8

DW8_KERNEL_FILE = "nki_dw8.py"
DW8_KERNEL_MD5 = "0420bca18e05f9ab42f9287af0f7d251"
DW8T_KERNEL_FILE = "nki_dw8t.py"          # switch 9u: nki_dw8.py with the plan-driven a-side staging width
DW8T_KERNEL_MD5 = "a901fc72c59a95ed60a899215b8e9d9b"
if R2_DW8_TALL:
    DW8_KERNEL_FILE, DW8_KERNEL_MD5 = DW8T_KERNEL_FILE, DW8T_KERNEL_MD5
DW8_MODULE = None
DW8_OPS: dict = {}
DW8_READY = False
DW8_COUNTS = {"g5a4_bodies": 0, "g4ca5_bodies": 0}      # op bodies only, as switch 9d's


def load_dw8_kernel_module():
    """Switch 9k: import DW8_KERNEL_FILE (in mlp_kernel_dir(), beside switch 9c's) after checking its md5, with no R1_*
    variable set while it imports. Returns (module, path)."""
    path = mlp_kernel_dir() / DW8_KERNEL_FILE
    digest = hashlib.md5(path.read_bytes()).hexdigest()
    if digest != DW8_KERNEL_MD5:
        raise RuntimeError(f"{path} has md5 {digest}, expected {DW8_KERNEL_MD5}")
    saved = {k: v for k, v in os.environ.items() if k.startswith("R1_")}
    for k in saved:
        del os.environ[k]
    try:
        spec = importlib.util.spec_from_file_location("s2_nki_dw8", path)
        module = importlib.util.module_from_spec(spec)
        sys.modules[spec.name] = module
        spec.loader.exec_module(module)
    finally:
        os.environ.update(saved)
    if module.NDW != 3 or (module.FMT_E4M3, module.FMT_E5M2, module.FMT_E4M3C) != (0, 1, 2):
        raise RuntimeError(f"{path}: NDW {module.NDW} and its formats are not the ones this file passes")
    return module, path


def register_dw8_ops(module) -> str:
    """Switch 9k: the module's kernel as two custom ops, one a format pair (e5m2 x e4m3: c_fc, the QKV projection, the
    attention's c_proj; clamped e4m3 x e5m2: the MLP's c_proj), registered as switch 9d registers its four, with fake
    implementations of the kernel's allocation [O, D]."""
    global DW8_OPS
    if R2_ROUTE != "compiled_customop" or R2_CUSTOMOP_FORM not in ("nki_op", "torch_library"):
        raise ValueError("switch 9k runs on the compiled custom-op route, form nki_op or torch_library")
    if R2_CUSTOMOP_FORM == "nki_op":
        from torch_neuronx import nki_op as make_op
    else:
        make_op = torch.library.custom_op
    kernel = module._launch(module._dw8_kernel)
    forms = R2_DW8_FORMS
    e4, e5, e4c = module.FMT_E4M3, module.FMT_E5M2, module.FMT_E4M3C

    @make_op("s2dw8::g5a4", mutates_args=())
    def dw_g5a4(g2: torch.Tensor, a2: torch.Tensor, sc: torch.Tensor) -> torch.Tensor:
        DW8_COUNTS["g5a4_bodies"] += 1
        return kernel(g2, a2, sc, e5, e4, forms)

    @make_op("s2dw8::g4ca5", mutates_args=())
    def dw_g4ca5(g2: torch.Tensor, a2: torch.Tensor, sc: torch.Tensor) -> torch.Tensor:
        DW8_COUNTS["g4ca5_bodies"] += 1
        return kernel(g2, a2, sc, e4c, e5, forms)

    fakes = []
    for name in ("s2dw8::g5a4", "s2dw8::g4ca5"):
        try:
            # The kernel's own allocation: out [O, D] in the operands' dtype.
            torch.library.register_fake(name)(lambda g2, a2, sc: g2.new_empty(g2.shape[1], a2.shape[1]))
            fakes.append("ours")
        except Exception as err:
            fakes.append(f"the decorator's ({type(err).__name__})")
    DW8_OPS = {(e5, e4): dw_g5a4, (e4c, e5): dw_g4ca5}
    return (f"custom ops s2dw8::g5a4 / g4ca5 by {R2_CUSTOMOP_FORM}, fake impls {'/'.join(fakes)}, called from the "
            f"backward formulas of switches 9c and 9d; forms={forms}")


def setup_dw8_kernel(device: torch.device) -> str:
    """Switch 9k: load its module (on every device: off a Neuron device its emulation runs) and, on a Neuron device,
    register its ops, once per process, before the model is built (main()). Returns the log line."""
    global DW8_READY, DW8_MODULE
    if not R2_DW8:
        return "off"
    if DW8_MODULE is None:
        DW8_MODULE, path = load_dw8_kernel_module()
    else:
        path = mlp_kernel_dir() / DW8_KERNEL_FILE
    tail = (f"set={','.join(R2_DW8_SET)} forms={R2_DW8_FORMS} mlp_dw_mode="
            f"{'token (switch 9c token mode, R2_MLP_DW=' + R2_MLP_DW + ')' if DW8_MLP else 'unchanged'}; {path} md5 "
            f"{DW8_KERNEL_MD5}")
    if device.type != "neuron":
        return f"emulation (not a Neuron device): {tail}"
    if not DW8_MODULE._HAS_NKI:
        raise RuntimeError(f"switch 9k needs nki on a Neuron device ({DW8_MODULE._NKI_ERROR})")
    if DW8_READY:
        return "on (registered earlier in this process)"
    how = register_dw8_ops(DW8_MODULE)
    DW8_READY = True
    return f"on: {how}; {tail}"


def dw8_grad(g2: torch.Tensor, a2: torch.Tensor, s_g: torch.Tensor, i_g: torch.Tensor, s_a: torch.Tensor,
             i_a: torch.Tensor, fg: int, fa: int) -> torch.Tensor:
    """Switch 9k: one weight gradient g2^T a2 [O, D] in fp8, the g-side cast at s_g into format fg, the a-side at s_a
    into fa, the descale i_g x i_a (every value a power of two): the module's kernel on a Neuron device (rows padded
    with zeros to a multiple of 256: a zero row adds exact zeros), its emulation elsewhere. A shape the kernel does not
    take raises on a Neuron device (no silent bf16)."""
    m = DW8_MODULE
    row = m.dw_row(s_g, i_g, s_a, i_a)
    g2 = g2.contiguous()
    a2 = a2.contiguous()
    if g2.device.type == "neuron":
        rows = g2.size(0)
        pad = (-rows) % 256
        if not (DW8_READY and g2.dtype == torch.bfloat16 and a2.dtype == torch.bfloat16 and a2.size(0) == rows
                and m.shapes_apply(rows + pad, g2.size(1), a2.size(1))):
            raise RuntimeError(f"switch 9k: the fp8 weight-gradient kernel does not take {tuple(g2.shape)} x "
                               f"{tuple(a2.shape)} {g2.dtype} (registered: {DW8_READY})")
        if pad:
            g2 = F.pad(g2, (0, 0, 0, pad))
            a2 = F.pad(a2, (0, 0, 0, pad))
        return DW8_OPS[(fg, fa)](g2, a2, m.sc_tile(row))
    return m.emulate_dw(g2, a2, row[0], row[1], row[2], fg, fa)


def mlp8_weight_grads(module8, dy2: torch.Tensor, x2: torch.Tensor, h_out: torch.Tensor, dp_out: torch.Tensor,
                      dw_mode: int, sc_b: torch.Tensor):
    """Switch 9c's two weight gradients from its backward kernel's outputs (dw_fc [F, d], dw_proj [d, F]): under
    switch 9k (its mlp piece) the fp8 kernel on the token-major dpre and h: dw_fc = dpre^T x with dpre e5m2 at s_dp
    (the bytes 9c's phase B multiplies) and x e4m3 at 4 (its forward's), dw_proj = (h^T dy)^T with h e4m3 at s_h
    clamped at 240 and dy e5m2 at s_dy (its phase A's), or under mlpfc the module's bf16 token-mode dy^T h; else the
    module's bf16 expressions."""
    if not DW8_MLP:
        return module8.weight_grads(dy2, x2, h_out, dp_out, dw_mode)
    if dw_mode != 0:
        raise RuntimeError("switch 9k reads token-major h and dpre: switch 9c's backward must run in token mode")
    d8 = DW8_MODULE
    row = sc_b[0]
    s_dp, s_h, s_dy = row[module8.SC_S_DP], row[module8.SC_S_H], row[module8.SC_S_DY]
    s_x = torch.full_like(s_dp, module8.X_SCALE)
    dw_fc = dw8_grad(dp_out, x2, s_dp, d8.pow2_inv(s_dp), s_x, d8.pow2_inv(s_x), d8.FMT_E5M2, d8.FMT_E4M3)
    if not DW8_MLP_PJ:
        return dw_fc, dy2.t().mm(h_out)
    dw_pt = dw8_grad(h_out, dy2, s_h, d8.pow2_inv(s_h), s_dy, d8.pow2_inv(s_dy), d8.FMT_E4M3C, d8.FMT_E5M2)
    return dw_fc, dw_pt.t()


def attn8_weight_grad(g: torch.Tensor, a2: torch.Tensor, sc: torch.Tensor, bc: torch.Tensor, kind: int) -> torch.Tensor:
    """Switch 9k: a projection's weight gradient g^T a2 in fp8: the g-side e5m2 at this call's scale (bc, the one
    switch 9d's input-gradient kernel casts with), the a-side e4m3 at its forward's (x's constant 4 for the QKV
    projection, y's weight-derived scale for c_proj)."""
    m, d8 = ATTN8_MODULE, DW8_MODULE
    row = sc[0]
    s_g = bc[0][m.BC_S_G]
    s_a = row[m.SC_S_X] if kind == 0 else row[m.SC_S_Y]
    return dw8_grad(g, a2, s_g, d8.pow2_inv(s_g), s_a, d8.pow2_inv(s_a), d8.FMT_E5M2, d8.FMT_E4M3)


class EmulatedFusedMlp8DW8(torch.autograd.Function):
    """Switch 9k off a Neuron device (CPU proxies and proofs): switch 9c's emulation (its forward, and its fp8 backward
    with this call's dy scales, in token mode) with the two weight gradients from the fp8 emulation
    (mlp8_weight_grads)."""

    @staticmethod
    def forward(ctx, x2, w_fc, w_proj, sc, mode):
        row = sc[0]
        if mode & 1:
            y, rT = MLP8_MODULE.emulate8_forward(x2, w_fc, w_proj, row)
        else:
            y, rT = MLP8_MODULE.emulate_forward(x2, w_fc, w_proj)
        ctx.save_for_backward(x2, rT, w_fc, w_proj, sc)
        return y

    @staticmethod
    def backward(ctx, dy2):
        x2, rT, w_fc, w_proj, sc = ctx.saved_tensors
        dy2 = dy2.contiguous()
        sc_b = MLP8_MODULE.sc_tile(MLP8_MODULE.backward_scales(dy2, sc[0]))
        dx, h_out, dp_out = MLP8_MODULE.emulate8_backward(dy2, rT, w_fc, w_proj, sc_b[0], 0)
        dw_fc, dw_proj = mlp8_weight_grads(MLP8_MODULE, dy2, x2, h_out, dp_out, 0, sc_b)
        return dx, dw_fc, dw_proj, None, None


# ---- switch 67 (lane FP8MLP): the dense MLPs' c_fc weight gradient in fp8

FC8_OPS: dict = {}
FC8_READY = False
FC8_COUNTS = {"fwd_bodies": 0, "bwd_bodies": 0}      # op bodies only, as switch 9f's (nothing traced mutates it)


def fc8_weight_grads(module8, dy2: torch.Tensor, x2: torch.Tensor, h_out: torch.Tensor, dp_out: torch.Tensor,
                     sc_b: torch.Tensor):
    """Switch 67: a dense unit's two weight gradients from switch 9c's token-mode backward outputs (h and dpre
    [M, F]): dw_fc [F, d] = dpre^T x on switch 9k's kernel (dpre e5m2 at s_dp, x e4m3 at the constant 4) and dw_proj
    [d, F] = dy^T h in bf16: mlp8_weight_grads' two lines under mlpfc (lane FP8MLP's static check compares the syntax
    trees)."""
    d8 = DW8_MODULE
    row = sc_b[0]
    s_dp = row[module8.SC_S_DP]
    s_x = torch.full_like(s_dp, module8.X_SCALE)
    dw_fc = dw8_grad(dp_out, x2, s_dp, d8.pow2_inv(s_dp), s_x, d8.pow2_inv(s_x), d8.FMT_E5M2, d8.FMT_E4M3)
    if R2_FC8_PROJ:
        # Lane L2 (switch 67p): c_proj's weight gradient on the wide form of switch 9k's kernel ([d, F], no transpose).
        return dw_fc, fc8_proj_grad(module8, dy2, h_out, sc_b)
    return dw_fc, dy2.t().mm(h_out)


def register_fc8_ops(module8, module) -> str:
    """Switch 67: s2mlp8k::fwd (switch 9f's pre-cast forward kernel, the call s2mlp8l::fwd makes under
    R2_MLP_FP8=both) with its autograd formula: s2mlp8k::bwd (switch 9f's pre-cast backward kernel in token mode,
    dw_mode 0) with this call's dy scales computed in the backward graph as switch 9c computes them, then
    fc8_weight_grads. Registered as register_mlp_l4_ops registers s2mlp8l's pair (module is switch 9r's under
    R2_MLP_TT: the same two functions)."""
    global FC8_OPS
    if R2_ROUTE != "compiled_customop" or R2_CUSTOMOP_FORM not in ("nki_op", "torch_library"):
        raise ValueError("switch 67 runs on the compiled custom-op route, form nki_op or torch_library")
    if R2_CUSTOMOP_FORM == "nki_op":
        from torch_neuronx import nki_op as make_op
    else:
        make_op = torch.library.custom_op
    tb, forms, u8 = R2_MLP_TB, R2_MLP8_FORMS, MLP_L4_U8
    fwd_kernel = module8._launch(module._mlp8_fwd_pc_kernel)
    bwd_kernel = module8._launch(module._mlp8_bwd_pc_kernel)

    @make_op("s2mlp8k::fwd", mutates_args=())
    def fc8_fwd(x2: torch.Tensor, w_fc: torch.Tensor, w_proj: torch.Tensor, sc: torch.Tensor,
                w8: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor]:
        FC8_COUNTS["fwd_bodies"] += 1
        y, rT = fwd_kernel(x2, w8, sc, tb, forms, u8)
        return y, rT

    @make_op("s2mlp8k::bwd", mutates_args=())
    def fc8_bwd(dy2: torch.Tensor, rT: torch.Tensor, sc: torch.Tensor,
                w8: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
        FC8_COUNTS["bwd_bodies"] += 1
        dx, h_out, dp_out = bwd_kernel(dy2, rT, w8, sc, tb, 0, forms, u8)
        return dx, h_out, dp_out

    def fc8_fwd_fake(x2, w_fc, w_proj, sc, w8):
        # The kernel's own allocations: y [M, d], rT [F, M].
        return x2.new_empty(x2.shape[0], x2.shape[1]), x2.new_empty(w_fc.shape[0], x2.shape[0])

    def fc8_bwd_fake(dy2, rT, sc, w8):
        # dx [M, d]; h and dpre token-major [M, F] (dw_mode 0).
        m, f = dy2.shape[0], rT.shape[0]
        return dy2.new_empty(m, dy2.shape[1]), dy2.new_empty(m, f), dy2.new_empty(m, f)

    fakes = []
    for name, fake in (("s2mlp8k::fwd", fc8_fwd_fake), ("s2mlp8k::bwd", fc8_bwd_fake)):
        try:
            torch.library.register_fake(name)(fake)
            fakes.append("ours")
        except Exception as err:
            fakes.append(f"the decorator's ({type(err).__name__})")

    def setup_context(ctx, inputs, output):
        x2, _w_fc, _w_proj, sc, w8 = inputs
        _y, rT = output
        ctx.save_for_backward(x2, rT, sc, w8)
        ctx.mark_non_differentiable(rT)
        ctx.set_materialize_grads(False)

    def backward(ctx, dy2, _d_rT):
        x2, rT, sc, w8 = ctx.saved_tensors
        dy2 = dy2.contiguous()
        # The fp8 backward's scales: this call's dy amax and the dpre bound, in the backward graph (as switch 9c's).
        sc_b = module8.sc_tile(module8.backward_scales(dy2, sc[0]))
        dx, h_out, dp_out = fc8_bwd(dy2, rT, sc_b, w8)
        dw_fc, dw_proj = fc8_weight_grads(module8, dy2, x2, h_out, dp_out, sc_b)
        return dx, dw_fc, dw_proj, None, None

    torch.library.register_autograd("s2mlp8k::fwd", backward, setup_context=setup_context)
    FC8_OPS = {"fwd": fc8_fwd, "bwd": fc8_bwd}
    return (f"custom ops s2mlp8k::fwd / bwd by {R2_CUSTOMOP_FORM}, fake impls {fakes[0]} / {fakes[1]}, autograd by "
            f"torch.library.register_autograd; dw_mode=0 (token) tb={tb} forms={forms} u8={u8}")


def setup_fc8_kernel(device: torch.device) -> str:
    """Switch 67: register its op pair, once per process, in main() after switches 9f's and 9k's (training only:
    load_for_eval's forward is s2mlp8l::fwd's, the same kernel call). Off a Neuron device the dense units run
    EmulatedFusedMlp8FC8 (setup_dw8_kernel loads switch 9k's module on every device). Returns the log line."""
    global FC8_READY
    if not R2_FC8:
        return "off"
    if DW8_MODULE is None or MLP8_MODULE is None or MLP_L4_MODULE is None:
        raise RuntimeError("switch 67 needs switches 9c's, 9f's and 9k's modules loaded first (main() loads them)")
    tail = (f"the dense units on s2mlp8k: switch 9f's pre-cast pair, the backward in token mode, c_fc's weight "
            f"gradient on switch 9k's s2dw8::g5a4 ({DW8_KERNEL_FILE} md5 {DW8_KERNEL_MD5}), c_proj's bf16")
    if device.type != "neuron":
        return f"emulation (not a Neuron device): {tail}"
    if not (MLP_L4_READY and DW8_READY):
        raise RuntimeError("switch 67 needs switch 9f's and switch 9k's ops registered first")
    if FC8_READY:
        return "on (registered earlier in this process)"
    how = register_fc8_ops(MLP8_MODULE, MLP_L4_MODULE)
    FC8_READY = True
    return f"on: {how}; {tail}"


def fc8_summary(model: nn.Module) -> str:
    """Switch 67: the end-of-run line: the op bodies' counts, whether the ops were registered, and the dense units
    the route covers (every block's MLP that is not a MoE block's)."""
    dense = sum(1 for blk in model.transformer.h if not isinstance(blk.mlp, MoeMLP))
    return (" ".join(f"{k}={v}" for k, v in FC8_COUNTS.items()) + (" registered" if FC8_READY else " not registered")
            + f" dense_units={dense}")


class EmulatedFusedMlp8FC8(torch.autograd.Function):
    """Switch 67 off a Neuron device (CPU proxies and proofs): switch 9c's emulation (its fp8 forward, and its fp8
    backward with this call's dy scales, in token mode) with fc8_weight_grads (c_fc's from switch 9k's emulation)."""

    @staticmethod
    def forward(ctx, x2, w_fc, w_proj, sc):
        y, rT = MLP8_MODULE.emulate8_forward(x2, w_fc, w_proj, sc[0])
        ctx.save_for_backward(x2, rT, w_fc, w_proj, sc)
        return y

    @staticmethod
    def backward(ctx, dy2):
        x2, rT, w_fc, w_proj, sc = ctx.saved_tensors
        dy2 = dy2.contiguous()
        sc_b = MLP8_MODULE.sc_tile(MLP8_MODULE.backward_scales(dy2, sc[0]))
        dx, h_out, dp_out = MLP8_MODULE.emulate8_backward(dy2, rT, w_fc, w_proj, sc_b[0], 0)
        dw_fc, dw_proj = fc8_weight_grads(MLP8_MODULE, dy2, x2, h_out, dp_out, sc_b)
        return dx, dw_fc, dw_proj, None


# ---- lane L2 (switch 67p): the dense units' c_proj weight gradient in fp8 on the wide form of switch 9k's kernel

DW8W_KERNEL_FILE = "nki_dw8w.py"
DW8W_KERNEL_MD5 = "59b9882dfc825a165f410ff0252130eb"
DW8W_MODULE = None
DW8W_OPS: dict = {}
DW8W_READY = False
DW8W_COUNTS = {"g5a4c_bodies": 0, "g4a4c_bodies": 0}      # op bodies only, as switch 9k's
FC8P_DY4_SHIFT = 2.0 ** -7      # R2_FC8_PROJ_DY=e4m3: dy's e4m3 scale is s_dy x 2^-7 (amax x the scale in (112, 224])


def load_dw8w_kernel_module():
    """Lane L2: import DW8W_KERNEL_FILE (in mlp_kernel_dir(), beside switch 9k's) after checking its md5, with no R1_*
    variable set while it imports (switch 9k's loader with its own module name). Returns (module, path)."""
    path = mlp_kernel_dir() / DW8W_KERNEL_FILE
    digest = hashlib.md5(path.read_bytes()).hexdigest()
    if digest != DW8W_KERNEL_MD5:
        raise RuntimeError(f"{path} has md5 {digest}, expected {DW8W_KERNEL_MD5}")
    saved = {k: v for k, v in os.environ.items() if k.startswith("R1_")}
    for k in saved:
        del os.environ[k]
    try:
        spec = importlib.util.spec_from_file_location("s2_nki_dw8w", path)
        module = importlib.util.module_from_spec(spec)
        sys.modules[spec.name] = module
        spec.loader.exec_module(module)
    finally:
        os.environ.update(saved)
    if module.NDW != 3 or (module.FMT_E4M3, module.FMT_E5M2, module.FMT_E4M3C) != (0, 1, 2):
        raise RuntimeError(f"{path}: NDW {module.NDW} and its formats are not the ones this file passes")
    return module, path


def register_dw8w_ops(module) -> str:
    """Lane L2: the wide kernel as two custom ops, one a format pair (e5m2 dy x clamped e4m3 h; e4m3 dy x clamped e4m3
    h under R2_FC8_PROJ_DY=e4m3), registered as switch 9k registers its two, with fake implementations of the
    kernel's allocation [O, D]; the a-side group width is the module's group_width of D (1,536 at F 6,144)."""
    global DW8W_OPS
    if R2_ROUTE != "compiled_customop" or R2_CUSTOMOP_FORM not in ("nki_op", "torch_library"):
        raise ValueError("lane L2 runs on the compiled custom-op route, form nki_op or torch_library")
    if R2_CUSTOMOP_FORM == "nki_op":
        from torch_neuronx import nki_op as make_op
    else:
        make_op = torch.library.custom_op
    kernel = module._launch(module._dw8w_kernel)
    forms = R2_DW8_FORMS
    e4, e5, e4c = module.FMT_E4M3, module.FMT_E5M2, module.FMT_E4M3C

    @make_op("s2dw8w::g5a4c", mutates_args=())
    def dw_g5a4c(g2: torch.Tensor, a2: torch.Tensor, sc: torch.Tensor) -> torch.Tensor:
        DW8W_COUNTS["g5a4c_bodies"] += 1
        return kernel(g2, a2, sc, e5, e4c, forms, module.group_width(a2.shape[1]))

    @make_op("s2dw8w::g4a4c", mutates_args=())
    def dw_g4a4c(g2: torch.Tensor, a2: torch.Tensor, sc: torch.Tensor) -> torch.Tensor:
        DW8W_COUNTS["g4a4c_bodies"] += 1
        return kernel(g2, a2, sc, e4, e4c, forms, module.group_width(a2.shape[1]))

    fakes = []
    for name in ("s2dw8w::g5a4c", "s2dw8w::g4a4c"):
        try:
            # The kernel's own allocation: out [O, D] in the operands' dtype.
            torch.library.register_fake(name)(lambda g2, a2, sc: g2.new_empty(g2.shape[1], a2.shape[1]))
            fakes.append("ours")
        except Exception as err:
            fakes.append(f"the decorator's ({type(err).__name__})")
    DW8W_OPS = {(e5, e4c): dw_g5a4c, (e4, e4c): dw_g4a4c}
    return (f"custom ops s2dw8w::g5a4c / g4a4c by {R2_CUSTOMOP_FORM}, fake impls {'/'.join(fakes)}, called from "
            f"switch 67's backward; forms={forms}")


def setup_dw8w_kernel(device: torch.device) -> str:
    """Lane L2: load the wide module (on every device: off a Neuron device its emulation runs) and, on a Neuron
    device, register its ops, once per process, in main() after switch 67's (training only). Returns the log line."""
    global DW8W_READY, DW8W_MODULE
    if not R2_FC8_PROJ:
        return "off"
    if DW8W_MODULE is None:
        DW8W_MODULE, path = load_dw8w_kernel_module()
    else:
        path = mlp_kernel_dir() / DW8W_KERNEL_FILE
    tail = (f"the dense units' c_proj weight gradient dy^T h [d, F] on {path} md5 {DW8W_KERNEL_MD5}: dy "
            f"{R2_FC8_PROJ_DY} x h e4m3 clamped, forms={R2_DW8_FORMS}")
    if device.type != "neuron":
        return f"emulation (not a Neuron device): {tail}"
    if not DW8W_MODULE._HAS_NKI:
        raise RuntimeError(f"lane L2 needs nki on a Neuron device ({DW8W_MODULE._NKI_ERROR})")
    if not FC8_READY:
        raise RuntimeError("lane L2 needs switch 67's ops registered first")
    if DW8W_READY:
        return "on (registered earlier in this process)"
    how = register_dw8w_ops(DW8W_MODULE)
    DW8W_READY = True
    return f"on: {how}; {tail}"


def dw8w_grad(g2: torch.Tensor, a2: torch.Tensor, s_g: torch.Tensor, i_g: torch.Tensor, s_a: torch.Tensor,
              i_a: torch.Tensor, fg: int, fa: int) -> torch.Tensor:
    """Lane L2: one weight gradient g2^T a2 [O, D] in fp8 on the wide kernel (dw8_grad's contract: the g-side cast at
    s_g into fg, the a-side at s_a into fa, the descale i_g x i_a, every value a power of two; rows padded with zeros
    to a multiple of 256 on a Neuron device), the module's emulate_dw elsewhere. A shape the kernel does not take
    raises on a Neuron device (no silent bf16)."""
    m = DW8W_MODULE
    row = m.dw_row(s_g, i_g, s_a, i_a)
    g2 = g2.contiguous()
    a2 = a2.contiguous()
    if g2.device.type == "neuron":
        rows = g2.size(0)
        pad = (-rows) % 256
        if not (DW8W_READY and g2.dtype == torch.bfloat16 and a2.dtype == torch.bfloat16 and a2.size(0) == rows
                and m.shapes_apply_w(rows + pad, g2.size(1), a2.size(1))):
            raise RuntimeError(f"lane L2: the wide fp8 weight-gradient kernel does not take {tuple(g2.shape)} x "
                               f"{tuple(a2.shape)} {g2.dtype} (registered: {DW8W_READY})")
        if pad:
            g2 = F.pad(g2, (0, 0, 0, pad))
            a2 = F.pad(a2, (0, 0, 0, pad))
        return DW8W_OPS[(fg, fa)](g2, a2, m.sc_tile(row))
    return m.emulate_dw(g2, a2, row[0], row[1], row[2], fg, fa)


def fc8_proj_grad(module8, dy2: torch.Tensor, h_out: torch.Tensor, sc_b: torch.Tensor) -> torch.Tensor:
    """Lane L2: a dense unit's c_proj weight gradient dw_proj [d, F] = dy^T h in fp8 from switch 9r's token-mode
    backward outputs: dy e5m2 at the backward's s_dy (R2_FC8_PROJ_DY=e4m3: e4m3 at s_dy x 2^-7), h e4m3 clamped at the
    forward's s_h (switch 9k's mlp-set format), on dw8w_grad."""
    d8 = DW8W_MODULE
    if d8 is None:
        raise RuntimeError("lane L2: the wide module is not loaded (main() runs setup_dw8w_kernel)")
    row = sc_b[0]
    s_h, s_dy = row[module8.SC_S_H], row[module8.SC_S_DY]
    if R2_FC8_PROJ_DY == "e4m3":
        s_g, fg = s_dy * FC8P_DY4_SHIFT, d8.FMT_E4M3
    else:
        s_g, fg = s_dy, d8.FMT_E5M2
    return dw8w_grad(dy2, h_out, s_g, d8.pow2_inv(s_g), s_h, d8.pow2_inv(s_h), fg, d8.FMT_E4M3C)


def dw8w_summary() -> str:
    """Lane L2: the end-of-run line: the op bodies' counts, whether the ops were registered, and dy's format."""
    return (" ".join(f"{k}={v}" for k, v in DW8W_COUNTS.items()) + (" registered" if DW8W_READY else " not registered")
            + f" dy={R2_FC8_PROJ_DY}")


# ---- switch 65 (lane NSK): the experts' Newton-Schulz kernel

NSK_KERNEL_FILE = "nki_nsk.py"
NSK_KERNEL_MD5 = "5712f4a311057681529146a639ee622e"
NSK_MODULE = None
NSK_OPS: dict = {}
NSK_READY = False
NSK_COUNTS = {"bodies": 0, "steps": 0}       # op bodies (as switch 9k's) and pair steps


def load_nsk_kernel_module():
    """Switch 65: import NSK_KERNEL_FILE (in mlp_kernel_dir(), beside switch 9c's) after checking its md5, with no R1_*
    variable set while it imports; its coefficients must be POLAR_EXPRESS_COEFFS. Returns (module, path)."""
    path = mlp_kernel_dir() / NSK_KERNEL_FILE
    digest = hashlib.md5(path.read_bytes()).hexdigest()
    if digest != NSK_KERNEL_MD5:
        raise RuntimeError(f"{path} has md5 {digest}, expected {NSK_KERNEL_MD5}")
    saved = {k: v for k, v in os.environ.items() if k.startswith("R1_")}
    for k in saved:
        del os.environ[k]
    try:
        spec = importlib.util.spec_from_file_location("s2_nki_nsk", path)
        module = importlib.util.module_from_spec(spec)
        sys.modules[spec.name] = module
        spec.loader.exec_module(module)
    finally:
        os.environ.update(saved)
    if tuple(tuple(float(v) for v in c) for c in POLAR_EXPRESS_COEFFS) != tuple(module.NSK_COEFFS):
        raise RuntimeError(f"{path}: its Polar Express coefficients are not this file's POLAR_EXPRESS_COEFFS")
    return module, path


def register_nsk_ops(module) -> str:
    """Switch 65: the module's kernel as one custom op, s2nsk::ns5 (both stacks in, four tensors out), registered as
    switch 9k registers its two, with a fake implementation of the kernel's allocations."""
    global NSK_OPS
    if R2_ROUTE != "compiled_customop" or R2_CUSTOMOP_FORM not in ("nki_op", "torch_library"):
        raise ValueError("switch 65 runs on the compiled custom-op route, form nki_op or torch_library")
    if R2_CUSTOMOP_FORM == "nki_op":
        from torch_neuronx import nki_op as make_op
    else:
        make_op = torch.library.custom_op
    kernel = module._launch(module._nsk_kernel)

    @make_op("s2nsk::ns5", mutates_args=())
    def nsk_ns5_op(ga: torch.Tensor, gb: torch.Tensor,
                   sc: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
        NSK_COUNTS["bodies"] += 1
        ya, yb, va, vb = kernel(ga, gb, sc)
        return ya, yb, va, vb

    def nsk_ns5_fake(ga, gb, sc):
        # The kernel's own allocations: X5 of both stacks in bf16, the row statistics [K, M] and [K2, M] in fp32.
        return (ga.new_empty(ga.shape, dtype=torch.bfloat16), gb.new_empty(gb.shape, dtype=torch.bfloat16),
                ga.new_empty(ga.shape[0], ga.shape[1], dtype=torch.float32),
                gb.new_empty(gb.shape[0], gb.shape[2], dtype=torch.float32))

    try:
        torch.library.register_fake("s2nsk::ns5")(nsk_ns5_fake)
        fake = "ours"
    except Exception as err:
        fake = f"the decorator's ({type(err).__name__})"
    NSK_OPS = {"ns5": nsk_ns5_op}
    return f"custom op s2nsk::ns5 by {R2_CUSTOMOP_FORM}, fake impl {fake}, called from muon_math_pair_nsk"


def setup_nsk_kernel(device: torch.device) -> str:
    """Switch 65: load its module (on every device: off a Neuron device its emulation runs) and, on a Neuron device,
    register its op, once per process, before the model is built (main()). Returns the log line."""
    global NSK_READY, NSK_MODULE
    if not R2_NSK:
        return "off"
    if NSK_MODULE is None:
        NSK_MODULE, path = load_nsk_kernel_module()
    else:
        path = mlp_kernel_dir() / NSK_KERNEL_FILE
    tail = f"{path} md5 {NSK_KERNEL_MD5}"
    if device.type != "neuron":
        return f"emulation (not a Neuron device): {tail}"
    if not NSK_MODULE._HAS_NKI:
        raise RuntimeError(f"switch 65 needs nki on a Neuron device ({NSK_MODULE._NKI_ERROR})")
    if NSK_READY:
        return "on (registered earlier in this process)"
    how = register_nsk_ops(NSK_MODULE)
    NSK_READY = True
    return f"on: {how}; {tail}"


def nsk_takes(ga: torch.Tensor, gb: torch.Tensor) -> bool:
    """Switch 65: whether the kernel takes this pair: fp32 stacks [K, M, N] and their transposed twin [K2, N, M] of
    a shape the module's shapes_apply accepts (its rule and its SBUF plan)."""
    return (ga.dtype == torch.float32 and gb.dtype == torch.float32 and ga.dim() == 3 and gb.dim() == 3
            and tuple(gb.shape[1:]) == (ga.shape[2], ga.shape[1])
            and NSK_MODULE.shapes_apply(ga.shape[1], ga.shape[2]))


def nsk_ns5(ga: torch.Tensor, gb: torch.Tensor, d_a: torch.Tensor, d_b: torch.Tensor):
    """Switch 65: the kernel's four outputs (X5 of the tall stack ga [K, M, N] and of the wide gb [K2, N, M], bf16,
    and their row sums of squares, [K, M] and [K2, M] fp32) from the lerped fp32 gradients and their denominators:
    the custom op on a Neuron device (a pair it does not take raises: no silent fallback), the module's emulation
    elsewhere."""
    m = NSK_MODULE
    if ga.device.type == "neuron":
        if not (NSK_READY and nsk_takes(ga, gb)):
            raise RuntimeError(f"switch 65: the kernel does not take {tuple(ga.shape)} and {tuple(gb.shape)} "
                               f"{ga.dtype} (registered: {NSK_READY})")
        ya, yb, va, vb = NSK_OPS["ns5"](ga.contiguous(), gb.contiguous(), m.sc_tile(d_a, d_b))
    else:
        ya, yb, va, vb = m.emulate_nsk(ga, gb, d_a, d_b)
    return ya, yb, va, vb


def nsk_summary() -> str:
    """Switch 65: the end-of-run line: the op bodies, the pair steps and whether the op was registered."""
    return (f"bodies={NSK_COUNTS['bodies']} steps={NSK_COUNTS['steps']}"
            + (" registered" if NSK_READY else " not registered"))


def dw8_summary() -> str:
    """Switch 9k: the end-of-run line: the op bodies' counts and whether the ops were registered."""
    if not R2_DW8:
        return "off"
    return (" ".join(f"{k}={v}" for k, v in DW8_COUNTS.items())
            + (" registered" if DW8_READY else " not registered") + f" set={','.join(R2_DW8_SET)}")


# ---- switch 9m: the RMSNorm folded into the fp8 projections' forward kernels

NF_ATTN_KERNEL_FILE = "nki_attn_nf8.py"
NF_ATTN_KERNEL_MD5 = "2e97a1eb2913edf097978fab1bd641aa"
NF_MLP_KERNEL_FILE = "nki_mlp_nf8.py"
NF_MLP_KERNEL_MD5 = "dfd25cfa03a36ccb5125e1118ef4415d"
NF_EPS = 2.0 ** -23                             # F.rms_norm's eps for bf16 inputs (the opmath type's epsilon)
NF_ATTN_MODULE = None
NF_MLP_MODULE = None
NF_OPS: dict = {}
NF_READY = False
NF_COUNTS = {"qkv_bodies": 0, "mlp_bodies": 0}  # op bodies only, as switch 9d's


def load_nf_kernel_module(fname: str, want: str, name: str):
    """Switch 9m: import one of its modules (in mlp_kernel_dir(), beside switch 9g's) after checking its md5, with no
    R1_* variable set while it imports. Returns (module, path)."""
    path = mlp_kernel_dir() / fname
    digest = hashlib.md5(path.read_bytes()).hexdigest()
    if digest != want:
        raise RuntimeError(f"{path} has md5 {digest}, expected {want}")
    saved = {k: v for k, v in os.environ.items() if k.startswith("R1_")}
    for k in saved:
        del os.environ[k]
    try:
        spec = importlib.util.spec_from_file_location(name, path)
        module = importlib.util.module_from_spec(spec)
        sys.modules[spec.name] = module
        spec.loader.exec_module(module)
    finally:
        os.environ.update(saved)
    return module, path


def register_nf_ops() -> str:
    """Switch 9m: the norm-fused forward kernels as custom ops (registered as switch 9g registers its ops: nki_op or
    torch_library), with fake implementations of the kernels' allocations. NormProj8PC and NormMlp8 carry the
    autograd formulas (the base's input-gradient kernels and weight gradients, then the norm's backward)."""
    global NF_OPS
    if R2_ROUTE != "compiled_customop" or R2_CUSTOMOP_FORM not in ("nki_op", "torch_library"):
        raise ValueError("switch 9m runs on the compiled custom-op route, form nki_op or torch_library")
    if R2_CUSTOMOP_FORM == "nki_op":
        from torch_neuronx import nki_op as make_op
    else:
        make_op = torch.library.custom_op
    ops, fakes = {}, []
    if NF_ATTN:
        ma = NF_ATTN_MODULE
        qkv_kernel = ma._launch(ma._proj8_fwd_nf_kernel)
        aforms, au8 = R2_ATTN8_FORMS, ATTN8PC_U8

        @make_op("s2nf8::qkv_fwd", mutates_args=())
        def nf_qkv_fwd(x2: torch.Tensor, w8: torch.Tensor,
                       sc: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
            NF_COUNTS["qkv_bodies"] += 1
            tb, cwid = attn8_plan(x2.shape[1], x2.shape[1], 3, True)
            return qkv_kernel(x2, w8, sc, 3, ma.PK_FQKV, ma.SC_S_X, ma.SC_DQ_QKV, tb, cwid, aforms, au8)

        def nf_qkv_fake(x2, w8, sc):
            # The kernel's allocations: qkv [M, 3 d], xn [M, d], rs [M, 1] fp32.
            m, d = x2.shape
            return x2.new_empty(m, 3 * d), x2.new_empty(m, d), x2.new_empty(m, 1, dtype=torch.float32)

        ops["qkv_fwd"] = nf_qkv_fwd
        try:
            torch.library.register_fake("s2nf8::qkv_fwd")(nf_qkv_fake)
            fakes.append("ours")
        except Exception as err:
            fakes.append(f"the decorator's ({type(err).__name__})")
    if NF_MLP:
        mm = NF_MLP_MODULE
        mlp_kernel = mm._launch(mm._mlp8_fwd_nf_kernel)
        tb8, mforms, mu8 = R2_MLP_TB, R2_MLP8_FORMS, MLP_L4_U8

        @make_op("s2nf8::mlp_fwd", mutates_args=())
        def nf_mlp_fwd(x2: torch.Tensor, w8: torch.Tensor,
                       sc: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
            NF_COUNTS["mlp_bodies"] += 1
            return mlp_kernel(x2, w8, sc, tb8, mforms, mu8)

        def nf_mlp_fake(x2, w8, sc):
            # The kernel's allocations: y [M, d], rT [F, M], xn [M, d], rs [M, 1] fp32 (F from the pack's row).
            m, d = x2.shape
            f = w8.shape[1] // d
            return (x2.new_empty(m, d), x2.new_empty(f, m), x2.new_empty(m, d),
                    x2.new_empty(m, 1, dtype=torch.float32))

        ops["mlp_fwd"] = nf_mlp_fwd
        try:
            torch.library.register_fake("s2nf8::mlp_fwd")(nf_mlp_fake)
            fakes.append("ours")
        except Exception as err:
            fakes.append(f"the decorator's ({type(err).__name__})")
    NF_OPS = ops
    return (f"custom ops {' / '.join('s2nf8::' + k for k in ops)} by {R2_CUSTOMOP_FORM}, fake impls "
            f"{'/'.join(fakes)}, autograd by NormProj8PC / NormMlp8")


def setup_nf_kernels(device: torch.device) -> str:
    """Switch 9m: load its modules and register its ops, once per process, after switches 9f's and 9g's (main() and
    load_for_eval). Off a Neuron device the routes run F.rms_norm's composite and 9g's / 9c's emulation (the base's
    CPU routes). Returns the log line."""
    global NF_READY, NF_ATTN_MODULE, NF_MLP_MODULE
    if not NF_ON:
        return "off"
    if R2_HEADGATE:
        raise ValueError("R2_NORM_FUSE (switch 9m) hands the attention the pre-norm stream, and switch 18's head gate "
                         "reads the normalised one: run them separately")
    if NF_ATTN and NF_ATTN_MODULE is None:
        NF_ATTN_MODULE, _p = load_nf_kernel_module(NF_ATTN_KERNEL_FILE, NF_ATTN_KERNEL_MD5, "s2_nki_attn_nf8")
    if NF_MLP and NF_MLP_MODULE is None:
        NF_MLP_MODULE, _p = load_nf_kernel_module(NF_MLP_KERNEL_FILE, NF_MLP_KERNEL_MD5, "s2_nki_mlp_nf8")
    tail = (f"norm_fuse={R2_NORM_FUSE}" + (f"; {NF_ATTN_KERNEL_FILE} md5 {NF_ATTN_KERNEL_MD5}" if NF_ATTN else "")
            + (f"; {NF_MLP_KERNEL_FILE} md5 {NF_MLP_KERNEL_MD5}" if NF_MLP else ""))
    if device.type != "neuron":
        return f"emulation (not a Neuron device): {tail}"
    for mod in (NF_ATTN_MODULE, NF_MLP_MODULE):
        if mod is not None and not mod._HAS_NKI:
            raise RuntimeError(f"switch 9m needs nki on a Neuron device ({mod._NKI_ERROR})")
    if NF_READY:
        return "on (registered earlier in this process)"
    how = register_nf_ops()
    NF_READY = True
    return f"on: {how}; {tail}"


def nf_norm_rows(x2: torch.Tensor):
    """Switch 9m off a Neuron device: F.rms_norm's composite on [M, d] rows, op for op (bitwise F.rms_norm(x2, (d,))):
    (xn in x2's dtype, rs [M, 1] fp32)."""
    up = x2.float()
    rs = torch.rsqrt(up.pow(2).mean(-1, keepdim=True) + NF_EPS)
    return (up * rs).to(x2.dtype), rs


def nf_norm_backward(g: torch.Tensor, x2: torch.Tensor, rs: torch.Tensor) -> torch.Tensor:
    """Switch 9m: the gradient of F.rms_norm's composite with respect to its bf16 input x2 [M, d] from the gradient g
    of its output, autograd's arithmetic op for op (ToCopy, Mul (up rs), Rsqrt, Add (eps), Mean, Pow (2), ToCopy:
    lane L1's backward_torch, its bf16 branch) on the saved x2 and rs: bitwise autograd of F.rms_norm on CPU for the
    same rs."""
    up = x2.float()
    gf = g.float()
    g_up = gf * rs
    g_rs = (gf * up).sum(-1, keepdim=True)
    g_ms = (g_rs * -0.5) * rs.pow(3)
    g_sq = g_ms.expand_as(up) / x2.shape[1]
    g_pow = g_sq * (up * 2.0)
    return (g_up + g_pow).to(x2.dtype)


class NormProj8PC(torch.autograd.Function):
    """Switch 9m: the attention-side norm and switch 9g's fp8 QKV projection. Forward (x2 the pre-norm rows): the
    norm-fused kernel's op on a Neuron device (qkv, xn, rs), F.rms_norm's composite and 9g's emulation elsewhere.
    Backward: AttnProj8PC's on the saved xn (9g's fp8 input gradient under R2_ATTN_FP8 both, the bf16 matmul under
    fwd; the bf16 weight gradient g^T xn), then the norm's backward on the saved x2 and rs."""

    @staticmethod
    def forward(ctx, x2, sc, w8, w0, w1, w2):
        if x2.device.type == "neuron":
            out, xn, rs = NF_OPS["qkv_fwd"](x2, w8, sc)
        else:
            xn, rs = nf_norm_rows(x2)
            out = attn8pc_fwd_rows(xn, w8, sc, 0)
        ctx.save_for_backward(x2, xn, rs, sc, w8, w0, w1, w2)
        return out

    @staticmethod
    def backward(ctx, g):
        x2, xn, rs, sc, w8, w0, w1, w2 = ctx.saved_tensors
        m = ATTN8_MODULE
        g = g.contiguous()
        if ATTN8_MODE & 2:
            row = sc[0]
            bc = m.backward_tile(g, row[m.SC_S_WQKV], row[m.SC_I_WQKV])
            dxn = attn8pc_bwd_rows(g, w8, bc, 0)
        else:
            dxn = g.mm(torch.cat((w0, w1, w2)))
        dw = g.t().mm(xn)
        n = w0.shape[0]
        return nf_norm_backward(dxn, x2, rs), None, None, dw[:n], dw[n:2 * n], dw[2 * n:]


def attn8nf_qkv(attn: nn.Module, x: torch.Tensor) -> torch.Tensor:
    """Switch 9m: attn8_qkv of norm(x) with the norm inside switch 9g's QKV forward kernel; x [b, t, n_embd] is the
    block's stream before the attention-side norm. On a Neuron device the rows are padded with zeros to a multiple of
    128 (a zero row normalises to zero, as attn8pc_project's padded rows are zero); a shape the kernel does not take
    raises."""
    ws = tuple(fold_in_weight(lin, x.dtype) for lin in (attn.c_q, attn.c_k, attn.c_v))     # (switch 9h's route)
    b, t, k = x.shape
    x2 = x.reshape(b * t, k).contiguous()
    m = x2.size(0)
    pad = 0
    if x2.dtype != torch.bfloat16 or ws[0].shape != (k, k):
        raise RuntimeError(f"switch 9m: the norm-fused QKV projection takes bf16 rows and square weights, not "
                           f"{tuple(x2.shape)} {x2.dtype} with {tuple(ws[0].shape)}")
    if x2.device.type == "neuron":
        if not (NF_READY and NF_ATTN_MODULE.shapes_apply_nf(m + (-m) % 128, k)):
            raise RuntimeError(f"switch 9m: the norm-fused QKV kernel does not take rows {tuple(x2.shape)} "
                               f"(registered: {NF_READY})")
        pad = (-m) % 128
        if pad:
            x2 = F.pad(x2, (0, 0, 0, pad))
    elif ATTN8PC_MODULE is None or ATTN8_MODULE is None:
        raise RuntimeError("switch 9m: switch 9g's modules are not loaded (setup_attn8_kernel, setup_attn8pc_kernel)")
    out = NormProj8PC.apply(x2, attn.attn8_sc, attn.attn8_w8, ws[0], ws[1], ws[2])
    if pad:
        out = out[:m]
    return out.view(b, t, out.size(-1))


class NormMlp8(torch.autograd.Function):
    """Switch 9m: the MLP-side norm and switch 9f's fp8 MLP. Forward (x2 the pre-norm rows): the norm-fused kernel's op
    on a Neuron device (y, rT, xn, rs), F.rms_norm's composite and switch 9c's emulation elsewhere (the base's CPU
    route). Backward: switch 9f's backward op on a Neuron device (register_mlp_l4_ops's formula: this call's dy scales,
    then 9c's weight gradients), 9c's emulation elsewhere (EmulatedFusedMlp8's), on the saved xn; then the norm's
    backward on the saved x2 and rs."""

    @staticmethod
    def forward(ctx, x2, w_fc, w_proj, sc, w8):
        if x2.device.type == "neuron":
            y, rT, xn, rs = NF_OPS["mlp_fwd"](x2, w8, sc)
        else:
            xn, rs = nf_norm_rows(x2)
            y, rT = MLP8_MODULE.emulate8_forward(xn, w_fc, w_proj, sc[0])
        ctx.save_for_backward(x2, xn, rs, rT, w_fc, w_proj, sc, w8)
        return y

    @staticmethod
    def backward(ctx, dy2):
        x2, xn, rs, rT, w_fc, w_proj, sc, w8 = ctx.saved_tensors
        m8 = MLP8_MODULE
        dy2 = dy2.contiguous()
        if dy2.device.type == "neuron":
            sc_b = m8.sc_tile(m8.backward_scales(dy2, sc[0])) if MLP8_MODE & 2 else sc
            dxn, a, b = MLP_L4_OPS["bwd"](dy2, rT, xn, w_fc, w_proj, sc_b, w8)
        elif MLP8_MODE & 2:
            dxn, a, b = m8.emulate8_backward(dy2, rT, w_fc, w_proj, m8.backward_scales(dy2, sc[0]), MLP_DW_MODE)
        else:
            dxn, a, b = m8.emulate_backward(dy2, rT, w_fc, w_proj, MLP_DW_MODE)
        dw_fc, dw_proj = m8.weight_grads(dy2, xn, a, b, MLP_DW_MODE)
        return nf_norm_backward(dxn, x2, rs), dw_fc, dw_proj, None, None


def mlp_fused8nf(mlp: nn.Module, x: torch.Tensor) -> torch.Tensor:
    """Switch 9m: mlp_fused8 of norm(x) with the norm inside switch 9f's forward kernel; x [b, t, n_embd] is the stream
    before the MLP-side norm. On a Neuron device the rows are padded with zeros to a multiple of 128 (a zero row
    normalises to zero, as mlp_fused8's padded rows are zero); a shape the kernels do not take raises."""
    b, t, c = x.shape
    x2 = x.reshape(b * t, c).contiguous()
    # Switch 9h: fold_in_weight is weight.to(dtype) unless the lean optimizer gave the layer its slab view.
    w_fc = fold_in_weight(mlp.c_fc, x.dtype)
    w_proj = fold_in_weight(mlp.c_proj, x.dtype)
    m = x2.size(0)
    pad = 0
    if x2.dtype != torch.bfloat16:
        raise RuntimeError(f"switch 9m: the norm-fused MLP takes bf16 rows, not {tuple(x2.shape)} {x2.dtype}")
    if x2.device.type == "neuron":
        if not (NF_READY and mlp8_applies(x2, w_fc.size(0))):
            raise RuntimeError(f"switch 9m: the norm-fused MLP kernel does not take rows {tuple(x2.shape)} with "
                               f"hidden width {w_fc.size(0)} (registered: {NF_READY})")
        pad = (-m) % 128
        if pad:
            x2 = F.pad(x2, (0, 0, 0, pad))
    elif MLP8_MODULE is None:
        raise RuntimeError("switch 9m: switch 9c's module is not loaded (setup_mlp8_kernel)")
    y = NormMlp8.apply(x2, w_fc, w_proj, mlp.mlp8_sc, mlp.mlp8_w8)
    if pad:
        y = y[:m]
    return y.view(b, t, c)


def nf_summary() -> str:
    """Switch 9m: the end-of-run line: the op bodies' counts and whether the ops were registered."""
    if not NF_ON:
        return "off"
    return (" ".join(f"{k}={v}" for k, v in NF_COUNTS.items()) + (" registered" if NF_READY else " not registered")
            + f" norm_fuse={R2_NORM_FUSE}")


# ---- switch 9t: the norms, the residual mix and the residual adds folded into the kernels on either side

NR_MLP_KERNEL_FILE = "nki_mlp_nr8.py"
NR_MLP_KERNEL_MD5 = "f5c8b51f1902ecc61bf2abbbb95f863e"
NR_ATTN_KERNEL_FILE = "nki_attn_nr8.py"
NR_ATTN_KERNEL_MD5 = "a9452fdd2a58e5380b27a5dd85f0ca21"
NR_MLP_MODULE = None
NR_ATTN_MODULE = None
NR_OPS: dict = {}
NR_READY = False
NR_COUNTS = {"mlp_fwd": 0, "mlp_bwd": 0, "qkv_fwd": 0, "qkv_fwd_sk": 0, "qkv_fwd_b0": 0, "qkv_fwd_ss": 0,
             "proj_fwd": 0}   # op bodies only
NR_FALLBACK = {"mode_fallback": 0}    # nr_attn's mode disagreements (identity against structure)


def load_nr_kernel_module(fname: str, want: str, name: str):
    """Switch 9t: import one of its modules (in mlp_kernel_dir(), beside switch 9g's) after checking its md5, with no
    R1_* variable set while it imports. Returns (module, path)."""
    path = mlp_kernel_dir() / fname
    digest = hashlib.md5(path.read_bytes()).hexdigest()
    if digest != want:
        raise RuntimeError(f"{path} has md5 {digest}, expected {want}")
    saved = {k: v for k, v in os.environ.items() if k.startswith("R1_")}
    for k in saved:
        del os.environ[k]
    try:
        spec = importlib.util.spec_from_file_location(name, path)
        module = importlib.util.module_from_spec(spec)
        sys.modules[spec.name] = module
        spec.loader.exec_module(module)
    finally:
        os.environ.update(saved)
    return module, path


def register_nr_ops() -> str:
    """Switch 9t: its kernels as custom ops (registered as switches 9f and 9g register theirs: nki_op or
    torch_library), with fake implementations of the kernels' allocations. NrMlp, NrAttnIn and NrAttnOut carry the
    autograd formulas."""
    global NR_OPS
    if R2_ROUTE != "compiled_customop" or R2_CUSTOMOP_FORM not in ("nki_op", "torch_library"):
        raise ValueError("switch 9t runs on the compiled custom-op route, form nki_op or torch_library")
    if R2_CUSTOMOP_FORM == "nki_op":
        from torch_neuronx import nki_op as make_op
    else:
        make_op = torch.library.custom_op
    ops, fakes = {}, []

    def fake_ok(name, fn):
        try:
            torch.library.register_fake(name)(fn)
            fakes.append("ours")
        except Exception as err:
            fakes.append(f"the decorator's ({type(err).__name__})")

    if NR_MLP:
        mm = NR_MLP_MODULE
        mlp_fwd_k = mm._launch(mm._mlp8_fwd_nr_kernel)
        mlp_bwd_k = mm._launch(mm._mlp8_bwd_nr_kernel)
        tb, u8m, dwm = R2_MLP_TB, MLP_L4_U8, MLP_DW_MODE

        @make_op("s2nr8::mlp_fwd", mutates_args=())
        def nr_mlp_fwd(x2: torch.Tensor, w8: torch.Tensor,
                       sc: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
            NR_COUNTS["mlp_fwd"] += 1
            return mlp_fwd_k(x2, w8, sc, tb, u8m)

        def nr_mlp_fwd_fake(x2, w8, sc):
            # The kernel's allocations: xo [M, d], rT [F, M], xn [M, d], rs [M, 1] fp32 (F from the pack's row).
            m, d = x2.shape
            f = w8.shape[1] // d
            return (x2.new_empty(m, d), x2.new_empty(f, m), x2.new_empty(m, d),
                    x2.new_empty(m, 1, dtype=torch.float32))

        @make_op("s2nr8::mlp_bwd", mutates_args=())
        def nr_mlp_bwd(dy2: torch.Tensor, rT: torch.Tensor, x2: torch.Tensor, rs: torch.Tensor, w8: torch.Tensor,
                       sc: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
            NR_COUNTS["mlp_bwd"] += 1
            return mlp_bwd_k(dy2, rT, x2, rs, w8, sc, tb, dwm, u8m)

        def nr_mlp_bwd_fake(dy2, rT, x2, rs, w8, sc):
            # The kernel's allocations: gx [M, d]; h and dpre [F, M] under dw_mode 1 (fmajor), [M, F] under 0.
            m, d, f = dy2.shape[0], dy2.shape[1], rT.shape[0]
            big = (f, m) if dwm == 1 else (m, f)
            return dy2.new_empty(m, d), dy2.new_empty(*big), dy2.new_empty(*big)

        ops["mlp_fwd"], ops["mlp_bwd"] = nr_mlp_fwd, nr_mlp_bwd
        fake_ok("s2nr8::mlp_fwd", nr_mlp_fwd_fake)
        fake_ok("s2nr8::mlp_bwd", nr_mlp_bwd_fake)
    if NR_ATTN:
        ma = NR_ATTN_MODULE
        qkv_k = ma._launch(ma._proj8_fwd_nm_kernel)
        qkv_sk_k = ma._launch(ma._proj8_fwd_nm_sk_kernel)
        qkv_b0_k = ma._launch(ma._proj8_fwd_nm_b0_kernel)
        qkv_ss_k = ma._launch(ma._proj8_fwd_nm_ss_kernel)
        proj_k = ma._launch(ma._proj8_fwd_ra_kernel)
        u8a = ATTN8PC_U8

        # Four QKV ops, one a block-input mode, so that no kernel argument is ever bound twice to one tensor: plain
        # (blocks without a skip), sk (decoder blocks), b0 (block 0, whose input is x0) and ss (the first decoder
        # block, whose skip is its input).
        @make_op("s2nr8::qkv_fwd", mutates_args=())
        def nr_qkv_fwd(xa: torch.Tensor, x0: torch.Tensor, lam: torch.Tensor, w8: torch.Tensor,
                       sc: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
            NR_COUNTS["qkv_fwd"] += 1
            cwid = attn8_plan(x0.shape[1], x0.shape[1], 3, True)[1]
            return qkv_k(xa, x0, lam, w8, sc, ma.PK_FQKV, ma.SC_S_X, ma.SC_DQ_QKV, cwid, u8a)

        @make_op("s2nr8::qkv_fwd_sk", mutates_args=())
        def nr_qkv_fwd_sk(xa: torch.Tensor, x0: torch.Tensor, sk: torch.Tensor, lam: torch.Tensor, w8: torch.Tensor,
                          sc: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
            NR_COUNTS["qkv_fwd_sk"] += 1
            cwid = attn8_plan(x0.shape[1], x0.shape[1], 3, True)[1]
            return qkv_sk_k(xa, x0, sk, lam, w8, sc, ma.PK_FQKV, ma.SC_S_X, ma.SC_DQ_QKV, cwid, u8a)

        @make_op("s2nr8::qkv_fwd_b0", mutates_args=())
        def nr_qkv_fwd_b0(x0: torch.Tensor, lam: torch.Tensor, w8: torch.Tensor,
                          sc: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
            NR_COUNTS["qkv_fwd_b0"] += 1
            cwid = attn8_plan(x0.shape[1], x0.shape[1], 3, True)[1]
            return qkv_b0_k(x0, lam, w8, sc, ma.PK_FQKV, ma.SC_S_X, ma.SC_DQ_QKV, cwid, u8a)

        @make_op("s2nr8::qkv_fwd_ss", mutates_args=())
        def nr_qkv_fwd_ss(xa: torch.Tensor, x0: torch.Tensor, lam: torch.Tensor, w8: torch.Tensor,
                          sc: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
            NR_COUNTS["qkv_fwd_ss"] += 1
            cwid = attn8_plan(x0.shape[1], x0.shape[1], 3, True)[1]
            return qkv_ss_k(xa, x0, lam, w8, sc, ma.PK_FQKV, ma.SC_S_X, ma.SC_DQ_QKV, cwid, u8a)

        def nr_qkv_shapes(x0):
            # The kernels' allocations: out [M, 3 d], xm [M, d], xn [M, d], rs [M, 1] fp32.
            m, d = x0.shape
            return (x0.new_empty(m, 3 * d), x0.new_empty(m, d), x0.new_empty(m, d),
                    x0.new_empty(m, 1, dtype=torch.float32))

        def nr_qkv_fake(xa, x0, lam, w8, sc):
            return nr_qkv_shapes(x0)

        def nr_qkv_sk_fake(xa, x0, sk, lam, w8, sc):
            return nr_qkv_shapes(x0)

        def nr_qkv_b0_fake(x0, lam, w8, sc):
            return nr_qkv_shapes(x0)

        @make_op("s2nr8::proj_fwd", mutates_args=())
        def nr_proj_fwd(y2: torch.Tensor, res: torch.Tensor, w8: torch.Tensor, sc: torch.Tensor) -> torch.Tensor:
            NR_COUNTS["proj_fwd"] += 1
            cwid = attn8_plan(y2.shape[1], y2.shape[1], 1, True)[1]
            return proj_k(y2, res, w8, sc, ma.PK_FPROJ, ma.SC_S_Y, ma.SC_DQ_PROJ, cwid, u8a)

        def nr_proj_fake(y2, res, w8, sc):
            # The kernel's allocation: out [M, d].
            return y2.new_empty(y2.shape[0], y2.shape[1])

        ops["qkv_fwd"], ops["qkv_fwd_sk"], ops["proj_fwd"] = nr_qkv_fwd, nr_qkv_fwd_sk, nr_proj_fwd
        ops["qkv_fwd_b0"], ops["qkv_fwd_ss"] = nr_qkv_fwd_b0, nr_qkv_fwd_ss
        fake_ok("s2nr8::qkv_fwd", nr_qkv_fake)
        fake_ok("s2nr8::qkv_fwd_sk", nr_qkv_sk_fake)
        fake_ok("s2nr8::qkv_fwd_b0", nr_qkv_b0_fake)
        fake_ok("s2nr8::qkv_fwd_ss", nr_qkv_fake)
        fake_ok("s2nr8::proj_fwd", nr_proj_fake)
    NR_OPS = ops
    return (f"custom ops {' / '.join('s2nr8::' + k for k in ops)} by {R2_CUSTOMOP_FORM}, fake impls "
            f"{'/'.join(fakes)}, autograd by NrMlp / NrAttnIn / NrAttnOut")


def setup_nr_kernels(device: torch.device) -> str:
    """Switch 9t: load its modules and register its ops, once per process, after switches 9f's and 9g's (main() and
    load_for_eval). Off a Neuron device the units run their torch chains (the base's CPU routes). Returns the log
    line."""
    global NR_READY, NR_MLP_MODULE, NR_ATTN_MODULE
    if not NR_ON:
        return "off"
    if R2_HEADGATE:
        raise ValueError("R2_NR (switch 9t) hands the attention unit the pre-norm stream, and switch 18's head gate "
                         "reads the normalised one: run them separately")
    if R2_STEM:
        raise ValueError("R2_NR (switch 9t) runs the block loop itself: switch 48's gated MLPs are not on its route")
    if NR_MLP and DW8_MLP:
        raise ValueError("R2_NR mlp (switch 9t) keeps the base's weight gradients: switch 9k's MLP set is not on it")
    if NR_MLP and NR_MLP_MODULE is None:
        NR_MLP_MODULE, _p = load_nr_kernel_module(NR_MLP_KERNEL_FILE, NR_MLP_KERNEL_MD5, "s2_nki_mlp_nr8")
    if NR_ATTN and NR_ATTN_MODULE is None:
        NR_ATTN_MODULE, _p = load_nr_kernel_module(NR_ATTN_KERNEL_FILE, NR_ATTN_KERNEL_MD5, "s2_nki_attn_nr8")
    tail = (f"nr={','.join(NR_UNITS)}" + (f"; {NR_MLP_KERNEL_FILE} md5 {NR_MLP_KERNEL_MD5}" if NR_MLP else "")
            + (f"; {NR_ATTN_KERNEL_FILE} md5 {NR_ATTN_KERNEL_MD5}" if NR_ATTN else ""))
    if device.type != "neuron":
        return f"emulation (not a Neuron device): {tail}"
    for mod in (NR_MLP_MODULE, NR_ATTN_MODULE):
        if mod is not None and not mod._HAS_NKI:
            raise RuntimeError(f"switch 9t needs nki on a Neuron device ({mod._NKI_ERROR})")
    if NR_READY:
        return "on (registered earlier in this process)"
    how = register_nr_ops()
    NR_READY = True
    return f"on: {how}; {tail}"


def nr_lnc() -> int:
    """Switch 9t: the launch width the kernels see (NEURON_LOGICAL_NC_CONFIG, 1 when unset)."""
    return int(os.environ.get("NEURON_LOGICAL_NC_CONFIG", "1") or "1")


def nr_mix_rows(xa2: torch.Tensor, x02: torch.Tensor, sk2, a: torch.Tensor, b: torch.Tensor, sl) -> torch.Tensor:
    """Switch 9t (torch): the block's input as the base makes it, eager op for op: x_s = xa + sl.to(bf16) sk (GPT's
    U-net line; decoder blocks only), xm = resid_lambda.to(bf16) x_s + x0_lambda.to(bf16) x0 (mix_residual's)."""
    dt = xa2.dtype
    xs = xa2 if sk2 is None else xa2 + sl.to(dtype=dt) * sk2
    return a.to(dtype=dt) * xs + b.to(dtype=dt) * x02


class NrMlp(torch.autograd.Function):
    """Switch 9t, unit mlp: x_out = x1 + MLP(rms_norm(x1)) for a dense block, x2 the pre-norm rows x1. Forward: the
    folded kernel's op on a Neuron device (xo, rT, xn, rs), elsewhere F.rms_norm's composite, switch 9c's emulation and
    the eager add (the base's CPU route). Backward: this call's dy scales as switch 9c computes them; on a Neuron
    device the folded backward op (switch 9r's backward with the norm's backward and the residual gradient's add in its
    epilogue) and the base's weight gradients on the saved xn (mlp8_weight_grads); elsewhere 9c's emulation, the
    module's weight gradients and the norm's backward (autograd's sequence) plus the residual gradient."""

    @staticmethod
    def forward(ctx, x2, w_fc, w_proj, sc, w8):
        if x2.device.type == "neuron":
            xo, rT, xn, rs = NR_OPS["mlp_fwd"](x2, w8, sc)
        else:
            xn, rs = nf_norm_rows(x2)
            y, rT = MLP8_MODULE.emulate8_forward(xn, w_fc, w_proj, sc[0])
            xo = x2 + y
        ctx.save_for_backward(x2, xn, rs, rT, w_fc, w_proj, sc, w8)
        return xo

    @staticmethod
    def backward(ctx, g):
        x2, xn, rs, rT, w_fc, w_proj, sc, w8 = ctx.saved_tensors
        m8 = MLP8_MODULE
        g = g.contiguous()
        if g.device.type == "neuron":
            sc_b = m8.sc_tile(m8.backward_scales(g, sc[0]))
            gx, h_out, dp_out = NR_OPS["mlp_bwd"](g, rT, x2, rs, w8, sc_b)
            dw_fc, dw_proj = mlp8_weight_grads(m8, g, xn, h_out, dp_out, MLP_DW_MODE, sc_b)
            return gx, dw_fc, dw_proj, None, None
        dxn, h_out, dp_out = m8.emulate8_backward(g, rT, w_fc, w_proj, m8.backward_scales(g, sc[0]), MLP_DW_MODE)
        dw_fc, dw_proj = m8.weight_grads(g, xn, h_out, dp_out, MLP_DW_MODE)
        return g + nf_norm_backward(dxn, x2, rs), dw_fc, dw_proj, None, None


def nr_mlp(mlp: nn.Module, x1: torch.Tensor) -> torch.Tensor:
    """Switch 9t, unit mlp: x1 + MLP(rms_norm(x1)) on [b, t, n_embd] through NrMlp. On a Neuron device the rows are
    padded with zeros to a multiple of 128 (a zero row normalises to zero and adds zero); a shape the kernels do not
    take raises, never a silent fallback."""
    b, t, c = x1.shape
    x2 = x1.reshape(b * t, c).contiguous()
    w_fc = fold_in_weight(mlp.c_fc, x1.dtype)       # (switch 9h's route, as mlp_fused8's)
    w_proj = fold_in_weight(mlp.c_proj, x1.dtype)
    m = x2.size(0)
    pad = 0
    if x2.dtype != torch.bfloat16:
        raise RuntimeError(f"switch 9t: the folded MLP takes bf16 rows, not {tuple(x2.shape)} {x2.dtype}")
    if x2.device.type == "neuron":
        if not (NR_READY and NR_MLP_MODULE.shapes_apply_nr(m + (-m) % 128, c, w_fc.size(0), R2_MLP_TB, nr_lnc())):
            raise RuntimeError(f"switch 9t: the folded MLP kernels do not take rows {tuple(x2.shape)} with hidden "
                               f"width {w_fc.size(0)} (registered: {NR_READY})")
        pad = (-m) % 128
        if pad:
            x2 = F.pad(x2, (0, 0, 0, pad))
    elif MLP8_MODULE is None:
        raise RuntimeError("switch 9t: switch 9c's module is not loaded (setup_mlp8_kernel)")
    xo = NrMlp.apply(x2, w_fc, w_proj, mlp.mlp8_sc, mlp.mlp8_w8)
    if pad:
        xo = xo[:m]
    return xo.view(b, t, c)


class NrAttnIn(torch.autograd.Function):
    """Switch 9t, unit attn, the attention's input: [qkv, xm] from the previous block's rows xa2, the stream x02 (x0),
    the U-net skip sk2 (decoder blocks; else None) and the gains. Forward: the folded QKV kernel's op on a Neuron device
    (the skip add, the mix, the norm and switch 9q's QKV projection; qkv, xm, xn, rs), elsewhere the eager mix, the
    norm's composite and switch 9g's emulation (the base's CPU route). Backward: AttnProj8PC's on the saved xn (9g's
    fp8 input gradient, the weight gradient by switch 9k's route or the bf16 GEMM), the norm's backward (autograd's
    sequence) added to xm's direct gradient, then the mix's and the skip's gradients as autograd forms them (switch
    9i's CPU expressions). mode (nr_attn's, from the caller's tensors): 0 no skip, 1 a skip, 2 block 0 (xa2 holds x0's
    rows: the op takes x0 alone), 3 the skip is the block's input (sk2 holds xa2's rows: the op takes xa alone), so
    the kernel is never launched with one tensor bound to two of its arguments."""

    @staticmethod
    def forward(ctx, xa2, x02, sk2, a, b, sl, sc, w8, w0, w1, w2, mode):
        has_skip = sk2 is not None
        if xa2.device.type == "neuron":
            lam = NR_ATTN_MODULE.lam_tile(a, b, sl).to(device=xa2.device)
            if mode == 2:
                out, xm2, xn2, rs = NR_OPS["qkv_fwd_b0"](x02, lam, w8, sc)
            elif mode == 3:
                out, xm2, xn2, rs = NR_OPS["qkv_fwd_ss"](xa2, x02, lam, w8, sc)
            elif mode == 1:
                out, xm2, xn2, rs = NR_OPS["qkv_fwd_sk"](xa2, x02, sk2, lam, w8, sc)
            else:
                out, xm2, xn2, rs = NR_OPS["qkv_fwd"](xa2, x02, lam, w8, sc)
        else:
            xm2 = nr_mix_rows(xa2, x02, sk2, a, b, sl)
            xn2, rs = nf_norm_rows(xm2)
            out = attn8pc_fwd_rows(xn2, w8, sc, 0)
        ctx.save_for_backward(xa2, x02, sk2, xm2, xn2, rs, a, b, sl, sc, w8, w0, w1, w2)
        ctx.has_skip = has_skip
        return out, xm2

    @staticmethod
    def backward(ctx, g, g_xm):
        xa2, x02, sk2, xm2, xn2, rs, a, b, sl, sc, w8, w0, w1, w2 = ctx.saved_tensors
        m = ATTN8_MODULE
        g = g.contiguous()
        row = sc[0]
        bc = m.backward_tile(g, row[m.SC_S_WQKV], row[m.SC_I_WQKV])
        dxn = attn8pc_bwd_rows(g, w8, bc, 0)
        dw = attn8_weight_grad(g, xn2, sc, bc, 0) if DW8_QKV else g.t().mm(xn2)
        n = w0.shape[0]
        gm = nf_norm_backward(dxn, xm2, rs)
        if g_xm is not None:
            gm = g_xm + gm
        dt = xa2.dtype
        ab = a.to(dtype=dt)
        bb = b.to(dtype=dt)
        if ctx.has_skip:
            slb = sl.to(dtype=dt)
            xs = xa2 + slb * sk2
        else:
            xs = xa2
        g_xs = gm * ab
        g_x0 = gm * bb
        ga = (gm * xs).sum_to_size(ab.shape).to(a.dtype)
        gb = (gm * x02).sum_to_size(bb.shape).to(b.dtype)
        g_sk = gsl = None
        if ctx.has_skip:
            g_sk = g_xs * slb
            gsl = (g_xs * sk2).sum_to_size(slb.shape).to(sl.dtype)
        return g_xs, g_x0, g_sk, ga, gb, gsl, None, None, dw[:n], dw[n:2 * n], dw[2 * n:], None


class NrAttnOut(torch.autograd.Function):
    """Switch 9t, unit attn, the attention's output: x1 = xm + c_proj(y) on rows. Forward: the folded projection op on
    a Neuron device (switch 9q's c_proj with the residual added in its evacuation), elsewhere 9g's emulation and the
    eager add. Backward: AttnProj8PC's for c_proj on the saved y; xm's gradient is the incoming one (the add's)."""

    @staticmethod
    def forward(ctx, y2, xm2, sc, w8, wp):
        if y2.device.type == "neuron":
            out = NR_OPS["proj_fwd"](y2, xm2, w8, sc)
        else:
            out = xm2 + attn8pc_fwd_rows(y2, w8, sc, 1)
        ctx.save_for_backward(y2, sc, w8, wp)
        return out

    @staticmethod
    def backward(ctx, g):
        y2, sc, w8, wp = ctx.saved_tensors
        m = ATTN8_MODULE
        g = g.contiguous()
        row = sc[0]
        bc = m.backward_tile(g, row[m.SC_S_WPROJ], row[m.SC_I_WPROJ])
        dy = attn8pc_bwd_rows(g, w8, bc, 1)
        dw = attn8_weight_grad(g, y2, sc, bc, 1) if DW8_PROJ else g.t().mm(y2)
        return dy, g, None, None, dw


def nr_rows(t: torch.Tensor, pad: int) -> torch.Tensor:
    """Switch 9t: [b, t, d] as contiguous rows [b t (+ pad), d] (zero rows appended on a Neuron device)."""
    r = t.reshape(-1, t.size(-1)).contiguous()
    return F.pad(r, (0, 0, 0, pad)) if pad else r


def nr_mode(x: torch.Tensor, x0: torch.Tensor, skip) -> int:
    """Switch 9t: the block input's mode for the QKV kernels by the tensors' identity (switch 9i's `x is x0` is the
    chip-run precedent): 0 no skip, 1 a skip, 2 block 0 (its x is x0 itself), 3 the skip is x itself (the first
    decoder block when the U-net has no middle blocks: the last encoder block pushes what it returns)."""
    if skip is None:
        return 2 if x is x0 else 0
    return 3 if skip is x else 1


def nr_mode_expected(i: int, n_layer: int, n_skip: int) -> int:
    """Switch 9t: the mode GPT.forward's structure gives block i (x0 = norm(embedding) is block 0's input; with a
    U-net of no middle blocks the first decoder block pops what the last encoder block pushed, its own input)."""
    if i == 0:
        return 2
    if n_skip and i >= n_layer - n_skip:
        return 3 if (i == n_layer - n_skip and n_layer - n_skip == n_skip) else 1
    return 0


def nr_attn(block: nn.Module, x: torch.Tensor, x0: torch.Tensor, cos: torch.Tensor, sin: torch.Tensor, ve, skip,
            sl, want: int) -> torch.Tensor:
    """Switch 9t, unit attn: the block's attention half, x1 = xm + attn(norm(xm)) with xm the mix of (x + sl skip)
    and x0: NrAttnIn, then the base's attention between the projections (switch 6's kernel on a Neuron device, the
    kit's SDPA route elsewhere, as CausalSelfAttention.forward), then NrAttnOut. x [b, t, n_embd]. The QKV kernel's
    mode is nr_mode's (identity) when it equals want (nr_mode_expected's, structure); when they disagree (Dynamo's
    view of `is`, or a structure this code does not know) the general mode runs on a copy of the rows that could
    alias, so no kernel is launched with one tensor in two arguments and the values are right either way; the
    count is printed at the end (mode_fallback)."""
    attn = block.attn
    b, t, c = x.shape
    ws = tuple(fold_in_weight(lin, x.dtype) for lin in (attn.c_q, attn.c_k, attn.c_v))     # (switch 9h's route)
    m = b * t
    pad = 0
    if x.dtype != torch.bfloat16:
        raise RuntimeError(f"switch 9t: the folded attention takes bf16 rows, not {tuple(x.shape)} {x.dtype}")
    if x.device.type == "neuron":
        cwid = attn8_plan(c, c, 3, True)[1]
        cwid_p = attn8_plan(c, c, 1, True)[1]
        if not (NR_READY and NR_ATTN_MODULE.shapes_apply_nm(m + (-m) % 128, c, cwid, nr_lnc(), cwid_p)
                and attn_kernel_applies(x, attn.head_dim)):
            raise RuntimeError(f"switch 9t: the folded attention kernels do not take rows {tuple(x.shape)} "
                               f"(registered: {NR_READY})")
        pad = (-m) % 128
    elif ATTN8PC_MODULE is None or ATTN8_MODULE is None:
        raise RuntimeError("switch 9t: switch 9g's modules are not loaded (setup_attn8_kernel, setup_attn8pc_kernel)")
    mode = nr_mode(x, x0, skip)
    xa2, sk2 = nr_rows(x, pad), (None if skip is None else nr_rows(skip, pad))
    if mode != want:
        NR_FALLBACK["mode_fallback"] += 1
        mode = 0 if skip is None else 1
        if skip is None:
            xa2 = xa2.clone()
        else:
            sk2 = sk2.clone()
    qkv2, xm2 = NrAttnIn.apply(xa2, nr_rows(x0, pad), sk2, block.resid_lambda, block.x0_lambda, sl, attn.attn8_sc,
                               attn.attn8_w8, *ws, mode)
    if pad:
        qkv2, xm2 = qkv2[:m], xm2[:m]
    qkv = qkv2.view(b, t, 3 * c)
    if x.device.type == "neuron":
        if ve is not None:
            # Switch 13 on the kernel route: this layer's value embedding, added to the v columns (the base's line).
            qkv = torch.cat([qkv[..., :2 * c], qkv[..., 2 * c:] + block.ve_lambda.to(qkv.dtype) * ve], dim=-1)
        y = fused_rope_attention(qkv, cos, sin, attn.n_head, attn.qk_scale).view(b, t, c)
    else:
        q, k, v = qkv.split(c, dim=-1)
        q = q.view(b, t, attn.n_head, attn.head_dim)
        k = k.view(b, t, attn.n_head, attn.head_dim)
        v = v.view(b, t, attn.n_head, attn.head_dim)
        if ve is not None:
            v = v + block.ve_lambda.to(v.dtype) * ve.view(b, t, attn.n_head, attn.head_dim)
        q = norm(apply_rotary_emb(q, cos, sin)).transpose(1, 2)
        k = norm(apply_rotary_emb(k, cos, sin)).transpose(1, 2)
        v = v.transpose(1, 2)
        if attn.qk_scale > 0.0:
            y = F.scaled_dot_product_attention(q, k, v, is_causal=True, scale=attn.qk_scale)
        else:
            y = F.scaled_dot_product_attention(q, k, v, is_causal=True)
        y = y.transpose(1, 2).contiguous().view(b, t, c)
    x1 = NrAttnOut.apply(nr_rows(y, pad), nr_rows(xm2.view(b, t, c), pad) if pad else xm2, attn.attn8_sc,
                         attn.attn8_w8, fold_in_weight(attn.c_proj, y.dtype))
    if pad:
        x1 = x1[:m]
    return x1.view(b, t, c)


def nr_block(block: nn.Module, x: torch.Tensor, x0: torch.Tensor, cos: torch.Tensor, sin: torch.Tensor, ve, skip, sl,
             moe_aux, want: int) -> torch.Tensor:
    """Switch 9t: Block.forward with its units folded (the attention half under attn, a dense MLP under mlp; a MoE
    block's MLP half stays the base's). skip and sl are the U-net skip and its gain for a decoder block under attn
    (the caller adds the skip itself otherwise); want the QKV kernel's mode by structure."""
    if NR_ATTN:
        x1 = nr_attn(block, x, x0, cos, sin, ve, skip, sl, want)
    else:
        x = mix_residual(x, x0, block.resid_lambda, block.x0_lambda)
        x1 = x + block.attn(norm(x), cos, sin, ve, block.ve_lambda)
    if isinstance(block.mlp, MoeMLP):
        if moe_aux is not None:
            y, aux, stats = block.mlp(norm(x1), want_stats=True)
            moe_aux.append((aux, stats))
            return x1 + y
        return x1 + block.mlp(norm(x1))
    if NR_MLP:
        return nr_mlp(block.mlp, x1)
    return x1 + block.mlp(norm(x1))


def nr_block_step(gpt: nn.Module, i: int, block: nn.Module, x: torch.Tensor, x0: torch.Tensor, cos: torch.Tensor,
                  sin: torch.Tensor, idx: torch.Tensor, skips: list, ve_grad_sinks, moe_aux) -> torch.Tensor:
    """Switch 9t: one iteration of GPT.forward's block loop (the U-net skip, the value embedding's lookup, the block,
    the skip's push), the base's lines but for the decoder's skip add, which goes into the block's QKV kernel under
    attn."""
    if gpt.stem_tables is not None:
        raise RuntimeError("switch 9t: switch 48's gated MLPs are not on its route")
    n_layer, n_skip = gpt.config.n_layer, gpt.n_skip
    skip = sl = None
    if n_skip and i >= n_layer - n_skip:
        j = i - (n_layer - n_skip)
        if NR_ATTN:
            skip, sl = skips.pop(), gpt.skip_lambda[j:j + 1]
        else:
            x = x + gpt.skip_lambda[j:j + 1].to(x.dtype) * skips.pop()
    ve = None
    if gpt.value_embeds is not None and str(i) in gpt.value_embeds:
        if ve_grad_sinks is not None:
            # T1 (training only): the same lookup through switch 10's LeanLookup, d(ve) to the table's sink.
            ve = LeanLookup.apply(idx, gpt.value_embeds[str(i)].weight, ve_grad_sinks[str(i)])
        else:
            # Switch 13: this layer's table, the kit's lookup (FP32 table, cast to the compute dtype).
            ve = gpt.value_embeds[str(i)](idx).to(COMPUTE_DTYPE)
    x = nr_block(block, x, x0, cos, sin, ve, skip, sl, moe_aux, nr_mode_expected(i, n_layer, n_skip))
    if n_skip and i < n_skip:
        skips.append(x)
    return x


def nr_summary() -> str:
    """Switch 9t: the end-of-run line: the op bodies' counts, whether the ops were registered, and the mode fallbacks
    (nr_attn's, counted where its Python runs: per call eagerly, per trace when compiled)."""
    if not NR_ON:
        return "off"
    return (" ".join(f"{k}={v}" for k, v in NR_COUNTS.items()) + (" registered" if NR_READY else " not registered")
            + f" nr={','.join(NR_UNITS)} mode_fallback={NR_FALLBACK['mode_fallback']}")


# ---- switch 10: the lean embedding backward

class LeanLookup(torch.autograd.Function):
    """Switch 10: the kit's lookup, F.embedding on the table and the cast to the compute dtype. The backward gives
    the table nothing and hands the gradient of the output to `sink`, a zero leaf of the output's shape that is not
    read: the table's gradient is formed once per optimizer step by lean_embedding_grad."""

    @staticmethod
    def forward(ctx, idx, weight, sink):
        return F.embedding(idx, weight).to(sink.dtype)

    @staticmethod
    def backward(ctx, dy):
        return None, None, dy


def lean_relabel(ids: torch.Tensor, vocab: int) -> tuple[torch.Tensor, torch.Tensor] | None:
    """Switch 10, on the host, once per step: the step's token ids as compact ids 0..U-1 (int32, the ids' order), and
    the table row each compact id stands for (int64, LE_COMPACT_V rows: the U touched rows ascending, then untouched
    rows as padding, whose compact gradient is zero). None when the step has more than LE_COMPACT_V distinct ids:
    that step's gradient is then lean_host_grad's."""
    uniq, inv = torch.unique(ids.reshape(-1), sorted=True, return_inverse=True)
    u = uniq.numel()
    if u > LE_COMPACT_V:
        return None
    touched = torch.zeros(vocab, dtype=torch.bool)
    touched[uniq.long()] = True
    pad = torch.nonzero(~touched).flatten()[:LE_COMPACT_V - u]
    return inv.to(torch.int32), torch.cat([uniq.long(), pad])


def lean_embedding_grad(dys: list, cid: torch.Tensor, rows: torch.Tensor, vocab: int, kernel: bool) -> torch.Tensor:
    """Switch 10, once per optimizer step: the table's dense FP32 gradient from the step's output gradients (one
    [b, t, n_embd] per micro-step, in loader order) and lean_relabel's ids: the kernel contracts all the step's
    tokens at the compact vocabulary (torch's index_add where the kernel does not run), then the compact rows are
    copied into a zero [vocab, n_embd] gradient."""
    c = dys[0].size(-1)
    dy = torch.cat([d.reshape(-1, c) for d in dys])
    n = dy.size(0)
    if kernel:
        # T1: a width the 352-column kernel does not tile takes the tile-width copy (admitted only under T1).
        op = S2B_OPS["lean_embed_bwd"] if c % _EB_MOVING == 0 else S2B_OPS["lean_embed_bwd_w"]
        dwc = op(cid.view(128, n // 128), dy.view(128, n // 128, c))
    else:
        dwc = torch.zeros(LE_COMPACT_V, c, dtype=torch.float32, device=dy.device).index_add_(0, cid.long(), dy.float())
    return torch.zeros(vocab, c, dtype=torch.float32, device=dy.device).index_copy(0, rows, dwc)


def lean_host_grad(dys: list, ids: torch.Tensor, vocab: int) -> torch.Tensor:
    """Switch 10, for a step with more distinct ids than LE_COMPACT_V (none in 6,000 measured rank-steps: at most
    4,909): the same FP32 sums, index_add over the step's ids in loader order, on the host, copied to the device."""
    S2B_COUNTS["lean_host_steps"] += 1
    c = dys[0].size(-1)
    dy = torch.cat([d.reshape(-1, c) for d in dys]).to("cpu", torch.float32)
    grad = torch.zeros(vocab, c, dtype=torch.float32).index_add_(0, ids.reshape(-1).long(), dy)
    return grad.to(dys[0].device)


def lean_kernel_applies(device: torch.device, tokens: int, n_embd: int) -> bool:
    """Switch 10: where the embedding-backward kernel runs: the kernels' device, a multiple of 128 tokens per step,
    and a width the kernel's 352-column matmul tiles evenly (4 x 352 = 1,408)."""
    return (s2b_kernel_device(device) and tokens % 128 == 0 and n_embd % _EB_MOVING == 0
            and (n_embd // _EB_MOVING) * _EB_VPP in (1, 2, 4, 8)) or (
        # T1: also a width the 384-column tile takes (1,536).
        R2_LEAN_EMBED_1536 and s2b_kernel_device(device) and tokens % 128 == 0 and lean_moving_width(n_embd) > 0)


def lean_moving_width(n_embd: int) -> int:
    """T1: the embedding backward's matmul tile width for a table width: switch 10's 352 where it gives 1, 2, 4 or
    8 PSUM accumulators over the kernel's 2 vocabulary tiles (widths 352, 704, 1,408), under T1 else 384 (1,536); 0
    where neither does."""
    for mov in ((_EB_MOVING, _EB_MOVING_W) if R2_LEAN_EMBED_1536 else (_EB_MOVING,)):
        if n_embd % mov == 0 and (n_embd // mov) * _EB_VPP in (1, 2, 4, 8):
            return mov
    return 0


def set_lean_embedding_grad(optimizer: torch.optim.Optimizer, weight: torch.Tensor, grad: torch.Tensor) -> None:
    """Switch 10: the table's gradient for this step, where the optimizer reads it."""
    if hasattr(optimizer, "set_deferred_grad"):
        optimizer.set_deferred_grad(weight, grad)
    else:
        weight.grad = grad


# ---- switch 48: the token-indexed gate on the MLP hidden activation

class StemLookup(torch.autograd.Function):
    """Switch 48: switch 10's LeanLookup for a gate table, with the cast forced to copy. The gate tables have bf16
    replicas, so LeanLookup's cast to the compute dtype is a no-op that returns the gather's own output, and in a
    compiled graph (torch 2.11's autograd.Function path, lane STEM's battery) the gradient then went to the table
    instead of through this backward to the sink: the sink's gradient was 0 and the table never trained. A copy gives
    the same values and keeps the custom backward. Switch 13's tables and the token embedding have FP32 replicas (the
    cast copies), so LeanLookup is unchanged for them."""

    @staticmethod
    def forward(ctx, idx, weight, sink):
        return F.embedding(idx, weight).to(sink.dtype, copy=True)

    @staticmethod
    def backward(ctx, dy):
        return None, None, dy


STEM_KERNEL_FILE = "nki_mlp_stem.py"
STEM_KERNEL_MD5 = "fe1a54b0522c40dfe10bc5adb5f24b16"
STEM_READY = False
STEM_MODULE = None
STEM_OPS: dict = {}
STEM_COUNTS = {"fwd_bodies": 0, "bwd_bodies": 0}     # op bodies only: nothing the compiled graph traces mutates it


def load_stem_kernel_module():
    """Switch 48: import STEM_KERNEL_FILE from mlp_kernel_dir() (switch 9b's folder) after checking its md5, with no
    R1_* variable set while it imports. Returns (module, path)."""
    path = mlp_kernel_dir() / STEM_KERNEL_FILE
    digest = hashlib.md5(path.read_bytes()).hexdigest()
    if digest != STEM_KERNEL_MD5:
        raise RuntimeError(f"{path} has md5 {digest}, expected {STEM_KERNEL_MD5}")
    saved = {k: v for k, v in os.environ.items() if k.startswith("R1_")}
    for k in saved:
        del os.environ[k]
    try:
        spec = importlib.util.spec_from_file_location("s2_nki_mlp_stem", path)
        module = importlib.util.module_from_spec(spec)
        sys.modules[spec.name] = module
        spec.loader.exec_module(module)
    finally:
        os.environ.update(saved)
    return module, path


def register_stem_ops(module) -> str:
    """Switch 48: the gated kernels as STEM_OPS["fwd"] / ["bwd"], registered as switch 9b registers its pair, the
    forward with the backward as its autograd formula: the backward kernel, then the two weight gradients as the
    module's weight_grads (switch 9b's F-major expressions with the gated hg in h's place); the gate's gradient is the
    kernel's dg^T (to gT, which the caller formed by a transpose of the gathered rows)."""
    global STEM_OPS
    if R2_ROUTE != "compiled_customop" or R2_CUSTOMOP_FORM not in ("nki_op", "torch_library"):
        raise ValueError("switch 48's kernel runs on the compiled custom-op route, form nki_op or torch_library")
    if R2_CUSTOMOP_FORM == "nki_op":
        from torch_neuronx import nki_op as make_op
    else:
        make_op = torch.library.custom_op
    fwd_kernel = module._launch(module._mlp_fwd_g_kernel)
    bwd_kernel = module._launch(module._mlp_bwd_g_kernel)
    tb = R2_STEM_TB

    @make_op("s2stem::mlp_fwd_g", mutates_args=())
    def mlp_fwd_g(x2: torch.Tensor, w_fc: torch.Tensor, w_proj: torch.Tensor,
                  gT: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor]:
        STEM_COUNTS["fwd_bodies"] += 1
        y, rT = fwd_kernel(x2, w_fc, w_proj, gT, tb)
        return y, rT

    @make_op("s2stem::mlp_bwd_g", mutates_args=())
    def mlp_bwd_g(dy2: torch.Tensor, rT: torch.Tensor, gT: torch.Tensor, w_fc: torch.Tensor,
                  w_proj: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
        STEM_COUNTS["bwd_bodies"] += 1
        dx, hg_out, dp_out, dg_out = bwd_kernel(dy2, rT, gT, w_fc, w_proj, tb)
        return dx, hg_out, dp_out, dg_out

    def fwd_fake(x2, w_fc, w_proj, gT):
        # The kernel's own allocations: y [M, d], rT [F, M].
        return x2.new_empty(x2.shape[0], x2.shape[1]), x2.new_empty(w_fc.shape[0], x2.shape[0])

    def bwd_fake(dy2, rT, gT, w_fc, w_proj):
        # dx [M, d]; hg^T, dpre^T, dg^T [F, M].
        m, f = dy2.shape[0], rT.shape[0]
        return dy2.new_empty(m, dy2.shape[1]), dy2.new_empty(f, m), dy2.new_empty(f, m), dy2.new_empty(f, m)

    fakes = []
    for name, fake in (("s2stem::mlp_fwd_g", fwd_fake), ("s2stem::mlp_bwd_g", bwd_fake)):
        try:
            torch.library.register_fake(name)(fake)
            fakes.append("ours")
        except Exception as err:
            fakes.append(f"the decorator's ({type(err).__name__})")

    def setup_context(ctx, inputs, output):
        x2, w_fc, w_proj, gT = inputs
        _y, rT = output
        ctx.save_for_backward(x2, rT, gT, w_fc, w_proj)
        ctx.mark_non_differentiable(rT)
        ctx.set_materialize_grads(False)

    def backward(ctx, dy2, _d_rT):
        x2, rT, gT, w_fc, w_proj = ctx.saved_tensors
        dy2 = dy2.contiguous()
        dx, hg_out, dp_out, dg_out = mlp_bwd_g(dy2, rT, gT, w_fc, w_proj)
        dw_fc, dw_proj = module.weight_grads(dy2, x2, hg_out, dp_out)
        return dx, dw_fc, dw_proj, dg_out

    torch.library.register_autograd("s2stem::mlp_fwd_g", backward, setup_context=setup_context)
    STEM_OPS = {"fwd": mlp_fwd_g, "bwd": mlp_bwd_g}
    return (f"custom ops s2stem::mlp_fwd_g / mlp_bwd_g by {R2_CUSTOMOP_FORM}, fake impls {fakes[0]} / {fakes[1]}, "
            f"autograd by torch.library.register_autograd; tb={tb}")


def setup_stem_kernel(device: torch.device) -> str:
    """Switch 48 with R2_STEM_KERNEL=1: load the gated kernel module and register its ops, once per process, before
    the model is built (main() and load_for_eval). Off a Neuron device the module's torch emulation runs instead."""
    global STEM_READY, STEM_MODULE
    if not R2_STEM_KERNEL:
        return "off"
    if STEM_MODULE is None:
        STEM_MODULE, path = load_stem_kernel_module()
    else:
        path = mlp_kernel_dir() / STEM_KERNEL_FILE
    if device.type != "neuron":
        return f"emulation (not a Neuron device): {path} md5 {STEM_KERNEL_MD5}, tb={R2_STEM_TB}"
    if not STEM_MODULE._HAS_NKI:
        raise RuntimeError(f"switch 48's kernel needs nki on a Neuron device ({STEM_MODULE._NKI_ERROR})")
    if STEM_READY:
        return "on (registered earlier in this process)"
    how = register_stem_ops(STEM_MODULE)
    STEM_READY = True
    return f"on: {how}; {path} md5 {STEM_KERNEL_MD5}"


def stem_kernel_applies(x2: torch.Tensor, hidden: int) -> bool:
    """Switch 48: where the gated kernels run: registered, a Neuron device, bf16 rows, every shape a multiple of 128."""
    return (STEM_READY and x2.device.type == "neuron" and x2.dtype == torch.bfloat16
            and STEM_MODULE.shapes_apply(x2.size(0), x2.size(1), hidden, R2_STEM_TB))


def mlp_stem(mlp: nn.Module, x: torch.Tensor, gate: torch.Tensor) -> torch.Tensor:
    """Switch 48: MLP.forward on [b, t, n_embd] with the gate rows [b, t, 4 n_embd]: c_proj(relu(c_fc(x))^2 * gate).
    R2_STEM_KERNEL=1: the gated kernels where they apply (the rows transposed to [F, M] for them), the module's
    emulation off a Neuron device; otherwise (and for a shape the kernels do not take) the kit's expression. Under
    R2_MLP=fused8: the gated fp8 kernels (mlp_stem8)."""
    if R2_MLP == "fused8":
        # Switch 48 on the fp8 line: the gate inside switch 9c's fp8 kernels.
        return mlp_stem8(mlp, x, gate)
    if R2_STEM_KERNEL:
        b, t, c = x.shape
        x2 = x.reshape(b * t, c).contiguous()
        w_fc = mlp.c_fc.weight.to(dtype=x.dtype)
        w_proj = mlp.c_proj.weight.to(dtype=x.dtype)
        # No counter here: this runs inside the compiled graph (a mutated global is a guard that recompiles).
        if stem_kernel_applies(x2, w_fc.size(0)):
            gT = gate.reshape(b * t, w_fc.size(0)).t().contiguous()
            y, _rT = STEM_OPS["fwd"](x2, w_fc, w_proj, gT)
            return y.view(b, t, c)
        if x2.device.type != "neuron" and STEM_MODULE is not None:
            gT = gate.reshape(b * t, w_fc.size(0)).t().contiguous()
            return STEM_MODULE.EmulatedGatedMlp.apply(x2, w_fc, w_proj, gT).view(b, t, c)
    return mlp.c_proj(relu_squared(mlp.c_fc(x)) * gate)


# ---- switch 48 on the fp8 line: the gate inside switch 9c's fp8 kernels

STEM8_KERNEL_FILE = "nki_mlp_stem8.py"
STEM8_KERNEL_MD5 = "1f8f710403fc83304f3bff69db4b4f7f"
STEM8_READY = False
STEM8_MODULE = None
STEM8_OPS: dict = {}
STEM8_COUNTS = {"fwd_bodies": 0, "bwd_bodies": 0}    # op bodies only, as switch 9c's
STEM8_GATE_FN = None                                 # the per-step gate scale function; main() compiles it
STEM8_LEAN = bool(R2_STEM) and R2_MLP == "fused8"    # lane STEM8B: switch 48 under switch 9c
STEM8_AMAX_ROWS = 4096                               # lane STEM8B: the amax's row block (48 MiB of bf16 at F 6,144)
STEM8_COLS_FN = None                                 # lane STEM8B: the column-block contraction; main() compiles it
STEM8_DENSE_FN = None                                # lane STEM8B: one [vocab, n_embd] block; main() compiles it
STEM8_RESCUE = {"copies": 0, "seconds": 0.0}         # lane STEM8B: rank 0's rescue copies to the host


def load_stem8_kernel_module():
    """Switch 48 on the fp8 line: import STEM8_KERNEL_FILE from mlp_kernel_dir() after checking its md5, with no R1_*
    variable set while it imports. Returns (module, path)."""
    path = mlp_kernel_dir() / STEM8_KERNEL_FILE
    digest = hashlib.md5(path.read_bytes()).hexdigest()
    if digest != STEM8_KERNEL_MD5:
        raise RuntimeError(f"{path} has md5 {digest}, expected {STEM8_KERNEL_MD5}")
    saved = {k: v for k, v in os.environ.items() if k.startswith("R1_")}
    for k in saved:
        del os.environ[k]
    try:
        spec = importlib.util.spec_from_file_location("s2_nki_mlp_stem8", path)
        module = importlib.util.module_from_spec(spec)
        sys.modules[spec.name] = module
        spec.loader.exec_module(module)
    finally:
        os.environ.update(saved)
    if module.NSC != MLP8_NSC or module.NSCG != MLP8_NSC + 2:
        raise RuntimeError(f"{path}: NSC {module.NSC} / NSCG {module.NSCG}, expected {MLP8_NSC} / {MLP8_NSC + 2}")
    return module, path


def register_stem8_ops(module) -> str:
    """Switch 48 on the fp8 line: s2stem8::fwd (the gated fp8 forward) with its autograd formula: the gated scales of
    this call's backward (9c's backward_scales on 9c's forward row, then the gate's powers of two) in the backward
    graph, s2stem8::bwd, then the two weight gradients as 9c's F-major expressions with hg in h's place; the gate's
    gradient is the kernel's dg'^T (with respect to the pre-scaled gT the caller formed). Registered as 9c's pair."""
    global STEM8_OPS
    if R2_ROUTE != "compiled_customop" or R2_CUSTOMOP_FORM not in ("nki_op", "torch_library"):
        raise ValueError("switch 48's fp8 kernels run on the compiled custom-op route, form nki_op or torch_library")
    if R2_CUSTOMOP_FORM == "nki_op":
        from torch_neuronx import nki_op as make_op
    else:
        make_op = torch.library.custom_op
    tb, forms = R2_STEM_TB, R2_MLP8_FORMS
    fwd_kernel = module._launch(module._mlp8g_fwd_kernel)
    bwd_kernel = module._launch(module._mlp8g_bwd_kernel)

    @make_op("s2stem8::fwd", mutates_args=())
    def stem8_fwd(x2: torch.Tensor, w_fc: torch.Tensor, w_proj: torch.Tensor, scg: torch.Tensor, sc: torch.Tensor,
                  gs: torch.Tensor, gT: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor]:
        STEM8_COUNTS["fwd_bodies"] += 1
        y, rT = fwd_kernel(x2, w_fc, w_proj, scg, gT, tb, forms)
        return y, rT

    @make_op("s2stem8::bwd", mutates_args=())
    def stem8_bwd(dy2: torch.Tensor, rT: torch.Tensor, gT: torch.Tensor, w_fc: torch.Tensor, w_proj: torch.Tensor,
                  scbg: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
        STEM8_COUNTS["bwd_bodies"] += 1
        dx, hg_out, dp_out, dg_out = bwd_kernel(dy2, rT, gT, w_fc, w_proj, scbg, tb, forms)
        return dx, hg_out, dp_out, dg_out

    def fwd_fake(x2, w_fc, w_proj, scg, sc, gs, gT):
        return x2.new_empty(x2.shape[0], x2.shape[1]), x2.new_empty(w_fc.shape[0], x2.shape[0])

    def bwd_fake(dy2, rT, gT, w_fc, w_proj, scbg):
        m, f = dy2.shape[0], rT.shape[0]
        return dy2.new_empty(m, dy2.shape[1]), dy2.new_empty(f, m), dy2.new_empty(f, m), dy2.new_empty(f, m)

    fakes = []
    for name, fake in (("s2stem8::fwd", fwd_fake), ("s2stem8::bwd", bwd_fake)):
        try:
            torch.library.register_fake(name)(fake)
            fakes.append("ours")
        except Exception as err:
            fakes.append(f"the decorator's ({type(err).__name__})")

    def setup_context(ctx, inputs, output):
        x2, w_fc, w_proj, _scg, sc, gs, gT = inputs
        _y, rT = output
        ctx.save_for_backward(x2, rT, gT, w_fc, w_proj, sc, gs)
        ctx.mark_non_differentiable(rT)
        ctx.set_materialize_grads(False)

    def backward(ctx, dy2, _d_rT):
        x2, rT, gT, w_fc, w_proj, sc, gs = ctx.saved_tensors
        dy2 = dy2.contiguous()
        # The gated fp8 backward's scales: 9c's (this call's dy amax and the dpre bound), then the gate's powers of two.
        scbg = module.sc_tile_g(module.gated_bwd_row(module.backward_scales(dy2, sc[0]), gs))
        dx, hg_out, dp_out, dg_out = stem8_bwd(dy2, rT, gT, w_fc, w_proj, scbg)
        dw_fc, dw_proj = module.weight_grads_g(dy2, x2, hg_out, dp_out)
        return dx, dw_fc, dw_proj, None, None, None, dg_out

    torch.library.register_autograd("s2stem8::fwd", backward, setup_context=setup_context)
    STEM8_OPS = {"fwd": stem8_fwd, "bwd": stem8_bwd}
    return (f"custom ops s2stem8::fwd / bwd by {R2_CUSTOMOP_FORM}, fake impls {fakes[0]} / {fakes[1]}, autograd by "
            f"torch.library.register_autograd; forms={forms} tb={tb}")


def setup_stem8_kernel(device: torch.device) -> str:
    """Switch 48 on the fp8 line: load the gated fp8 module and register its ops, once per process, before the gated
    model is built (main() and load_for_eval). Off a Neuron device the module's torch emulation runs instead."""
    global STEM8_READY, STEM8_MODULE
    if R2_MLP != "fused8":
        return "off"
    if STEM8_MODULE is None:
        STEM8_MODULE, path = load_stem8_kernel_module()
    else:
        path = mlp_kernel_dir() / STEM8_KERNEL_FILE
    if device.type != "neuron":
        return f"emulation (not a Neuron device): {path} md5 {STEM8_KERNEL_MD5}, tb={R2_STEM_TB}"
    if not STEM8_MODULE._HAS_NKI:
        raise RuntimeError(f"switch 48's fp8 kernels need nki on a Neuron device ({STEM8_MODULE._NKI_ERROR})")
    if STEM8_READY:
        return "on (registered earlier in this process)"
    how = register_stem8_ops(STEM8_MODULE)
    STEM8_READY = True
    return f"on: {how}; {path} md5 {STEM8_KERNEL_MD5}"


def stem8_applies(x2: torch.Tensor, hidden: int) -> bool:
    """Switch 48 on the fp8 line: where the gated fp8 kernels run (9c's shapes: d and F multiples of 256)."""
    return (STEM8_READY and x2.device.type == "neuron" and x2.dtype == torch.bfloat16
            and STEM8_MODULE.shapes_apply8(128, x2.size(1), hidden, R2_STEM_TB))


def mlp_stem8(mlp: nn.Module, x: torch.Tensor, gate: torch.Tensor) -> torch.Tensor:
    """Switch 48 on the fp8 line: MLP.forward of a gated layer under R2_MLP=fused8: the gate pre-scaled by the
    layer's s_g (exact), switch 9c's row with the gate's power of two (the module's gated_row), the gated fp8 kernels
    on a Neuron device (rows padded to a multiple of 128 as 9c pads them), the module's emulation off one. No bf16
    MLP is reachable here: a shape the kernels do not take on a Neuron device raises."""
    b, t, c = x.shape
    x2 = x.reshape(b * t, c).contiguous()
    w_fc = mlp.c_fc.weight.to(dtype=x.dtype)
    w_proj = mlp.c_proj.weight.to(dtype=x.dtype)
    m, f = x2.size(0), w_fc.size(0)
    gs = mlp.stem8_gs
    gp = gate.reshape(b * t, f) * gs[0].to(gate.dtype)        # g' = g x s_g: a power of two, exact
    if stem8_applies(x2, f):
        pad = (-m) % 128
        if pad:
            x2 = F.pad(x2, (0, 0, 0, pad))
            gp = F.pad(gp, (0, 0, 0, pad))
        scg = STEM8_MODULE.sc_tile_g(STEM8_MODULE.gated_row(mlp.mlp8_sc[0], gs))
        y, _rT = STEM8_OPS["fwd"](x2, w_fc, w_proj, scg, mlp.mlp8_sc, gs, gp.t().contiguous())
        if pad:
            y = y[:m]
    elif x2.device.type != "neuron" and STEM8_MODULE is not None:
        y = STEM8_MODULE.EmulatedGatedMlp8.apply(x2, w_fc, w_proj, mlp.mlp8_sc, gs, gp.t().contiguous())
    else:
        raise RuntimeError(f"switch 48: the gated fp8 kernels do not take rows {tuple(x2.shape)} {x2.dtype} with "
                           f"hidden width {f} (registered: {STEM8_READY}); no bf16 MLP runs under R2_MLP=fused8")
    return y.view(b, t, c)


def stem8_table_amax(table: torch.Tensor) -> torch.Tensor:
    """Lane STEM8B: max |U| of a gate table in its bf16 view (as gate_scales reads it), over blocks of STEM8_AMAX_ROWS
    rows. abs and max are exact in bf16, so this is gate_scales' own amax, and no FP32 or full-size copy of the table
    is made (STEM8_m60: the end line's .float().abs() asked the device for 805,306,368 bytes twice)."""
    t = table.detach()
    return torch.stack([t[i:i + STEM8_AMAX_ROWS].to(torch.bfloat16).abs().amax()
                        for i in range(0, t.size(0), STEM8_AMAX_ROWS)]).amax()


@torch.no_grad()
def stem8_gates_into(tables: list, gs_list: list) -> None:
    """Switch 48 on the fp8 line, once per optimizer step: each gated layer's [s_g, gamma] from its table (the
    module's gate_scales: the exact amax and powers of two), written into the layer's buffer in place. Lane STEM8B:
    gate_scales takes the table's amax (stem8_table_amax) as a one-element table: the same [s_g, gamma]."""
    for t, gs in zip(tables, gs_list):
        gs.copy_(STEM8_MODULE.gate_scales(stem8_table_amax(t).reshape(1)))


def set_stem8_gate_fn(fn) -> None:
    """Switch 48 on the fp8 line: main() hands over the compiled gate scale function (the model's backend)."""
    global STEM8_GATE_FN
    STEM8_GATE_FN = fn


def stem8_refresh_gates(model: nn.Module) -> None:
    """Switch 48 on the fp8 line: fp8_refresh_weights' share for the gate tables (compiled in training, eager in
    load_for_eval: the same operations on the same values)."""
    keys = list(model.stem_tables)
    fn = STEM8_GATE_FN or stem8_gates_into
    fn([model.stem_tables[k].weight for k in keys], [model.transformer.h[int(k)].mlp.stem8_gs for k in keys])


def stem_impl_name() -> str:
    """Switch 48: how the gate is applied, for the stem line: the gated fp8 kernels (fp8_kernel_tb<n>), the bf16
    gated kernel (kernel_tb<n>) or the kit's expression."""
    if R2_MLP == "fused8":
        return f"fp8_kernel_tb{R2_STEM_TB}"
    return f"kernel_tb{R2_STEM_TB}" if R2_STEM_KERNEL else "kit_expression"


def stem8_gates_line(model: nn.Module) -> str:
    """Switch 48 on the fp8 line: the gate scales in force, one line (each gated layer's max |U|, s_g and gamma)."""
    parts = []
    for k in model.stem_tables:
        gs = model.transformer.h[int(k)].mlp.stem8_gs.detach().float().cpu()
        amax = float(stem8_table_amax(model.stem_tables[k].weight))          # lane STEM8B: no FP32 copy
        parts.append(f"layer={k} max_abs_u={amax:.6g} s_g={float(gs[0]):g} gamma={float(gs[1]):g}")
    return " ".join(parts)


def stem_embedding_grad(dys: list, cid: torch.Tensor, rows: torch.Tensor, vocab: int, kernel: bool,
                        chunk: int) -> torch.Tensor:
    """Switch 48, once per optimizer step: a gate table's dense FP32 gradient [vocab, F] from the step's output
    gradients (one [b, t, F] per micro-step, in loader order) and lean_relabel's ids, as lean_embedding_grad forms
    switch 13's. Where the embedding-backward kernel runs, F / chunk column chunks of `chunk` columns (n_embd: the
    width T1 launches the kernel at for a value-embedding table), each gathered from the micro-steps' gradients as one
    contiguous [tokens, chunk] block and contracted by that launch at the compact ids, their compact rows side by
    side (no full-width copy of the step's gradients); elsewhere torch's index_add at the full width (the same FP32
    sums). The compact rows are then copied into a zero [vocab, F] gradient, in place."""
    f = dys[0].size(-1)
    if kernel:
        op = S2B_OPS["lean_embed_bwd"] if chunk % _EB_MOVING == 0 else S2B_OPS["lean_embed_bwd_w"]
        n = sum(d.numel() // f for d in dys)
        parts = []
        for c0 in range(0, f, chunk):
            dyc = torch.cat([d.reshape(-1, f)[:, c0:c0 + chunk] for d in dys])
            parts.append(op(cid.view(128, n // 128), dyc.view(128, n // 128, chunk)))
        dwc = torch.cat(parts, dim=1)
    else:
        dy = torch.cat([d.reshape(-1, f) for d in dys])
        dwc = torch.zeros(LE_COMPACT_V, f, dtype=torch.float32, device=dy.device).index_add_(0, cid.long(), dy.float())
    return torch.zeros(vocab, f, dtype=torch.float32, device=dwc.device).index_copy_(0, rows, dwc)


def stem_embedding_grad_cols(dys: list, cid: torch.Tensor, rows: torch.Tensor, vocab: int, kernel: bool,
                             chunk: int) -> list:
    """Lane STEM8B, once per optimizer step on the fp8 line: stem_embedding_grad's compact rows as F / chunk column
    blocks [LE_COMPACT_V, chunk] FP32 (the kernel launches' own outputs where it runs; elsewhere the full-width
    index_add's columns: the same FP32 sums), with no [vocab, F] gradient: the optimizer forms one [vocab, chunk] block
    at a time (stem_reduce_cols)."""
    f = dys[0].size(-1)
    if kernel:
        op = S2B_OPS["lean_embed_bwd"] if chunk % _EB_MOVING == 0 else S2B_OPS["lean_embed_bwd_w"]
        n = sum(d.numel() // f for d in dys)
        parts = []
        for c0 in range(0, f, chunk):
            dyc = torch.cat([d.reshape(-1, f)[:, c0:c0 + chunk] for d in dys])
            parts.append(op(cid.view(128, n // 128), dyc.view(128, n // 128, chunk)))
        return parts
    dy = torch.cat([d.reshape(-1, f) for d in dys])
    dwc = torch.zeros(LE_COMPACT_V, f, dtype=torch.float32, device=dy.device).index_add_(0, cid.long(), dy.float())
    return [dwc[:, c0:c0 + chunk].contiguous() for c0 in range(0, f, chunk)]


def stem_dense_cols(part: torch.Tensor, rows: torch.Tensor, vocab: int) -> torch.Tensor:
    """Lane STEM8B: one column block of a gate table's step gradient, [vocab, chunk] FP32 (at chunk = n_embd 1,536
    the shape and the index_copy of switch 10's embedding gradient): the compact rows copied into a zero block."""
    return torch.zeros(vocab, part.size(1), dtype=torch.float32, device=part.device).index_copy_(0, rows, part)


def stem_host_cols(dys: list, ids: torch.Tensor, vocab: int, chunk: int) -> list:
    """Lane STEM8B: lean_host_grad's FP32 sums (a step past LE_COMPACT_V distinct ids) kept on the host as
    [vocab, chunk] column blocks; stem_reduce_cols moves one at a time to the device."""
    S2B_COUNTS["lean_host_steps"] += 1
    f = dys[0].size(-1)
    dy = torch.cat([d.reshape(-1, f) for d in dys]).to("cpu", torch.float32)
    grad = torch.zeros(vocab, f, dtype=torch.float32).index_add_(0, ids.reshape(-1).long(), dy)
    return [grad[:, c0:c0 + chunk].contiguous() for c0 in range(0, f, chunk)]


def stem_reduce_cols(grad_slice: torch.Tensor, cols: tuple, op) -> None:
    """Lane STEM8B, in the optimizer's reduce: a gate table's step gradient from its column blocks. Each [vocab, chunk]
    FP32 block is formed from the compact rows (or moved from the host), reduce-scattered over the rows as the whole
    table's gradient was (every rank gets its own rows of that block) and written into its columns of the rank's
    grad_slice: the same FP32 values per element, with one [vocab, chunk] block alive at a time."""
    kind, parts, rows, vocab, dense_fn = cols
    c0 = 0
    for part in parts:
        w = part.size(1)
        block = dense_fn(part, rows, vocab) if kind == "compact" else part.to(grad_slice.device)
        out = torch.empty((grad_slice.size(0), w), dtype=grad_slice.dtype, device=grad_slice.device)
        dist.reduce_scatter_tensor(out, block, op=op)
        grad_slice[:, c0:c0 + w].copy_(out)
        del block
        c0 += w


def set_stem8_cols_fns(cols_fn, dense_fn) -> None:
    """Lane STEM8B: main() hands over the compiled column-block contraction and block function."""
    global STEM8_COLS_FN, STEM8_DENSE_FN
    STEM8_COLS_FN, STEM8_DENSE_FN = cols_fn, dense_fn


def stem8_set_grad(optimizer, weight: torch.Tensor, dys: list, cid: torch.Tensor, rows: torch.Tensor, vocab: int,
                   kernel: bool, chunk: int, host_ids: torch.Tensor | None = None) -> None:
    """Lane STEM8B: a gate table's step gradient to the lean optimizer as column blocks: the compact form, or the host
    form for a step past LE_COMPACT_V distinct ids (as lean_host_grad)."""
    if host_ids is None:
        parts = (STEM8_COLS_FN or stem_embedding_grad_cols)(dys, cid, rows, vocab, kernel, chunk)
        cols = ("compact", parts, rows, vocab, STEM8_DENSE_FN or stem_dense_cols)
    else:
        cols = ("host", stem_host_cols(dys, host_ids, vocab, chunk), None, vocab, None)
    optimizer.set_deferred_grad_cols(weight, cols)


def thr2_memory_line(device: torch.device) -> str:
    """R2_MEM_PRINT: this rank's allocator counters (GiB): the peaks over the run so far and what is held now, then
    memory_stats()'s requested-bytes peak (active_bytes.all.peak, GiB) and its retry and failure counters
    (torch_neuronx.memory.memory_stats: num_alloc_retries, num_ooms, num_alloc_deferred, num_alloc_drain_retry_ok,
    num_alloc_drain_retry_fail); a key the backend does not report is left out."""
    mod = getattr(torch, device.type, None) if device.type in ("neuron", "cuda") else None
    if mod is None:
        return f"no allocator counters on device type {device.type}"
    parts = []
    for name in ("max_memory_allocated", "max_memory_reserved", "memory_allocated", "memory_reserved"):
        try:
            parts.append(f"{name}={int(getattr(mod, name)()) / 2 ** 30:.3f}GiB")
        except Exception as err:  # noqa: BLE001
            parts.append(f"{name}=unavailable({type(err).__name__})")
    try:
        stats = mod.memory_stats()
        if "active_bytes.all.peak" in stats:
            parts.append(f"active_peak={int(stats['active_bytes.all.peak']) / 2 ** 30:.3f}GiB")
        for k in ("num_alloc_retries", "num_ooms", "num_alloc_deferred", "num_alloc_drain_retry_ok",
                  "num_alloc_drain_retry_fail"):
            if k in stats:
                parts.append(f"{k}={stats[k]}")
    except Exception as err:  # noqa: BLE001
        parts.append(f"memory_stats=unavailable({type(err).__name__})")
    return " ".join(parts)


class Db4Barrier:
    """S13 (R2_MICRO_BARRIER=1): the event after each micro-step's backward and the host's wait on it before the next
    forward (see the switch). Off a Neuron device it records nothing and waits for nothing; the counts still run."""

    def __init__(self, device: torch.device):
        self.event_cls = None
        if device.type == "neuron":
            self.event_cls = getattr(getattr(torch, "neuron", None), "Event", None)
            if self.event_cls is None:
                import torch_neuronx
                self.event_cls = torch_neuronx.Event
        self.ev = None
        self.marks = 0
        self.waits = 0
        self.wait_ms = 0.0
        self.max_ms = 0.0

    def mark(self) -> None:
        self.marks += 1
        if self.event_cls is not None:
            self.ev = self.event_cls()
            self.ev.record()

    def wait(self) -> None:
        if self.ev is None:
            return
        t = time.perf_counter()
        self.ev.synchronize()
        ms = 1000.0 * (time.perf_counter() - t)
        self.ev = None
        self.waits += 1
        self.wait_ms += ms
        self.max_ms = max(self.max_ms, ms)

    def summary(self) -> str:
        return (f"marks={self.marks} waits={self.waits} wait_ms={self.wait_ms:.1f} max_wait_ms={self.max_ms:.2f} "
                f"events={'on' if self.event_cls is not None else 'off'}")


class MemPhase:
    """R2_MEM_PHASE (lane DB4): one step's synchronous memory by phase on this rank (see the switch); a print only.
    Each field is peak/held in GiB: the allocator's peak since the previous read and what it holds now, read after a
    synchronize, the peak reset after each read. The first field (before=) is read before the step's first forward:
    its peak is the run's peak so far."""

    def __init__(self, device: torch.device, rank: int, at_step: int):
        self.device, self.rank, self.at = device, rank, at_step
        self.mod = getattr(torch, device.type, None) if device.type in ("neuron", "cuda") else None
        self.on = False
        self.parts = []
        self.count = {}

    def _read(self) -> str:
        synchronize(self.device)
        if self.mod is None:
            return "none"
        try:
            pk = int(self.mod.max_memory_allocated()) / 2 ** 30
            cur = int(self.mod.memory_allocated()) / 2 ** 30
            self.mod.reset_peak_memory_stats()
        except Exception as err:  # noqa: BLE001
            return f"unavailable({type(err).__name__})"
        return f"{pk:.3f}/{cur:.3f}"

    def begin(self, step: int) -> None:
        self.on = step == self.at
        if self.on:
            self.parts = [f"before={self._read()}"]
            self.count = {}

    def mark(self, name: str) -> None:
        if self.on:
            k = self.count.get(name, 0)
            self.count[name] = k + 1
            self.parts.append(f"{name}{k}={self._read()}")

    def end(self, step: int) -> None:
        if self.on:
            self.parts.append(f"opt={self._read()}")
            print(f"mem_phase: rank {self.rank} step {step} " + " ".join(self.parts), flush=True)
            self.on = False


class CausalSelfAttention(nn.Module):
    # Switch 47: this layer's band in key tiles of 128 (0, the class default: the full causal attention); GPT sets it
    # on every layer from model_config when the model has a window.
    attn_nw = 0

    def __init__(self, config: GPTConfig):
        super().__init__()
        self.n_head = config.n_head
        self.n_embd = config.n_embd
        self.head_dim = config.n_embd // config.n_head
        assert self.head_dim * self.n_head == self.n_embd
        self.c_q = Linear(config.n_embd, config.n_embd, bias=False)
        self.c_k = Linear(config.n_embd, config.n_embd, bias=False)
        self.c_v = Linear(config.n_embd, config.n_embd, bias=False)
        self.c_proj = Linear(config.n_embd, config.n_embd, bias=False)
        # Switch 14, qk_scale: the softmax scale; 0.0 keeps SDPA's 1/sqrt(head_dim).
        self.qk_scale = config.qk_scale
        # Switch 18: the gate's weight [n_embd, n_head], built as zeros (no draw from the generator).
        self.head_gate = nn.Parameter(torch.zeros(config.n_embd, config.n_head)) if config.head_gate else None
        if ATTN8_ON:
            # Switch 9d: the layer's scale tile [128, ATTN8_NSC] fp32 (forward_scales' row down every partition),
            # rewritten from the weights after every optimizer step and in load_for_eval; never saved. NaN until the
            # first refresh, so a forward that ran before it could not pass unnoticed.
            self.register_buffer("attn8_sc", torch.full((128, ATTN8_NSC), float("nan")), persistent=False)
            if R2_ATTN_PRECAST:
                # Switch 9g: the layer's e4m3 weight bytes [8, n_embd^2] uint8 (written by fp8_refresh_weights from
                # the weights and the scale tile above; never saved).
                self.register_buffer("attn8_w8", torch.zeros((8, config.n_embd * config.n_embd), dtype=torch.uint8),
                                     persistent=False)

    def forward(
        self,
        x: torch.Tensor,
        cos: torch.Tensor,
        sin: torch.Tensor,
        ve: torch.Tensor | None = None,
        ve_lambda: torch.Tensor | None = None,
        nf: bool = False,
    ) -> torch.Tensor:
        # Switch 9m: nf (Block's flag under R2_NORM_FUSE both or attn) means x is the block's stream BEFORE the
        # attention-side norm, which attn8nf_qkv runs inside the QKV forward kernel; x then feeds that projection only.
        b, t, c = x.shape
        if R2_ATTN_KERNEL and attn_kernel_applies(x, self.head_dim):
            # Switch 6: one projection into [q | k | v], then the fused kernel (RoPE, QK norm, causal attention).
            if ATTN8_QKV:
                # Switch 9d: the fp8 projection of the three weights (no concatenated weight).
                qkv = attn8nf_qkv(self, x) if nf else attn8_qkv(self, x)
            else:
                w = torch.cat([lin.weight.to(dtype=x.dtype) for lin in (self.c_q, self.c_k, self.c_v)])
                qkv = F.linear(x, w, None)
            if ve is not None:
                # Switch 13 on the kernel route: this layer's value embedding, added to the v columns before the
                # kernel reads them (the kit's route below adds it to v), with the same two bf16 operations.
                qkv = torch.cat([qkv[..., :2 * c], qkv[..., 2 * c:] + ve_lambda.to(qkv.dtype) * ve], dim=-1)
            if self.attn_nw and self.attn_nw * 128 < t:
                # Switch 47: a short layer whose band is narrower than the call runs the tile-band pair, then this
                # route's own tail, line for line (at 128 nw >= t the band is the causal mask: the call below).
                y = fused_rope_attention_band(qkv, cos, sin, self.n_head, self.qk_scale, self.attn_nw)
                if self.head_gate is not None:
                    y = head_gated(y, x, self.head_gate)                  # switch 47
                if ATTN8_PROJ:
                    return attn8_proj(self, y.view(b, t, c))              # switch 47
                return self.c_proj(y.view(b, t, c))                       # switch 47
            y = fused_rope_attention(qkv, cos, sin, self.n_head, self.qk_scale)
            if self.head_gate is not None:
                # Switch 18: the gate on the kernel's output, [b, t, n_head, head_dim].
                y = head_gated(y, x, self.head_gate)
            if ATTN8_PROJ:
                # Switch 9d: c_proj in fp8.
                return attn8_proj(self, y.view(b, t, c))
            return self.c_proj(y.view(b, t, c))
        if ATTN8_QKV:
            # Switch 9d: q, k and v split from the kernel route's fp8 projection (the same arithmetic per element).
            q, k, v = (attn8nf_qkv(self, x) if nf else attn8_qkv(self, x)).split(c, dim=-1)
            q = q.view(b, t, self.n_head, self.head_dim)
            k = k.view(b, t, self.n_head, self.head_dim)
            v = v.view(b, t, self.n_head, self.head_dim)
        else:
            q = self.c_q(x).view(b, t, self.n_head, self.head_dim)
            k = self.c_k(x).view(b, t, self.n_head, self.head_dim)
            v = self.c_v(x).view(b, t, self.n_head, self.head_dim)
        if ve is not None:
            # Switch 13: this layer's value embedding, added to the values.
            v = v + ve_lambda.to(v.dtype) * ve.view(b, t, self.n_head, self.head_dim)
        q = norm(apply_rotary_emb(q, cos, sin))
        k = norm(apply_rotary_emb(k, cos, sin))
        q = q.transpose(1, 2)
        k = k.transpose(1, 2)
        v = v.transpose(1, 2)
        if self.attn_nw and self.attn_nw * 128 < t:
            # Switch 47: a short layer on SDPA's route: the band [t, t] as SDPA's boolean mask (attn_band_attach put it
            # on the layer), at the layer's scale (None: SDPA's 1 / sqrt(head_dim)), then this route's own tail.
            band = getattr(self, "attn_band", None)
            if band is None:
                raise RuntimeError("switch 47: a short layer on SDPA's route needs its band mask (attn_band_attach)")
            y = F.scaled_dot_product_attention(q, k, v, attn_mask=band[:t, :t],
                                               scale=self.qk_scale if self.qk_scale > 0.0 else None)
            y = y.transpose(1, 2)                                         # switch 47
            if self.head_gate is not None:                              # switch 47
                y = head_gated(y, x, self.head_gate)                      # switch 47
            y = y.contiguous().view(b, t, c)                              # switch 47
            if ATTN8_PROJ:                                              # switch 47
                return attn8_proj(self, y)                                # switch 47
            return self.c_proj(y)                                         # switch 47
        if self.qk_scale > 0.0:
            y = F.scaled_dot_product_attention(q, k, v, is_causal=True, scale=self.qk_scale)
        else:
            y = F.scaled_dot_product_attention(q, k, v, is_causal=True)
        y = y.transpose(1, 2)
        if self.head_gate is not None:
            # Switch 18: the gate on SDPA's output, in the kernel route's layout [b, t, n_head, head_dim].
            y = head_gated(y, x, self.head_gate)
        y = y.contiguous().view(b, t, c)
        if ATTN8_PROJ:
            # Switch 9d: c_proj in fp8.
            return attn8_proj(self, y)
        return self.c_proj(y)


class MLP(nn.Module):
    def __init__(self, config: GPTConfig):
        super().__init__()
        self.c_fc = Linear(config.n_embd, 4 * config.n_embd, bias=False)
        self.c_proj = Linear(4 * config.n_embd, config.n_embd, bias=False)
        if R2_FP8_ROWS:
            # Switch 9: the fp8 bytes of the two weights the kernel reads, [4 n_embd, padded n_embd] (row 2's
            # c_proj.weight^T, row 3's c_fc.weight), refreshed by fp8_refresh_weights; never saved.
            shape = (4 * config.n_embd, fp8_padded(config.n_embd))
            self.register_buffer("fp8_wq2", torch.zeros(shape, dtype=torch.uint8), persistent=False)
            self.register_buffer("fp8_wq3", torch.zeros(shape, dtype=torch.uint8), persistent=False)
            self.fp8_h_scale = FP8_H_SCALE      # row 2's h scale; GPT sets each layer's (fp8_h_scale)
        if R2_MLP == "fused8":
            # Switch 9c: the layer's scale tile [128, MLP8_NSC] fp32 (forward_scales' row down every partition),
            # rewritten from the weights after every optimizer step and in load_for_eval; never saved. NaN until the
            # first refresh, so a forward that ran before it could not pass unnoticed.
            self.register_buffer("mlp8_sc", torch.full((128, MLP8_NSC), float("nan")), persistent=False)
            if R2_MLP_L4 or R2_MLP_PRECAST:
                # Switches 9e, 9f: the layer's e4m3 bytes [4, 4 n_embd x n_embd] uint8 under 9f (written by
                # fp8_refresh_weights; never saved), a [1, 1] placeholder under 9e alone (the ops' signature).
                shape = (4, 4 * config.n_embd * config.n_embd) if R2_MLP_PRECAST else (1, 1)
                self.register_buffer("mlp8_w8", torch.zeros(shape, dtype=torch.uint8), persistent=False)

    def forward(self, x: torch.Tensor, gate: torch.Tensor | None = None, nf: bool = False) -> torch.Tensor:
        # Switch 9m: nf (Block's flag under R2_NORM_FUSE both or mlp) means x is the stream BEFORE the MLP-side norm,
        # which mlp_fused8nf runs inside the forward kernel.
        if gate is not None:
            # Switch 48: this layer's hidden activation times the tokens' gate rows.
            return mlp_stem(self, x, gate)
        if R2_MLP == "fused":
            return mlp_fused(self, x)
        if R2_MLP == "fused8":
            return mlp_fused8nf(self, x) if nf else mlp_fused8(self, x)
        if R2_FP8_ROWS:
            return mlp_fp8(self, x)
        return self.c_proj(relu_squared(self.c_fc(x)))


# ---- switch 9i: the residual mix's backward in one kernel pass a block

RESMIX_KERNEL_FILE = "nki_resmix.py"
RESMIX_KERNEL_MD5 = "2c1597e03218fbe60a12056b657152c4"
RESMIX_MODULE = None
RESMIX_OPS: dict = {}
RESMIX_READY = False
RESMIX_COUNTS = {"bwd_bodies": 0}               # op bodies only, as switch 9d's


def load_resmix_kernel_module():
    """Switch 9i: import RESMIX_KERNEL_FILE (in mlp_kernel_dir()) after checking its md5, with no R1_* variable set
    while it imports. Returns (module, path)."""
    path = mlp_kernel_dir() / RESMIX_KERNEL_FILE
    digest = hashlib.md5(path.read_bytes()).hexdigest()
    if digest != RESMIX_KERNEL_MD5:
        raise RuntimeError(f"{path} has md5 {digest}, expected {RESMIX_KERNEL_MD5}")
    saved = {k: v for k, v in os.environ.items() if k.startswith("R1_")}
    for k in saved:
        del os.environ[k]
    try:
        spec = importlib.util.spec_from_file_location("s2_nki_resmix", path)
        module = importlib.util.module_from_spec(spec)
        sys.modules[spec.name] = module
        spec.loader.exec_module(module)
    finally:
        os.environ.update(saved)
    if module.NAB != 2:
        raise RuntimeError(f"{path}: NAB {module.NAB}, expected 2")
    return module, path


def register_resmix_ops(module) -> str:
    """Switch 9i: the module's kernel as one custom op with a fake implementation of its allocations."""
    global RESMIX_OPS
    if R2_ROUTE != "compiled_customop" or R2_CUSTOMOP_FORM not in ("nki_op", "torch_library"):
        raise ValueError("switch 9i runs on the compiled custom-op route, form nki_op or torch_library")
    if R2_CUSTOMOP_FORM == "nki_op":
        from torch_neuronx import nki_op as make_op
    else:
        make_op = torch.library.custom_op
    bwd_kernel = module._launch(module._resmix_bwd_kernel)
    rows = 128 * module.programs()

    @make_op("s2resmix::bwd", mutates_args=())
    def resmix_bwd(g2: torch.Tensor, x2: torch.Tensor, x02: torch.Tensor,
                   ab: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
        RESMIX_COUNTS["bwd_bodies"] += 1
        dx2, dx02, part = bwd_kernel(g2, x2, x02, ab)
        return dx2, dx02, part

    def resmix_bwd_fake(g2, x2, x02, ab):
        # The kernel's own allocations: dx and dx0 [M, D] in the stream's dtype, the partials [rows, 2] fp32.
        return g2.new_empty(g2.shape), g2.new_empty(g2.shape), g2.new_empty(rows, module.NAB, dtype=torch.float32)

    try:
        torch.library.register_fake("s2resmix::bwd")(resmix_bwd_fake)
        fake = "ours"
    except Exception as err:
        fake = f"the decorator's ({type(err).__name__})"
    RESMIX_OPS = {"bwd": resmix_bwd}
    return f"custom op s2resmix::bwd by {R2_CUSTOMOP_FORM}, fake impl {fake}, autograd by ResidMix; part rows {rows}"


def setup_resmix_kernel(device: torch.device) -> str:
    """Switch 9i: load its module and register its op, once per process (main()). Off a Neuron device the backward is
    the autograd backward's expressions and the module is only loaded. Returns the log line."""
    global RESMIX_READY, RESMIX_MODULE
    if not R2_RESMIX_FUSE:
        return "off"
    if RESMIX_MODULE is None:
        RESMIX_MODULE, path = load_resmix_kernel_module()
    else:
        path = mlp_kernel_dir() / RESMIX_KERNEL_FILE
    tail = f"{path} md5 {RESMIX_KERNEL_MD5}"
    if device.type != "neuron":
        return f"emulation (not a Neuron device): {tail}"
    if not RESMIX_MODULE._HAS_NKI:
        raise RuntimeError(f"switch 9i needs nki on a Neuron device ({RESMIX_MODULE._NKI_ERROR})")
    if RESMIX_READY:
        return "on (registered earlier in this process)"
    how = register_resmix_ops(RESMIX_MODULE)
    RESMIX_READY = True
    return f"on: {how}; {tail}"


class ResidMix(torch.autograd.Function):
    """Switch 9i: mix_residual's expression in the forward; the backward returns the autograd backward's dx = g a,
    dx0 = g b and the two gains' gradients, on a Neuron device from one kernel call (the same dx and dx0; the gains'
    sums of the same bf16 products in the kernel's fp32 order, rounded to bf16 as there), elsewhere by the autograd
    backward's own expressions (bit for bit). x and x0 are distinct tensors (mix_residual keeps the base expression
    for block 0, where x is x0 itself: the order in which two gradients of one tensor are added is the graph's, not
    this function's)."""

    @staticmethod
    def forward(ctx, x, x0, resid_lambda, x0_lambda):
        a = resid_lambda.to(dtype=x.dtype)
        b = x0_lambda.to(dtype=x.dtype)
        ctx.save_for_backward(x, x0, a, b)
        ctx.lambda_dtypes = (resid_lambda.dtype, x0_lambda.dtype)
        return a * x + b * x0

    @staticmethod
    def backward(ctx, g):
        x, x0, a, b = ctx.saved_tensors
        ta, tb = ctx.lambda_dtypes
        if g.device.type == "neuron":
            dx, dx0, ga, gb = resmix_bwd_device(g, x, x0, a, b)
        else:
            dx = g * a
            dx0 = g * b
            ga = (g * x).sum_to_size(a.shape)
            gb = (g * x0).sum_to_size(b.shape)
        return dx, dx0, ga.to(ta), gb.to(tb)


def resmix_bwd_device(g: torch.Tensor, x: torch.Tensor, x0: torch.Tensor, a: torch.Tensor, b: torch.Tensor) -> tuple:
    """Switch 9i: ResidMix's backward through the kernel's op on rows [M, D]: (dx, dx0) in g's shape and the two
    gains' gradients as bf16 [1] tensors (the fp32 sum of the op's partials, rounded as the autograd backward
    rounds its own)."""
    shape, d = g.shape, g.size(-1)
    g2 = g.contiguous().reshape(-1, d)
    dx2, dx02, part = RESMIX_OPS["bwd"](g2, x.contiguous().reshape(-1, d), x0.contiguous().reshape(-1, d),
                                        RESMIX_MODULE.ab_tile(a, b))
    ga, gb = RESMIX_MODULE.lambda_grads(part, a.dtype)
    return dx2.view(shape), dx02.view(shape), ga.reshape(a.shape), gb.reshape(b.shape)


def resmix_apply(x: torch.Tensor, x0: torch.Tensor, resid_lambda: torch.Tensor,
                 x0_lambda: torch.Tensor) -> torch.Tensor:
    """Switch 9i: the mix through ResidMix (x and x0 of one shape; on a Neuron device bf16 rows the kernel takes, with
    its op registered: anything else raises, never a silent fallback)."""
    if x0.shape != x.shape:
        raise RuntimeError(f"switch 9i: x0 {tuple(x0.shape)} and x {tuple(x.shape)} differ")
    if x.device.type == "neuron":
        m, d = x.numel() // x.size(-1), x.size(-1)
        if not (RESMIX_READY and x.dtype == torch.bfloat16 and x0.dtype == x.dtype
                and RESMIX_MODULE.shapes_apply(m, d)):
            raise RuntimeError(f"switch 9i: the kernel does not take {tuple(x.shape)} {x.dtype} (registered: "
                               f"{RESMIX_READY})")
    return ResidMix.apply(x, x0, resid_lambda, x0_lambda)


def resmix_summary() -> str:
    """Switch 9i: the end-of-run line: the op body's count and whether the op was registered."""
    if not R2_RESMIX_FUSE:
        return "off"
    return (" ".join(f"{k}={v}" for k, v in RESMIX_COUNTS.items())
            + (" registered" if RESMIX_READY else " not registered"))


# -----------------------------------------------------------------------------
# Switch 55: the expert-parallel mixture of experts (its settings and their meaning: the switch block at the top).
# The routing follows lane MOE's moe_route.py (the feasibility bench's code, laptop-proven and 4-rank smoked: the
# tournament, the block counts, the bf16-exact token digits, GatherRows) with the capacity count made per sequence
# and in token order (A-moe-rules F1), so a token's skip depends only on the tokens before it in its own sequence.

MOE_EP = {"rank": 0, "world": 1, "attach": False}  # how MoeMLP builds its experts: main() sets rank and world (rank e
#                                                    holds expert e); load_for_eval sets attach (no expert tensor
#                                                    until attach_experts hands the checkpoint's over)
MOE_BLOCK = 128            # positions per block of the capacity count (the in-block and cross-block products)
MOE_DIGIT = 64             # a slot table's positions as hi * 64 + lo, each digit below 64: exact in bf16 products
MOE_B_MAX = 256            # rows one forward may hold (the length of the constant row index)
MOE_LOCAL_IMPL = "bmm"     # every expert on this device: "bmm" (one batched product a matrix) or "loop" (one F.linear
#                            an expert, the expert-parallel form's own call: the CPU proofs' bitwise leg)
MOE_RESCUE = {"copies": 0, "seconds": 0.0}         # lane MOE3: rank 0's rescue copies to the host
MOE_KERNEL = {"module": None, "ready": False}      # R2_MOE_EXPERT_MLP=fused: switch 9b's bf16 kernel pair
MOE_FUNCOL = None          # torch.distributed._functional_collectives, imported when an expert-parallel layer is built


def parse_moe_layers(value: str, n_layer: int) -> tuple:
    """Switch 55: R2_MOE_LAYERS as block indices: "odd" (1, 3, ...), "all", or a comma list."""
    if value == "odd":
        layers = tuple(range(1, n_layer, 2))
    elif value == "all":
        layers = tuple(range(n_layer))
    else:
        try:
            layers = tuple(sorted({int(v) for v in value.split(",") if v.strip()}))
        except ValueError:
            layers = ()
        if not layers or any(not 0 <= i < n_layer for i in layers):
            raise ValueError(f"R2_MOE_LAYERS={value!r}: expected odd, all or a comma list of block indices below "
                             f"{n_layer}")
    if not layers:
        raise ValueError(f"R2_MOE_LAYERS={value!r}: no block at depth {n_layer}")
    return layers


def moe_capacity_for(cf: float, seq_len: int, topk: int, n_exp: int) -> int:
    """Switch 55: C, the assignments one expert serves within one sequence: round(cf x seq_len x k / E), at least 1."""
    return max(1, int(round(cf * seq_len * topk / n_exp)))


def moe_config_fields(depth: int, n_embd: int, sequence_len: int) -> dict:
    """Switch 55: the GPTConfig fields of the layout as run (empty while R2_MOE is off, so the config is the base's)."""
    if not R2_MOE:
        return {}
    n_exp = R2_MOE_EXPERTS or MOE_EP["world"]
    return {"moe_layers": parse_moe_layers(R2_MOE_LAYERS, depth), "moe_experts": n_exp, "moe_topk": R2_MOE_TOPK,
            "moe_capacity": moe_capacity_for(R2_MOE_CF, sequence_len, R2_MOE_TOPK, n_exp),
            "moe_hidden": R2_MOE_HIDDEN or n_embd,
            "moe_shared": 2 * n_embd if R2_MOE_SHARED < 0 else R2_MOE_SHARED,
            "moe_dispatch": R2_MOE_DISPATCH, "moe_shared_mlp": R2_MOE_SHARED_MLP}


def moe_seed(*parts) -> int:
    """Switch 55: a generator seed from the run's seed and a tensor's place (an md5 of the parts: the same on every
    rank and platform), so each expert and each router draws its own stream and the base's stream is untouched."""
    return int(hashlib.md5(":".join(str(p) for p in ("moe",) + parts).encode("ascii")).hexdigest()[:15], 16)


def moe_tournament(v: torch.Tensor, iota: torch.Tensor):
    """Switch 55 (lane MOE's tournament_max): the largest entry of each row of v [N, E] and its index (fp32), by
    log2 E levels of pairwise compares: at each level the entries pair as (2j, 2j + 1) and b > a takes the upper one.
    Ties go low (torch.argmax's first maximum). No index-returning reduction and no equality compare: inside a compiled
    graph with matmul-produced inputs the device returns a sentinel for the first and mismatches the second
    (LBD2_devdiag; the tournament read SAFE there). A NaN never wins a compare, so a NaN row returns an in-range
    index."""
    n = v.size(-1)
    i = iota.expand_as(v)
    while n > 1:
        h = n // 2
        v2 = v.reshape(*v.shape[:-1], h, 2)
        i2 = i.reshape(*i.shape[:-1], h, 2)
        up = v2[..., 1] > v2[..., 0]
        v = torch.where(up, v2[..., 1], v2[..., 0])
        i = torch.where(up, i2[..., 1], i2[..., 0])
        n = h
    return v[..., 0], i[..., 0]


def moe_route(logits: torch.Tensor, iota_e: torch.Tensor, topk: int) -> dict:
    """Switch 55: fp32 router logits [N, E] -> the softmax p, each token's k best experts (fp32 indices i, boolean
    masks m [N, E]) and their gates g: renormalised over the two at k = 2 (Mixtral's form), the probability itself at
    k = 1 (Switch's form, so the router keeps a gradient). Masks are |a - b| < 0.5 between exact small integers."""
    p = torch.softmax(logits.float(), dim=-1)
    if R2_MOE_ROUTE_DETACH:
        # Lane MOE3 (MOEK's (t)): the picks from the detached probabilities; each gate is the probabilities times
        # the pick's mask summed, one nonzero term, so the tournament's value exactly, and its gradient reaches the
        # picked probability alone, as through the tournament's selections, with no backward through the compares.
        pd = p.detach()
        i1 = moe_tournament(pd, iota_e)[1]
        m1 = (iota_e - i1.unsqueeze(-1)).abs() < 0.5
        v1 = (p * m1).sum(-1)
        if topk == 1:
            return {"p": p, "m": (m1,), "i": (i1,), "g": (v1,)}
        i2 = moe_tournament(pd.masked_fill(m1, -1.0), iota_e)[1]
        m2 = (iota_e - i2.unsqueeze(-1)).abs() < 0.5
        v2 = (p * m2).sum(-1)
        den = v1 + v2
        return {"p": p, "m": (m1, m2), "i": (i1, i2), "g": (v1 / den, v2 / den)}
    v1, i1 = moe_tournament(p, iota_e)
    m1 = (iota_e - i1.unsqueeze(-1)).abs() < 0.5
    if topk == 1:
        return {"p": p, "m": (m1,), "i": (i1,), "g": (v1,)}
    v2, i2 = moe_tournament(p.masked_fill(m1, -1.0), iota_e)
    m2 = (iota_e - i2.unsqueeze(-1)).abs() < 0.5
    den = v1 + v2
    return {"p": p, "m": (m1, m2), "i": (i1, i2), "g": (v1 / den, v2 / den)}


def moe_positions(mall: torch.Tensor, b: int, t: int, tril_in: torch.Tensor, tril_ex: torch.Tensor) -> torch.Tensor:
    """Switch 55, the capacity count: mall [b * t, E] fp32 0/1 (every assignment of every token; a token's choices are
    distinct experts) -> excl [b, t, E]: for each token and expert, the assignments to that expert at earlier positions
    of the same row. Two products over blocks of MOE_BLOCK positions (inside a block tril_in, the inclusive lower
    triangle; across blocks tril_ex, the strict one), no cumsum and no scatter. Exact in fp32; with bf16 product outputs
    (the compiler's auto-cast) every count below 256 is still exact and a count at or above 256 stays at or above 256,
    so a capacity up to 256 decides every keep exactly. A row is padded with positions that hold no assignment, which
    change no real position's count (the padding follows every real position)."""
    n_exp = mall.size(-1)
    blk = MOE_BLOCK
    tp = -(-t // blk) * blk
    m = mall.reshape(b, t, n_exp)
    if tp != t:
        m = F.pad(m, (0, 0, 0, tp - t))
    nb = tp // blk
    mb = m.reshape(b, nb, blk, n_exp)
    incl = torch.matmul(tril_in, mb)                                   # [b, nb, blk, E], at most blk
    prefix = torch.matmul(tril_ex[:nb, :nb], incl[:, :, blk - 1, :])  # [b, nb, E]: the row's earlier blocks
    excl = incl - mb + prefix.unsqueeze(2)
    return excl.reshape(b, tp, n_exp)[:, :t]


def moe_slot_onehot(excl: torch.Tensor, mall3: torch.Tensor, cap: int, iota_c: torch.Tensor, dtype) -> torch.Tensor:
    """Switch 55: [b, t, E, cap] in dtype (0/1): 1 where token t's assignment to expert e holds that expert's slot c of
    the row (its count below cap). A skipped assignment (a count at or above cap) matches no slot."""
    oc = (iota_c - excl.unsqueeze(-1)).abs() < 0.5
    return oc.to(dtype) * mall3.to(dtype).unsqueeze(-1)


def moe_gather_tables(route: dict, excl: torch.Tensor, mall: torch.Tensor, b: int, t: int, cap: int,
                      c: dict) -> dict:
    """Switch 55, the gather form's int32 tables for a [b, t] input, the slot buffer laid out [E, b, cap] (expert e's
    chunk of b * cap rows travels to rank e):
      s  [b * t] each    the slot of each token's k-th assignment, or S = E * b * cap (a zero row) when it is skipped;
      p  [S]             the token in each slot, or N = b * t (a zero row) when the slot is empty;
      sel [S]            (k = 2) whether a slot holds a first choice.
    p comes from a transient bf16 one-hot through three [1, t] x [t, E * cap] products a row, each output below 64
    (exact in bf16); every index is an exact integer in fp32 (below 2^24) before its cast to int32."""
    n_exp = c["iota_e"].numel()
    n = b * t
    s_total = n_exp * b * cap
    rowf = c["iota_b"][:b]
    row_tok = rowf.view(b, 1).expand(b, t).reshape(n)
    ex = excl.reshape(n, n_exp)
    slots, poss = [], []
    for mk, ik in zip(route["m"], route["i"]):
        pos = (ex * mk.to(ex.dtype)).sum(-1)
        keep = pos < (cap - 0.5)
        slot = torch.where(keep, (ik * b + row_tok) * cap + pos, torch.full_like(pos, float(s_total)))
        slots.append(slot.to(torch.int32))
        poss.append(pos)
    if R2_MOE_SLOT_FACTOR:
        # Lane MOE3 (MOEK's (f)): for each assignment k, [E, t] (its expert mask times a digit of the position) x
        # [t, cap] (the one-hot of its slot) a row. A slot is held by one assignment of one token or by none, so
        # every output is one digit below 64 or 0, exact in bf16: the one-hot form's tables bit for bit.
        bf = torch.bfloat16
        hi = lo = occ = None
        for mk, pos in zip(route["m"], poss):
            oc = ((c["iota_c"] - pos.unsqueeze(-1)).abs() < 0.5).to(bf).reshape(b, t, cap)
            mt = mk.to(bf).reshape(b, t, n_exp)
            parts = [torch.matmul((mt * c[dg][:, :t].to(bf).reshape(1, t, 1)).transpose(1, 2), oc).float()
                     for dg in ("tok_hi", "tok_lo")]
            parts.append(torch.matmul(mt.transpose(1, 2), oc).float())             # [b, E, cap] each
            hi, lo, occ = parts if hi is None else (hi + parts[0], lo + parts[1], occ + parts[2])
    else:
        d = moe_slot_onehot(excl, mall.reshape(b, t, n_exp), cap, c["iota_c"], torch.bfloat16).reshape(
            b, t, n_exp * cap)
        hi = torch.matmul(c["tok_hi"][:, :t].to(torch.bfloat16), d).float()      # [b, 1, E * cap]
        lo = torch.matmul(c["tok_lo"][:, :t].to(torch.bfloat16), d).float()
        occ = torch.matmul(c["ones_t"][:, :t].to(torch.bfloat16), d).float()
    tok = hi * MOE_DIGIT + lo + (rowf * t).view(b, 1, 1)
    p = torch.where(occ > 0.5, tok, torch.full_like(tok, float(n)))
    p = p.reshape(b, n_exp, cap).transpose(0, 1).reshape(s_total).to(torch.int32)
    out = {"s": slots, "p": p}
    if len(route["i"]) == 2:
        i1 = route["i"][0]
        i1_pad = torch.cat([i1, i1.new_full((1,), -1.0)])
        e_slot = c["iota_e"].view(n_exp, 1, 1).expand(n_exp, b, cap).reshape(s_total)
        out["sel"] = (i1_pad.index_select(0, p) - e_slot).abs() < 0.5
    return out


class MoeGatherRows(torch.autograd.Function):
    """Switch 55 (lane MOE's GatherRows): out[n] = src_pad[idx[n]] (src_pad = src plus one zero row), and its backward
    as a second gather, d_src[s] = g_pad[inv[s]]. Exact when every real row of src is read by at most one n and inv is
    that n (or the zero row's index for none). No index_add, scatter or index_put on the device, forward or backward."""

    @staticmethod
    def forward(ctx, src, idx, inv):
        ctx.save_for_backward(inv)
        pad = torch.cat([src, src.new_zeros(1, src.size(1))], 0)
        return pad.index_select(0, idx)

    @staticmethod
    def backward(ctx, g):
        (inv,) = ctx.saved_tensors
        gpad = torch.cat([g, g.new_zeros(1, g.size(1))], 0)
        return gpad.index_select(0, inv), None, None


class MoeDispatch2(torch.autograd.Function):
    """Switch 55, the top-2 dispatch: xs[s] = h_pad[p[s]] (a slot holds one assignment), and its backward d_h[n] =
    g_pad[s1[n]] + g_pad[s2[n]] (a token's two slots; the zero row for a skipped one): gathers both ways."""

    @staticmethod
    def forward(ctx, h, p, s1, s2):
        ctx.save_for_backward(s1, s2)
        pad = torch.cat([h, h.new_zeros(1, h.size(1))], 0)
        return pad.index_select(0, p)

    @staticmethod
    def backward(ctx, g):
        s1, s2 = ctx.saved_tensors
        gpad = torch.cat([g, g.new_zeros(1, g.size(1))], 0)
        return gpad.index_select(0, s1) + gpad.index_select(0, s2), None, None, None


class MoeCombine2(torch.autograd.Function):
    """Switch 55, the top-2 combine's two reads: y_k[n] = ys_pad[s_k[n]], and the backward d_ys[s] = d_y1_pad[p[s]]
    where slot s holds a first choice, d_y2_pad[p[s]] where it holds a second (an empty slot reads the zero rows)."""

    @staticmethod
    def forward(ctx, ys, s1, s2, p, sel):
        ctx.save_for_backward(p, sel)
        pad = torch.cat([ys, ys.new_zeros(1, ys.size(1))], 0)
        return pad.index_select(0, s1), pad.index_select(0, s2)

    @staticmethod
    def backward(ctx, g1, g2):
        p, sel = ctx.saved_tensors
        z = g1.new_zeros(1, g1.size(1))
        a = torch.cat([g1, z], 0).index_select(0, p)
        c = torch.cat([g2, z], 0).index_select(0, p)
        return torch.where(sel.unsqueeze(-1), a, c), None, None, None, None


def moe_all_to_all(t: torch.Tensor) -> torch.Tensor:
    """Switch 55: chunk e of t's rows (equal splits over the world) to rank e: one all_to_all_single over the world
    group, the functional collective (traceable inside the compiled graph; its registered autograd is the reversed
    exchange). The neuron backend maps a functional collective on the default group to the world group."""
    return MOE_FUNCOL.all_to_all_single(t.contiguous(), None, None, dist.group.WORLD)


def moe_expert_mlp(x2: torch.Tensor, w_fc: torch.Tensor, w_proj: torch.Tensor) -> torch.Tensor:
    """Switch 55: one expert's ReLU^2 MLP on its received rows x2 [R, d] with its 2-D weights: switch 9b's bf16 kernel
    pair where R2_MOE_EXPERT_MLP=fused and the kernels take the shape (rows, width and hidden multiples of 128), its
    torch emulation off a Neuron device, else the kit's expression (bf16 products, fp32 accumulation: the kernel's
    rounding points up to summation order)."""
    dt = x2.dtype
    wf, wp = w_fc.to(dt), w_proj.to(dt)
    mod = MOE_KERNEL["module"]
    if R2_MOE_EXPERT_MLP == "fused" and mod is not None:
        if (MOE_KERNEL["ready"] and x2.device.type == "neuron" and dt == torch.bfloat16
                and mod.shapes_apply(x2.size(0), x2.size(1), wf.size(0), R2_MLP_TB)):
            y, _rT = MLP_OPS["fwd"](x2.contiguous(), wf, wp)
            return y
        if x2.device.type != "neuron":
            return mod.EmulatedFusedMlp.apply(x2.contiguous(), wf, wp, MLP_DW_MODE)
    return F.linear(torch.relu(F.linear(x2, wf)).square(), wp)


def moe_experts_local(xs3: torch.Tensor, w_fc: torch.Tensor, w_proj: torch.Tensor) -> torch.Tensor:
    """Switch 55, every expert on this device: xs3 [E, R, d] (expert e's slots), w_fc [E, H, d], w_proj [E, d, H] ->
    [E, R, d], the kit's expression for each expert (MOE_LOCAL_IMPL: one batched product a matrix, or one F.linear
    an expert)."""
    dt = xs3.dtype
    wf, wp = w_fc.to(dt), w_proj.to(dt)
    if MOE_LOCAL_IMPL == "loop":
        return torch.stack([F.linear(torch.relu(F.linear(xs3[e], wf[e])).square(), wp[e]) for e in range(xs3.size(0))])
    hid = torch.relu(torch.bmm(xs3, wf.transpose(1, 2))).square()
    return torch.bmm(hid, wp.transpose(1, 2))


MOE8_COUNTS = {"ep_blocks": 0, "local_blocks": 0, "refreshes": 0}   # switch 66: host counts (moe8_refresh only)


def moe_expert8_mlp(x2: torch.Tensor, w_fc: torch.Tensor, w_proj: torch.Tensor, sc: torch.Tensor,
                    w8: torch.Tensor) -> torch.Tensor:
    """Switch 66 (lane THR13): one expert's MLP on its received rows x2 [R, d] (training, one expert a rank) on switch
    9f's op pair with the expert's scale tile sc [128, NSC] and e4m3 bytes w8 [4, F x d] (fp8_refresh_weights writes
    both after every optimizer step), the rows padded with zeros to a multiple of 128 as mlp_fused8 pads (a zero row
    gives a zero output row and touches no other row); off a Neuron device switch 9c's emulation (the same
    arithmetic). No bf16 expert runs under switch 66: a shape the kernels do not take on a Neuron device raises."""
    dt = x2.dtype
    wf, wp = w_fc.to(dt), w_proj.to(dt)
    m = x2.size(0)
    if MLP_L4_READY and mlp8_applies(x2, wf.size(0)):
        pad = (-m) % 128
        if pad:
            x2 = F.pad(x2, (0, 0, 0, pad))
        y, _rT = MLP_L4_OPS["fwd"](x2.contiguous(), wf, wp, sc, w8)
        return y[:m] if pad else y
    if x2.device.type != "neuron" and MLP8_MODULE is not None:
        return MLP8_MODULE.EmulatedFusedMlp8.apply(x2.contiguous(), wf, wp, sc, MLP8_MODE, MLP_DW_MODE)
    raise RuntimeError(f"switch 66: the fp8 MLP kernels do not take the experts' rows {tuple(x2.shape)} {dt} with "
                       f"hidden width {wf.size(0)} (switch 9f registered: {MLP_L4_READY})")


def moe_experts8_local(xs3: torch.Tensor, w_fc: torch.Tensor, w_proj: torch.Tensor, sc: torch.Tensor) -> torch.Tensor:
    """Switch 66 (lane THR13), every expert on this device (load_for_eval's model, a one-rank run): xs3 [E, R, d] ->
    [E, R, d], expert e on switch 9c's op pair with its scale tile sc[e] (its in-kernel cast gives switch 9f's outputs
    bit for bit, so no e4m3 bytes are held here), the rows padded to a multiple of 128; off a Neuron device switch
    9c's emulation. The forward the experts trained with, one expert at a time."""
    dt = xs3.dtype
    wf, wp = w_fc.to(dt), w_proj.to(dt)
    m = xs3.size(1)
    outs = []
    for e in range(xs3.size(0)):
        x2 = xs3[e]
        if mlp8_applies(x2, wf.size(1)):
            pad = (-m) % 128
            if pad:
                x2 = F.pad(x2, (0, 0, 0, pad))
            y, _rT = MLP8_OPS["fwd"](x2.contiguous(), wf[e], wp[e], sc[e])
            outs.append(y[:m] if pad else y)
        elif x2.device.type != "neuron" and MLP8_MODULE is not None:
            outs.append(MLP8_MODULE.EmulatedFusedMlp8.apply(x2.contiguous(), wf[e], wp[e], sc[e], MLP8_MODE,
                                                            MLP_DW_MODE))
        else:
            raise RuntimeError(f"switch 66: the fp8 MLP kernels do not take the experts' rows {tuple(x2.shape)} "
                               f"{dt} with hidden width {wf.size(1)} (switch 9c registered: {MLP8_READY})")
    return torch.stack(outs)


def moe_aux_terms(route: dict, logits: torch.Tensor, mall: torch.Tensor, b: int, t: int, n_exp: int, topk: int):
    """Switch 55, training only: the Switch load-balance term E sum_e f_e P_e over the rank's micro-batch (f_e: the
    share of the k x N assignments that chose e, from the masks, no gradient; P_e: the mean router probability), its
    per-sequence form under R2_MOE_AUX_SEQ, and the router z-loss mean(logsumexp(logits)^2). Returns the weighted sum
    and (lb, z, f) for the statistics."""
    p = route["p"]
    f = mall.mean(0) / topk
    lb = n_exp * (f * p.mean(0)).sum()
    z = torch.logsumexp(logits, dim=-1).square().mean()
    aux = R2_MOE_AUX * lb + R2_MOE_ZLOSS * z
    if R2_MOE_AUX_SEQ > 0.0:
        fs = mall.reshape(b, t, n_exp).mean(1) / topk
        ps = p.reshape(b, t, n_exp).mean(1)
        aux = aux + R2_MOE_AUX_SEQ * (n_exp * (fs * ps).sum(-1)).mean()
    return aux, lb, z, f


class MoeShared(MLP):
    """Switch 55: a MoE block's shared half, the base's MLP at width `hidden` (R2_MOE_SHARED): the same forward (the
    fused or the fp8 kernels as R2_MLP picks them, with its own scale tile under fused8) or, on route "plain", the
    kit's expression."""

    def __init__(self, config: GPTConfig, hidden: int, route: str):
        nn.Module.__init__(self)
        # skip_init: no draw from the global generator (MoeMLP makes the dense MLP's construction draws itself).
        self.c_fc = torch.nn.utils.skip_init(Linear, config.n_embd, hidden, bias=False)
        self.c_proj = torch.nn.utils.skip_init(Linear, hidden, config.n_embd, bias=False)
        self.route = route
        if R2_MLP == "fused8" and route == "base":
            self.register_buffer("mlp8_sc", torch.full((128, MLP8_NSC), float("nan")), persistent=False)
            if R2_MOE_SHPC:
                # Switch 55s: the shared half's e4m3 bytes in switch 9f's layout, written by fp8_refresh_weights.
                self.register_buffer("mlp8_w8", torch.zeros((4, hidden * config.n_embd), dtype=torch.uint8),
                                     persistent=False)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if self.route == "plain":
            return self.c_proj(relu_squared(self.c_fc(x)))
        return MLP.forward(self, x)


class MoeMLP(nn.Module):
    """Switch 55: a block's MLP as its shared half plus E routed experts. x [b, t, n_embd] (the block's normalised
    input) -> the MLP's output of that shape; with want_stats (training) also the router's weighted loss terms and a
    statistics vector [3 + E] (kept share of assignments, balance term, z term, the experts' load shares)."""

    def __init__(self, config: GPTConfig, layer: int):
        super().__init__()
        global MOE_FUNCOL
        d, n_exp, hid = config.n_embd, config.moe_experts, config.moe_hidden
        self.layer, self.n_exp, self.hidden = layer, n_exp, hid
        self.topk, self.cap, self.dispatch = config.moe_topk, config.moe_capacity, config.moe_dispatch
        rank, world = MOE_EP["rank"], MOE_EP["world"]
        if n_exp < 2 or n_exp & (n_exp - 1):
            raise ValueError(f"switch 55: {n_exp} experts is not a power of two from 2 (the tournament pairs them)")
        if world > 1 and n_exp != world:
            raise ValueError(f"switch 55: {n_exp} experts on {world} ranks: the expert-parallel form holds one a rank")
        if not 1 <= self.cap <= 256:
            raise ValueError(f"switch 55: capacity {self.cap} outside 1 to 256 (the bf16-exact count bound)")
        if self.dispatch not in ("gather", "onehot") or config.moe_topk not in (1, 2) or hid < 1:
            raise ValueError(f"switch 55: dispatch {self.dispatch!r}, top-k {config.moe_topk}, hidden {hid}")
        # The base's MLP construction draws (nn.Linear's default init, overwritten by init_weights) are made and
        # discarded, so the global generator reaches init_weights where the base's does: every base tensor's values
        # are then the base's. Nothing below draws from it (torch.empty, skip_init, the host constants).
        MLP(config)
        self.ep = world > 1
        self.e0 = rank if self.ep else 0
        self.n_local = 1 if self.ep else n_exp
        if self.ep and MOE_FUNCOL is None:
            import torch.distributed._functional_collectives as funcol
            MOE_FUNCOL = funcol
        self.router = nn.Parameter(torch.empty(n_exp, d))
        route = config.moe_shared_mlp or "base"
        self.shared = MoeShared(config, config.moe_shared, route) if config.moe_shared else None
        if MOE_EP["attach"]:
            self.register_parameter("w_fc", None)
            self.register_parameter("w_proj", None)
        else:
            self.w_fc = nn.Parameter(torch.empty(self.n_local, hid, d))
            self.w_proj = nn.Parameter(torch.empty(self.n_local, d, hid))
        # Switch 66 (lane THR13): the fp8 experts' scale tiles (fp8_refresh_weights writes them): in training (one
        # expert a rank) [128, NSC] and the expert's e4m3 bytes [4, F x d] in switch 9f's layout; on one device
        # (scoring) [n_local, 128, NSC], one an expert, and no bytes (switch 9c's op pair casts in the kernel).
        self.e8 = bool(config.moe_expert8)
        if self.e8:
            if R2_MLP != "fused8":
                raise RuntimeError("switch 66: this model's routed experts run the fp8 MLP route: R2_MLP=fused8 must "
                                   "be set where it trains or is scored (the dense fp8 MLPs need it too)")
            if self.ep:
                self.register_buffer("exp8_sc", torch.full((128, MLP8_NSC), float("nan")), persistent=False)
                self.register_buffer("exp8_w8", torch.zeros((4, hid * d), dtype=torch.uint8), persistent=False)
            else:
                self.register_buffer("exp8_sc", torch.full((self.n_local, 128, MLP8_NSC), float("nan")),
                                     persistent=False)
        nb = -(-config.sequence_len // MOE_BLOCK)
        if nb * MOE_BLOCK > MOE_DIGIT * MOE_DIGIT:
            raise ValueError(f"switch 55: sequence_len {config.sequence_len} above the two-digit position bound "
                             f"{MOE_DIGIT * MOE_DIGIT}")
        pos = torch.arange(nb * MOE_BLOCK, dtype=torch.int64)
        consts = {"iota_e": torch.arange(n_exp, dtype=torch.float32),
                  "iota_c": torch.arange(self.cap, dtype=torch.float32),
                  "iota_b": torch.arange(MOE_B_MAX, dtype=torch.float32),
                  "tril_in": torch.tril(torch.ones(MOE_BLOCK, MOE_BLOCK, dtype=torch.float32)),
                  "tril_ex": torch.tril(torch.ones(nb, nb, dtype=torch.float32), diagonal=-1),
                  "tok_hi": (pos // MOE_DIGIT).to(torch.float32).view(1, -1),
                  "tok_lo": (pos % MOE_DIGIT).to(torch.float32).view(1, -1),
                  "ones_t": torch.ones(1, nb * MOE_BLOCK, dtype=torch.float32)}
        self.const_names = tuple(consts)
        for k, v in consts.items():
            # Host-built constants, never in model_state (non-persistent) and never written after construction.
            self.register_buffer("moe_" + k, v, persistent=False)

    def trunk_parameters(self) -> list:
        """The data-parallel parameters: the router and the shared half (the experts are the rank's own)."""
        ps = [self.router]
        if self.shared is not None:
            ps.extend(self.shared.parameters())
        return ps

    def expert_parameters(self) -> list:
        """This rank's (or, on one device, every) expert tensor: w_fc [n, H, d], then w_proj [n, d, H]."""
        return [p for p in (self.w_fc, self.w_proj) if p is not None]

    @torch.no_grad()
    def init_stream(self, s: float) -> None:
        """The base's draws for this block's MLP, made as the base makes them: one [4 n_embd, n_embd] uniform (so every
        later tensor of the base draws the values it draws without the switch); the shared half's c_fc takes its first
        rows and its c_proj starts at zero."""
        d = self.router.size(1)
        dense = torch.empty(4 * d, d, dtype=torch.float32, device=self.router.device)
        torch.nn.init.uniform_(dense, -0.4 * s, 0.4 * s)
        if self.shared is not None:
            w = self.shared.c_fc.weight
            if w.size(0) > dense.size(0):
                raise ValueError(f"switch 55: a shared half of {w.size(0)} is wider than the dense MLP's "
                                 f"{dense.size(0)}")
            w.copy_(dense[:w.size(0)])
            torch.nn.init.zeros_(self.shared.c_proj.weight)

    @torch.no_grad()
    def init_own(self, s: float) -> None:
        """The router (normal, R2_MOE_ROUTER_STD) and each expert held here (W_in uniform by the kit's c_fc rule, W_out
        zero) from their own generators: expert e's tensors are the same on any rank and in any build."""
        g = torch.Generator().manual_seed(moe_seed(R2_SEED, self.layer, "router"))
        self.router.copy_(torch.randn(tuple(self.router.shape), generator=g) * R2_MOE_ROUTER_STD)
        if self.w_fc is None:
            return
        for j in range(self.n_local):
            g = torch.Generator().manual_seed(moe_seed(R2_SEED, self.layer, self.e0 + j, "fc"))
            self.w_fc[j].copy_(torch.empty(tuple(self.w_fc.shape[1:])).uniform_(-0.4 * s, 0.4 * s, generator=g))
        self.w_proj.zero_()

    def attach_experts(self, w_fc: torch.Tensor, w_proj: torch.Tensor) -> None:
        """load_for_eval: the checkpoint's experts, [E, H, d] and [E, d, H] at their saved dtype (the training
        replicas'), as this layer's parameters (every expert on this device)."""
        want = (self.n_exp, self.hidden, self.router.size(1))
        if tuple(w_fc.shape) != want or tuple(w_proj.shape) != (want[0], want[2], want[1]):
            raise ValueError(f"switch 55: block {self.layer}'s experts {tuple(w_fc.shape)} / {tuple(w_proj.shape)}, "
                             f"expected {want} / {(want[0], want[2], want[1])}")
        self.w_fc = nn.Parameter(w_fc, requires_grad=False)
        self.w_proj = nn.Parameter(w_proj, requires_grad=False)

    def forward(self, x: torch.Tensor, want_stats: bool = False):
        if self.e8:
            return self.forward_e8(x, want_stats)       # switch 66 (lane THR13): forward with the fp8 experts
        b, t, d = x.shape
        if R2_SEQ_LEN and want_stats and t < SEQ_RAMP_STATE["moe_rows"] and (b * t) % SEQ_RAMP_STATE["moe_rows"] == 0:
            # Switch 27, the window phase: the capacity counted over the base's rows of SEQ_RAMP_STATE["moe_rows"]
            # tokens (this micro-step's windows in loader order), so routing, slots, drops and the exchange are the
            # base's for the same hidden states.
            s27_rows = SEQ_RAMP_STATE["moe_rows"]
            y, aux, stats = self.forward(x.reshape(b * t // s27_rows, s27_rows, d), want_stats=True)
            return y.reshape(b, t, d), aux, stats
        n_tok_max = self.moe_tok_hi.size(1)
        if b > MOE_B_MAX or t > n_tok_max:
            raise ValueError(f"switch 55: a [{b}, {t}] input exceeds the layer's {MOE_B_MAX} rows or {n_tok_max} "
                             f"positions")
        n_exp, cap, k = self.n_exp, self.cap, self.topk
        c = {name: getattr(self, "moe_" + name) for name in self.const_names}
        h = x.reshape(b * t, d)
        logits = F.linear(h.float(), self.router.float())
        route = moe_route(logits, c["iota_e"], k)
        mall = route["m"][0].to(torch.float32)
        for mk in route["m"][1:]:
            mall = mall + mk.to(torch.float32)
        excl = moe_positions(mall, b, t, c["tril_in"], c["tril_ex"])
        s_total = n_exp * b * cap
        if self.dispatch == "onehot":
            dmat = moe_slot_onehot(excl, mall.reshape(b, t, n_exp), cap, c["iota_c"], x.dtype)
            xs = torch.einsum("btec,btd->ebcd", dmat, x).reshape(s_total, d)
        else:
            tab = moe_gather_tables(route, excl, mall, b, t, cap, c)
            if k == 1:
                xs = MoeGatherRows.apply(h, tab["p"], tab["s"][0])
            else:
                xs = MoeDispatch2.apply(h, tab["p"], tab["s"][0], tab["s"][1])
        if self.ep:
            # Training: this rank's slots for expert e to rank e, this rank's expert on every rank's slots for it, and
            # the outputs back to the slots they came from.
            ys = moe_all_to_all(moe_expert_mlp(moe_all_to_all(xs), self.w_fc[0], self.w_proj[0]))
        else:
            ys = moe_experts_local(xs.reshape(n_exp, b * cap, d), self.w_fc, self.w_proj).reshape(s_total, d)
        dt = ys.dtype
        if self.dispatch == "onehot":
            gate = route["m"][0].to(torch.float32) * route["g"][0].unsqueeze(-1)
            for mk, gk in zip(route["m"][1:], route["g"][1:]):
                gate = gate + mk.to(torch.float32) * gk.unsqueeze(-1)
            gmat = dmat * gate.reshape(b, t, n_exp, 1).to(dmat.dtype)
            out = torch.einsum("btec,ebcd->btd", gmat, ys.reshape(n_exp, b, cap, d))
        elif k == 1:
            out = route["g"][0].to(dt).unsqueeze(-1) * MoeGatherRows.apply(ys, tab["s"][0], tab["p"])
        else:
            y1, y2 = MoeCombine2.apply(ys, tab["s"][0], tab["s"][1], tab["p"], tab["sel"])
            out = route["g"][0].to(dt).unsqueeze(-1) * y1 + route["g"][1].to(dt).unsqueeze(-1) * y2
        out = out.reshape(b, t, d)
        if self.shared is not None:
            out = out + self.shared(x)
        if not want_stats:
            return out
        aux, lb, z, f = moe_aux_terms(route, logits, mall, b, t, n_exp, k)
        kept = (mall * (excl.reshape(b * t, n_exp) < cap - 0.5).to(torch.float32)).sum() / (b * t * k)
        stats = torch.cat([torch.stack([kept, lb.detach(), z.detach()]), f]).detach()
        return out, aux, stats

    def forward_e8(self, x: torch.Tensor, want_stats: bool = False):
        """Switch 66 (lane THR13): forward with the routed experts on the fp8 route: moe_expert8_mlp with this rank's
        expert's scale tile and e4m3 bytes in training (one expert a rank), moe_experts8_local on one device. Every
        other line is forward's (lane THR13's static check compares the two syntax trees: these two calls differ, and
        forward's two-line dispatch here)."""
        b, t, d = x.shape
        if R2_SEQ_LEN and want_stats and t < SEQ_RAMP_STATE["moe_rows"] and (b * t) % SEQ_RAMP_STATE["moe_rows"] == 0:
            # Switch 27, the window phase: the capacity counted over the base's rows of SEQ_RAMP_STATE["moe_rows"]
            # tokens (this micro-step's windows in loader order), so routing, slots, drops and the exchange are the
            # base's for the same hidden states.
            s27_rows = SEQ_RAMP_STATE["moe_rows"]
            y, aux, stats = self.forward(x.reshape(b * t // s27_rows, s27_rows, d), want_stats=True)
            return y.reshape(b, t, d), aux, stats
        n_tok_max = self.moe_tok_hi.size(1)
        if b > MOE_B_MAX or t > n_tok_max:
            raise ValueError(f"switch 55: a [{b}, {t}] input exceeds the layer's {MOE_B_MAX} rows or {n_tok_max} "
                             f"positions")
        n_exp, cap, k = self.n_exp, self.cap, self.topk
        c = {name: getattr(self, "moe_" + name) for name in self.const_names}
        h = x.reshape(b * t, d)
        logits = F.linear(h.float(), self.router.float())
        route = moe_route(logits, c["iota_e"], k)
        mall = route["m"][0].to(torch.float32)
        for mk in route["m"][1:]:
            mall = mall + mk.to(torch.float32)
        excl = moe_positions(mall, b, t, c["tril_in"], c["tril_ex"])
        s_total = n_exp * b * cap
        if self.dispatch == "onehot":
            dmat = moe_slot_onehot(excl, mall.reshape(b, t, n_exp), cap, c["iota_c"], x.dtype)
            xs = torch.einsum("btec,btd->ebcd", dmat, x).reshape(s_total, d)
        else:
            tab = moe_gather_tables(route, excl, mall, b, t, cap, c)
            if k == 1:
                xs = MoeGatherRows.apply(h, tab["p"], tab["s"][0])
            else:
                xs = MoeDispatch2.apply(h, tab["p"], tab["s"][0], tab["s"][1])
        if self.ep:
            # Training: this rank's slots for expert e to rank e, this rank's expert on every rank's slots for it, and
            # the outputs back to the slots they came from.
            ys = moe_all_to_all(moe_expert8_mlp(moe_all_to_all(xs), self.w_fc[0], self.w_proj[0], self.exp8_sc,
                                                self.exp8_w8))
        else:
            ys = moe_experts8_local(xs.reshape(n_exp, b * cap, d), self.w_fc, self.w_proj,
                                    self.exp8_sc).reshape(s_total, d)
        dt = ys.dtype
        if self.dispatch == "onehot":
            gate = route["m"][0].to(torch.float32) * route["g"][0].unsqueeze(-1)
            for mk, gk in zip(route["m"][1:], route["g"][1:]):
                gate = gate + mk.to(torch.float32) * gk.unsqueeze(-1)
            gmat = dmat * gate.reshape(b, t, n_exp, 1).to(dmat.dtype)
            out = torch.einsum("btec,ebcd->btd", gmat, ys.reshape(n_exp, b, cap, d))
        elif k == 1:
            out = route["g"][0].to(dt).unsqueeze(-1) * MoeGatherRows.apply(ys, tab["s"][0], tab["p"])
        else:
            y1, y2 = MoeCombine2.apply(ys, tab["s"][0], tab["s"][1], tab["p"], tab["sel"])
            out = route["g"][0].to(dt).unsqueeze(-1) * y1 + route["g"][1].to(dt).unsqueeze(-1) * y2
        out = out.reshape(b, t, d)
        if self.shared is not None:
            out = out + self.shared(x)
        if not want_stats:
            return out
        aux, lb, z, f = moe_aux_terms(route, logits, mall, b, t, n_exp, k)
        kept = (mall * (excl.reshape(b * t, n_exp) < cap - 0.5).to(torch.float32)).sum() / (b * t * k)
        stats = torch.cat([torch.stack([kept, lb.detach(), z.detach()]), f]).detach()
        return out, aux, stats


def mix_residual(
    x: torch.Tensor,
    x0: torch.Tensor,
    resid_lambda: torch.Tensor,
    x0_lambda: torch.Tensor,
) -> torch.Tensor:
    """Mix residual streams without promoting BF16 activations to FP32."""
    if R2_RESMIX_FUSE and torch.is_grad_enabled() and x is not x0:
        return resmix_apply(x, x0, resid_lambda, x0_lambda)     # switch 9i (training; block 0, x is x0: as below)
    return resid_lambda.to(dtype=x.dtype) * x + x0_lambda.to(dtype=x.dtype) * x0


class Block(nn.Module):
    def __init__(self, config: GPTConfig, use_ve: bool = False, layer: int = -1):
        super().__init__()
        self.attn = CausalSelfAttention(config)
        # Switch 55: a block of config.moe_layers has its shared half and the routed experts in the MLP's place.
        self.mlp = MoeMLP(config, layer) if layer in config.moe_layers else MLP(config)
        self.resid_lambda = nn.Parameter(torch.ones(1))
        # x0 skip: mixes initial embedding into each layer's input (stabilizes deep nets)
        self.x0_lambda = nn.Parameter(torch.zeros(1))
        # Switch 13: the gain of this layer's value embedding (no random draw).
        self.ve_lambda = nn.Parameter(torch.full((1,), 0.5)) if use_ve else None

    def forward(
        self,
        x: torch.Tensor,
        x0: torch.Tensor,
        cos: torch.Tensor,
        sin: torch.Tensor,
        ve: torch.Tensor | None = None,
        gate: torch.Tensor | None = None,
        moe_aux: list | None = None,
    ) -> torch.Tensor:
        x = mix_residual(x, x0, self.resid_lambda, self.x0_lambda)
        if NF_ATTN:
            # Switch 9m: the attention-side norm runs inside switch 9g's QKV forward kernel (attn8nf_qkv).
            x = x + self.attn(x, cos, sin, ve, self.ve_lambda, nf=True)
        else:
            x = x + self.attn(norm(x), cos, sin, ve, self.ve_lambda)
        if moe_aux is not None and isinstance(self.mlp, MoeMLP):
            # Switch 55, a training forward: the block's router terms and statistics join the forward's list.
            y, aux, stats = self.mlp(norm(x), want_stats=True)
            moe_aux.append((aux, stats))
            return x + y
        if gate is not None:
            # Switch 48: the MLP with this layer's gate rows (lane STACK4: never with switch 9m's MLP side).
            x = x + self.mlp(norm(x), gate)
        elif NF_MLP:
            # Switch 9m: the MLP-side norm runs inside switch 9f's forward kernel (mlp_fused8nf).
            x = x + self.mlp(x, nf=True)
        else:
            x = x + self.mlp(norm(x))
        return x


class GPT(nn.Module):
    def __init__(self, config: GPTConfig):
        super().__init__()
        self.config = config
        padded_vocab_size = ((config.vocab_size + 63) // 64) * 64
        ve_layers = value_embed_layers(config.n_layer, config.value_embeds)
        self.transformer = nn.ModuleDict({
            "wte": nn.Embedding(padded_vocab_size, config.n_embd),
            "h": nn.ModuleList([Block(config, use_ve=i in ve_layers, layer=i) for i in range(config.n_layer)]),
        })
        self.has_moe = bool(config.moe_layers)       # switch 55
        if config.attn_window:
            # Switch 47: model_config's window checked, then every layer's band in key tiles (0 on a long layer); the
            # band mask is attn_band_attach's, where SDPA runs the short layers.
            attn_window_check(config)
            for i, blk in enumerate(self.transformer.h):
                blk.attn.attn_nw = attn_layer_nw(config, i)
        if R2_FP8_ROWS:
            # Switch 9: row 2's h scale per layer.
            for i, block in enumerate(self.transformer.h):
                block.mlp.fp8_h_scale = fp8_h_scale(i, config.n_layer, config.n_embd)
        self.lm_head = Linear(config.n_embd, padded_vocab_size, bias=False)
        cos, sin = self._precompute_rotary_embeddings(config.sequence_len, config.n_embd // config.n_head)
        self.register_buffer("cos", cos, persistent=False)
        self.register_buffer("sin", sin, persistent=False)
        # Switch 13: one table per value-embedding layer. Built on an empty weight,
        # so construction draws nothing from the generator and the base's random
        # stream is unchanged; init_weights draws the tables after the base.
        self.value_embeds = nn.ModuleDict({
            str(i): nn.Embedding(padded_vocab_size, config.n_embd,
                                 _weight=torch.empty(padded_vocab_size, config.n_embd))
            for i in ve_layers
        }) if ve_layers else None
        # Switch 12: one skip gain per encoder/decoder pair.
        if config.unet and config.n_layer < 2:
            raise ValueError("unet needs at least 2 layers")
        self.n_skip = config.n_layer // 2 if config.unet else 0
        self.skip_lambda = nn.Parameter(torch.zeros(self.n_skip)) if self.n_skip else None
        # Switch 17: the projections to n_embd ([n_embd, dim], built empty, so construction draws nothing; init_weights
        # draws them after every other tensor) and one gain per order. The table is not a module of the training
        # model: it lives in host memory (NgramHostTable), set by set_ngram_host; load_for_eval attaches the
        # checkpoint's table as a parameter (attach_ngram_table).
        self.ngram_orders = tuple(config.ngram_orders)
        self._ngram_host = None
        if self.ngram_orders:
            rows, dim = config.ngram_rows, config.ngram_dim
            if rows == 1 << 31:                 # lane EMA31 (R2_NGRAM_ROWS): a 2^31-row table (the 31-bit hash) ...
                rows = 1 << NGRAM_HASH_BITS     # ... whose bound below reads 2^30 (rows is not read after it)
            if rows < 2 or rows & (rows - 1) or rows > 1 << NGRAM_HASH_BITS or dim < 1:
                raise ValueError(f"ngram_rows={rows}, ngram_dim={dim}: rows a power of two up to 2^{NGRAM_HASH_BITS}")
            if config.ngram_proj not in ("separate", "shared"):
                raise ValueError(f"ngram_proj={config.ngram_proj!r}: expected separate or shared")
            n_proj = 1 if config.ngram_proj == "shared" else len(self.ngram_orders)
            self.ngram_proj = nn.ParameterList([nn.Parameter(torch.empty(config.n_embd, dim)) for _ in range(n_proj)])
            self.ngram_lambda = nn.Parameter(torch.zeros(len(self.ngram_orders)))
        else:
            self.ngram_proj = None
            self.ngram_lambda = None
        # Switch 59: the one-shot table's readout: its codebook scaled by 1 / a0 (in the compute dtype), the gate's
        # codebook (the same, FP32, the BOS row zero) and the gate's window matrix: buffers rebuilt from model_config,
        # never saved; no parameter (the readout's scalars are hand-set). The host table is set by set_os1_host or
        # attach_os1_table. Unset: nothing is built.
        if config.os1_rows:
            if (not self.ngram_orders or config.os1_dim < config.ngram_dim or config.os1_dim % config.ngram_dim
                    or not 0.0 < config.os1_thr < 1.0 or not config.os1_a0 > 0.0 or config.os1_gate_w < 1
                    or not 0 <= config.os1_bos < padded_vocab_size or config.os1_bits not in (0, 1)):
                raise ValueError("switch 59 needs switch 17's table (its slots are rows of R2_NGRAM_DIM: os1_dim a "
                                 "multiple of it), a threshold in (0, 1), a0 > 0, a gate window, a BOS id inside the "
                                 "vocabulary and os1_bits 0 or 1")
            self._os1_host = None
            self.os1_slots = config.os1_dim // config.ngram_dim      # lane TABXB: the window's slots of the table
            code = os1_codebook(padded_vocab_size, config.os1_dim, config.os1_code_seed) / config.os1_a0
            gcode = code.clone()
            gcode[config.os1_bos] = 0.0
            self.register_buffer("os1_code", code.to(COMPUTE_DTYPE), persistent=False)
            self.register_buffer("os1_gcode", gcode, persistent=False)
            self.register_buffer("os1_band", os1_band(config.sequence_len, config.os1_gate_w), persistent=False)
            if R2_OS1_FUSED:
                # Lane OS1A2: the fused readout's constants, made here on the host like the buffers above and never
                # saved: the codebook transposed for the kernels' read term [D, padded vocab], and glin C / a0 in the
                # compute dtype for the folded head GEMM's weight columns.
                self.register_buffer("os1_codeT", self.os1_code.t().contiguous(), persistent=False)
                self.register_buffer("os1_codeg", (self.os1_code.float() * config.os1_glin).to(COMPUTE_DTYPE),
                                     persistent=False)
                if R2_OS1_WCAT:
                    # Lane OS1R (rider b): [W | glin C / a0] in the compute dtype, [padded vocab, n_embd + D], written
                    # by fp8_refresh_weights after every optimizer step and once before the first; never saved.
                    wv, wd = self.os1_code.size(0), config.n_embd + self.os1_code.size(1)
                    self.register_buffer("os1_wcat", torch.zeros(wv, wd, dtype=COMPUTE_DTYPE), persistent=False)
        # Switch 48: one gate table per listed layer, [padded vocab, 4 n_embd], built on an empty weight (construction
        # draws nothing); init_weights fills it with ones after every other tensor.
        stem_layers = tuple(config.stem_layers)
        if any(not 0 <= i < config.n_layer for i in stem_layers) or len(set(stem_layers)) != len(stem_layers):
            raise ValueError(f"stem_layers={stem_layers}: distinct layer indices below n_layer={config.n_layer}")
        self.stem_tables = nn.ModuleDict({
            str(i): nn.Embedding(padded_vocab_size, 4 * config.n_embd,
                                 _weight=torch.empty(padded_vocab_size, 4 * config.n_embd))
            for i in stem_layers
        }) if stem_layers else None
        if stem_layers and R2_MLP == "fused8":
            # Switch 48 on the fp8 line: each gated layer's [s_g, gamma] (stem8_refresh_gates writes it; never saved;
            # NaN until the first refresh, so a forward before it could not pass unnoticed).
            for i in stem_layers:
                self.transformer.h[i].mlp.register_buffer("stem8_gs", torch.full((2,), float("nan")),
                                                          persistent=False)

    @torch.no_grad()
    def init_weights(self) -> None:
        torch.nn.init.normal_(self.transformer.wte.weight, mean=0.0, std=0.8)
        torch.nn.init.normal_(self.lm_head.weight, mean=0.0, std=0.001)
        s = math.sqrt(3.0) * self.config.n_embd**-0.5
        for block in self.transformer.h:
            torch.nn.init.uniform_(block.attn.c_q.weight, -s, s)
            torch.nn.init.uniform_(block.attn.c_k.weight, -s, s)
            torch.nn.init.uniform_(block.attn.c_v.weight, -s, s)
            torch.nn.init.zeros_(block.attn.c_proj.weight)
            if isinstance(block.mlp, MoeMLP):
                # Switch 55: the base's two draws here (the shared half takes the dense c_fc's first rows).
                block.mlp.init_stream(s)
            else:
                torch.nn.init.uniform_(block.mlp.c_fc.weight, -0.4 * s, 0.4 * s)
                torch.nn.init.zeros_(block.mlp.c_proj.weight)
            block.resid_lambda.fill_(1.0)
            block.x0_lambda.fill_(0.05)
            if block.ve_lambda is not None:
                block.ve_lambda.fill_(0.5)
            if block.attn.head_gate is not None:
                # Switch 18: every gate starts at sigmoid(0) = 0.5 (no draw: the random stream is the base's).
                block.attn.head_gate.zero_()
        # Recipe switches: drawn after every base tensor, so the base's initial
        # weights are the same with any switch on.
        if self.value_embeds is not None:
            for table in self.value_embeds.values():
                torch.nn.init.normal_(table.weight, mean=0.0, std=0.8)
        if self.skip_lambda is not None:
            self.skip_lambda.fill_(R2_UNET_INIT)
        if self.ngram_proj is not None:
            # Switch 17: the projections orthogonal (PR #854's up-projection), drawn after every other tensor; the
            # table starts at zero, so the first forward is the base's.
            for w in self.ngram_proj:
                torch.nn.init.orthogonal_(w)
            self.ngram_lambda.fill_(R2_NGRAM_GAIN)
        if self.stem_tables is not None:
            # Switch 48: every gate starts at 1 (no draw), so the first forward is the base's.
            for t in self.stem_tables.values():
                t.weight.fill_(1.0)
        for block in self.transformer.h:
            if isinstance(block.mlp, MoeMLP):
                # Switch 55: the router and the experts held here, from their own generators.
                block.mlp.init_own(s)
        cos, sin = self._precompute_rotary_embeddings(self.config.sequence_len, self.config.n_embd // self.config.n_head)
        self.cos.copy_(cos)
        self.sin.copy_(sin)

    def _precompute_rotary_embeddings(self, seq_len: int, head_dim: int, base: int = 100000):
        device = self.transformer.wte.weight.device
        freqs = torch.arange(0, head_dim, 2, dtype=torch.float32, device=device)
        inv_freq = 1.0 / (base ** (freqs / head_dim))
        t = torch.arange(seq_len, dtype=torch.float32, device=device)
        table = torch.outer(t, inv_freq)
        cos = table.cos().to(COMPUTE_DTYPE)[None, :, None, :]
        sin = table.sin().to(COMPUTE_DTYPE)[None, :, None, :]
        return cos, sin

    def get_device(self) -> torch.device:
        return self.transformer.wte.weight.device

    def estimate_flops(self) -> int:
        """Estimate FLOPs per token (forward + backward). Attention QK^T and AV are O(T) per token."""
        nparams = sum(p.numel() for p in self.parameters())
        non_matmul = self.transformer.wte.weight.numel() + 2 * self.config.n_layer  # per-block scalars
        # Recipe switches: lookup tables and gains are not matmul parameters.
        if self.value_embeds is not None:
            non_matmul += sum(table.weight.numel() for table in self.value_embeds.values())
        if self.stem_tables is not None:
            # Switch 48: the gate tables are lookups (their multiply is elementwise).
            non_matmul += sum(t.weight.numel() for t in self.stem_tables.values())
        non_matmul += sum(p.numel() for p in self.arch_gain_params())
        # Switch 17: the table (a parameter only of load_for_eval's model) is a lookup; the projections are matmuls.
        non_matmul += sum(p.numel() for n, p in self.named_parameters() if n in ("ngram_table", "ngram_scale"))
        non_matmul += sum(p.numel() for n, p in self.named_parameters() if n in ("os1_table", "os1_scale"))  # 59
        h = self.config.n_head
        d = self.config.n_embd // self.config.n_head
        t = self.config.sequence_len
        # QK^T: 2*h*d*T per token, AV: 2*h*d*T per token, x3 for fwd+bwd
        attn_flops = self.config.n_layer * 12 * h * d * t
        return 6 * (nparams - non_matmul) + attn_flops

    def num_scaling_params(self) -> dict[str, int]:
        """Parameter count used for nanochat-style data:parameter scaling."""
        transformer_matrices = sum(
            p.numel()
            for block in self.transformer.h
            for p in block.parameters()
            if p.ndim == 2
        )
        lm_head = self.lm_head.weight.numel()
        return {
            "transformer_matrices": transformer_matrices,
            "lm_head": lm_head,
            "total": transformer_matrices + lm_head,
        }

    def arch_gain_params(self) -> list[nn.Parameter]:
        """The 1-D gains the recipe switches add (ve_lambda per value-embedding
        layer, skip_lambda); empty with every recipe switch off."""
        gains = [block.ve_lambda for block in self.transformer.h if block.ve_lambda is not None]
        if self.skip_lambda is not None:
            gains.append(self.skip_lambda)
        if self.ngram_lambda is not None:
            gains.append(self.ngram_lambda)
        return gains

    def set_ngram_host(self, host: "NgramHostTable | None") -> None:
        """Switch 17: the host table this model's scorer-style calls (no n-gram input given) look up."""
        self._ngram_host = host

    def attach_ngram_table(self, table: torch.Tensor, scale: torch.Tensor | None) -> None:
        """Switch 17, load_for_eval: the checkpoint's table (and an int8 table's row scales) as parameters of this
        model, kept in host memory (call after .to(device)), and the host lookup reading them. A table mapped from
        the checkpoint is read once in file order first (one byte of every 4 KiB page), so the lookups find it in
        the page cache instead of reading the disk at random."""
        for t in (table, scale):
            if t is not None:
                t.view(torch.uint8).reshape(-1)[::4096].sum()
        self.ngram_table = nn.Parameter(table, requires_grad=False)
        if scale is not None:
            self.ngram_scale = nn.Parameter(scale, requires_grad=False)
        self._ngram_host = NgramHostTable.read_only(self.ngram_table.data, None if scale is None else self.ngram_scale.data,
                                                    self.ngram_orders, self.config.ngram_seed,
                                                    ((self.config.vocab_size + 63) // 64) * 64)
        if self.config.ngram_bits:
            # Lane TABLE2: the checkpoint's packed view (its values and scales): the lookups unpack them.
            b = self.config.ngram_bits
            self._ngram_host.bits, self._ngram_host.packed, self._ngram_host.dim = b, True, table.size(1) * 8 // b

    @torch.compiler.disable
    def ngram_lookup(self, idx: torch.Tensor) -> torch.Tensor:
        """Switch 17, a call without the n-gram input (the scorers, the in-process evaluation): hash idx on the host,
        gather the rows there and bring them to idx's device, [b, t, orders, dim] bf16. Outside any compiled graph."""
        host = self._ngram_host
        if host is None:
            raise RuntimeError("switch 17: no n-gram table is attached (set_ngram_host or attach_ngram_table)")
        if getattr(self, "_os1_host", None) is not None:
            # Switch 59: the one-shot table's unbound row as one more slot (the scorers' and the in-run lookups).
            cpu_idx = idx.detach().to("cpu")
            rows = host.gather(host.ids(cpu_idx))
            u = self._os1_host.lookup_u(cpu_idx)
            # Lane TABXB: a row k slots wide fills its k slots (one slot: as before).
            u = u.unsqueeze(-2) if u.size(-1) == rows.size(-1) else u.view(*u.shape[:-1], -1, rows.size(-1))
            return torch.cat([rows, u], dim=-2).to(idx.device)
        return host.gather(host.ids(idx.detach().to("cpu"))).to(idx.device)

    def ngram_input(self, e: torch.Tensor) -> torch.Tensor:
        """Switch 17: the n-gram term added to the token embedding, in the compute dtype, from the gathered rows
        e [b, t, orders, dim]: per order the row times its gain, projected to n_embd (one projection per order, or
        one for their sum)."""
        e = e.to(COMPUTE_DTYPE)
        es = [self.ngram_lambda[j:j + 1].to(e.dtype) * e[:, :, j] for j in range(len(self.ngram_orders))]
        if len(self.ngram_proj) == 1:
            s = es[0]
            for x in es[1:]:
                s = s + x
            return F.linear(s, self.ngram_proj[0].to(s.dtype))
        out = None
        for x, w in zip(es, self.ngram_proj):
            y = F.linear(x, w.to(x.dtype))
            out = y if out is None else out + y
        return out

    def set_os1_host(self, host: "Os1HostTable | None") -> None:
        """Switch 59: the one-shot table this model's scorer-style calls (no n-gram input given) look up."""
        self._os1_host = host

    def attach_os1_table(self, table: torch.Tensor, scale: torch.Tensor) -> None:
        """Switch 59, load_for_eval: the checkpoint's int8 rows and bf16 row scales as parameters of this model, kept
        in host memory (call after .to(device)), read once in file order first, and the host lookup reading them."""
        for t in (table, scale):
            t.view(torch.uint8).reshape(-1)[::4096].sum()
        self.os1_table = nn.Parameter(table, requires_grad=False)
        self.os1_scale = nn.Parameter(scale, requires_grad=False)
        self._os1_host = Os1HostTable.read_only(self.os1_table.data, self.os1_scale.data, self.config,
                                                ((self.config.vocab_size + 63) // 64) * 64)

    def os1_bias(self, u: torch.Tensor, idx: torch.Tensor) -> torch.Tensor:
        """Switch 59: the readout over every token v, [b, t, padded vocab] in the compute dtype: glin * s_v plus the
        gated thresholded read G_t * beta * relu(sg(s_v) - thr) / (1 - thr), s_v = (u . C_v) / a0 (os1_code is
        C / a0). G_t = sigmoid(slope (h_t - h0)), h_t the mean over the previous gate_w positions j of the window of
        z_j = (u_j . C[idx_j+1]) / a0 (0 where the next token is BOS and at the window's last position): the rows'
        own reads of the token that followed (inputs only: causal). The read and the gate are stop-gradient terms;
        the gradient reaches u through glin * s alone. Value ops only: two matmuls, an embedding lookup of the
        codebook by the input ids, products, sums, relu and sigmoid."""
        cfg = self.config
        u = u.to(COMPUTE_DTYPE)
        s = F.linear(u, self.os1_code.to(COMPUTE_DTYPE))
        b, t = idx.shape
        ud = u.detach().float()
        cn = F.embedding(idx[:, 1:], self.os1_gcode)
        z = torch.cat([(ud[:, :t - 1] * cn).sum(-1), ud.new_zeros(b, 1)], dim=1)
        h = z @ self.os1_band[:t, :t]
        g = torch.sigmoid(cfg.os1_gate_slope * (h - cfg.os1_gate_h0)).to(s.dtype).unsqueeze(-1)
        read = (cfg.os1_beta / (1.0 - cfg.os1_thr)) * F.relu(s.detach() - cfg.os1_thr) * g
        return cfg.os1_glin * s + read

    def os1_tail(self, x: torch.Tensor, ngram_emb: torch.Tensor, idx: torch.Tensor, targets, loss_reduction: str,
                 loss_div, moe_aux: list | None = None):
        """Switch 59: the base's head with the readout added to its logits before the softcap (training's loss head
        kernel where it applies, the kit's chain otherwise). Label smoothing and answer weights are refused with the
        switch at launch, so this is the base's tail with the bias added."""
        n, k = len(self.ngram_orders), self.os1_slots
        # Lane TABXB: a row k slots wide is read as the slots' concatenation (one slot: the slot itself, as before).
        u = ngram_emb[:, :, n] if k == 1 else ngram_emb[:, :, n:n + k].flatten(-2)
        if R2_OS1_FUSED and targets is not None and loss_reduction == "mean":
            # Lane OS1A2: training's mean loss through the fused readout (the scorers keep the unfused form below).
            loss = self.os1_fused_loss(x, u, idx, targets)
            return loss_scaled(loss, loss_div) if moe_aux is None else moe_loss_out(loss, moe_aux, loss_div)
        head = self.lm_head(x) + self.os1_bias(u, idx)
        if (targets is not None and R2_LOSS_HEAD_KERNEL
                and loss_head_applies(x, loss_reduction, self.config.vocab_size, self.lm_head.weight.size(0))):
            loss = chunked_loss_mean(head, targets)
            # Lane STACK5: with switch 55's blocks, (the loss with the router terms, the statistics), as GPT.forward.
            return loss_scaled(loss, loss_div) if moe_aux is None else moe_loss_out(loss, moe_aux, loss_div)
        logits = head[..., :self.config.vocab_size].float()
        logits = LOGIT_SOFTCAP * torch.tanh(logits / LOGIT_SOFTCAP)
        if targets is None:
            return logits
        loss = F.cross_entropy(logits.reshape(-1, logits.size(-1)), targets.reshape(-1), ignore_index=-1,
                               reduction=loss_reduction)
        if loss_reduction == "none":
            return loss.view_as(targets)
        return loss_scaled(loss, loss_div) if moe_aux is None else moe_loss_out(loss, moe_aux, loss_div)

    def os1_read_scale(self, u: torch.Tensor, idx: torch.Tensor) -> torch.Tensor:
        """Lane OS1A2: c G_t per position, FP32 [b * t], c = beta / (1 - thr): os1_bias's gate by the same
        expression, cast to the compute dtype as os1_bias casts it (the window's last position is the zero of an
        F.pad where os1_bias concatenates one); c times it in FP32 (os1_bias multiplies in the compute dtype)."""
        cfg = self.config
        b, t = idx.shape
        ud = u.detach().float()
        cn = F.embedding(idx[:, 1:], self.os1_gcode)
        z = F.pad((ud[:, :t - 1] * cn).sum(-1), (0, 1))
        h = z @ self.os1_band[:t, :t]
        g = torch.sigmoid(cfg.os1_gate_slope * (h - cfg.os1_gate_h0)).to(COMPUTE_DTYPE)
        return ((cfg.os1_beta / (1.0 - cfg.os1_thr)) * g.float()).reshape(b * t)

    def os1_fused_loss(self, x: torch.Tensor, u: torch.Tensor, idx: torch.Tensor, targets: torch.Tensor):
        """Lane OS1A2 (R2_OS1_FUSED): training's mean loss with switch 59's readout fused: the linear term in the head
        GEMM (Os1FoldHead) and, on the device, the gated thresholded read inside switch 8's kernel pair
        (chunked_loss_mean_os1); off it (the CPU battery) the same arithmetic in torch: relu(s - thr) cg + lin in
        FP32 (the kernels' order), s = u C^T / a0 by an FP32 product, then the kit's softcap and mean cross-entropy."""
        cfg = self.config
        b, t, c = x.shape
        xu = torch.cat([x, u.to(x.dtype)], dim=-1).reshape(b * t, -1)
        if R2_OS1_WCAT or R2_OS1_DWX:
            # Lane OS1R (riders b, c): the fold's weight from the step's cache and/or d(W) from x's own rows.
            lin = Os1FoldHeadR.apply(xu, self.lm_head.weight.to(dtype=x.dtype), self.os1_codeg,
                                     self.os1_wcat if R2_OS1_WCAT else None,
                                     x.reshape(b * t, c) if R2_OS1_DWX else None)
        else:
            lin = Os1FoldHead.apply(xu, self.lm_head.weight.to(dtype=x.dtype), self.os1_codeg)
        cg = self.os1_read_scale(u, idx)
        if R2_LOSS_HEAD_KERNEL and loss_head_applies(x, "mean", cfg.vocab_size, self.lm_head.weight.size(0)):
            return chunked_loss_mean_os1(lin, targets, xu.detach(), self.os1_codeT, cg, cfg.os1_thr)
        if x.device.type != "cpu":
            raise RuntimeError("R2_OS1_FUSED: off the CPU the readout runs only inside switch 8's kernel pair (bf16, "
                               "an unpadded vocabulary of 8,192-multiples, rows a multiple of 128)")
        cgc = cg.reshape(-1, 1)
        s = F.linear(xu.detach()[:, c:].float(), self.os1_code.float())
        head = torch.clamp_min(s - cfg.os1_thr, 0.0) * cgc + lin.float()
        logits = LOGIT_SOFTCAP * torch.tanh(head[:, :cfg.vocab_size] / LOGIT_SOFTCAP)
        return F.cross_entropy(logits, targets.reshape(-1), ignore_index=-1, reduction="mean")

    def setup_optimizer(self):
        scalar_params = []
        resid_params = []
        matrix_params = []
        split_resid = "resid_lr" in BUNDLE_ITEMS
        for block in self.transformer.h:
            if split_resid:
                # Switch 14, resid_lr: the residual gains get their own group below.
                resid_params.append(block.resid_lambda)
                scalar_params.append(block.x0_lambda)
            else:
                scalar_params.extend([block.resid_lambda, block.x0_lambda])
            matrix_params.extend(block.attn.parameters())
            # Switch 55: a MoE block's router and shared half train as the trunk's matrices; its experts below.
            matrix_params.extend(block.mlp.trunk_parameters() if isinstance(block.mlp, MoeMLP)
                                 else block.mlp.parameters())
        if self.ngram_proj is not None:
            # Switch 17: the projections are matrices (Muon, grouped by shape like the blocks' matrices).
            matrix_params.extend(self.ngram_proj)
        # Switches 12, 13 and 17: the skip gains, the value-embedding gains and the n-gram gains train with the scalars.
        scalar_params.extend(self.arch_gain_params())
        # Switch 18: the gates are parameters of the blocks' attention, so the loop above listed them with the
        # matrices; they leave Muon for an AdamW group of their own (below).
        gate_params = [block.attn.head_gate for block in self.transformer.h if block.attn.head_gate is not None]
        if gate_params:
            gate_ids = {id(p) for p in gate_params}
            matrix_params = [p for p in matrix_params if id(p) not in gate_ids]
        moe = [block.mlp for block in self.transformer.h if isinstance(block.mlp, MoeMLP)]
        router_params = [m.router for m in moe] if R2_MOE_ROUTER_OPT == "adamw" else []
        if router_params:
            # Switch 55, R2_MOE_ROUTER_OPT=adamw: the routers leave Muon for an AdamW group (below).
            router_ids = {id(p) for p in router_params}
            matrix_params = [p for p in matrix_params if id(p) not in router_ids]
        table_params = list(self.transformer.wte.parameters())
        embedding_params = list(table_params)
        if self.value_embeds is not None:
            # Switch 13: the value-embedding tables train in the token embedding's AdamW group.
            embedding_params.extend(self.value_embeds.parameters())
        lm_head_params = list(self.lm_head.parameters())
        dmodel_lr_scale = (self.config.n_embd / 768) ** -0.5
        param_groups = [
            dict(kind="adamw", params=embedding_params, lr=EMBEDDING_LR * dmodel_lr_scale, betas=(0.8, 0.995), eps=1e-10, weight_decay=0.001),
            dict(kind="adamw", params=lm_head_params, lr=UNEMBEDDING_LR * dmodel_lr_scale, betas=(0.8, 0.96), eps=1e-10, weight_decay=0.01),
            dict(kind="adamw", params=scalar_params, lr=SCALAR_LR, betas=(0.9, 0.95), eps=1e-10, weight_decay=0.0),
        ]
        if resid_params:
            param_groups.append(dict(kind="adamw", params=resid_params, lr=SCALAR_LR / R2_RESID_LR_DIV, betas=(0.9, 0.95), eps=1e-10, weight_decay=0.0))
        if gate_params:
            # Switch 18: the gates' AdamW group, at the output head's settings with R2_HEADGATE_LR for its rate.
            param_groups.append(dict(kind="adamw", params=gate_params, lr=R2_HEADGATE_LR * dmodel_lr_scale, betas=(0.8, 0.96), eps=1e-10, weight_decay=0.01))
        if router_params:
            # Switch 55: the routers' AdamW group at the output head's settings (no decay).
            param_groups.append(dict(kind="adamw", params=router_params, lr=UNEMBEDDING_LR * dmodel_lr_scale,
                                     betas=(0.8, 0.96), eps=1e-10, weight_decay=0.0))
        for shape in sorted({p.shape for p in matrix_params}):
            params = [p for p in matrix_params if p.shape == shape]
            # Switch 15: R2_WD in WEIGHT_DECAY's place.
            param_groups.append(dict(kind="muon", params=params, lr=MATRIX_LR, momentum=0.95, beta2=0.90, ns_steps=5, weight_decay=R2_WD))
        stem_params = list(self.stem_tables.parameters()) if self.stem_tables is not None else []
        if stem_params:
            # Switch 48: the gate tables' AdamW group (the embedding group's betas and eps), last, at R2_STEM_LR.
            param_groups.append(dict(kind="adamw", params=stem_params, lr=R2_STEM_LR, betas=(0.8, 0.995), eps=1e-10,
                                     weight_decay=R2_STEM_WD))
        experts = [p for m in moe for p in m.expert_parameters()]
        for shape in sorted({tuple(p.shape[1:]) for p in experts}):
            # Switch 55: each rank's experts as local groups (moe_local: no data-parallel reduce, the whole
            # gradient forms on this rank), Muon at R2_MOE_LR with the trunk's schedules, or AdamW.
            params = [p for p in experts if tuple(p.shape[1:]) == shape]
            if R2_MOE_OPT == "muon":
                param_groups.append(dict(kind="muon", params=params, lr=R2_MOE_LR, momentum=0.95, beta2=0.90,
                                         ns_steps=5, weight_decay=R2_WD, moe_local=True))
            else:
                param_groups.append(dict(kind="adamw", params=params, lr=R2_MOE_LR, betas=(0.8, 0.95), eps=1e-10,
                                         weight_decay=0.0, moe_local=True))
        distributed = dist.is_available() and dist.is_initialized() and dist.get_world_size() > 1
        if distributed and R2_LEAN_OPT:
            # Switch 11: the lean step under the review's decisions (2026-10-08).
            if GRAD_CLIP > 0:
                raise ValueError("GRAD_CLIP needs autograd-held gradients; LeanDistMuonAdamW.accumulate() takes them")
            # The FP32 replicas are the lookup tables, the token embedding and switch 13's tables: each is looked up
            # in FP32, and a bf16 replica would sum its repeated tokens' gradients in bf16 (W3-F3).
            lean = dict(polar_coeffs=POLAR_EXPRESS_COEFFS, ns_dtype_fn=lambda: COMPUTE_DTYPE, slab_collectives=1,
                        leftover_route="auto", param_views=False, replica_dtype=COMPUTE_DTYPE,
                        acc_dtype=torch.float32, finite_gate=False, fp32_replicas=embedding_params)
            if R2_SLAB_COPY:
                lean["foreach_copy"] = True    # O2: one multi-tensor copy of the slab into the parameters
            if R2_RS_UNSPLIT:
                # S1: the Muon slab's gradients in bf16 (with bf16 replicas the all-gather writes into the same
                # buffer), reduced with SUM and scaled by 1 / world in FP32.
                lean["slab_dtype"] = torch.bfloat16
                lean["slab_sum"] = True
            if R2_LEAN_EMBED_1536 or R2_COMPILED_ACCUM:
                # T1 and T3: the subclass that checks every deferred gradient (T1 defers switch 13's tables too) and
                # can compile its accumulation (T3: main() calls compile_accumulate).
                deferred = list(table_params) if R2_LEAN_EMBED else []
                if R2_LEAN_EMBED_1536 and R2_LEAN_EMBED and self.value_embeds is not None:
                    deferred.extend(self.value_embeds.parameters())
                if R2_LEAN_EMBED_1536 and R2_LEAN_EMBED:
                    # Switch 48: the gate tables take their step's gradient as switch 13's tables do (bf16 replicas:
                    # they are not in fp32_replicas; the deferred gradient is summed in FP32 by the contraction).
                    deferred.extend(stem_params)
                opt = LeanDistMuonAdamWThroughput(param_groups, deferred=deferred, **lean)
            elif R2_LEAN_EMBED:
                # Switches 10 and 11: the token embedding's gradient arrives once per step, outside autograd. Switch
                # 13's tables are not deferred: their gradient is autograd's, accumulated after every micro-step.
                opt = LeanDistMuonAdamWDeferred(param_groups, deferred=table_params, **lean)
            else:
                opt = LeanDistMuonAdamW(param_groups, **lean)
        else:
            opt = DistMuonAdamW(param_groups) if distributed else MuonAdamW(param_groups)
        for group in opt.param_groups:
            group["initial_lr"] = group["lr"]
        return opt

    def forward(self, idx: torch.Tensor, targets: torch.Tensor | None = None, loss_reduction: str = "mean",
                emb_grad_sink: torch.Tensor | None = None, ngram_emb: torch.Tensor | None = None,
                ve_grad_sinks: dict | None = None, label_smooth: bool = False, loss_div: int | None = None,
                stem_grad_sinks: dict | None = None):
        _b, t = idx.shape
        assert t <= self.config.sequence_len
        cos, sin = self.cos[:, :t], self.sin[:, :t]
        if emb_grad_sink is not None:
            # Switch 10 (training only): the kit's lookup, its backward handing d(x) to the sink.
            x = LeanLookup.apply(idx, self.transformer.wte.weight, emb_grad_sink)
        else:
            x = self.transformer.wte(idx).to(COMPUTE_DTYPE)
        if self.ngram_proj is not None:
            # Switch 17: the n-gram term, added to the token embedding before the norm. Training passes the step's
            # gathered rows (ngram_emb, a leaf whose gradient goes back to the host table); a call without them
            # (the scorers) looks the rows up on the host.
            if ngram_emb is None:
                ngram_emb = self.ngram_lookup(idx)
            x = x + self.ngram_input(ngram_emb)
        x = norm(x)
        x0 = x
        n_layer, n_skip = self.config.n_layer, self.n_skip
        skips: list[torch.Tensor] = []
        # Switch 55: a training forward (targets, the mean loss) collects every MoE block's router terms.
        moe_aux = [] if (self.has_moe and targets is not None and loss_reduction == "mean") else None
        for i, block in enumerate(self.transformer.h):
            if NR_ON:
                # Switch 9t: the iteration through nr_block_step (under its attn unit the decoder's skip add goes into
                # the block's QKV kernel).
                x = nr_block_step(self, i, block, x, x0, cos, sin, idx, skips, ve_grad_sinks, moe_aux)
                continue
            if n_skip and i >= n_layer - n_skip:
                # Switch 12: decoder block j takes encoder block n_skip - 1 - j's output.
                j = i - (n_layer - n_skip)
                x = x + self.skip_lambda[j:j + 1].to(x.dtype) * skips.pop()
            ve = None
            if self.value_embeds is not None and str(i) in self.value_embeds:
                if ve_grad_sinks is not None:
                    # T1 (training only): the same lookup through switch 10's LeanLookup, d(ve) to the table's sink.
                    ve = LeanLookup.apply(idx, self.value_embeds[str(i)].weight, ve_grad_sinks[str(i)])
                else:
                    # Switch 13: this layer's table, the kit's lookup (FP32 table, cast to the compute dtype).
                    ve = self.value_embeds[str(i)](idx).to(COMPUTE_DTYPE)
            if self.stem_tables is not None and str(i) in self.stem_tables:
                # Switch 48: this layer's gate rows, looked up as switch 13's rows are (training: StemLookup, switch
                # 10's LeanLookup with a copying cast, d(rows) to the table's sink; otherwise the kit's lookup cast to
                # the compute dtype).
                if stem_grad_sinks is not None:
                    gate = StemLookup.apply(idx, self.stem_tables[str(i)].weight, stem_grad_sinks[str(i)])
                else:
                    gate = self.stem_tables[str(i)](idx).to(COMPUTE_DTYPE)
                x = block(x, x0, cos, sin, ve, gate)
            else:
                # Switch 55: moe_aux by keyword (lane STACK5: switch 48's gate is the sixth argument).
                x = block(x, x0, cos, sin, ve) if moe_aux is None else block(x, x0, cos, sin, ve, moe_aux=moe_aux)
            if n_skip and i < n_skip:
                skips.append(x)
        x = norm(x)
        if self.config.os1_rows:
            # Switch 59: the one-shot table's readout added to the logits before the softcap (training and the
            # scorers alike).
            return self.os1_tail(x, ngram_emb, idx, targets, loss_reduction, loss_div, moe_aux)
        if label_smooth and not (R2_LABEL_SMOOTH > 0.0 and targets is not None and loss_reduction == "mean"):
            # Switch 26 smooths training's mean loss only, with eps > 0.
            raise ValueError("label_smooth needs R2_LABEL_SMOOTH > 0, targets and loss_reduction 'mean'")
        tok_w = None
        if QA_WEIGHTED and targets is not None and loss_reduction == "mean":
            # Switch 29: the loader's marked targets (target + vocabulary size) carry R2_QA_ANSWER_WEIGHT.
            targets, tok_w = qa_unmark(targets, self.config.vocab_size)
        if (targets is not None and R2_LOSS_HEAD_KERNEL
                and loss_head_applies(x, loss_reduction, self.config.vocab_size, self.lm_head.weight.size(0))):
            # Switch 8: the kit's lm_head matmul, then the chunked loss head kernel (softcap, cross-entropy, mean).
            # Switch 26: label_smooth runs the label-smoothed kernel pair.
            loss = chunked_loss_mean(self.lm_head(x), targets, smooth=label_smooth, tok_w=tok_w)
            # Switch 55: with MoE blocks, (the loss with the router terms, the statistics vector).
            return loss_scaled(loss, loss_div) if moe_aux is None else moe_loss_out(loss, moe_aux, loss_div)
        logits = self.lm_head(x)[..., :self.config.vocab_size].float()
        logits = LOGIT_SOFTCAP * torch.tanh(logits / LOGIT_SOFTCAP)
        if targets is None:
            return logits
        if label_smooth:
            # Switch 26 off the loss head kernel's route: the kit's chain with PyTorch's label smoothing (the same
            # loss: (1 - eps) CE + eps (lse - mean_v z), averaged over the targets that are not ignored).
            loss = F.cross_entropy(logits.reshape(-1, logits.size(-1)), targets.reshape(-1), ignore_index=-1,
                                   reduction="mean", label_smoothing=R2_LABEL_SMOOTH)
            return loss_scaled(loss, loss_div) if moe_aux is None else moe_loss_out(loss, moe_aux, loss_div)
        loss = F.cross_entropy(
            logits.reshape(-1, logits.size(-1)),
            targets.reshape(-1),
            ignore_index=-1,
            reduction=loss_reduction,
        )
        if loss_reduction == "none":
            return loss.view_as(targets)
        if tok_w is not None:
            # Switch 29 off the kernel's route: the marked targets' extra (w - 1) share (zero at w = 1).
            loss = loss + qa_extra_loss(logits, targets, tok_w)
        return loss_scaled(loss, loss_div) if moe_aux is None else moe_loss_out(loss, moe_aux, loss_div)


def loss_scaled(loss: torch.Tensor, loss_div: int | None) -> torch.Tensor:
    """S3 (H1): training's mean loss divided by grad_accum_steps inside the compiled forward; None (every call but
    the training micro-steps under R2_HOST_IDLE) returns it unchanged, so the graph is the one without S3."""
    return loss if loss_div is None else loss / loss_div


def build_config(
    depth: int = DEPTH,
    aspect_ratio: int = ASPECT_RATIO,
    head_dim: int = HEAD_DIM,
    sequence_len: int = SEQ_LEN,
) -> GPTConfig:
    base_dim = depth * aspect_ratio
    n_embd = ((base_dim + head_dim - 1) // head_dim) * head_dim
    n_head = n_embd // head_dim
    return GPTConfig(
        sequence_len=sequence_len,
        vocab_size=TOKENIZER_VOCAB_SIZE,
        n_layer=depth,
        n_head=n_head,
        n_embd=n_embd,
        unet=R2_UNET,
        value_embeds=R2_VE,
        qk_scale=R2_QK_SCALE if "qk_scale" in BUNDLE_ITEMS else 0.0,
        ngram_orders=R2_NGRAM_ORDERS if R2_NGRAM else (),
        ngram_rows=R2_NGRAM_ROWS if R2_NGRAM else 0,
        ngram_dim=R2_NGRAM_DIM if R2_NGRAM else 0,
        ngram_proj=R2_NGRAM_PROJ if R2_NGRAM else "",
        ngram_seed=NGRAM_HASH_SEED if R2_NGRAM else 0,
        ngram_bits=R2_NGRAM_BITS if R2_NGRAM else 0,
        head_gate=R2_HEADGATE,
        stem_layers=R2_STEM,
        **({"attn_window": R2_ATTN_WINDOW, "attn_long": tuple(sorted(R2_ATTN_WIN_LAYERS))}
           if R2_ATTN_WINDOW else {}),                   # switch 47 (lane BAND); unset: no field
        **os1_config_fields(),
        **moe_config_fields(depth, n_embd, sequence_len),
        **({"moe_expert8": 1} if R2_MOE_EXPERT8 else {}),     # switch 66 (lane THR13); unset: no field
    )


# -----------------------------------------------------------------------------
# Optimizer

POLAR_EXPRESS_COEFFS = [
    (8.156554524902461, -22.48329292557795, 15.878769915207462),
    (4.042929935166739, -2.808917465908714, 0.5000178451051316),
    (3.8916678022926607, -2.772484153217685, 0.5060648178503393),
    (3.285753657755655, -2.3681294933425376, 0.46449024233003106),
    (2.3465413258596377, -1.7097828382687081, 0.42323551169305323),
]


# MQ1. MuonEq row equilibration and Muon+ renormalisation in the lean optimizer's Muon step, R2_MUONEQ=1 (lane BATCH,
# build 2, work/p2/batch/NOTES.md; nanochat commit 4e014d3, contributed by jn2clark: "both seem to be very slight
# improvements at both d12 and d24"). In both of the lean class's Muon math paths (muon_math_body, S4's compiled
# function, which runs the trunk's segments and the experts' local units, and its S4-off twin _muon_math): after the
# momentum mix and the cast to the orthogonalisation dtype, every row of each matrix of the stack is rescaled to the
# matrix's mean row norm, ||X||_F / sqrt(rows) (row norms clamped at 1e-6; MuonEq, arXiv 2603.28254: a better
# conditioned spectrum entering the iteration); after the Polar Express iterations each matrix's Frobenius norm is
# snapped to sqrt(min(rows, cols)), an exactly semi-orthogonal matrix's (clamped at 1e-6; Muon+, arXiv 2602.21545:
# the iteration's under-convergence corrected), before the variance reduction. Momentum, the variance reduction, the
# decay and the schedules are unchanged. Refused with an optimizer other than the lean class (main()). kit: unset.
R2_MUONEQ = _env("R2_MUONEQ", False, bool)
if R2_MUONEQ and R2_NSK:
    # COMBO5 (work/p2/combo5/NOTES.md, collision K4): MQ1 edits muon_math_body and _muon_math, and switch 65 replaces
    # muon_math_body's calls for the experts' local units with its own pair function, so with both set the experts
    # would take the plain Muon step while the trunk takes MuonEq (lane PORT's NOTES B; never built together).
    raise ValueError("R2_MUONEQ (MQ1, lane BATCH) and R2_NSK (switch 65, lane PORT) are not built together: the "
                     "experts' Newton-Schulz kernel does not carry MuonEq or Muon+; set one of them")


class MuonAdamW(torch.optim.Optimizer):
    def __init__(self, param_groups):
        super().__init__(param_groups, defaults={})
        # Changing Python scalar arguments retraces Neuron eager optimizer ops.
        # Keep the changing schedule values in persistent 0-D CPU tensors so the
        # same device graphs can be reused throughout warmup and training.
        for group in self.param_groups:
            group["_lr_t"] = torch.tensor(float(group["lr"]), dtype=torch.float32)
            group["_wd_t"] = torch.tensor(float(group["weight_decay"]), dtype=torch.float32)
            if group["kind"] == "adamw":
                beta1, beta2 = group["betas"]
                group["_one_minus_beta1_t"] = torch.tensor(1 - beta1, dtype=torch.float32)
                group["_one_minus_beta2_t"] = torch.tensor(1 - beta2, dtype=torch.float32)
                group["_eps_t"] = torch.tensor(float(group["eps"]), dtype=torch.float32)
            elif group["kind"] == "muon":
                group["_momentum_t"] = torch.tensor(float(group["momentum"]), dtype=torch.float32)
                group["_one_minus_momentum_t"] = torch.tensor(1 - float(group["momentum"]), dtype=torch.float32)
                group["_one_minus_beta2_t"] = torch.tensor(1 - float(group["beta2"]), dtype=torch.float32)

    @staticmethod
    def _adamw_update(p, grad, state, group):
        beta1, beta2 = group["betas"]
        lr_t = group["_lr_t"]
        wd_t = group["_wd_t"]
        one_minus_beta1_t = group["_one_minus_beta1_t"]
        one_minus_beta2_t = group["_one_minus_beta2_t"]
        eps_t = group["_eps_t"]
        lr_t.fill_(group["lr"])
        wd_t.fill_(group["weight_decay"])
        if not state:
            state["step"] = 0
            state["exp_avg"] = torch.zeros_like(p)
            state["exp_avg_sq"] = torch.zeros_like(p)
            state["bias1_t"] = torch.tensor(0.0, dtype=torch.float32)
            state["bias2_t"] = torch.tensor(0.0, dtype=torch.float32)
        state["step"] += 1
        exp_avg = state["exp_avg"]
        exp_avg_sq = state["exp_avg_sq"]
        bias1_t = state["bias1_t"]
        bias2_t = state["bias2_t"]
        bias1_t.fill_(1 - beta1 ** state["step"])
        bias2_t.fill_(1 - beta2 ** state["step"])
        p.mul_(1 - lr_t * wd_t)
        exp_avg.lerp_(grad, one_minus_beta1_t)
        exp_avg_sq.lerp_(grad.square(), one_minus_beta2_t)
        update = exp_avg / bias1_t / ((exp_avg_sq / bias2_t).sqrt() + eps_t)
        p.sub_(lr_t * update)

    @torch.no_grad()
    def _adamw_step(self, group):
        for p in group["params"]:
            if p.grad is None:
                continue
            self._adamw_update(p, p.grad, self.state[p], group)

    @torch.no_grad()
    def _muon_step(self, group):
        params = group["params"]
        if not params:
            return
        p0 = params[0]
        state = self.state[p0]
        shape = p0.shape
        if "momentum_buffer" not in state:
            state["momentum_buffer"] = torch.zeros(len(params), *shape, dtype=p0.dtype, device=p0.device)
        if "second_momentum_buffer" not in state:
            state_shape = (len(params), shape[-2], 1) if shape[-2] >= shape[-1] else (len(params), 1, shape[-1])
            state["second_momentum_buffer"] = torch.zeros(state_shape, dtype=torch.float32, device=p0.device)
        if "stacked_grads" not in state:
            state["stacked_grads"] = torch.empty(len(params), *shape, dtype=p0.dtype, device=p0.device)
        if "stacked_params" not in state:
            state["stacked_params"] = torch.empty(len(params), *shape, dtype=p0.dtype, device=p0.device)

        g = state["stacked_grads"]
        w = state["stacked_params"]
        for i, p in enumerate(params):
            if p.grad is None:
                g[i].zero_()
            else:
                g[i].copy_(p.grad)
            w[i].copy_(p)
        momentum_buffer = state["momentum_buffer"]
        second = state["second_momentum_buffer"]

        momentum_t = group["_momentum_t"]
        one_minus_momentum_t = group["_one_minus_momentum_t"]
        one_minus_beta2_t = group["_one_minus_beta2_t"]
        lr_t = group["_lr_t"]
        wd_t = group["_wd_t"]
        momentum_t.fill_(group["momentum"])
        one_minus_momentum_t.fill_(1 - group["momentum"])
        one_minus_beta2_t.fill_(1 - group["beta2"])
        lr_t.fill_(group["lr"] * max(1.0, shape[-2] / shape[-1]) ** 0.5)
        wd_t.fill_(group["weight_decay"])

        momentum_buffer.lerp_(g, one_minus_momentum_t)
        g = g.lerp_(momentum_buffer, momentum_t)
        x = g.bfloat16() if COMPUTE_DTYPE == torch.bfloat16 else g
        x = x / (x.norm(dim=(-2, -1), keepdim=True) * 1.01 + 1e-6)
        if x.shape[-2] > x.shape[-1]:
            for a, b, c in POLAR_EXPRESS_COEFFS[:group["ns_steps"]]:
                xtx = x.mT @ x
                x = a * x + x @ (b * xtx + c * (xtx @ xtx))
        else:
            for a, b, c in POLAR_EXPRESS_COEFFS[:group["ns_steps"]]:
                xxt = x @ x.mT
                x = a * x + (b * xxt + c * (xxt @ xxt)) @ x
        g = x

        red_dim = -1 if shape[-2] >= shape[-1] else -2
        v_mean = g.float().square().mean(dim=red_dim, keepdim=True)
        red_dim_size = g.size(red_dim)
        v_norm = (v_mean.sum(dim=(-2, -1), keepdim=True) * red_dim_size).sqrt()
        second.lerp_(v_mean, one_minus_beta2_t)
        step_size = second.clamp_min(1e-10).rsqrt()
        scaled = (v_mean * red_dim_size) * step_size.square()
        v_norm_new = scaled.sum(dim=(-2, -1), keepdim=True).sqrt()
        g = g * (step_size * (v_norm / v_norm_new.clamp_min(1e-10))).to(g.dtype)

        mask = (g * w) >= 0
        w.sub_(lr_t * g + lr_t * wd_t * w * mask)
        torch._foreach_copy_(params, list(w.unbind(0)))

    @torch.no_grad()
    def _moe_local_step(self, group):
        """Switch 55 on one rank (no data-parallel peer: every expert is here): each expert stack [n, r, c] is
        updated as n matrices from its own gradient, with _muon_step's arithmetic on a stack (or AdamW's)."""
        for p in group["params"]:
            if p.grad is None:
                continue
            if group["kind"] == "adamw":
                self._adamw_update(p, p.grad, self.state[p], group)
                continue
            st = self.state[p]
            shape = p.shape[-2:]
            if "momentum_buffer" not in st:
                st["momentum_buffer"] = torch.zeros_like(p)
                st_shape = (p.shape[0], shape[0], 1) if shape[0] >= shape[1] else (p.shape[0], 1, shape[1])
                st["second_momentum_buffer"] = torch.zeros(st_shape, dtype=torch.float32, device=p.device)
            g = p.grad.to(p.dtype).clone()
            w = p
            momentum_t, one_minus_momentum_t = group["_momentum_t"], group["_one_minus_momentum_t"]
            one_minus_beta2_t, lr_t, wd_t = group["_one_minus_beta2_t"], group["_lr_t"], group["_wd_t"]
            momentum_t.fill_(group["momentum"])
            one_minus_momentum_t.fill_(1 - group["momentum"])
            one_minus_beta2_t.fill_(1 - group["beta2"])
            lr_t.fill_(group["lr"] * max(1.0, shape[-2] / shape[-1]) ** 0.5)
            wd_t.fill_(group["weight_decay"])
            momentum_buffer, second = st["momentum_buffer"], st["second_momentum_buffer"]
            momentum_buffer.lerp_(g, one_minus_momentum_t)
            g = g.lerp_(momentum_buffer, momentum_t)
            x = g.bfloat16() if COMPUTE_DTYPE == torch.bfloat16 else g
            x = x / (x.norm(dim=(-2, -1), keepdim=True) * 1.01 + 1e-6)
            if x.shape[-2] > x.shape[-1]:
                for a, b, c in POLAR_EXPRESS_COEFFS[:group["ns_steps"]]:
                    xtx = x.mT @ x
                    x = a * x + x @ (b * xtx + c * (xtx @ xtx))
            else:
                for a, b, c in POLAR_EXPRESS_COEFFS[:group["ns_steps"]]:
                    xxt = x @ x.mT
                    x = a * x + (b * xxt + c * (xxt @ xxt)) @ x
            g = x
            red_dim = -1 if shape[-2] >= shape[-1] else -2
            v_mean = g.float().square().mean(dim=red_dim, keepdim=True)
            red_dim_size = g.size(red_dim)
            v_norm = (v_mean.sum(dim=(-2, -1), keepdim=True) * red_dim_size).sqrt()
            second.lerp_(v_mean, one_minus_beta2_t)
            step_size = second.clamp_min(1e-10).rsqrt()
            scaled = (v_mean * red_dim_size) * step_size.square()
            v_norm_new = scaled.sum(dim=(-2, -1), keepdim=True).sqrt()
            g = g * (step_size * (v_norm / v_norm_new.clamp_min(1e-10))).to(g.dtype)
            mask = (g * w) >= 0
            w.sub_(lr_t * g + lr_t * wd_t * w * mask)

    @torch.no_grad()
    def step(self):
        for group in self.param_groups:
            if group.get("moe_local"):
                self._moe_local_step(group)        # switch 55 on one rank
            elif group["kind"] == "adamw":
                self._adamw_step(group)
            elif group["kind"] == "muon":
                self._muon_step(group)
            else:
                raise ValueError(f"unknown optimizer kind: {group['kind']}")


class DistMuonAdamW(MuonAdamW):
    """ZeRO-2-style distributed variant with replicated FP32 parameters.

    AdamW tensors are sharded along their first dimension. Muon tensors are
    sharded by whole matrices within each equal-shape group. Gradients use
    reduce-scatter, only the owned shard carries optimizer state, and updated
    parameters are all-gathered back to every rank.

    Muon groups execute serially and share one communication slab. This is the
    memory-critical part of the port: allocating one padded slab per matrix
    shape would erase most of the optimizer-state saving on Trainium.
    """

    handles_gradient_sync = True

    def __init__(self, param_groups):
        if not (dist.is_available() and dist.is_initialized()):
            raise RuntimeError("DistMuonAdamW requires an initialized process group")
        super().__init__(param_groups)
        self.rank = dist.get_rank()
        self.world_size = dist.get_world_size()
        self._adamw_grad_slices = {}
        self._shared_muon_buffers = {}

    def _shared_muon_buffer(self, name, rows, shape, dtype, device, *, zero=False):
        need = rows * shape[0] * shape[1]
        buf = self._shared_muon_buffers.get(name)
        if buf is None or buf.numel() < need or buf.dtype != dtype or buf.device != device:
            factory = torch.zeros if zero else torch.empty
            buf = factory(need, dtype=dtype, device=device)
            self._shared_muon_buffers[name] = buf
        return buf.flatten()[:need].view(rows, *shape)

    @staticmethod
    def _copy_muon_params(params, stacked):
        if not params:
            return
        if params[0].device.type == "neuron":
            per = params[0].numel()
            torch.split_with_sizes_copy(
                stacked.reshape(-1)[:len(params) * per],
                [per] * len(params),
                out=[p.data.view(-1) for p in params],
            )
        else:
            torch._foreach_copy_(params, list(stacked[:len(params)].unbind(0)))

    @torch.no_grad()
    def _distributed_adamw_step(self, group):
        for param_index, p in enumerate(group["params"]):
            if p.grad is None:
                p.grad = torch.zeros_like(p)
            grad = p.grad
            if p.numel() < 1024:
                dist.all_reduce(grad, op=dist.ReduceOp.AVG)
                self._adamw_update(p, grad, self.state[p], group)
                p.grad = None
                continue

            if p.shape[0] % self.world_size:
                raise ValueError(
                    f"AdamW parameter first dimension {p.shape[0]} must be divisible "
                    f"by world size {self.world_size}"
                )
            rows = p.shape[0] // self.world_size
            grad_slice = self._adamw_grad_slices.get(id(p))
            if grad_slice is None or grad_slice.shape != grad[:rows].shape:
                grad_slice = torch.empty_like(grad[:rows])
                self._adamw_grad_slices[id(p)] = grad_slice
            dist.reduce_scatter_tensor(grad_slice, grad, op=dist.ReduceOp.AVG)

            start = self.rank * rows
            p_slice = p[start:start + rows]
            self._adamw_update(p_slice, grad_slice, self.state[p], group)
            dist.all_gather_into_tensor(p, p_slice)
            p.grad = None

    @torch.no_grad()
    def _distributed_muon_step(self, group):
        params = group["params"]
        if not params:
            return
        p0 = params[0]
        shape = tuple(p0.shape)
        if any(tuple(p.shape) != shape for p in params):
            raise ValueError("Muon groups must contain equal-shape matrices")

        chunk_size = (len(params) + self.world_size - 1) // self.world_size
        padded_count = chunk_size * self.world_size
        dtype, device = p0.dtype, p0.device
        stacked = self._shared_muon_buffer(
            "stacked", padded_count, shape, dtype, device, zero=True
        )
        grad_chunk = self._shared_muon_buffer(
            "grad_chunk", chunk_size, shape, dtype, device
        )
        updated = self._shared_muon_buffer(
            "updated", chunk_size, shape, dtype, device
        )

        for i, p in enumerate(params):
            if p.grad is None:
                stacked[i].zero_()
            else:
                stacked[i].copy_(p.grad)
            p.grad = None
        dist.reduce_scatter_tensor(grad_chunk, stacked, op=dist.ReduceOp.AVG)

        start = self.rank * chunk_size
        num_owned = min(chunk_size, max(0, len(params) - start))
        state = self.state[p0]
        if num_owned:
            if "momentum_buffer" not in state:
                state["momentum_buffer"] = torch.zeros(
                    num_owned, *shape, dtype=dtype, device=device
                )
            if "second_momentum_buffer" not in state:
                state_shape = (
                    (num_owned, shape[-2], 1)
                    if shape[-2] >= shape[-1]
                    else (num_owned, 1, shape[-1])
                )
                state["second_momentum_buffer"] = torch.zeros(
                    state_shape, dtype=torch.float32, device=device
                )
            for i in range(num_owned):
                updated[i].copy_(params[start + i])

            momentum_t = group["_momentum_t"]
            one_minus_momentum_t = group["_one_minus_momentum_t"]
            one_minus_beta2_t = group["_one_minus_beta2_t"]
            lr_t = group["_lr_t"]
            wd_t = group["_wd_t"]
            momentum_t.fill_(group["momentum"])
            one_minus_momentum_t.fill_(1 - group["momentum"])
            one_minus_beta2_t.fill_(1 - group["beta2"])
            lr_t.fill_(group["lr"] * max(1.0, shape[-2] / shape[-1]) ** 0.5)
            wd_t.fill_(group["weight_decay"])

            g = grad_chunk[:num_owned]
            momentum = state["momentum_buffer"]
            second = state["second_momentum_buffer"]
            momentum.lerp_(g, one_minus_momentum_t)
            g = g.lerp_(momentum, momentum_t)
            x = g.bfloat16() if COMPUTE_DTYPE == torch.bfloat16 else g
            x = x / (x.norm(dim=(-2, -1), keepdim=True) * 1.01 + 1e-6)
            # A one-matrix shard would lower the 3-D products below as batch-1
            # bmm, which the Trainium lazy prologue cannot merge. Use ordinary
            # 2-D matmul for that case and restore the batch dimension after the
            # Polar Express iterations.
            squeezed = x.dim() == 3 and x.size(0) == 1
            if squeezed:
                x = x.squeeze(0)
            if x.shape[-2] > x.shape[-1]:
                for a, b, c in POLAR_EXPRESS_COEFFS[:group["ns_steps"]]:
                    xtx = x.mT @ x
                    x = a * x + x @ (b * xtx + c * (xtx @ xtx))
            else:
                for a, b, c in POLAR_EXPRESS_COEFFS[:group["ns_steps"]]:
                    xxt = x @ x.mT
                    x = a * x + (b * xxt + c * (xxt @ xxt)) @ x
            if squeezed:
                x = x.unsqueeze(0)
            g = x

            red_dim = -1 if shape[-2] >= shape[-1] else -2
            v_mean = g.float().square().mean(dim=red_dim, keepdim=True)
            red_dim_size = g.size(red_dim)
            v_norm = (v_mean.sum(dim=(-2, -1), keepdim=True) * red_dim_size).sqrt()
            second.lerp_(v_mean, one_minus_beta2_t)
            step_size = second.clamp_min(1e-10).rsqrt()
            scaled = (v_mean * red_dim_size) * step_size.square()
            v_norm_new = scaled.sum(dim=(-2, -1), keepdim=True).sqrt()
            g = g * (step_size * (v_norm / v_norm_new.clamp_min(1e-10))).to(g.dtype)

            w = updated[:num_owned]
            mask = (g * w) >= 0
            w.sub_(lr_t * g + lr_t * wd_t * w * mask)

        if num_owned < chunk_size:
            updated[num_owned:].zero_()
        dist.all_gather_into_tensor(stacked, updated)
        self._copy_muon_params(params, stacked)

    @torch.no_grad()
    def step(self):
        # AdamW state is small after row sharding, so process it first. Muon
        # groups remain serial to reuse the large padded communication slab.
        for group in self.param_groups:
            if group["kind"] == "adamw":
                self._distributed_adamw_step(group)
        for group in self.param_groups:
            if group["kind"] == "muon":
                self._distributed_muon_step(group)


# -----------------------------------------------------------------------------
# Switch 11: LeanDistMuonAdamW, copied verbatim from work/agents/p2_optimizer/lean_dist_muon.py (md5 87da02ad,
# study W3, reviewed 2026-10-08; its module docstring lists the mechanisms). The update arithmetic is the kit's
# (above); the differences are the communication layout, the FP32 masters and the options left off here.

def ns_flops(r: int, c: int, iters: int) -> int:
    """FLOPs of `iters` Polar Express iterations on one [r, c] matrix (the products of kit train.py:774-781)."""
    if r > c:
        per = 2 * c * r * c + 2 * c * c * c + 2 * r * c * c
    else:
        per = 2 * r * c * r + 2 * r * r * r + 2 * r * r * c
    return iters * per


def plan_layout(shapes, counts, world, ns_steps=5, balance=True, leftover_route="auto"):
    """Decide which Muon matrix travels where.

    shapes[g], counts[g]: matrix shape and number of matrices of Muon group g (kit order: sorted shapes).
    Returns a dict:
      U            elements per unit (the largest matrix)
      per[g]       matrices of group g per unit
      units        list of (g, first matrix index, number of matrices)
      c            main units per rank
      main[r]      unit ids owned by rank r in the main slab, in chunk order (same-shape units adjacent)
      left         list of (g, matrix index) that travel outside the main slab
      route        "none" | "allreduce" | "slots"
      rounds       number of slot rounds (route "slots")
      left_owner   owning rank of each leftover matrix
      left_round   slot round of each leftover matrix (route "slots")
      load[r]      Newton-Schulz FLOPs per step on rank r
    """
    numel = [r * c for r, c in shapes]
    U = max(numel)
    per = []
    for n in numel:
        if U % n:
            raise ValueError(f"Muon matrix of {n} elements does not divide the unit of {U}")
        per.append(U // n)
    units = []
    for g, cnt in enumerate(counts):
        for s in range(0, cnt, per[g]):
            units.append((g, s, min(per[g], cnt - s)))
    cost_m = [ns_flops(r, c, ns_steps) for r, c in shapes]
    ucost = [cost_m[g] * n for g, _s, n in units]
    n_units = len(units)
    c = max(1, n_units // world)
    n_main = min(n_units, c * world)
    # Units that do not fit the main slab: take the ones with the most matrices (finest grain), last blocks first.
    order = sorted(range(n_units), key=lambda i: (-units[i][2], -i))
    left_ids = sorted(order[:n_units - n_main])
    left_set = set(left_ids)
    main_ids = [i for i in range(n_units) if i not in left_set]
    deal = sorted(main_ids, key=lambda i: (-ucost[i], i)) if balance else list(main_ids)
    main = [[] for _ in range(world)]
    for j, uid in enumerate(deal):
        main[j % world].append(uid)
    for r in range(world):
        main[r].sort(key=lambda i: (units[i][0], i))
    load = [sum(ucost[i] for i in main[r]) for r in range(world)]
    left = [(units[i][0], units[i][1] + k) for i in left_ids for k in range(units[i][2])]
    n_left = len(left)
    rounds = -(-n_left // world) if n_left else 0
    single_shape = len({g for g, _m in left}) <= 1
    if n_left == 0:
        route = "none"
    elif leftover_route == "auto":
        # all_reduce pair: 2 * n_left matrices of traffic each way. Slot rounds: rounds * world matrices each way.
        route = "allreduce" if (2 * n_left < rounds * world or not single_shape) else "slots"
    else:
        route = leftover_route
        if route == "slots" and not single_shape:
            raise ValueError("the slot route needs leftover matrices of one shape")
    cap = rounds if route == "slots" else n_left
    left_owner, left_round, cnt = [], [], [0] * world
    for j, (g, _m) in enumerate(left):
        if balance:
            r = min((q for q in range(world) if cnt[q] < cap), key=lambda q: (load[q], q))
        else:
            r = j % world
        left_owner.append(r)
        left_round.append(cnt[r])
        cnt[r] += 1
        load[r] += cost_m[g]
    return dict(U=U, per=per, units=units, c=c, main=main, left=left, route=route, rounds=rounds,
                left_owner=left_owner, left_round=left_round, load=load, cost_m=cost_m, numel=numel)


class LeanDistMuonAdamW(torch.optim.Optimizer):
    """See the module docstring. Constructor arguments:

    param_groups      the kit's own groups (kind="adamw" | "muon"), as built by GPT.setup_optimizer.
    polar_coeffs      the kit's POLAR_EXPRESS_COEFFS.
    ns_dtype_fn       callable returning the orthogonalisation dtype at step time (the kit reads COMPUTE_DTYPE).
    slab_collectives  K: number of collectives the main slab is cut into (1 = one large collective).
    leftover_route    "auto" | "allreduce" | "slots".
    balance           spread orthogonalisation work (False = natural order, leftover j to rank j % world).
    param_views       parameters become views of the slabs the all-gather writes (no copy-back).
    replica_dtype     dtype of the replicated parameters (FP32, or bf16 with FP32 masters on the owner).
    acc_dtype         dtype of the gradient payload of the reduce collectives (FP32, or bf16).
    finite_gate       device-side skip of a step whose reduced gradient is not finite.
    fp32_replicas     parameters whose replica stays FP32 whatever replica_dtype is (AdamW tensors only). With
                      bf16 replicas it must hold the embedding (`wte`): the kit looks it up in FP32, so a bf16
                      replica would sum repeated tokens' gradients in bf16 (W3-F3; review 2026-10-08).
    """

    handles_gradient_sync = True

    def __init__(self, param_groups, *, polar_coeffs, ns_dtype_fn, slab_collectives=1, leftover_route="auto",
                 balance=True, param_views=False, replica_dtype=torch.float32, acc_dtype=torch.float32,
                 finite_gate=False, fp32_replicas=(), foreach_copy=False, slab_dtype=None, slab_sum=False):
        if not (dist.is_available() and dist.is_initialized()):
            raise RuntimeError("LeanDistMuonAdamW requires an initialized process group")
        super().__init__(param_groups, defaults={})
        self.rank = dist.get_rank()
        self.world = dist.get_world_size()
        self.polar_coeffs = list(polar_coeffs)
        self.ns_dtype_fn = ns_dtype_fn
        self.K = int(slab_collectives)
        self.param_views = bool(param_views)
        self.replica_dtype = replica_dtype
        self.acc_dtype = acc_dtype
        self.foreach_copy = bool(foreach_copy)   # O2: the slab into the parameters by one multi-tensor copy
        self.slab_dtype = acc_dtype if slab_dtype is None else slab_dtype   # S1: the Muon slab's payload dtype
        self.slab_sum = bool(slab_sum)   # S1: the slab's reductions with SUM, the mean over ranks taken in FP32
        self._fold = None                # S2: the slab's accumulation function (enable_fold)
        self._math = None                # S4: the update functions (enable_compiled_math)
        self._sched_bufs = {}            # S4: one persistent device tensor of schedule values per state
        self.finite_gate = bool(finite_gate)
        self._fp32_ids = {id(p) for p in fp32_replicas}
        self.skipped_steps = 0
        self._acc_count = 0
        self._last_ok = None
        self._adamw_states = []
        self._snap = None
        self._gate_only = None
        # The kit's convention (train.py:487-501): schedule values live in persistent 0-D CPU tensors.
        for group in self.param_groups:
            group["_lr_t"] = torch.tensor(float(group["lr"]), dtype=torch.float32)
            group["_wd_t"] = torch.tensor(float(group["weight_decay"]), dtype=torch.float32)
            if group["kind"] == "adamw":
                beta1, beta2 = group["betas"]
                group["_one_minus_beta1_t"] = torch.tensor(1 - beta1, dtype=torch.float32)
                group["_one_minus_beta2_t"] = torch.tensor(1 - beta2, dtype=torch.float32)
                group["_eps_t"] = torch.tensor(float(group["eps"]), dtype=torch.float32)
            elif group["kind"] == "muon":
                group["_momentum_t"] = torch.tensor(float(group["momentum"]), dtype=torch.float32)
                group["_one_minus_momentum_t"] = torch.tensor(1 - float(group["momentum"]), dtype=torch.float32)
                group["_one_minus_beta2_t"] = torch.tensor(1 - float(group["beta2"]), dtype=torch.float32)
            else:
                raise ValueError(f"unknown optimizer kind: {group['kind']}")
        self._build(leftover_route, balance)
        self._build_local()               # switch 55: each rank's experts (none without it)

    # ----------------------------------------------------------------------------------------------- build

    def _adopt(self, p, slab_view, replica_index_if_view, offset):
        """Point parameter p at its replica storage and record where its replica lives (for snapshots)."""
        if self.param_views:
            slab_view.copy_(p.detach().reshape(slab_view.shape))
            p.data = slab_view.view(p.shape)
            self._replica_map[id(p)] = (replica_index_if_view, offset)
        else:
            if p.dtype != self.replica_dtype:
                p.data = p.data.to(self.replica_dtype)
            self._replica_map[id(p)] = (len(self._replica_tensors), 0)
            self._replica_tensors.append(p.data)

    def _build(self, leftover_route, balance):
        f32 = torch.float32
        W = self.world
        self._small, self._rows, self._left, self._own, self._runs = [], [], [], [], []
        self._acc_params, self._acc_targets = [], []       # slab accumulation: parameter -> where its gradient goes
        self._replica_tensors, self._replica_map = [], {}  # for snapshots: id(param) -> (tensor index, flat offset)
        # ---- AdamW: small parameters are stacked and replicated, large ones are row-sharded (kit train.py:669-696)
        for g in self.param_groups:
            if g["kind"] != "adamw" or g.get("moe_local"):
                continue
            small = [p for p in g["params"] if p.numel() < 1024]
            if small:
                sizes = [p.numel() for p in small]
                n = sum(sizes)
                master = torch.cat([p.detach().reshape(-1).to(f32) for p in small])   # FP32, replicated on every rank
                extra = 1 if (self.finite_gate and not self._small) else 0          # the gate's slot rides here
                pay = torch.zeros(n + extra, dtype=f32, device=master.device)
                ti = len(self._replica_tensors)
                if self.param_views:
                    self._replica_tensors.append(master)
                o = 0
                for p, s in zip(small, sizes):
                    if self.param_views:
                        p.data = master[o:o + s].view(p.shape)
                        self._replica_map[id(p)] = (ti, o)
                    else:
                        self._replica_map[id(p)] = (len(self._replica_tensors), 0)
                        self._replica_tensors.append(p.data)
                    self._acc_params.append(p)
                    self._acc_targets.append(pay[o:o + s].view(p.shape))
                    o += s
                self._small.append(dict(group=g, params=small, sizes=sizes, n=n, master=master, pay=pay, st={}))
            for p in g["params"]:
                if p.numel() < 1024:
                    continue
                if p.shape[0] % W:
                    raise ValueError(f"AdamW parameter first dimension {p.shape[0]} must be divisible by world size {W}")
                rows = p.shape[0] // W
                start = self.rank * rows
                master = p.detach()[start:start + rows].to(f32, copy=True)      # FP32 master of the owned rows
                rd = f32 if id(p) in self._fp32_ids else self.replica_dtype     # `wte` stays FP32 (W3-F3)
                if p.dtype != rd:
                    p.data = p.data.to(rd)
                tail = tuple(p.shape[1:])
                out = None if rd == f32 else torch.empty((rows, *tail), dtype=rd, device=p.device)
                self._replica_map[id(p)] = (len(self._replica_tensors), 0)
                self._replica_tensors.append(p.data)
                self._rows.append(dict(group=g, p=p, rows=rows, start=start, master=master, out=out, st={}, acc=None,
                                       grad_slice=torch.empty((rows, *tail), dtype=self.acc_dtype, device=p.device)))
        stray = self._fp32_ids - {id(r["p"]) for r in self._rows} - {id(p) for S in self._small for p in S["params"]}
        if stray:
            raise ValueError("fp32_replicas: only AdamW parameters can keep an FP32 replica (Muon replicas share the slab dtype)")
        # ---- Muon
        self._mg = [g for g in self.param_groups if g["kind"] == "muon" and g["params"] and not g.get("moe_local")]
        self.plan = None
        if not self._mg:
            return
        shapes = []
        for g in self._mg:
            shape = tuple(g["params"][0].shape)
            if any(tuple(p.shape) != shape for p in g["params"]):
                raise ValueError("Muon groups must contain equal-shape matrices")
            shapes.append(shape)
        self._shapes = shapes
        plan = plan_layout(shapes, [len(g["params"]) for g in self._mg], W, ns_steps=self._mg[0]["ns_steps"],
                           balance=balance, leftover_route=leftover_route)
        self.plan = plan
        U, c = plan["U"], plan["c"]
        CU = c * U
        self.CU = CU
        dev = self._mg[0]["params"][0].device
        # Shape used for the collective calls: the largest matrix shape, so that at world 64 and c = 1 the main
        # reduce-scatter and all-gather have exactly the shapes of the kit's own MLP-group collectives.
        big = next(s for s in shapes if s[0] * s[1] == U)
        self._coll_in = (W * c, *big)
        self._coll_out = (c, *big)
        self.Gm = torch.zeros(W, CU, dtype=self.slab_dtype, device=dev)      # gradient payload, reduce-scatter input
        self.mine_g = torch.empty(1, CU, dtype=self.slab_dtype, device=dev)  # this rank's reduced chunk
        self.Mm = torch.zeros(1, CU, dtype=f32, device=dev)                  # FP32 master of this rank's chunk
        reuse = (not self.param_views) and self.slab_dtype == self.replica_dtype
        self.Wm = self.Gm if reuse else torch.zeros(W, CU, dtype=self.replica_dtype, device=dev)  # all-gather output
        self.mine_out = None if self.replica_dtype == f32 else torch.empty(1, CU, dtype=self.replica_dtype, device=dev)
        Gflat, Wflat = self.Gm.view(-1), self.Wm.view(-1)
        ti_main = len(self._replica_tensors)
        if self.param_views:
            self._replica_tensors.append(self.Wm)
        items = []          # (flat offset, parameter) of every main-slab parameter
        for r in range(W):
            seg = None
            for j, uid in enumerate(plan["main"][r]):
                g, s, n = plan["units"][uid]
                ne = plan["numel"][g]
                for k in range(n):
                    p = self._mg[g]["params"][s + k]
                    items.append((r * CU + j * U + k * ne, p))
                    if r == self.rank:
                        self.Mm.view(-1)[j * U + k * ne: j * U + (k + 1) * ne].copy_(p.detach().reshape(-1))
                if r == self.rank:
                    if seg is not None and seg["g"] == g and seg["b"] == j * U and seg["full"]:
                        seg["b"] = j * U + n * ne
                        seg["k"] += n
                    else:
                        seg = dict(g=g, a=j * U, b=j * U + n * ne, k=n, shape=shapes[g], st={})
                        self._own.append(seg)
                    seg["full"] = (n == plan["per"][g])
        items.sort(key=lambda t: t[0])
        for off, p in items:
            ne = p.numel()
            self._adopt(p, Wflat[off:off + ne], ti_main, off)
            self._acc_params.append(p)
            self._acc_targets.append(Gflat[off:off + ne].view(p.shape))
            # contiguous runs of real elements: one cat in, one split copy out per run
            if self._runs and self._runs[-1]["end"] == off:
                run = self._runs[-1]
                run["end"] += ne
                run["params"].append(p)
                run["sizes"].append(ne)
            else:
                self._runs.append(dict(start=off, end=off + ne, params=[p], sizes=[ne]))
        self._pieces = [(i * CU // self.K, (i + 1) * CU // self.K) for i in range(self.K)]
        # ---- leftover matrices
        route = plan["route"]
        if route == "allreduce":
            by_g = OrderedDict()
            for j, (g, m) in enumerate(plan["left"]):
                by_g.setdefault(g, []).append((m, plan["left_owner"][j]))
            for g, lst in by_g.items():
                shape = shapes[g]
                params = [self._mg[g]["params"][m] for m, _o in lst]
                own = [i for i, (_m, o) in enumerate(lst) if o == self.rank]
                master = torch.stack([params[i].detach().to(f32) for i in own]) if own else None
                Gl = torch.zeros(len(lst), *shape, dtype=self.slab_dtype, device=dev)
                Wl = Gl if reuse else torch.zeros(len(lst), *shape, dtype=self.replica_dtype, device=dev)
                ti = len(self._replica_tensors)
                if self.param_views:
                    self._replica_tensors.append(Wl)
                for i, p in enumerate(params):
                    self._adopt(p, Wl[i], ti, i * p.numel())
                    self._acc_params.append(p)
                    self._acc_targets.append(Gl[i])
                self._left.append(dict(kind="allreduce", g=g, shape=shape, params=params, own=own, Gl=Gl, Wl=Wl,
                                       master=master, st={},
                                       idx=torch.tensor(own, dtype=torch.long, device=dev) if own else None))
        elif route == "slots":
            g = plan["left"][0][0]
            shape = shapes[g]
            for q in range(plan["rounds"]):
                slots = [(plan["left_owner"][j], self._mg[g]["params"][m])
                         for j, (_g, m) in enumerate(plan["left"]) if plan["left_round"][j] == q]
                mine_p = next((p for o, p in slots if o == self.rank), None)
                master = torch.zeros(1, *shape, dtype=f32, device=dev)
                if mine_p is not None:
                    master[0].copy_(mine_p.detach())
                Gl = torch.zeros(W, *shape, dtype=self.slab_dtype, device=dev)
                Wl = Gl if reuse else torch.zeros(W, *shape, dtype=self.replica_dtype, device=dev)
                ti = len(self._replica_tensors)
                if self.param_views:
                    self._replica_tensors.append(Wl)
                for o, p in slots:
                    self._adopt(p, Wl[o], ti, o * p.numel())
                    self._acc_params.append(p)
                    self._acc_targets.append(Gl[o])
                self._left.append(dict(kind="slots", g=g, shape=shape, slots=slots, owns=mine_p is not None, Gl=Gl, Wl=Wl,
                                       master=master, st={},
                                       mine=torch.empty(1, *shape, dtype=self.slab_dtype, device=dev),
                                       out=None if self.replica_dtype == f32 else torch.empty(1, *shape, dtype=self.replica_dtype, device=dev)))

    def _build_local(self) -> None:
        """Switch 55: the experts' local units. A group marked moe_local holds this rank's expert stacks [n, r, c]
        (one expert a rank on the chip): an FP32 master and an FP32 accumulator on this rank, the replicas at the
        matrices' replica dtype, no reduce and no gather (the whole gradient of an expert forms on the rank that
        holds it, from every rank's tokens). Their accumulation rides accumulate()'s multi-tensor copy and add (they
        join _acc_params); step() updates them after the trunk's units, from the accumulation times 1 / world (the
        data-parallel mean's normalisation: each rank's loss is its own tokens' mean)."""
        f32 = torch.float32
        self._local = []
        for g in self.param_groups:
            if not g.get("moe_local") or not g["params"]:
                continue
            ps = g["params"]
            shape = tuple(ps[0].shape[1:])
            if any(p.dim() != 3 or tuple(p.shape[1:]) != shape for p in ps):
                raise ValueError("switch 55: a local group holds expert stacks [n, r, c] of one matrix shape")
            counts = [p.shape[0] for p in ps]
            master = torch.cat([p.detach().to(f32) for p in ps])
            acc = torch.zeros_like(master)
            for p, view in zip(ps, acc.split(counts)):
                if p.dtype != self.replica_dtype:
                    p.data = p.data.to(self.replica_dtype)
                self._acc_params.append(p)
                self._acc_targets.append(view)
            self._local.append(dict(group=g, params=ps, counts=counts, shape=shape, master=master, acc=acc, st={},
                                    scale=1.0 / self.world))

    # ------------------------------------------------------------------------------------ gradient staging

    @torch.no_grad()
    def accumulate(self):
        """Optional. Call after every backward: folds this micro-step's gradients into the communication buffers
        (one multi-tensor call for all stacked parameters, one add per row-sharded tensor) and drops the .grad
        tensors, so autograd never issues its per-parameter accumulation adds. The sums are the ones autograd
        would form, in the same order."""
        first = self._acc_count == 0
        acc_params, acc_targets = self._fold_rest(first)      # S2: the slab's runs by the fold, if one is set
        grads = [p.grad if p.grad is not None else torch.zeros_like(p) for p in acc_params]
        if getattr(self, "_rest_fn", None) is not None:
            self._acc_rest_s12(acc_targets, grads, first)       # S12: nothing on the copy unit
        elif first and acc_targets:
            torch._foreach_copy_(acc_targets, grads)
        elif acc_targets:
            torch._foreach_add_(acc_targets, grads)
        for r in self._rows:
            g = r["p"].grad
            if g is None:
                g = torch.zeros_like(r["p"])
            if first:
                if r["acc"] is None:
                    r["acc"] = torch.empty(r["p"].shape, dtype=self.acc_dtype, device=g.device)
                r["acc"].copy_(g)
            else:
                r["acc"].add_(g)
        for group in self.param_groups:
            for p in group["params"]:
                p.grad = None
        self._acc_count += 1

    def enable_fold(self, fn) -> None:
        """S2: from now on accumulate() folds the Muon slab's gradients by fn(bases, groups, first)
        (lean_fold_slab, compiled or not): one base per contiguous run of real elements (a contiguous view of Gm)
        with that run's parameters in slab order. The other targets (the scalar stacks, the leftover matrices) keep
        the eager multi-tensor copy and add, the row-sharded tables their own adds."""
        if self.plan is None:
            raise ValueError("R2_ACC_FOLD: this optimizer has no Muon slab to fold into")
        Gflat = self.Gm.view(-1)
        self._fold_bases = [Gflat[run["start"]:run["end"]] for run in self._runs]
        self._fold_params = [list(run["params"]) for run in self._runs]
        slab = {id(p) for run in self._runs for p in run["params"]}
        rest = [(p, t) for p, t in zip(self._acc_params, self._acc_targets) if id(p) not in slab]
        self._rest_params = [p for p, _t in rest]
        self._rest_targets = [t for _p, t in rest]
        self._fold = fn

    def _fold_rest(self, first):
        """S2: with a fold set, the slab's runs go through it here and the remaining (parameters, targets) are
        returned for the eager path; without one, every target is returned (the accumulation as before)."""
        if self._fold is None:
            return self._acc_params, self._acc_targets
        self._fold(self._fold_bases, [[p.grad if p.grad is not None else torch.zeros_like(p) for p in ps]
                                      for ps in self._fold_params], first)
        if first and getattr(self, "_fold_in", None) is not None:
            self._fold_in_after_first()       # switch 9h: the later micro-steps add into the slab
        return self._rest_params, self._rest_targets

    def enable_fold_in(self, modules) -> dict:
        """Switch 9h, after enable_fold (S2): every module of `modules` (fold_in_modules) whose weight lies in the Muon
        slab's runs gets two attributes: r2_fold_in, the weight's view of Gm (the elements accumulate() writes for
        it), and r2_fold_flag, one 0-D bool tensor on the slab's device shared by all of them, True until a step's
        first micro-step has been folded and again from the end of step(). GradFoldIn writes those weights'
        gradients into their views in the backward; S2's fold keeps the runs' other parameters, cut into their
        contiguous sub-runs (lean_fold_none when none is left). A weight on a leftover route is left alone."""
        if self._fold is None or self.plan is None:
            raise ValueError("R2_GRAD_FOLD_IN (switch 9h) needs S2's fold on a Muon slab (enable_fold first)")
        if getattr(self, "_fold_in", None) is not None:
            raise ValueError("switch 9h: enable_fold_in was already called")
        Gflat = self.Gm.view(-1)
        where = {}
        for run in self._runs:
            off = run["start"]
            for p, ne in zip(run["params"], run["sizes"]):
                where[id(p)] = (off, ne)
                off += ne
        dev = self.Gm.device
        flag = torch.ones((), dtype=torch.bool, device=dev)
        covered = {}
        for lin in modules:
            p = lin.weight
            if id(p) in where and id(p) not in covered:
                off, ne = where[id(p)]
                lin.r2_fold_in = Gflat[off:off + ne].view(p.shape)
                lin.r2_fold_flag = flag
                covered[id(p)] = p
        segs = []
        for run in self._runs:
            off, cur = run["start"], None
            for p, ne in zip(run["params"], run["sizes"]):
                if id(p) in covered:
                    cur = None
                else:
                    if cur is None:
                        cur = [off, off, []]
                        segs.append(cur)
                    cur[1] = off + ne
                    cur[2].append(p)
                off += ne
        self._fold_bases = [Gflat[a:b] for a, b, _ps in segs]
        self._fold_params = [ps for _a, _b, ps in segs]
        if not segs:
            self._fold = lean_fold_none
        self._fold_in = {"flag": flag, "true": torch.ones((), dtype=torch.bool, device=dev),
                         "false": torch.zeros((), dtype=torch.bool, device=dev), "params": list(covered.values())}
        return {"listed": len(modules), "covered": len(covered),
                "covered_numel": sum(p.numel() for p in covered.values()), "fold_runs": len(segs),
                "fold_numel": sum(b - a for a, b, _ps in segs),
                "slab_numel": sum(run["end"] - run["start"] for run in self._runs), "flag": "bool"}

    def _fold_in_after_first(self) -> None:
        """Switch 9h, after a step's first micro-step: no weight with a slab view may hold a .grad (a forward that
        bypassed fold_in_weight; S2's fold would never read it), then the flag to False."""
        stray = sum(1 for p in self._fold_in["params"] if p.grad is not None)
        if stray:
            raise RuntimeError(f"switch 9h: {stray} weight(s) with a slab view got a .grad: their forward bypassed "
                               "fold_in_weight")
        if getattr(self, "_rest_fn", None) is None:
            self._fold_in["flag"].copy_(self._fold_in["false"])     # under S12, lean_acc_rest sets it

    def enable_acc_nowrite(self, fn) -> dict:
        """S12, after enable_fold (S2): from now on accumulate() hands the targets S2's fold leaves (the scalar stacks,
        the leftover matrices) and their gradients to fn(targets, grads, first, flag, value) (lean_acc_rest, compiled
        or not) in place of the eager multi-tensor copy and add, and at a step's first micro-step switch 9h's flag, if
        set up, goes to False inside fn. The row-sharded tables keep their own adds."""
        if self._fold is None:
            raise ValueError("R2_ACC_NOWRITE (S12) needs S2's fold on a Muon slab (enable_fold first)")
        if getattr(self, "_rest_fn", None) is not None:
            raise ValueError("S12: enable_acc_nowrite was already called")
        self._rest_fn = fn
        self._s12_n = {"copies": 0, "adds": 0, "flags": 0}
        return {"targets": len(self._rest_targets), "numel": sum(t.numel() for t in self._rest_targets),
                "dtypes": ",".join(sorted({str(t.dtype).replace("torch.", "") for t in self._rest_targets}))}

    def _acc_rest_s12(self, targets, grads, first) -> None:
        """S12: one micro-step's eager targets by the function enable_acc_nowrite set (9h's flag with the first)."""
        fi = getattr(self, "_fold_in", None)
        flag, value = (fi["flag"], fi["false"]) if first and fi is not None else (None, None)
        if targets or flag is not None:
            self._rest_fn(targets, grads, first, flag, value)
        self._s12_n["copies" if first else "adds"] += 1
        self._s12_n["flags"] += flag is not None

    def enable_compiled_math(self, muon_fn, adamw_fn) -> None:
        """S4: from now on the Muon and AdamW updates run through muon_fn (muon_math_body) and adamw_fn
        (adamw_math_body), compiled or not, wherever the finiteness gate is off (ok is None)."""
        self._math = {"muon": muon_fn, "adamw": adamw_fn}

    def enable_nsk(self, fn) -> dict:
        """Switch 65 (lane NSK): from now on step() updates switch 55's two Muon expert units of this rank (a tall stack
        and its transposed twin: w_fc and w_proj) by one call of fn (muon_math_pair_nsk, compiled or not) in place of
        their two muon_math_body calls. Refused unless S4's math is on, the finiteness gate is off, and the units are
        exactly that pair at the kit's five Polar Express steps in bf16 with this file's coefficients."""
        if self._math is None:
            raise ValueError("R2_NSK (switch 65) needs S4's update math on the lean optimizer (R2_OPT_COMPILED=1)")
        if self.finite_gate:
            raise ValueError("R2_NSK (switch 65) runs without the finiteness gate (its kernel has no gate operand)")
        units = [L for L in self._local if L["group"]["kind"] == "muon"]
        tall = [L for L in units if L["shape"][0] > L["shape"][1]]
        wide = [L for L in units if L["shape"][0] < L["shape"][1]]
        if not (len(units) == 2 and len(tall) == 1 and len(wide) == 1
                and tuple(wide[0]["shape"]) == tuple(tall[0]["shape"])[::-1]
                and sum(tall[0]["counts"]) == sum(wide[0]["counts"])):
            raise ValueError("R2_NSK (switch 65): switch 55's Muon units must be one tall stack and its transposed "
                             f"twin of equal count (got {[(tuple(L['shape']), sum(L['counts'])) for L in units]})")
        if any(L["group"]["ns_steps"] != 5 for L in units) or self.ns_dtype_fn() != torch.bfloat16:
            raise ValueError("R2_NSK (switch 65) runs the kit's five Polar Express steps in bf16")
        if tuple(tuple(float(v) for v in c) for c in self.polar_coeffs[:5]) != tuple(NSK_MODULE.NSK_COEFFS):
            raise ValueError("R2_NSK (switch 65): the optimizer's Polar Express coefficients are not the kernel's")
        r, c = tuple(tall[0]["shape"])
        if NSK_READY and not NSK_MODULE.shapes_apply(r, c):
            raise ValueError(f"R2_NSK (switch 65): the kernel does not take the experts' [{r}, {c}] pair (its shape "
                             f"rule and SBUF plan: kernels/nki_nsk.py shapes_apply)")
        self._nsk = {"fn": fn, "tall": tall[0], "wide": wide[0]}
        self._nsk_ids = {id(tall[0]), id(wide[0])}
        a, b = tall[0], wide[0]
        return {"tall": "x".join(str(v) for v in (sum(a["counts"]), *a["shape"])),
                "wide": "x".join(str(v) for v in (sum(b["counts"]), *b["shape"])), "calls_a_step": 1}

    def _nsk_pair_step(self) -> None:
        """Switch 65: the two expert units through enable_nsk's function: each unit's prologue as step 5b and
        _muon_math run it (the accumulation times 1 / world in place, the FP32 state made at the first step, the 0-D
        schedule fills, the device schedule tensor by _sched), one call for both, then each unit's replicas (step
        5b's multi-tensor copy)."""
        args = []
        for L in (self._nsk["tall"], self._nsk["wide"]):
            g = L["acc"]                     # the step's FP32 accumulation
            if L["scale"] != 1.0:
                g.mul_(L["scale"])
            group, st, shape = L["group"], L["st"], L["shape"]
            k = g.shape[0]
            if "momentum_buffer" not in st:
                st["momentum_buffer"] = torch.zeros(k, *shape, dtype=torch.float32, device=g.device)
                st_shape = (k, shape[-2], 1) if shape[-2] >= shape[-1] else (k, 1, shape[-1])
                st["second_momentum_buffer"] = torch.zeros(st_shape, dtype=torch.float32, device=g.device)
            momentum_t = group["_momentum_t"]
            one_minus_momentum_t = group["_one_minus_momentum_t"]
            one_minus_beta2_t = group["_one_minus_beta2_t"]
            lr_t, wd_t = group["_lr_t"], group["_wd_t"]
            momentum_t.fill_(group["momentum"])
            one_minus_momentum_t.fill_(1 - group["momentum"])
            one_minus_beta2_t.fill_(1 - group["beta2"])
            lr_t.fill_(group["lr"] * max(1.0, shape[-2] / shape[-1]) ** 0.5)
            wd_t.fill_(group["weight_decay"])
            sched = self._sched(("muon", id(st)), (momentum_t, one_minus_momentum_t, one_minus_beta2_t, lr_t, wd_t),
                                g.device)
            args += [g, L["master"], st["momentum_buffer"], st["second_momentum_buffer"], sched]
        self._nsk["fn"](*args, tuple(self._nsk["tall"]["shape"]), tuple(self._nsk["wide"]["shape"]))
        for L in (self._nsk["tall"], self._nsk["wide"]):
            torch._foreach_copy_([p.data for p in L["params"]], list(L["master"].split(L["counts"])))
        NSK_COUNTS["steps"] += 1

    def enable_stage(self) -> None:
        """S6: from now on stage_schedule(), called at each step's start, writes every schedule tensor the update math
        will read, and _sched() skips its own copy for a staged key whose values are equal. The attributes exist only
        from this call on (an optimizer without S6 has none of them)."""
        self._staged = {}
        self._stage_dev = None
        self._stage_n = {"steps": 0, "keys": 0, "hits": 0, "misses": 0}

    @torch.no_grad()
    def stage_schedule(self, non_blocking: bool = False) -> None:
        """S6: the step's schedule vectors, in step()'s order and with _adamw_math's and _muon_math's own expressions
        (a state's bias corrections at its next step), for every state whose device tensor exists (from step 1 on),
        written by one host-to-device copy into one staging tensor and one device copy into the states' tensors."""
        f32 = torch.float32
        keys, vecs = [], []

        def adamw(st, group):
            if st and ("adamw", id(st)) in self._sched_bufs:
                beta1, beta2 = group["betas"]
                n = st["step"] + 1
                vecs.append(torch.stack([torch.tensor(float(group["lr"]), dtype=f32),
                                         torch.tensor(float(group["weight_decay"]), dtype=f32),
                                         group["_one_minus_beta1_t"].reshape(()),
                                         group["_one_minus_beta2_t"].reshape(()), group["_eps_t"].reshape(()),
                                         torch.tensor(1 - beta1 ** n, dtype=f32),
                                         torch.tensor(1 - beta2 ** n, dtype=f32)]))
                keys.append(("adamw", id(st)))

        def muon(group, st, shape):
            if ("muon", id(st)) in self._sched_bufs:
                vecs.append(torch.stack([torch.tensor(float(group["momentum"]), dtype=f32),
                                         torch.tensor(float(1 - group["momentum"]), dtype=f32),
                                         torch.tensor(float(1 - group["beta2"]), dtype=f32),
                                         torch.tensor(float(group["lr"] * max(1.0, shape[-2] / shape[-1]) ** 0.5),
                                                      dtype=f32),
                                         torch.tensor(float(group["weight_decay"]), dtype=f32)]))
                keys.append(("muon", id(st)))

        for S in self._small:
            adamw(S["st"], S["group"])
        for r in self._rows:
            adamw(r["st"], r["group"])
        if self.plan is not None:
            for seg in self._own:
                muon(self._mg[seg["g"]], seg["st"], seg["shape"])
            for L in self._left:
                if L["own"] if L["kind"] == "allreduce" else L["owns"]:
                    muon(self._mg[L["g"]], L["st"], L["shape"])
        for L in self._local:
            # Switch 55: each rank's expert units, staged as every unit is.
            if L["group"]["kind"] == "muon":
                muon(L["group"], L["st"], L["shape"])
            else:
                adamw(L["st"], L["group"])
        self._staged = dict(zip(keys, vecs))
        if keys:
            cpu = torch.cat(vecs)
            dev = self._stage_dev
            if dev is None or dev.numel() != cpu.numel():
                dev = self._stage_dev = torch.empty(cpu.shape, dtype=f32, device=self._sched_bufs[keys[0]].device)
            dev.copy_(cpu, non_blocking=non_blocking)
            torch._foreach_copy_([self._sched_bufs[k] for k in keys], list(dev.split([v.numel() for v in vecs])))
        self._stage_n["steps"] += 1
        self._stage_n["keys"] = len(keys)

    def _sched(self, key, vals, device):
        """S4: the step's schedule values (vals: the 0-D FP32 tensors the eager math reads, already filled) in one
        persistent device tensor per state, written by one host-to-device copy: the same FP32 values."""
        cpu = torch.stack([v.reshape(()) for v in vals])
        buf = self._sched_bufs.get(key)
        if buf is None:
            buf = torch.empty(cpu.shape, dtype=cpu.dtype, device=device)
            self._sched_bufs[key] = buf
        staged = getattr(self, "_staged", None)
        if staged is not None:
            # S6: the staged values are already in buf when they equal this call's; else the copy, as without S6.
            want = staged.get(key)
            if want is not None and torch.equal(want, cpu):
                self._stage_n["hits"] += 1
                return buf
            self._stage_n["misses"] += 1
        buf.copy_(cpu)
        return buf

    def _pack_from_autograd(self):
        """Kit-compatible path: read the .grad tensors autograd accumulated and stage them for the collectives."""
        if self.plan is not None:
            Gflat = self.Gm.view(-1)
            for run in self._runs:
                grads = [(p.grad if p.grad is not None else torch.zeros_like(p)).reshape(-1) for p in run["params"]]
                torch.cat(grads, out=Gflat[run["start"]:run["end"]])
        for L in self._left:
            if L["kind"] == "allreduce":
                torch.stack([(p.grad if p.grad is not None else torch.zeros_like(p)) for p in L["params"]], out=L["Gl"])
            elif L["slots"]:
                torch._foreach_copy_([L["Gl"][o] for o, _p in L["slots"]],
                                     [(p.grad if p.grad is not None else torch.zeros_like(p)) for _o, p in L["slots"]])
        for S in self._small:
            torch.cat([(p.grad if p.grad is not None else torch.zeros_like(p)).reshape(-1) for p in S["params"]],
                      out=S["pay"][:S["n"]])
        for L in self._local:
            # Switch 55: the experts' gradients as autograd holds them (accumulate() was not called).
            torch.cat([(p.grad if p.grad is not None else torch.zeros_like(p)).to(L["acc"].dtype)
                       for p in L["params"]], out=L["acc"])

    # ---------------------------------------------------------------------------------------- update math

    def _adamw_math(self, p, grad, st, group, ok):
        """kit train.py:505-532 (_adamw_update), unchanged; `ok` (0-D, 1.0 or 0.0) gates every in-place write."""
        beta1, beta2 = group["betas"]
        lr_t, wd_t = group["_lr_t"], group["_wd_t"]
        one_minus_beta1_t, one_minus_beta2_t = group["_one_minus_beta1_t"], group["_one_minus_beta2_t"]
        eps_t = group["_eps_t"]
        lr_t.fill_(group["lr"])
        wd_t.fill_(group["weight_decay"])
        if not st:
            st["step"] = 0
            st["exp_avg"] = torch.zeros_like(p)
            st["exp_avg_sq"] = torch.zeros_like(p)
            st["bias1_t"] = torch.tensor(0.0, dtype=torch.float32)
            st["bias2_t"] = torch.tensor(0.0, dtype=torch.float32)
            self._adamw_states.append(st)
        st["step"] += 1
        exp_avg, exp_avg_sq = st["exp_avg"], st["exp_avg_sq"]
        bias1_t, bias2_t = st["bias1_t"], st["bias2_t"]
        bias1_t.fill_(1 - beta1 ** st["step"])
        bias2_t.fill_(1 - beta2 ** st["step"])
        lr, omb1, omb2 = lr_t, one_minus_beta1_t, one_minus_beta2_t
        if ok is not None:
            lr, omb1, omb2 = lr * ok, omb1 * ok, omb2 * ok
        if self._math is not None and ok is None:
            # S4: the four lines below as one function (adamw_math_body), its schedule in one device tensor.
            self._math["adamw"](p, grad, exp_avg, exp_avg_sq,
                                self._sched(("adamw", id(st)), (lr_t, wd_t, one_minus_beta1_t, one_minus_beta2_t,
                                                                 eps_t, bias1_t, bias2_t), p.device))
            return
        p.mul_(1 - lr * wd_t)
        exp_avg.lerp_(grad, omb1)
        exp_avg_sq.lerp_(grad.square(), omb2)
        update = exp_avg / bias1_t / ((exp_avg_sq / bias2_t).sqrt() + eps_t)
        p.sub_(lr * update)

    def _muon_math(self, group, g, w, st, shape, ok):
        """kit train.py:749-798 on a stack g, w of [k, r, c]. g is consumed, w (the FP32 master) is updated in place."""
        if g.dtype != torch.float32:
            g = g.float()
        k = g.shape[0]
        if "momentum_buffer" not in st:
            st["momentum_buffer"] = torch.zeros(k, *shape, dtype=torch.float32, device=g.device)
            st_shape = (k, shape[-2], 1) if shape[-2] >= shape[-1] else (k, 1, shape[-1])
            st["second_momentum_buffer"] = torch.zeros(st_shape, dtype=torch.float32, device=g.device)
        momentum_t = group["_momentum_t"]
        one_minus_momentum_t = group["_one_minus_momentum_t"]
        one_minus_beta2_t = group["_one_minus_beta2_t"]
        lr_t, wd_t = group["_lr_t"], group["_wd_t"]
        momentum_t.fill_(group["momentum"])
        one_minus_momentum_t.fill_(1 - group["momentum"])
        one_minus_beta2_t.fill_(1 - group["beta2"])
        lr_t.fill_(group["lr"] * max(1.0, shape[-2] / shape[-1]) ** 0.5)
        wd_t.fill_(group["weight_decay"])
        lr, omm, omb2 = lr_t, one_minus_momentum_t, one_minus_beta2_t
        if ok is not None:
            lr, omm, omb2 = lr * ok, omm * ok, omb2 * ok
        momentum, second = st["momentum_buffer"], st["second_momentum_buffer"]
        if self._math is not None and ok is None:
            # S4: the rest of this function as one function (muon_math_body), its schedule in one device tensor.
            self._math["muon"](g, w, momentum, second,
                               self._sched(("muon", id(st)), (momentum_t, one_minus_momentum_t, one_minus_beta2_t,
                                                              lr_t, wd_t), g.device),
                               tuple(tuple(c) for c in self.polar_coeffs[:group["ns_steps"]]),
                               self.ns_dtype_fn() == torch.bfloat16, tuple(shape))
            return
        momentum.lerp_(g, omm)
        g = g.lerp_(momentum, momentum_t)
        x = g.bfloat16() if self.ns_dtype_fn() == torch.bfloat16 else g
        if R2_MUONEQ:
            # MQ1 (lane BATCH): MuonEq, as muon_math_body's (S4 off).
            x = x * (x.float().norm(dim=(-2, -1), keepdim=True) / (x.size(-2) ** 0.5)
                     / x.float().norm(dim=-1, keepdim=True).clamp_min(1e-6)).to(x.dtype)
        x = x / (x.norm(dim=(-2, -1), keepdim=True) * 1.01 + 1e-6)
        squeezed = x.dim() == 3 and x.size(0) == 1      # kit train.py:767-773: a one-matrix stack uses 2-D matmul
        if squeezed:
            x = x.squeeze(0)
        if x.shape[-2] > x.shape[-1]:
            for a, b, c in self.polar_coeffs[:group["ns_steps"]]:
                xtx = x.mT @ x
                x = a * x + x @ (b * xtx + c * (xtx @ xtx))
        else:
            for a, b, c in self.polar_coeffs[:group["ns_steps"]]:
                xxt = x @ x.mT
                x = a * x + (b * xxt + c * (xxt @ xxt)) @ x
        if squeezed:
            x = x.unsqueeze(0)
        g = x
        if R2_MUONEQ:
            # MQ1 (lane BATCH): Muon+, as muon_math_body's (S4 off).
            g = g * (min(g.size(-2), g.size(-1)) ** 0.5
                     / g.float().norm(dim=(-2, -1), keepdim=True).clamp_min(1e-6)).to(g.dtype)
        red_dim = -1 if shape[-2] >= shape[-1] else -2
        v_mean = g.float().square().mean(dim=red_dim, keepdim=True)
        red_dim_size = g.size(red_dim)
        v_norm = (v_mean.sum(dim=(-2, -1), keepdim=True) * red_dim_size).sqrt()
        second.lerp_(v_mean, omb2)
        step_size = second.clamp_min(1e-10).rsqrt()
        scaled = (v_mean * red_dim_size) * step_size.square()
        v_norm_new = scaled.sum(dim=(-2, -1), keepdim=True).sqrt()
        g = g * (step_size * (v_norm / v_norm_new.clamp_min(1e-10))).to(g.dtype)
        mask = (g * w) >= 0
        w.sub_(lr * g + lr * wd_t * w * mask)

    # ------------------------------------------------------------------- lane OVERLAP (R2_OPT_OVERLAP=1)

    def enable_overlap(self, fn) -> dict:
        """Lane OVERLAP: from now on step() runs _step_overlap, whose collectives and expert updates are one call of
        fn (opt_overlap_rs, compiled or not). Refused unless S4's math is on, the finiteness gate off, the slab one
        collective with no leftover route, switch 55's local units all Muon and switch 65 off."""
        global OPT_OVL_FUNCOL
        units = getattr(self, "_local", [])
        if (self._math is None or self.finite_gate or self.plan is None or self.K != 1 or self._left
                or getattr(self, "_nsk", None) is not None or not units
                or any(L["group"]["kind"] != "muon" for L in units)):
            raise ValueError("R2_OPT_OVERLAP (lane OVERLAP) needs S4's update math, no finiteness gate, one slab "
                             "collective with no leftover route, switch 55's Muon expert units and switch 65 off")
        if OPT_OVL_FUNCOL is None:
            import torch.distributed._functional_collectives as funcol
            OPT_OVL_FUNCOL = funcol
        self._ovl = fn
        self._ovl_n = {"steps": 0, "fallback": 0}
        return {"rows": len(self._rows), "slab_op": "sum" if self.slab_sum else "avg", "stacks": len(self._small),
                "units": "+".join("x".join(str(v) for v in (sum(L["counts"]), *L["shape"])) for L in units)}

    def _ovl_unit(self, group, g, w, st, shape) -> tuple:
        """Lane OVERLAP: _muon_math's prologue for one unit, the gate off and S4's math on (the FP32 cast, the state
        made at the first step, the 0-D schedule fills and their device tensor), as _muon_math runs it; returns the
        unit's muon_math_body arguments."""
        if g.dtype != torch.float32:
            g = g.float()
        k = g.shape[0]
        if "momentum_buffer" not in st:
            st["momentum_buffer"] = torch.zeros(k, *shape, dtype=torch.float32, device=g.device)
            st_shape = (k, shape[-2], 1) if shape[-2] >= shape[-1] else (k, 1, shape[-1])
            st["second_momentum_buffer"] = torch.zeros(st_shape, dtype=torch.float32, device=g.device)
        momentum_t = group["_momentum_t"]
        one_minus_momentum_t = group["_one_minus_momentum_t"]
        one_minus_beta2_t = group["_one_minus_beta2_t"]
        lr_t, wd_t = group["_lr_t"], group["_wd_t"]
        momentum_t.fill_(group["momentum"])
        one_minus_momentum_t.fill_(1 - group["momentum"])
        one_minus_beta2_t.fill_(1 - group["beta2"])
        lr_t.fill_(group["lr"] * max(1.0, shape[-2] / shape[-1]) ** 0.5)
        wd_t.fill_(group["weight_decay"])
        sched = self._sched(("muon", id(st)), (momentum_t, one_minus_momentum_t, one_minus_beta2_t, lr_t, wd_t),
                            g.device)
        return (g, w, st["momentum_buffer"], st["second_momentum_buffer"], sched,
                tuple(tuple(c) for c in self.polar_coeffs[:group["ns_steps"]]),
                self.ns_dtype_fn() == torch.bfloat16, tuple(shape))

    @torch.no_grad()
    def _step_overlap(self):
        """Lane OVERLAP: step() with its sections 1 to 3 (the gate off) and section 5b's updates as one call of the
        overlap function: each expert unit's accumulation times 1 / world and its prologue first, as 5b runs them; then
        step()'s section 5 as written (the gate off), 5b's replica copies and section 6."""
        f32 = torch.float32
        ok = None
        units = []
        for L in self._local:
            g = L["acc"]
            if L["scale"] != 1.0:
                g.mul_(L["scale"])
            units.append(self._ovl_unit(L["group"], g, L["master"], L["st"], L["shape"]))
        ref = None
        if R2_OPT_OVERLAP_CHECK and self._ovl_n["steps"] == 1:      # the second overlap step: its graph is warm
            ref = self._ovl_ref()
        self._ovl([r["grad_slice"] for r in self._rows], [r["acc"] for r in self._rows],
                  self.mine_g.view(self._coll_out), self.Gm.view(self._coll_in), "sum" if self.slab_sum else "avg",
                  [S["pay"] for S in self._small], units)
        if ref is not None:
            self._ovl_check(*ref)
        row_grads = [r["grad_slice"] for r in self._rows]
        g_main = self.mine_g.float().div_(self.world) if self.slab_sum else self.mine_g
        small_grads = [S["pay"][:S["n"]] for S in self._small]
        self._last_ok = ok
        # ---- 5. updates on the FP32 masters, then the gathers (step()'s lines, the gate off)
        for S, sg in zip(self._small, small_grads):
            self._adamw_math(S["master"], sg, S["st"], S["group"], ok)
            if not self.param_views:
                torch.split_with_sizes_copy(S["master"], S["sizes"], out=[p.data.view(-1) for p in S["params"]])
        for r, rg in zip(self._rows, row_grads):
            if rg.dtype != f32:
                rg = rg.float()
            self._adamw_math(r["master"], rg, r["st"], r["group"], ok)
            if r["out"] is None:
                dist.all_gather_into_tensor(r["p"].data, r["master"])
            else:
                r["out"].copy_(r["master"])
                dist.all_gather_into_tensor(r["p"].data, r["out"])
        for seg in self._own:
            g = g_main[0, seg["a"]:seg["b"]].view(seg["k"], *seg["shape"])
            w = self.Mm[0, seg["a"]:seg["b"]].view(seg["k"], *seg["shape"])
            self._muon_math(self._mg[seg["g"]], g, w, seg["st"], seg["shape"], ok)
        src = self.Mm
        if self.mine_out is not None:
            self.mine_out.copy_(self.Mm)             # the one FP32 -> bf16 cast of this rank's chunk
            src = self.mine_out
        dist.all_gather_into_tensor(self.Wm.view(self._coll_in), src.view(self._coll_out))
        if not self.param_views:
            Wflat = self.Wm.view(-1)
            for run in self._runs:
                if self.foreach_copy:
                    torch._foreach_copy_([p.data.view(-1) for p in run["params"]],
                                         list(Wflat[run["start"]:run["end"]].split(run["sizes"])))
                else:
                    torch.split_with_sizes_copy(Wflat[run["start"]:run["end"]], run["sizes"],
                                                out=[p.data.view(-1) for p in run["params"]])
        # ---- 5b. the experts' replicas (their update ran in the overlap call)
        for L in self._local:
            torch._foreach_copy_([p.data for p in L["params"]], list(L["master"].split(L["counts"])))
        # ---- 6. gradients are consumed
        for group in self.param_groups:
            for p in group["params"]:
                p.grad = None
        self._acc_count = 0
        if getattr(self, "_fold_in", None) is not None:
            self._fold_in["flag"].copy_(self._fold_in["true"])     # switch 9h: the next step's first micro-step
        n = self._ovl_n["steps"] = self._ovl_n["steps"] + 1
        if n in (1, 5) or n % 1000 == 0:
            print0(f"opt_overlap: steps={n} fallback={self._ovl_n['fallback']} units={len(units)} "
                   f"rows={len(row_grads)} stacks={len(small_grads)}")

    @torch.no_grad()
    def _ovl_ref(self) -> tuple:
        """Lane OVERLAP (R2_OPT_OVERLAP_CHECK=1, the smoke only): step()'s own eager collectives on this step's live
        inputs, just before the overlap call, into fresh outputs: each row table's reduce-scatter (AVG), the slab's
        (step()'s op) and each scalar stack's all-reduce (AVG) on a copy, the stacks being reduced in place. A
        reduce-scatter does not write its input, and nothing writes the rows' acc or Gm between here and the call."""
        AVG, SUM = dist.ReduceOp.AVG, dist.ReduceOp.SUM
        rows = []
        for r in self._rows:
            e = torch.empty_like(r["grad_slice"])
            dist.reduce_scatter_tensor(e, r["acc"], op=AVG)
            rows.append(e)
        es = torch.empty_like(self.mine_g)
        op = SUM if self.slab_sum else AVG
        dist.reduce_scatter_tensor(es.view(self._coll_out), self.Gm.view(self._coll_in), op=op)
        pays = []
        for S in self._small:
            p = S["pay"].clone()
            dist.all_reduce(p, op=AVG)
            pays.append(p)
        return rows, es, pays

    @torch.no_grad()
    def _ovl_check(self, rows, es, pays) -> None:
        """Lane OVERLAP (R2_OPT_OVERLAP_CHECK=1, the smoke only): _ovl_ref's results against what the overlap call
        wrote: each pair's unequal elements (a value compare; NaN counts as unequal) summed over the ranks; one line
        on rank 0 with rank 0's largest difference and the slab's norm ratio (a missing or doubled 1 / world reads 64
        or 1 / 64)."""
        SUM = dist.ReduceOp.SUM
        pairs = [("rows", e, r["grad_slice"]) for r, e in zip(self._rows, rows)]
        pairs.append(("slab", es, self.mine_g))
        pairs += [("stacks", p, S["pay"]) for S, p in zip(self._small, pays)]
        cnt = torch.stack([(e.float() != g.float()).float().sum() for _k, e, g in pairs])
        dmax = torch.stack([(e.float() - g.float()).abs().max() for _k, e, g in pairs])
        ratio = self.mine_g.float().norm() / es.float().norm().clamp_min(1e-30)
        dist.all_reduce(cnt, op=SUM)
        cnt, dmax, ratio = cnt.tolist(), dmax.tolist(), float(ratio.item())
        eq = {"rows": [0, 0], "slab": [0, 0], "stacks": [0, 0]}
        for (k, _e, _g), c in zip(pairs, cnt):
            eq[k][0] += int(c == 0)
            eq[k][1] += 1
        print0(f"opt_overlap_check: step={self._ovl_n['steps'] + 1} "
               + " ".join(f"{k}_equal={a}/{b}" for k, (a, b) in eq.items())
               + f" mismatched_elements={int(sum(cnt))} max_abs_rank0={max(dmax):.3e} slab_norm_ratio={ratio:.6f}")

    # ------------------------------------------------------------------------------------------------ step

    @torch.no_grad()
    def step(self):
        AVG, SUM = dist.ReduceOp.AVG, dist.ReduceOp.SUM
        if getattr(self, "_ovl", None) is not None:        # lane OVERLAP (R2_OPT_OVERLAP=1)
            if self._acc_count > 0 and all(r.get("cols") is None for r in self._rows):
                return self._step_overlap()
            self._ovl_n["fallback"] += 1
        f32 = torch.float32
        use_acc = self._acc_count > 0
        if not use_acc:
            self._pack_from_autograd()
        gate = self.finite_gate
        sq = None                                        # this rank's sum of squares over its reduced shards
        # ---- 1. reduce: row-sharded AdamW tensors
        row_grads = []
        for r in self._rows:
            if r.get("cols") is not None:
                # Lane STEM8B: a gate table's step gradient as column blocks (no [vocab, F] FP32 block).
                stem_reduce_cols(r["grad_slice"], r["cols"], AVG)
            else:
                if use_acc:
                    src = r["acc"]
                else:
                    src = r["p"].grad if r["p"].grad is not None else torch.zeros_like(r["p"])
                    if src.dtype != self.acc_dtype:
                        src = src.to(self.acc_dtype)
                dist.reduce_scatter_tensor(r["grad_slice"], src, op=AVG)
            row_grads.append(r["grad_slice"])
            if gate:
                s = r["grad_slice"].float().square().sum()
                sq = s if sq is None else sq + s
        # ---- 2. reduce: the main Muon slab (K collectives) and the leftover matrices
        g_main = None
        left_grads = []
        if self.plan is not None:
            slab_op = SUM if self.slab_sum else AVG     # S1: the bf16 slab sums; the mean is taken in FP32 below
            if self.K == 1:
                dist.reduce_scatter_tensor(self.mine_g.view(self._coll_out), self.Gm.view(self._coll_in), op=slab_op)
            else:
                for a, b in self._pieces:
                    # Prototype staging copy. The production form stores the slab piece-major so every piece is
                    # contiguous (and then MLP matrices cannot be views of it: see the report, section 4).
                    dist.reduce_scatter_tensor(self.mine_g[:, a:b], self.Gm[:, a:b].contiguous(), op=slab_op)
            g_main = self.mine_g.float().div_(self.world) if self.slab_sum else self.mine_g
            if gate:
                s = g_main.float().square().sum()
                sq = s if sq is None else sq + s
            for L in self._left:
                if L["kind"] == "allreduce":
                    dist.all_reduce(L["Gl"], op=slab_op)
                    left_grads.append(L["Gl"].float().div_(self.world) if self.slab_sum else L["Gl"])
                else:
                    dist.reduce_scatter_tensor(L["mine"], L["Gl"], op=slab_op)
                    left_grads.append(L["mine"].float().div_(self.world) if self.slab_sum else L["mine"])
                    if gate:
                        s = L["mine"].float().square().sum()
                        sq = s if sq is None else sq + s
        # ---- 3. reduce: the scalar stacks; the gate's slot rides on the first one
        gate_pay = None
        if gate:
            if self._small:
                gate_pay = self._small[0]["pay"]
            else:
                if self._gate_only is None:
                    self._gate_only = torch.zeros(1, dtype=f32)
                gate_pay = self._gate_only
            gate_pay[-1:].copy_((sq if sq is not None else torch.zeros((), dtype=f32)).reshape(1))
        for S in self._small:
            dist.all_reduce(S["pay"], op=AVG)
        if gate and not self._small:
            dist.all_reduce(gate_pay, op=AVG)
        # ---- 4. the gate: identical on every rank, computed on the device, no host round-trip
        ok = None
        small_grads = [S["pay"][:S["n"]] for S in self._small]
        if gate:
            total = gate_pay[-1]                         # mean over ranks of the shard sums
            for sg in small_grads:
                total = total + sg.square().sum()
            for L, lg in zip(self._left, left_grads):
                if L["kind"] == "allreduce":
                    total = total + lg.float().square().sum()
            okb = torch.isfinite(total)                  # 0-D bool
            ok = okb.to(f32)                             # 0-D, 1.0 or 0.0
            zero = torch.zeros((), dtype=f32, device=total.device)
            row_grads = [torch.where(okb, t, zero.to(t.dtype)) for t in row_grads]
            small_grads = [torch.where(okb, t, zero) for t in small_grads]
            left_grads = [torch.where(okb, t, zero.to(t.dtype)) for t in left_grads]
            if g_main is not None:
                g_main = torch.where(okb, g_main, zero.to(g_main.dtype))
        self._last_ok = ok
        # ---- 5. updates on the FP32 masters, then the gathers
        for S, sg in zip(self._small, small_grads):
            self._adamw_math(S["master"], sg, S["st"], S["group"], ok)
            if not self.param_views:
                torch.split_with_sizes_copy(S["master"], S["sizes"], out=[p.data.view(-1) for p in S["params"]])
        for r, rg in zip(self._rows, row_grads):
            if rg.dtype != f32:
                rg = rg.float()
            self._adamw_math(r["master"], rg, r["st"], r["group"], ok)
            if r["out"] is None:
                dist.all_gather_into_tensor(r["p"].data, r["master"])
            else:
                r["out"].copy_(r["master"])
                dist.all_gather_into_tensor(r["p"].data, r["out"])
        if self.plan is not None:
            for seg in self._own:
                g = g_main[0, seg["a"]:seg["b"]].view(seg["k"], *seg["shape"])
                w = self.Mm[0, seg["a"]:seg["b"]].view(seg["k"], *seg["shape"])
                self._muon_math(self._mg[seg["g"]], g, w, seg["st"], seg["shape"], ok)
            src = self.Mm
            if self.mine_out is not None:
                self.mine_out.copy_(self.Mm)             # the one FP32 -> bf16 cast of this rank's chunk
                src = self.mine_out
            if self.K == 1:
                dist.all_gather_into_tensor(self.Wm.view(self._coll_in), src.view(self._coll_out))
            else:
                for a, b in self._pieces:
                    tmp = torch.empty(self.world, b - a, dtype=self.Wm.dtype, device=self.Wm.device)
                    dist.all_gather_into_tensor(tmp, src[:, a:b])
                    self.Wm[:, a:b].copy_(tmp)
            if not self.param_views:
                Wflat = self.Wm.view(-1)
                for run in self._runs:
                    if self.foreach_copy:
                        torch._foreach_copy_([p.data.view(-1) for p in run["params"]],
                                             list(Wflat[run["start"]:run["end"]].split(run["sizes"])))
                    else:
                        torch.split_with_sizes_copy(Wflat[run["start"]:run["end"]], run["sizes"],
                                                    out=[p.data.view(-1) for p in run["params"]])
            for L, lg in zip(self._left, left_grads):
                group = self._mg[L["g"]]
                if L["kind"] == "allreduce":
                    if L["own"]:
                        self._muon_math(group, lg.index_select(0, L["idx"]), L["master"], L["st"], L["shape"], ok)
                    L["Wl"].zero_()
                    if L["own"]:
                        L["Wl"].index_copy_(0, L["idx"], L["master"].to(L["Wl"].dtype))
                    dist.all_reduce(L["Wl"], op=SUM)     # one value plus zeros: exact in any dtype
                    if not self.param_views:
                        n = L["Wl"][0].numel()
                        if self.foreach_copy:
                            torch._foreach_copy_([p.data.view(-1) for p in L["params"]],
                                                 list(L["Wl"].view(-1).split([n] * len(L["params"]))))
                        else:
                            torch.split_with_sizes_copy(L["Wl"].view(-1), [n] * len(L["params"]),
                                                        out=[p.data.view(-1) for p in L["params"]])
                else:
                    if L["owns"]:
                        self._muon_math(group, lg, L["master"], L["st"], L["shape"], ok)
                    src = L["master"]
                    if L["out"] is not None:
                        L["out"].copy_(L["master"])
                        src = L["out"]
                    dist.all_gather_into_tensor(L["Wl"], src)
                    if not self.param_views and L["slots"]:
                        torch._foreach_copy_([p.data for _o, p in L["slots"]], [L["Wl"][o] for o, _p in L["slots"]])
        # ---- 5b. switch 55: each rank's experts, no collective: the update on the FP32 master from the step's
        #      accumulation (times 1 / world), then the replicas
        if getattr(self, "_nsk", None) is not None and ok is None:
            self._nsk_pair_step()            # switch 65: both Muon expert units in one kernel call
        for L in self._local:
            if getattr(self, "_nsk", None) is not None and ok is None and id(L) in self._nsk_ids:
                continue                     # switch 65: updated by _nsk_pair_step above
            g = L["acc"]
            if L["scale"] != 1.0:
                g.mul_(L["scale"])
            if L["group"]["kind"] == "muon":
                self._muon_math(L["group"], g, L["master"], L["st"], L["shape"], ok)
            else:
                self._adamw_math(L["master"], g, L["st"], L["group"], ok)
            torch._foreach_copy_([p.data for p in L["params"]], list(L["master"].split(L["counts"])))
        # ---- 6. gradients are consumed
        for group in self.param_groups:
            for p in group["params"]:
                p.grad = None
        self._acc_count = 0
        if getattr(self, "_fold_in", None) is not None:
            self._fold_in["flag"].copy_(self._fold_in["true"])     # switch 9h: the next step's first micro-step

    # ----------------------------------------------------------------------------- gate bookkeeping (host)

    def last_step_ok(self) -> bool:
        """Host read of the last step's gate (call it after the loop's own synchronize). True without a gate."""
        return True if self._last_ok is None else bool(self._last_ok.item())

    def rollback_counters(self) -> None:
        """After a skipped step: the device state is untouched, so undo the host-side AdamW step counters too.
        The skipped step then never happened as far as the optimizer is concerned."""
        for st in self._adamw_states:
            st["step"] -= 1
        self.skipped_steps += 1

    # ------------------------------------------------------------------------------- checkpoint and rescue

    @torch.no_grad()
    def consolidated_state_dict(self, model, mode="replicas"):
        """The kit's state-dict layout: same keys in the same order, FP32, independent host tensors.

        mode="replicas": the weights as this rank holds them (what the forward computes with). No collective.
        mode="masters":  the FP32 masters of every owning rank, gathered once. Collective: call it on every
                         rank at the same point. Allocates FP32 buffers of the full parameter size."""
        f32 = torch.float32
        named = OrderedDict(model.named_parameters())
        full = {}
        if mode == "masters":
            if self.plan is not None:
                tmp = torch.empty(self.world, self.CU, dtype=f32, device=self.Mm.device)
                dist.all_gather_into_tensor(tmp, self.Mm)
                flat = tmp.view(-1)
                for run in self._runs:
                    o = run["start"]
                    for p, ne in zip(run["params"], run["sizes"]):
                        full[id(p)] = flat[o:o + ne].view(p.shape)
                        o += ne
                for L in self._left:
                    if L["kind"] == "allreduce":
                        t = torch.zeros(len(L["params"]), *L["shape"], dtype=f32, device=self.Mm.device)
                        if L["own"]:
                            t.index_copy_(0, L["idx"], L["master"])
                        dist.all_reduce(t, op=dist.ReduceOp.SUM)
                        for i, p in enumerate(L["params"]):
                            full[id(p)] = t[i]
                    else:
                        t = torch.empty(self.world, *L["shape"], dtype=f32, device=self.Mm.device)
                        dist.all_gather_into_tensor(t, L["master"])
                        for o, p in L["slots"]:
                            full[id(p)] = t[o]
            for r in self._rows:
                t = torch.empty(r["p"].shape, dtype=f32, device=r["p"].device)
                dist.all_gather_into_tensor(t, r["master"])
                full[id(r["p"])] = t
            for S in self._small:
                o = 0
                for p, s in zip(S["params"], S["sizes"]):
                    full[id(p)] = S["master"][o:o + s].view(p.shape)
                    o += s
        elif mode != "replicas":
            raise ValueError(mode)
        out = OrderedDict()
        for k, v in model.state_dict().items():
            p = named.get(k)
            src = full.get(id(p), v) if p is not None else v
            # Lane STEM8B: on the fp8 gate route each tensor goes to the host as it is and widens there (no FP32 copy
            # of a bf16 gate table on the device); the same FP32 values.
            out[k] = (src.detach().to("cpu").to(f32) if STEM8_LEAN else src.detach().to("cpu", f32)).clone()
        return out

    @torch.no_grad()
    def snapshot_refresh(self) -> None:
        """Device-side copy of the replicated weights (a handful of copies with views on, one multi-tensor copy
        without). No host transfer and no synchronisation: the host reads it back only in snapshot_state_dict."""
        if self._snap is None:
            self._snap = [torch.empty_like(t) for t in self._replica_tensors]
        torch._foreach_copy_(self._snap, self._replica_tensors)

    @torch.no_grad()
    def snapshot_state_dict(self, model):
        """State dict (kit layout, FP32, host) of the last snapshot. The only host transfer of the rescue path."""
        if self._snap is None:
            raise RuntimeError("no snapshot was taken")
        named = OrderedDict(model.named_parameters())
        out = OrderedDict()
        for k, v in model.state_dict().items():
            p = named.get(k)
            if p is not None and id(p) in self._replica_map:
                ti, off = self._replica_map[id(p)]
                src = self._snap[ti].reshape(-1)[off:off + p.numel()].view(p.shape)
            else:
                src = v
            out[k] = src.detach().to("cpu", torch.float32).clone()
        return out

    def assert_views_intact(self) -> None:
        """With param_views: every parameter must still alias its slab (a later model.to() would silently undo it)."""
        if not self.param_views:
            return
        for p in self._acc_params:
            ti, off = self._replica_map[id(p)]
            base = self._replica_tensors[ti]
            if p.data.untyped_storage().data_ptr() != base.untyped_storage().data_ptr():
                raise RuntimeError("a parameter no longer aliases its slab")
            if p.data.storage_offset() != base.storage_offset() + off:
                raise RuntimeError("a parameter moved inside its slab")

    def describe(self) -> dict:
        """Layout summary for logs and tests."""
        d = dict(world=self.world, rank=self.rank, K=self.K, param_views=self.param_views,
                 replica_dtype=str(self.replica_dtype), acc_dtype=str(self.acc_dtype), finite_gate=self.finite_gate,
                 foreach_copy=self.foreach_copy,
                 fp32_replicas=len(self._fp32_ids))
        if self.plan is not None:
            p = self.plan
            d.update(U=p["U"], c=p["c"], n_units=len(p["units"]), n_left=len(p["left"]), route=p["route"],
                     rounds=p["rounds"], load_max=max(p["load"]), load_min=min(p["load"]),
                     load_mean=sum(p["load"]) / len(p["load"]), own_segments=[(s["g"], s["k"]) for s in self._own])
        return d


class LeanDistMuonAdamWDeferred(LeanDistMuonAdamW):
    """Switches 10 and 11 together: LeanDistMuonAdamW whose `deferred` parameters (row-sharded AdamW tensors: the
    input embedding) take their whole-step gradient once per step from set_deferred_grad, not from autograd after
    every micro-step. accumulate() is the parent's with the deferred rows skipped (their .grad stays None)."""

    def __init__(self, param_groups, *, deferred=(), **kwargs):
        super().__init__(param_groups, **kwargs)
        self._deferred_ids = {id(p) for p in deferred}
        if not self._deferred_ids <= {id(r["p"]) for r in self._rows}:
            raise ValueError("deferred parameters must be row-sharded AdamW tensors")

    @torch.no_grad()
    def accumulate(self):
        first = self._acc_count == 0
        acc_params, acc_targets = self._fold_rest(first)      # S2: the slab's runs by the fold, if one is set
        grads = [p.grad if p.grad is not None else torch.zeros_like(p) for p in acc_params]
        if getattr(self, "_rest_fn", None) is not None:
            self._acc_rest_s12(acc_targets, grads, first)       # S12: nothing on the copy unit
        elif first and acc_targets:
            torch._foreach_copy_(acc_targets, grads)
        elif acc_targets:
            torch._foreach_add_(acc_targets, grads)
        for r in self._rows:
            if id(r["p"]) in self._deferred_ids:
                continue
            g = r["p"].grad
            if g is None:
                g = torch.zeros_like(r["p"])
            if first:
                if r["acc"] is None:
                    r["acc"] = torch.empty(r["p"].shape, dtype=self.acc_dtype, device=g.device)
                r["acc"].copy_(g)
            else:
                r["acc"].add_(g)
        for group in self.param_groups:
            for p in group["params"]:
                p.grad = None
        self._acc_count += 1

    def set_deferred_grad(self, p, grad):
        """The step's whole gradient of a deferred parameter, read by step() as that row's accumulation."""
        if id(p) not in self._deferred_ids or grad.dtype != self.acc_dtype or tuple(grad.shape) != tuple(p.shape):
            raise ValueError("set_deferred_grad: not a deferred parameter, or a gradient of another dtype or shape")
        for r in self._rows:
            if r["p"] is p:
                r["acc"] = grad


class EmaLawa:
    """Lane EMA31 (R2_EMA): the uniform average of the FP32 masters switch 11's lean optimizer holds on this rank, in a
    fixed order (sources): each scalar stack's, each row-sharded AdamW tensor's owned rows, the Muon slab's chunk, each
    leftover group's own matrices, each local expert group's. sample() runs after the optimizer step: the first step
    whose schedule fraction is at least `start`, every `every` steps after it; finish() adds the last step when it was
    not a sample (the last step alone when none was) and divides the FP32 sums by the count. publish(True) writes the
    average into the replicas by step()'s own casts and gathers (its section 5 with the update math left out), the
    masters untouched; publish(False) writes the masters back the same way. Collective: every rank calls it at the same
    point. Every rank takes the same decisions from the same values (the step, the schedule's fraction as every rank
    received it), so every shard holds the same steps' average."""

    def __init__(self, opt, start: float, every: int):
        if not isinstance(opt, LeanDistMuonAdamW) or opt.param_views:
            raise ValueError("lane EMA31: R2_EMA averages switch 11's lean optimizer's FP32 masters (a distributed run "
                             "with R2_LEAN_OPT=1; parameters not views of the slabs, as main() builds it)")
        self.opt, self.start, self.every = opt, float(start), int(every)
        self.src = self.sources()
        self.avg = [torch.zeros_like(m) for m in self.src]       # FP32, the masters' devices and shapes
        self.w = torch.ones((), dtype=torch.float32)             # 1 / samples: a 0-D FP32 CPU tensor (a runtime value)
        self.n, self.s0, self.first, self.last, self.seen, self.final = 0, -1, -1, -1, -1, 0
        self.numel = sum(m.numel() for m in self.src)
        self.bytes = sum(m.numel() * m.element_size() for m in self.src)
        t0 = time.perf_counter()
        self.warm()
        self.warm_s = time.perf_counter() - t0

    def sources(self) -> list:
        o = self.opt
        out = [S["master"] for S in o._small] + [r["master"] for r in o._rows]
        if o.plan is not None:
            out.append(o.Mm)
            out += [L["master"] for L in o._left if L["master"] is not None]
        return out + [L["master"] for L in o._local]

    @torch.no_grad()
    def warm(self) -> None:
        """The eager operations of sample(), finish() and publish()'s sources once on every buffer (copy_, add_, the 0-D
        scale's mul_), inside the uncharged startup, so none is first met inside the clock; the values are dropped."""
        for a, m in zip(self.avg, self.src):
            a.copy_(m)
            a.add_(m)
            a.mul_(self.w)
            a.zero_()

    @torch.no_grad()
    def sample(self, step: int, progress: float) -> bool:
        """After optimizer step `step` (its schedule fraction `progress`): the masters join the average when due (the
        first sample copies, later ones add). True when they joined."""
        self.seen = step
        if self.n == 0:
            if progress < self.start:
                return False
            self.s0 = self.first = step
            for a, m in zip(self.avg, self.src):
                a.copy_(m)
        elif (step - self.s0) % self.every:
            return False
        else:
            for a, m in zip(self.avg, self.src):
                a.add_(m)
        self.n += 1
        self.last = step
        return True

    @torch.no_grad()
    def finish(self, steps: int) -> dict:
        """At the save (every rank, once, after the last step): the masters as they end join the average when the last
        step (index seen) was not a sample (with no sample at all they are the average alone); then the sums times
        1 / samples (a 0-D FP32 CPU tensor). Returns the record (the checkpoint's meta and the end line)."""
        if self.n == 0 or self.last != self.seen:
            for a, m in zip(self.avg, self.src):
                if self.n == 0:
                    a.copy_(m)
                else:
                    a.add_(m)
            if self.n == 0:
                self.s0 = self.first = self.seen
            self.n += 1
            self.last = self.seen
            self.final = 1
        self.w.fill_(1.0 / self.n)
        for a in self.avg:
            a.mul_(self.w)
        return {"from": self.start, "every": self.every, "samples": self.n, "first_step": self.first,
                "last_step": self.last, "last_added": self.final, "steps": steps, "save_both": R2_EMA_SAVE_BOTH,
                "file": EMA_SIBLING if R2_EMA_SAVE_BOTH else "final.pt"}

    @torch.no_grad()
    def publish(self, average: bool) -> float:
        """The average (True) or the masters (False) into the replicas: step()'s section 5 without the update math, on
        the same buffers in the same order (the replica-dtype casts into the out buffers, the all-gathers, the leftover
        groups' one-value-plus-zeros all-reduce, the copies into the parameters), each master's place taken by its
        source. Collective. Returns the host seconds it took to issue."""
        t0 = time.perf_counter()
        o = self.opt
        it = iter(self.avg if average else self.src)
        for S in o._small:
            torch.split_with_sizes_copy(next(it), S["sizes"], out=[p.data.view(-1) for p in S["params"]])
        for r in o._rows:
            m = next(it)
            if r["out"] is None:
                dist.all_gather_into_tensor(r["p"].data, m)
            else:
                r["out"].copy_(m)
                dist.all_gather_into_tensor(r["p"].data, r["out"])
        if o.plan is not None:
            src = next(it)
            if o.mine_out is not None:
                o.mine_out.copy_(src)
                src = o.mine_out
            if o.K == 1:
                dist.all_gather_into_tensor(o.Wm.view(o._coll_in), src.view(o._coll_out))
            else:
                for a, b in o._pieces:
                    tmp = torch.empty(o.world, b - a, dtype=o.Wm.dtype, device=o.Wm.device)
                    dist.all_gather_into_tensor(tmp, src[:, a:b])
                    o.Wm[:, a:b].copy_(tmp)
            wflat = o.Wm.view(-1)
            for run in o._runs:
                if o.foreach_copy:
                    torch._foreach_copy_([p.data.view(-1) for p in run["params"]],
                                         list(wflat[run["start"]:run["end"]].split(run["sizes"])))
                else:
                    torch.split_with_sizes_copy(wflat[run["start"]:run["end"]], run["sizes"],
                                                out=[p.data.view(-1) for p in run["params"]])
            for L in o._left:
                m = next(it) if L["master"] is not None else None
                if L["kind"] == "allreduce":
                    L["Wl"].zero_()
                    if L["own"]:
                        L["Wl"].index_copy_(0, L["idx"], m.to(L["Wl"].dtype))
                    dist.all_reduce(L["Wl"], op=dist.ReduceOp.SUM)     # one value plus zeros: exact in any dtype
                    n = L["Wl"][0].numel()
                    if o.foreach_copy:
                        torch._foreach_copy_([p.data.view(-1) for p in L["params"]],
                                             list(L["Wl"].view(-1).split([n] * len(L["params"]))))
                    else:
                        torch.split_with_sizes_copy(L["Wl"].view(-1), [n] * len(L["params"]),
                                                    out=[p.data.view(-1) for p in L["params"]])
                else:
                    src = m
                    if L["out"] is not None:
                        L["out"].copy_(m)
                        src = L["out"]
                    dist.all_gather_into_tensor(L["Wl"], src)
                    if L["slots"]:
                        torch._foreach_copy_([p.data for _o, p in L["slots"]], [L["Wl"][q] for q, _p in L["slots"]])
        for L in o._local:
            torch._foreach_copy_([p.data for p in L["params"]], list(next(it).split(L["counts"])))
        if next(it, None) is not None:
            raise RuntimeError("lane EMA31: publish's sources outnumber the optimizer's masters")
        return time.perf_counter() - t0

    def setup_line(self, rank: int) -> str:
        return (f"ema rank {rank}: on (lane EMA31) from={self.start:g} every={self.every} "
                f"save={self.save_name()} "
                f"sources={len(self.src)} numel={self.numel} bytes={self.bytes} GiB={self.bytes / 2 ** 30:.4f} "
                f"dtypes={'+'.join(sorted({str(m.dtype).replace('torch.', '') for m in self.src}))} "
                f"warm_s={self.warm_s:.2f}")

    @staticmethod
    def save_name() -> str:
        return f"both: final.pt the last iterate, {EMA_SIBLING} the average" if R2_EMA_SAVE_BOTH else "final.pt"

    def end_line(self, rank: int) -> str:
        return (f"ema rank {rank}: samples={self.n} first_step={self.first} last_step={self.last} "
                f"last_added={self.final} seen={self.seen}")


def lean_accumulate_into(targets: list, grads: list, first: bool) -> None:
    """T3: LeanDistMuonAdamW.accumulate()'s arithmetic as one function for torch.compile: every target (a view of a
    communication buffer, or a row-sharded tensor's FP32 accumulation) takes its gradient, copied at a step's first
    micro-step and added after, with the eager calls' casts and type promotion."""
    if first:
        torch._foreach_copy_(targets, grads)
    else:
        torch._foreach_add_(targets, grads)


def lean_fold_slab(bases: list, groups: list, first: bool) -> None:
    """S2: the Muon slab's share of LeanDistMuonAdamW.accumulate() for one micro-step, as one function for
    torch.compile. For each contiguous run of the slab (bases[i], a contiguous view of Gm) the run's gradients,
    flattened in slab order, are concatenated, then copied into the view (a step's first micro-step) or added to
    it, in place: each element is the target plus the gradient cast to the target's dtype, one rounding, as in
    the eager multi-tensor copy and add. No foreach op (the neuron backend has no lowering for them: T3); the
    backend keeps the in-place copy_ / add_ on the input in the graph (keep_inference_input_mutations) and runs
    it as an input-output alias, so the NEFF writes the slab in place."""
    for base, grads in zip(bases, groups):
        flat = torch.cat([g.reshape(-1) for g in grads])
        if first:
            base.copy_(flat)
        else:
            base.add_(flat)


def lean_fold_none(bases: list, groups: list, first: bool) -> None:
    """Switch 9h: S2's fold when GradFoldIn took every run of the slab (nothing is left to fold)."""


def lean_acc_rest(targets: list, grads: list, first: bool, flag, value) -> None:
    """S12: the accumulation of the targets S2's fold leaves, as one function for torch.compile: per target an in-place
    copy_ (a step's first micro-step) or add_ of its gradient, each element the target plus the gradient in their
    promoted dtype rounded once to the target's (the eager multi-tensor copy and add, without their alpha tensor);
    with a flag, flag.copy_(value) (switch 9h's flag to False). As S2's fold, the backend keeps the mutations in the
    graph as input-output aliases, so nothing is written from the host and no op runs on the copy unit."""
    for t, g in zip(targets, grads):
        if first:
            t.copy_(g)
        else:
            t.add_(g)
    if flag is not None:
        flag.copy_(value)


def muon_math_body(g, w, momentum, second, sched, coeffs: tuple, ns_bf16: bool, shape: tuple) -> None:
    """S4: LeanDistMuonAdamW._muon_math after its prologue (the FP32 cast, the state, the schedule fills), as one
    function for torch.compile: the same operations in the same order. sched holds the step's momentum,
    1 - momentum, 1 - beta2, learning rate and weight decay (FP32, on the device); coeffs (the Polar Express
    coefficients), ns_bf16 and shape are constants of the graph. g, momentum, second and w are updated in place."""
    momentum_t, omm, omb2, lr, wd_t = sched[0], sched[1], sched[2], sched[3], sched[4]
    momentum.lerp_(g, omm)
    g = g.lerp_(momentum, momentum_t)
    x = g.bfloat16() if ns_bf16 else g
    if R2_MUONEQ:
        # MQ1 (lane BATCH): MuonEq, each row of each matrix to the matrix's mean row norm (nanochat 4e014d3).
        x = x * (x.float().norm(dim=(-2, -1), keepdim=True) / (x.size(-2) ** 0.5)
                 / x.float().norm(dim=-1, keepdim=True).clamp_min(1e-6)).to(x.dtype)
    x = x / (x.norm(dim=(-2, -1), keepdim=True) * 1.01 + 1e-6)
    squeezed = x.dim() == 3 and x.size(0) == 1
    if squeezed:
        x = x.squeeze(0)
    if x.shape[-2] > x.shape[-1]:
        for a, b, c in coeffs:
            xtx = x.mT @ x
            x = a * x + x @ (b * xtx + c * (xtx @ xtx))
    else:
        for a, b, c in coeffs:
            xxt = x @ x.mT
            x = a * x + (b * xxt + c * (xxt @ xxt)) @ x
    if squeezed:
        x = x.unsqueeze(0)
    g = x
    if R2_MUONEQ:
        # MQ1 (lane BATCH): Muon+, each matrix's Frobenius norm to sqrt(min(rows, cols)) (nanochat 4e014d3).
        g = g * (min(g.size(-2), g.size(-1)) ** 0.5
                 / g.float().norm(dim=(-2, -1), keepdim=True).clamp_min(1e-6)).to(g.dtype)
    red_dim = -1 if shape[-2] >= shape[-1] else -2
    v_mean = g.float().square().mean(dim=red_dim, keepdim=True)
    red_dim_size = g.size(red_dim)
    v_norm = (v_mean.sum(dim=(-2, -1), keepdim=True) * red_dim_size).sqrt()
    second.lerp_(v_mean, omb2)
    step_size = second.clamp_min(1e-10).rsqrt()
    scaled = (v_mean * red_dim_size) * step_size.square()
    v_norm_new = scaled.sum(dim=(-2, -1), keepdim=True).sqrt()
    g = g * (step_size * (v_norm / v_norm_new.clamp_min(1e-10))).to(g.dtype)
    mask = (g * w) >= 0
    w.sub_(lr * g + lr * wd_t * w * mask)


def muon_math_pair_nsk(g1, w1, m1, s1, sch1, g2, w2, m2, s2, sch2, shape1: tuple, shape2: tuple) -> None:
    """Switch 65: muon_math_body for switch 55's two expert units of a rank, unit 1 the tall stack [K, r, c] (r > c,
    the experts' w_fc), unit 2 the wide one [K, c, r] (w_proj), as one function for torch.compile: each unit's two
    lerps and its denominator x.norm() * 1.01 + 1e-6 of x = g.bfloat16(), as muon_math_body writes them; then
    nsk_ns5 (one kernel call: x = bf16(g) x (1 / d) and the five Polar Express iterations of both stacks, with each
    X5's sum of squares over red_dim, divided here by red_dim's size: muon_math_body's v_mean); then each unit's
    lines after v_mean (nsk_tail). g, momentum, second and w are updated in place as muon_math_body updates them;
    sch1 and sch2 are its sched."""
    m1.lerp_(g1, sch1[1])
    g1 = g1.lerp_(m1, sch1[0])
    m2.lerp_(g2, sch2[1])
    g2 = g2.lerp_(m2, sch2[0])
    d1 = g1.bfloat16().norm(dim=(-2, -1), keepdim=True) * 1.01 + 1e-6
    d2 = g2.bfloat16().norm(dim=(-2, -1), keepdim=True) * 1.01 + 1e-6
    x1, x2, v1, v2 = nsk_ns5(g1, g2, d1, d2)
    nsk_tail(x1, (v1 / x1.size(-1)).unsqueeze(-1), w1, s1, sch1, shape1)
    nsk_tail(x2, (v2 / x2.size(-2)).unsqueeze(-2), w2, s2, sch2, shape2)


def nsk_tail(g, v_mean, w, second, sched, shape: tuple) -> None:
    """Switch 65: muon_math_body's lines after its v_mean (the NorMuon scale, the cautious decay and the update),
    unchanged; v_mean is the kernel's (the same mean of x^2 over red_dim, its sum in fp32 in the kernel's order)."""
    omb2, lr, wd_t = sched[2], sched[3], sched[4]
    red_dim = -1 if shape[-2] >= shape[-1] else -2
    red_dim_size = g.size(red_dim)
    v_norm = (v_mean.sum(dim=(-2, -1), keepdim=True) * red_dim_size).sqrt()
    second.lerp_(v_mean, omb2)
    step_size = second.clamp_min(1e-10).rsqrt()
    scaled = (v_mean * red_dim_size) * step_size.square()
    v_norm_new = scaled.sum(dim=(-2, -1), keepdim=True).sqrt()
    g = g * (step_size * (v_norm / v_norm_new.clamp_min(1e-10))).to(g.dtype)
    mask = (g * w) >= 0
    w.sub_(lr * g + lr * wd_t * w * mask)


def adamw_math_body(p, grad, exp_avg, exp_avg_sq, sched) -> None:
    """S4: LeanDistMuonAdamW._adamw_math after its prologue, as one function for torch.compile: the same operations
    in the same order. sched holds lr, weight decay, 1 - beta1, 1 - beta2, eps and the two bias corrections (FP32,
    on the device). p, exp_avg and exp_avg_sq are updated in place."""
    lr, wd_t, omb1, omb2 = sched[0], sched[1], sched[2], sched[3]
    eps_t, bias1_t, bias2_t = sched[4], sched[5], sched[6]
    p.mul_(1 - lr * wd_t)
    exp_avg.lerp_(grad, omb1)
    exp_avg_sq.lerp_(grad.square(), omb2)
    update = exp_avg / bias1_t / ((exp_avg_sq / bias2_t).sqrt() + eps_t)
    p.sub_(lr * update)


OPT_OVL_FUNCOL = None      # lane OVERLAP: torch.distributed._functional_collectives (set by enable_overlap)


def opt_overlap_rs(row_outs: list, row_srcs: list, slab_out: torch.Tensor, slab_in: torch.Tensor, slab_op: str,
                   pays: list, units: list) -> None:
    """Lane OVERLAP (R2_OPT_OVERLAP=1): step()'s sections 1 to 3 and the experts' updates as one function for
    torch.compile. Issued first, as functional collectives over the world group: each row table's reduce-scatter (AVG)
    of its accumulation, the Muon slab's (slab_op) and each scalar stack's all-reduce (AVG), in step()'s order; then
    each expert unit's update (muon_math_body(*u), its prologue done by _ovl_unit); then each result copied into the
    buffer step() reduces into (row_outs, slab_out, the stacks themselves), the first read of each after its issue. No
    tensor a collective reads or writes is touched by an update, so the device may run them together; every value is
    step()'s."""
    fc, grp = OPT_OVL_FUNCOL, dist.group.WORLD
    rows = [fc.reduce_scatter_tensor(s, "avg", 0, grp) for s in row_srcs]
    slab = fc.reduce_scatter_tensor(slab_in, slab_op, 0, grp)
    small = [fc.all_reduce(p, "avg", grp) for p in pays]
    for u in units:
        muon_math_body(*u)
    for o, r in zip(row_outs, rows):
        o.copy_(r)
    slab_out.copy_(slab)
    for p, r in zip(pays, small):
        p.copy_(r)


class LeanDistMuonAdamWThroughput(LeanDistMuonAdamWDeferred):
    """T1 and T3 on switch 11's optimizer (with `deferred` empty it steps as LeanDistMuonAdamW: the parent's
    accumulate() then skips nothing).
    T1: step() raises unless every deferred parameter has this step's gradient from set_deferred_grad (without the
    check a deferred table with no gradient hands None, or its last step's gradient, to its reduce_scatter); the
    deferred gradients are dropped at zero_grad, the next step's start.
    T3: after compile_accumulate(backend), accumulate() hands every non-deferred gradient and its FP32 target to one
    compiled lean_accumulate_into (the eager accumulate()'s copies and adds); before that, it is the parent's."""

    def __init__(self, param_groups, *, deferred=(), **kwargs):
        super().__init__(param_groups, deferred=deferred, **kwargs)
        self._deferred_got = set()
        self._acc_fn = None

    def compile_accumulate(self, backend: str) -> None:
        self._acc_fn = torch.compile(lean_accumulate_into, backend=backend, dynamic=False)

    @torch.no_grad()
    def accumulate(self):
        if self._acc_fn is None:
            return super().accumulate()
        first = self._acc_count == 0
        targets = list(self._acc_targets)
        grads = [p.grad if p.grad is not None else torch.zeros_like(p) for p in self._acc_params]
        for r in self._rows:
            if id(r["p"]) in self._deferred_ids:
                continue
            g = r["p"].grad
            if g is None:
                g = torch.zeros_like(r["p"])
            if r["acc"] is None:
                r["acc"] = torch.empty(r["p"].shape, dtype=self.acc_dtype, device=g.device)
            targets.append(r["acc"])
            grads.append(g)
        self._acc_fn(targets, grads, first)
        for group in self.param_groups:
            for p in group["params"]:
                p.grad = None
        self._acc_count += 1

    def set_deferred_grad(self, p, grad):
        super().set_deferred_grad(p, grad)
        self._deferred_got.add(id(p))

    def set_deferred_grad_cols(self, p, cols):
        """Lane STEM8B: a deferred gate table's step gradient as column blocks (stem8_set_grad), which step()'s reduce
        reads in place of a [vocab, F] accumulation; dropped at zero_grad as the others are."""
        if id(p) not in self._deferred_ids:
            raise ValueError("set_deferred_grad_cols: not a deferred parameter")
        for r in self._rows:
            if r["p"] is p:
                r["acc"] = None
                r["cols"] = cols
        self._deferred_got.add(id(p))

    def zero_grad(self, set_to_none: bool = True):
        super().zero_grad(set_to_none=set_to_none)
        for r in self._rows:
            if id(r["p"]) in self._deferred_ids:
                r["acc"] = None
                r.pop("cols", None)          # lane STEM8B: a gate table's column blocks
        self._deferred_got = set()

    @torch.no_grad()
    def step(self):
        missing = self._deferred_ids - self._deferred_got
        if missing:
            raise RuntimeError(f"T1: {len(missing)} deferred parameter(s) without this step's gradient "
                               "(set_deferred_grad was not called for them)")
        super().step()


class LoaderPrefetchT2:
    """T2: the next step's batch, prepared on a background thread while the device runs the step (work/p2/diag2's
    R2_LOADER_PREFETCH=1, chip-verified bitwise as D2_M3c_pf100, extended to switch 10's relabel). fetch() returns the
    loader's next host row with switch 2's mask applied; it runs once per step, in step order, never from two threads
    at once. The thread copies the row into the pair of device tensors the current step does not read and, under
    switch 10, relabels it (lean_relabel) into spare device tensors; finish() joins it after the step's synchronize,
    copies the spare compact ids and rows into the step's lean tensors (on the device) and returns the new pair. A
    pair is written only after the step that last read it has finished on the device: the thread starts after the
    synchronize at the top of the step that follows it."""

    def __init__(self, fetch, window_x: torch.Tensor, window_y: torch.Tensor, lean=None, vocab: int = 0):
        self.fetch = fetch
        self.bx = [window_x, torch.empty_like(window_x)]
        self.by = [window_y, torch.empty_like(window_y)]
        self.lean = lean            # (lean_cid, lean_rows, lean_host_ids) the step reads, or None
        self.vocab = vocab
        self.spare = None if lean is None else (torch.empty_like(lean[0]), torch.empty_like(lean[1]))
        self.cur = 0                # the pair the current step reads; the first batch is in pair 0
        self.thread = None
        self.result = None
        self.error = None

    def _work(self, target: int) -> None:
        try:
            x, y, state = self.fetch()
            self.bx[target].copy_(x.view(self.bx[target].shape))
            self.by[target].copy_(y.view(self.by[target].shape))
            host_ids = None
            if self.lean is not None:
                relabel = lean_relabel(x, self.vocab)
                if relabel is None:
                    host_ids = x.clone()
                else:
                    self.spare[0].copy_(relabel[0])
                    self.spare[1].copy_(relabel[1])
            self.result = (target, state, host_ids)
        except BaseException as err:  # re-raised on the main thread by finish()
            self.error = err

    def start(self) -> None:
        import threading
        if self.thread is not None:
            raise RuntimeError("T2 prefetch: a fetch is already running")
        self.result, self.error = None, None
        self.thread = threading.Thread(target=self._work, args=(1 - self.cur,), name="r2-prefetch", daemon=True)
        self.thread.start()

    def finish(self):
        self.thread.join()
        self.thread = None
        if self.error is not None:
            raise RuntimeError("T2 prefetch: the background fetch failed") from self.error
        target, state, host_ids = self.result
        if self.lean is not None:
            cid, rows, host = self.lean
            host[0] = host_ids
            if host_ids is None:
                cid.copy_(self.spare[0])
                rows.copy_(self.spare[1])
        self.cur = target
        return self.bx[target], self.by[target], state

    def close(self) -> None:
        if self.thread is not None:
            self.thread.join()
            self.thread = None


class NgramStaleT21(LoaderPrefetchT2):
    """Switch 21: T2's double-buffered next-batch thread, extended to the n-gram table's host work. During step s the
    worker first applies the pending table update (step s-1's rows, gradients, LR and step: NgramHostTable.step,
    collective), then fetches step s+1's batch into the pair of device tensors step s does not read (and, under
    switch 10, relabels it), hashes the batch's n-grams and gathers their rows into the n-gram window of that pair.
    bn[cur] and ids[cur] are the current step's window and rows. The main thread sets `pending` only after finish()
    (never while the worker runs) and calls flush() after the loop for the last step's update. inline=True runs the
    same work in start(), on the calling thread (the schedule without the thread)."""

    def __init__(self, fetch, window_x, window_y, lean, vocab, ngram, window, ids0, shape, timing, inline=False,
                 host_writes=False):
        super().__init__(fetch, window_x, window_y, lean, vocab)
        self.ngram, self.shape, self.timing, self.inline = ngram, shape, timing, inline
        self.bn = [window, torch.empty_like(window)]
        self.ids = [ids0, None]
        self.pending = None
        self.timing.setdefault("wait", 0.0)
        # S11: the worker fills host tensors and finish() writes them into the pair (non-blocking copies); a pending
        # update carries the event after its gradient's read, waited on before the update.
        self.host_writes = host_writes
        if host_writes:
            self.timing.setdefault("event_wait", 0.0)
            self.timing.setdefault("write", 0.0)

    def _apply_pending(self) -> None:
        if self.pending is not None:
            if len(self.pending) == 5:
                # S11: the step's gradient was read without a drain; its event first (Event.synchronize releases the
                # GIL), then the update as without S11.
                t = time.perf_counter()
                if self.pending[4] is not None:
                    self.pending[4].synchronize()
                self.pending = self.pending[:4]
                self.timing["event_wait"] += time.perf_counter() - t
            t = time.perf_counter()
            self.ngram.step(*self.pending)
            self.pending = None
            self.timing["update"] += time.perf_counter() - t

    def _work(self, target: int) -> None:
        try:
            self._apply_pending()
            x, y, state = self.fetch()
            host = {}
            if self.host_writes:
                # S11: host tensors only (clones: the loader reuses its buffers); finish() writes them into this pair.
                host["x"], host["y"] = x.view(self.bx[target].shape).clone(), y.view(self.by[target].shape).clone()
            else:
                self.bx[target].copy_(x.view(self.bx[target].shape))
                self.by[target].copy_(y.view(self.by[target].shape))
            host_ids = None
            if self.lean is not None:
                relabel = lean_relabel(x, self.vocab)
                if relabel is None:
                    host_ids = x.clone()
                elif self.host_writes:
                    host["cid"], host["rows"] = relabel[0], relabel[1]
                else:
                    self.spare[0].copy_(relabel[0])
                    self.spare[1].copy_(relabel[1])
            t = time.perf_counter()
            self.ids[target] = self.ngram.ids(x.view(self.shape))
            if self.host_writes:
                host["bn"] = self.ngram.gather(self.ids[target])
            else:
                self.bn[target].copy_(self.ngram.gather(self.ids[target]))
            self.timing["gather"] += time.perf_counter() - t
            self.result = (target, state, host_ids, host) if self.host_writes else (target, state, host_ids)
        except BaseException as err:  # re-raised on the main thread by finish()
            self.error = err

    def start(self) -> None:
        if not self.inline:
            super().start()
            return
        self.result, self.error = None, None
        self._work(1 - self.cur)

    def finish(self):
        t = time.perf_counter()
        if self.host_writes:
            # S11: the join, then this pair's writes by non-blocking copies (each source is copied to a bounce buffer
            # by the call), queued after everything this step queued and before the next step's first forward.
            if self.thread is not None:
                self.thread.join()
                self.thread = None
            if self.error is not None:
                raise RuntimeError("switch 21: the n-gram worker's job failed") from self.error
            target, state, host_ids, host = self.result
            self.timing["wait"] += time.perf_counter() - t
            t = time.perf_counter()
            self.bx[target].copy_(host["x"], non_blocking=True)
            self.by[target].copy_(host["y"], non_blocking=True)
            if self.lean is not None:
                cid, rows, hostref = self.lean
                hostref[0] = host_ids
                if host_ids is None:
                    cid.copy_(host["cid"], non_blocking=True)
                    rows.copy_(host["rows"], non_blocking=True)
            self.bn[target].copy_(host["bn"], non_blocking=True)
            self.timing["write"] += time.perf_counter() - t
            self.cur = target
            return self.bx[target], self.by[target], state
        if self.inline:
            if self.error is not None:
                raise RuntimeError("switch 21: the n-gram worker's job failed") from self.error
            target, state, host_ids = self.result
            if self.lean is not None:
                cid, rows, host = self.lean
                host[0] = host_ids
                if host_ids is None:
                    cid.copy_(self.spare[0])
                    rows.copy_(self.spare[1])
            self.cur = target
            out = self.bx[target], self.by[target], state
        else:
            out = super().finish()
        self.timing["wait"] += time.perf_counter() - t
        return out

    def flush(self) -> None:
        """The last step's update, after the loop (every rank, collective)."""
        self.close()
        if self.host_writes and self.error is not None and self.pending is not None:
            # S11: a stop or a bad loss read in a deferred tail leaves the worker running; a failure of it before or
            # inside its update is raised here, never applied a second time.
            raise RuntimeError("switch 21: the n-gram worker failed before its table update") from self.error
        self._apply_pending()


class BoundaryS11:
    """S11 (R2_BOUNDARY_ASYNC=1): the events, the control on its own gloo group and the counts of the boundary that
    does not drain the device. record() puts an event after everything this rank has queued (None off a Neuron
    device, where every op has finished when it returns); wait() waits for one (the GIL is released). exit_async()
    gives the same answer on every rank: it reads the step, the step target, S5's probe schedule and the near-end flag
    the control's MAX gave every rank."""

    def __init__(self, device, group, rank: int):
        self.group, self.rank = group, rank
        self.event_cls = None
        if device.type == "neuron":
            self.event_cls = getattr(getattr(torch, "neuron", None), "Event", None)
            if self.event_cls is None:
                import torch_neuronx
                self.event_cls = torch_neuronx.Event
        self.prev_obs = time.monotonic()
        self.near_end = False
        self.n = {"async": 0, "sync": 0, "tails": 0}
        self.ms = {"wait": 0.0, "ctrl": 0.0, "read": 0.0}

    def record(self):
        if self.event_cls is None:
            return None
        ev = self.event_cls()
        ev.record()
        return ev

    def wait(self, ev) -> None:
        t = time.perf_counter()
        if ev is not None:
            ev.synchronize()
        self.ms["wait"] += 1000.0 * (time.perf_counter() - t)

    def control(self, values: list) -> list:
        """The MAX over the ranks of each value (int64), on this switch's gloo group."""
        t = time.perf_counter()
        x = torch.tensor(values, dtype=torch.int64)
        if self.group is not None:
            dist.all_reduce(x, op=dist.ReduceOp.MAX, group=self.group)
        self.ms["ctrl"] += 1000.0 * (time.perf_counter() - t)
        return [int(v) for v in x.tolist()]

    def exit_async(self, step: int, explicit_last: bool, probe_next: bool) -> bool:
        ok = (step >= TRAIN_STARTUP_STEPS_EXCLUDED and not explicit_last and not probe_next and not self.near_end
              and (R2_BOUNDARY_SYNC_EVERY <= 0 or (step + 1) % R2_BOUNDARY_SYNC_EVERY != 0))
        self.n["async" if ok else "sync"] += 1
        return ok

    def line(self, rank: int, timing: dict) -> str:
        n = max(1, self.n["tails"])
        m = max(1, self.n["async"] + self.n["sync"])
        return (f"S11 boundary rank {rank}: async_exits={self.n['async']} sync_exits={self.n['sync']} "
                f"tails={self.n['tails']} wait_ms={self.ms['wait'] / n:.2f} ctrl_ms={self.ms['ctrl'] / n:.2f} "
                f"read_ms={self.ms['read'] / m:.2f} write_ms={1000.0 * timing.get('write', 0.0) / m:.2f} "
                f"worker_event_wait_ms={1000.0 * timing.get('event_wait', 0.0) / m:.2f} near_end={int(self.near_end)}")


class NgramStaleOS1(NgramStaleT21):
    """Switch 59: switch 21's worker with the one-shot table's work beside it. During step s: step s-1's switch 17
    update (after S11's event when present) and step s-1's one-shot table update (every rank together, on its own gloo
    group); then step s+1's batch is fetched, switch 17's rows gathered, the one-shot table's keys recorded (the targets
    cloned) and its unbound rows gathered; both are written into the window of the pair step s does not read, one slot
    wider than switch 17's (directly, or under S11 as host tensors finish() writes by non-blocking copies). With
    os1_thread (R2_OS1_THREAD=1) the one-shot table's update and rows run on a thread of their own, started with switch
    21's worker and joined after it (lane E1LK's form): its update overlaps switch 17's, its rows wait for the batch
    switch 21's worker hands over, and switch 21's worker waits for those rows before it writes the window. Otherwise
    the same work runs in switch 21's worker after switch 17's (or inline). The values are the same either way (the two
    tables are independent; each keeps update s-1 before gather s+1 before update s). recs[cur] is the current step's
    record; os1_pending is set by the main thread after finish(), as pending is. Lane OS1D (C3): the table's thread
    also waits for os1_release(), which the main thread calls once it has queued the step (before its blocking
    gradient read; under S11 after its non-blocking reads), so its update overlaps the device's step, not the
    launches."""

    def __init__(self, os1, fetch, window_x, window_y, lean, vocab, ngram, window, ids0, shape, timing, inline=False,
                 host_writes=False, os1_thread=True):
        super().__init__(fetch, window_x, window_y, lean, vocab, ngram, window, ids0, shape, timing, inline=inline,
                         host_writes=host_writes)
        self.os1 = os1
        self.recs = [os1.first, None]
        self.os1_pending = None
        self.os1_threaded = bool(os1_thread) and not self.inline
        self.os1_thread = None
        self.os1_error = None
        self._os1_in = self._os1_out = self._os1_go = self._os1_done = self._grad_ready = None
        # Lane OS1D (C3): set by the main thread once it has queued the step (os1_release), so the table's update does
        # not contend for the GIL with the step's launches; the order of the table's work is unchanged.
        self._os1_rel = None
        self.timing.setdefault("os1_gather", 0.0)
        self.timing.setdefault("os1_job", 0.0)
        self.timing.setdefault("os1_wait", 0.0)

    def _apply_os1_pending(self) -> None:
        if self.os1_pending is not None:
            t = time.perf_counter()
            self.os1.job(*self.os1_pending)
            self.os1_pending = None
            self.timing["os1_job"] += time.perf_counter() - t

    def _apply_pending(self) -> None:
        """Switch 17's pending update as switch 21's (S11: its event first), and then the table's thread released:
        the step's gradient on the host, the one-shot table's slot included, is complete once the event has been
        waited on (one wait, on this thread; the table's thread never touches the device event)."""
        if self.pending is not None and len(self.pending) == 5:
            t = time.perf_counter()
            if self.pending[4] is not None:
                self.pending[4].synchronize()
            self.pending = self.pending[:4]
            self.timing["event_wait"] += time.perf_counter() - t
        if self._grad_ready is not None:
            self._grad_ready.set()
        super()._apply_pending()

    def _os1_rows(self, target: int, x: torch.Tensor, y: torch.Tensor) -> torch.Tensor:
        t = time.perf_counter()
        self.recs[target] = self.os1.record(x.view(self.shape), y.view(self.shape))
        u = self.os1.gather_u(self.recs[target])
        self.timing["os1_gather"] += time.perf_counter() - t
        return u

    def _os1_work(self) -> None:
        """The one-shot table's thread: step s-1's update (once switch 21's worker has the step's gradient complete on
        the host), then step s+1's rows once it hands over the batch."""
        try:
            os1_table_threads(self.timing, "tt_os1")        # lane OS1R (riders a, d): a no-op unset
            self._grad_ready.wait()
            self._os1_rel.wait()                # C3: after the main thread has queued the step
            self._apply_os1_pending()
            self._os1_go.wait()
            if self._os1_in is not None:        # None: switch 21's worker failed first (finish() raises its error)
                self._os1_out = self._os1_rows(*self._os1_in)
        except BaseException as err:  # re-raised on the main thread by finish()
            self.os1_error = err
        finally:
            self._os1_done.set()

    def _os1_take(self) -> torch.Tensor:
        t = time.perf_counter()
        self._os1_done.wait()
        self.timing["os1_wait"] += time.perf_counter() - t
        if self.os1_error is not None or self._os1_out is None:
            raise RuntimeError("switch 59: the one-shot table's thread failed") from self.os1_error
        return self._os1_out

    def _work(self, target: int) -> None:
        try:
            os1_table_threads(self.timing, "tt_worker")     # lane OS1R (riders a, d): a no-op unset
            self._apply_pending()
            if not self.os1_threaded:
                self._apply_os1_pending()
            x, y, state = self.fetch()
            if self.os1_threaded:
                self._os1_in = (target, x, y)
                self._os1_go.set()
            host = {}
            if self.host_writes:
                # S11: host tensors only (clones: the loader reuses its buffers); finish() writes them into this pair.
                host["x"], host["y"] = x.view(self.bx[target].shape).clone(), y.view(self.by[target].shape).clone()
            else:
                self.bx[target].copy_(x.view(self.bx[target].shape))
                self.by[target].copy_(y.view(self.by[target].shape))
            host_ids = None
            if self.lean is not None:
                relabel = lean_relabel(x, self.vocab)
                if relabel is None:
                    host_ids = x.clone()
                elif self.host_writes:
                    host["cid"], host["rows"] = relabel[0], relabel[1]
                else:
                    self.spare[0].copy_(relabel[0])
                    self.spare[1].copy_(relabel[1])
            t = time.perf_counter()
            self.ids[target] = self.ngram.ids(x.view(self.shape))
            rows = self.ngram.gather(self.ids[target])
            self.timing["gather"] += time.perf_counter() - t
            u = self._os1_take() if self.os1_threaded else self._os1_rows(target, x, y)
            # Lane TABXB: a row k slots wide fills its k slots (one slot: as before).
            both = torch.cat([rows, u.unsqueeze(2) if u.size(-1) == rows.size(-1)
                              else u.view(*u.shape[:2], -1, rows.size(-1))], dim=2)
            if self.host_writes:
                host["bn"] = both
            else:
                self.bn[target].copy_(both)
            self.result = (target, state, host_ids, host) if self.host_writes else (target, state, host_ids)
        except BaseException as err:  # re-raised on the main thread by finish()
            self.error = err

    def start(self) -> None:
        if self.os1_threaded:
            import threading
            if self.os1_thread is not None:
                raise RuntimeError("switch 59: the one-shot table's thread is already running")
            self._os1_in = self._os1_out = self.os1_error = None
            self._os1_go, self._os1_done, self._grad_ready = threading.Event(), threading.Event(), threading.Event()
            self._os1_rel = threading.Event()
            self.os1_thread = threading.Thread(target=self._os1_work, name="r2-os1", daemon=True)
            self.os1_thread.start()
        super().start()

    def os1_release(self) -> None:
        """Lane OS1D (C3): the main thread has queued the step (called just before its blocking gradient read, or
        under S11 after its non-blocking reads): the table's thread may start step s-1's update."""
        if self._os1_rel is not None:
            self._os1_rel.set()

    def _join_os1(self) -> None:
        if self.os1_thread is not None:
            self._grad_ready.set()        # no-ops when they were set; release the thread when a failure came first
            self._os1_rel.set()
            self._os1_go.set()
            self.os1_thread.join()
            self.os1_thread = None

    def finish(self):
        self.os1_release()        # C3: a no-op after main()'s release; the worker never waits on a release not given
        try:
            out = super().finish()
        finally:
            self._join_os1()
        if self.os1_error is not None:
            raise RuntimeError("switch 59: the one-shot table's thread failed") from self.os1_error
        return out

    def close(self) -> None:
        # C3: a loop that stops before the step's release (T2's or S11's stop read at the tail) frees the table's
        # thread first, so the worker's wait for its rows ends and the join returns (0fd43a66's order of work).
        self.os1_release()
        super().close()
        self._join_os1()

    def flush(self) -> None:
        """The last step's updates, after the loop (every rank, collective): switch 17's, then the one-shot table's."""
        self.close()
        if (self.host_writes and (self.error is not None or self.os1_error is not None)
                and (self.pending is not None or self.os1_pending is not None)):
            # S11: as switch 21's flush: a failure of a worker before or inside its updates is raised here.
            raise RuntimeError("switch 59: a table worker failed before its updates") from (self.error
                                                                                            or self.os1_error)
        self._apply_pending()
        self._apply_os1_pending()


def shed_plan(e4: list, current: frozenset, since: dict, n_probe: int, accum: int, step_s: float, frac: float,
              margin: float, keep: float, hold: int, max_chips: int) -> tuple:
    """S5: the chips to shed until the next probe, from one probe's numbers and the previous decision; a pure function
    (the same numbers give the same plan on every rank and in every replay; its arguments are not changed). e4[c]:
    chip c's time from the step's start to the end of its micro-steps (its slowest rank's), scaled to all `accum`
    micro-steps; current: the chips shed now; since[c]: the probe index each was shed at; n_probe: this probe's
    index; step_s: the step time; frac: one chip's token share of a step per skipped micro-batch. A chip shed fewer
    than `hold` probes ago stays (held). Then for m = 0 to max_chips - len(held), S = held + the m slowest other chips
    (the lower index first on a tie): saving = the longest chip time minus the longest once S's chips run accum - 1
    micro-steps (their time x (accum - 1) / accum); cost = step_s x the sum over S of frac + margin (frac + keep for a
    chip shed now); the plan is the S of the largest saving - cost (the smaller m on a tie, so a chip is shed only
    when that pays). Returns (plan, records, tries): records (chip, its time over the median chip's, action) for
    every chip planned or shed now (the slowest chip with action none when neither), tries (m, S, saving, cost, net)."""
    n = len(e4)
    s = sorted(e4)
    med = (s[(n - 1) // 2] + s[n // 2]) / 2.0
    held = sorted(c for c in current if n_probe - since.get(c, n_probe) < hold)
    rest = sorted((c for c in range(n) if c not in held), key=lambda c: (-e4[c], c))
    shrink = (accum - 1) / accum
    longest = max(e4)
    tries = []
    best = None
    for m in range(0, max(0, max_chips - len(held)) + 1):
        S = set(held) | set(rest[:m])
        saving = longest - max(e4[c] * (shrink if c in S else 1.0) for c in range(n))
        cost = step_s * sum(frac + (keep if c in current else margin) for c in S)
        tries.append((m, sorted(S), saving, cost, saving - cost))
        if best is None or tries[-1][4] > best[4]:
            best = tries[-1]
    plan = frozenset(best[1])
    recs = []
    for c in sorted(set(plan) | set(current)):
        action = ("hold" if c in held else "keep" if c in current else "shed") if c in plan else "unshed"
        recs.append((c, e4[c] / med, action))
    if not recs:
        slowest = min(range(n), key=lambda c: (-e4[c], c))
        recs.append((slowest, e4[slowest] / med, "none"))
    return plan, recs, tries


class ShedS5:
    """S5 (R2_SHED): which ranks train one micro-batch fewer in a step, the probe that decides it (modes 1 and 3) and
    the run's counts. begin_step() gives this rank's micro-steps for the step; step_tokens() books the step (the
    tokens every rank trained) once it is taken; probe() times, gathers and decides; zero_dy and zero_ng are the
    persistent zero gradients the skipped micro-step leaves in the step's lists (the same shapes as the real ones, so
    the step's compiled functions and its copy to the host see the shapes of every other step)."""

    def __init__(self, mode: int, rank: int, world: int, accum: int, rows: int, seq_len: int, device, *, group=None,
                 zero_dy_shape=None, zero_ng_shape=None):
        G = R2_SHED_GROUP
        if world % G or (mode in (1, 3) and world // G < 2):
            raise ValueError(f"R2_SHED={mode}: {world} ranks do not split into at least two chips of "
                             f"R2_SHED_GROUP={G} ranks")
        if accum < 2:
            raise ValueError(f"R2_SHED needs at least two micro-steps a step (grad_accum_steps={accum})")
        if mode == 2 and any(not 0 <= c < world // G for c in R2_SHED_CHIPS):
            raise ValueError(f"R2_SHED_CHIPS={list(R2_SHED_CHIPS)}: chips are 0 to {world // G - 1}")
        self.mode, self.rank, self.world, self.accum, self.rows, self.seq_len = mode, rank, world, accum, rows, seq_len
        self.G, self.n_chips, self.chip = G, world // G, rank // G
        self.group = group
        self.frac = G / (world * accum)
        self.shed = frozenset()            # mode 1: the chips shedding until the next probe
        self.since = {}                    # mode 1: chip -> the probe index it was shed at
        self.n_probe = 0
        self.active = frozenset()          # the chips shedding in the current step
        self.k = accum
        self.micro = [0] * self.n_chips    # micro-batches trained by each chip's ranks together
        self.shed_steps = [0] * self.n_chips
        self.steps = 0
        self.cost = {"probes": 0, "sync_s": 0.0, "allreduce_s": 0.0, "decide_s": 0.0}
        self.last = None
        self.zero_dy = self.zero_ng = None
        if mode in (1, 2):
            if zero_dy_shape is not None:
                self.zero_dy = torch.zeros(zero_dy_shape, dtype=COMPUTE_DTYPE, device=device)
            if zero_ng_shape is not None:
                self.zero_ng = torch.zeros(zero_ng_shape, dtype=COMPUTE_DTYPE, device=device)

    def setup_line(self) -> str:
        return (f"S5 shed: mode={self.mode} chips={self.n_chips} ranks_per_chip={self.G} from={R2_SHED_FROM} "
                f"every={R2_SHED_EVERY} margin={R2_SHED_MARGIN:g} keep={R2_SHED_KEEP:g} hold={R2_SHED_HOLD} "
                f"max={R2_SHED_MAX} fixed_chips={list(R2_SHED_CHIPS)} micro_steps={self.accum} "
                f"token_share_per_chip={self.frac:.6f}")

    def begin_step(self, step: int) -> int:
        if self.mode == 2:
            self.active = frozenset(R2_SHED_CHIPS) if step >= R2_SHED_FROM else frozenset()
        else:
            self.active = self.shed if self.mode == 1 else frozenset()
        self.k = self.accum - 1 if self.chip in self.active else self.accum
        return self.k

    def step_tokens(self, total: int) -> int:
        for c in range(self.n_chips):
            self.micro[c] += self.G * (self.accum - 1 if c in self.active else self.accum)
            self.shed_steps[c] += int(c in self.active)
        self.steps += 1
        return total - len(self.active) * self.G * self.rows * self.seq_len

    def probe_due(self, step: int) -> bool:
        return self.mode in (1, 3) and step >= R2_SHED_FROM and (step - R2_SHED_FROM) % R2_SHED_EVERY == 0

    def gather(self, elapsed: float, step_s: float) -> list:
        """Every rank's [seconds to the end of its micro-steps, micro-steps run, median step seconds], by rank."""
        buf = torch.zeros(self.world, 3, dtype=torch.float64)
        buf[self.rank, 0] = elapsed
        buf[self.rank, 1] = float(self.k)
        buf[self.rank, 2] = step_s
        if self.world > 1:
            dist.all_reduce(buf, op=dist.ReduceOp.SUM, group=self.group)
        return buf.tolist()

    def probe(self, device, t0: float, step: int, recent: list) -> None:
        a = time.monotonic()
        synchronize(device)
        b = time.monotonic()
        tail = sorted(recent[-20:])
        rows = self.gather(b - t0, tail[len(tail) // 2] if tail else 0.0)
        c = time.monotonic()
        G, A = self.G, self.accum
        e4 = [max(rows[r][0] * A / rows[r][1] for r in range(ch * G, ch * G + G)) for ch in range(self.n_chips)]
        st = sorted(r[2] for r in rows)
        step_s = (st[(len(st) - 1) // 2] + st[len(st) // 2]) / 2.0
        if step_s <= 0.0:
            step_s = max(e4)
        plan, recs, tries = shed_plan(e4, self.shed, self.since, self.n_probe, A, step_s, self.frac, R2_SHED_MARGIN,
                                      R2_SHED_KEEP, R2_SHED_HOLD, R2_SHED_MAX)
        before = self.shed
        if self.mode == 1:
            for ch in plan - self.shed:
                self.since[ch] = self.n_probe
            for ch in self.shed - plan:
                self.since.pop(ch, None)
            self.shed = plan
        self.n_probe += 1
        d = time.monotonic()
        self.cost["probes"] += 1
        self.cost["sync_s"] += b - a
        self.cost["allreduce_s"] += c - b
        self.cost["decide_s"] += d - c
        s = sorted(e4)
        med = (s[(len(s) - 1) // 2] + s[len(s) // 2]) / 2.0
        self.last = {"step": step, "chip_ms": [round(1000.0 * x, 2) for x in e4], "step_ms": round(1000.0 * step_s, 2),
                     "plan": sorted(plan)}
        if self.rank == 0:
            tag = "" if self.mode == 1 else "would_"
            print(f"S5 probe step={step} step_ms={1000.0 * step_s:.1f} median_chip_ms={1000.0 * med:.1f} chip_ratio="
                  + ",".join(f"{ch}:{e4[ch] / med:.4f}" for ch in range(self.n_chips))
                  + f" shed_before={sorted(before)} {tag}shed_after={sorted(plan)} sync_ms={1000.0 * (b - a):.2f} "
                  f"allreduce_ms={1000.0 * (c - b):.2f} decide_ms={1000.0 * (d - c):.3f}", flush=True)
            for m, chips, saving, cost, net in tries:
                print(f"S5 plan step={step} m={m} chips={chips} saving_ms={1000.0 * saving:.1f} "
                      f"cost_ms={1000.0 * cost:.1f} net_ms={1000.0 * net:.1f}", flush=True)
            for ch, ratio, action in recs:
                print(f"S5 decision step={step} chip={ch} ratio={ratio:.4f} action={tag}{action}", flush=True)

    def record(self) -> dict:
        return {"mode": self.mode, "from": R2_SHED_FROM, "every": R2_SHED_EVERY, "margin": R2_SHED_MARGIN,
                "keep": R2_SHED_KEEP, "hold": R2_SHED_HOLD, "max": R2_SHED_MAX, "ranks_per_chip": self.G,
                "fixed_chips": list(R2_SHED_CHIPS), "steps": self.steps, "probes": self.n_probe,
                "micro_batches_by_chip": list(self.micro), "shed_steps_by_chip": list(self.shed_steps),
                "tokens_by_chip": [m * self.rows * self.seq_len for m in self.micro], "last_probe": self.last}

    def summary_line(self) -> str:
        toks = [m * self.rows * self.seq_len for m in self.micro]
        full = self.steps * self.G * self.accum * self.rows * self.seq_len
        return (f"S5 summary: mode={self.mode} steps={self.steps} probes={self.n_probe} tokens_by_chip="
                + ",".join(f"{c}:{t}" for c, t in enumerate(toks)) + " shed_steps_by_chip="
                + ",".join(f"{c}:{n}" for c, n in enumerate(self.shed_steps))
                + f" tokens_trained={sum(toks)} tokens_if_unshed={full * self.n_chips} "
                f"skipped_fraction={1.0 - sum(toks) / max(1, full * self.n_chips):.6f}")

    def cost_line(self) -> str:
        n = max(1, self.cost["probes"])
        per_step = (self.cost["allreduce_s"] + self.cost["decide_s"]) / max(1, self.steps)
        c = self.cost
        return (f"S5 cost rank {self.rank}: probes={c['probes']} sync_ms={1000.0 * c['sync_s'] / n:.2f} "
                f"allreduce_ms={1000.0 * c['allreduce_s'] / n:.2f} decide_ms={1000.0 * c['decide_s'] / n:.3f} "
                f"host_ms_per_step={1000.0 * per_step:.4f}")


class DataRuleTables:
    """Switch 25: per-vocabulary-id class tables, built once (about a second) from the shipped tokenizer's own byte
    strings: word ids (a space and letters), alphabetic, digit, '#' or ellipsis, Gopher's eight stop words, non-ASCII,
    newline, bullet-led and ellipsis-ended ids, the ids whose stripped bytes are "question" or "answer" in any case,
    colon-led ids, and each id's stripped byte length."""

    def __init__(self, tokenizer):
        import numpy as np
        enc = tokenizer.enc
        vocab = enc.n_vocab
        raw = []
        for i in range(vocab):
            try:
                raw.append(enc.decode_single_token_bytes(i))
            except KeyError:
                raw.append(b"")
        stop = {b"the", b"be", b"to", b"of", b"and", b"that", b"have", b"with"}
        ellipsis = b"\xe2\x80\xa6"          # U+2026, horizontal ellipsis, in UTF-8
        bullet = b"\xe2\x80\xa2"            # U+2022, bullet, in UTF-8

        def table(fn):
            return np.fromiter((bool(fn(b)) for b in raw), dtype=bool, count=vocab)

        self.vocab = vocab
        self.bos = tokenizer.get_bos_token_id()
        self.word = table(lambda b: b.startswith(b" ") and len(b) > 1 and b[1:].isalpha())
        self.alpha = self.word | table(lambda b: len(b) > 0 and b.isalpha())
        self.digit = table(lambda b: len(b.strip()) > 0 and b.strip().isdigit())
        self.symbol = table(lambda b: b"#" in b or b"..." in b or ellipsis in b)
        self.stop = table(lambda b: b.strip().lower() in stop)
        self.non_ascii = table(lambda b: any(c >= 128 for c in b))
        self.newline = table(lambda b: b"\n" in b)
        self.bullet = table(lambda b: b.strip()[:1] in (b"-", b"*") or b.strip().startswith(bullet))
        self.ellipsis_end = table(lambda b: b.strip().endswith(b"...") or b.strip().endswith(ellipsis))
        self.question = table(lambda b: b.strip().lower() == b"question")
        self.answer = table(lambda b: b.strip().lower() == b"answer")
        self.colon = table(lambda b: b.strip().startswith(b":"))
        self.word_bytes = np.fromiter((len(b.strip()) for b in raw), dtype=np.int64, count=vocab)


class DataRule:
    """Switch 25: R2_DATA_RULE's decisions and their counters. decide() takes one refill's token lists (each with the
    kit's BOS first; no feature reads it) and returns, per document, the keep flag and the class (1: its last quarter
    carries a question-answer pair, 0: not). `phase` is the run's elapsed fraction, set by main() before each step's
    next batch is fetched; the rule acts when phase >= R2_DATA_FROM. Counters, indexed [0 before R2_DATA_FROM, 1 from
    it][class]: documents and tokens (BOS included) read, kept and dropped as they enter the buffer, and tokens trained
    (placed in rows; of a cropped document, the part placed) as they are packed."""

    RING = 65536                            # rule 3: the band's quantiles are over the last RING scored documents
    HASH_BITS = 22                          # rule 3: buckets of the hashed bigram counts

    def __init__(self, tokenizer, rule: int, start: float = R2_DATA_FROM, keep: float = R2_DATA_KEEP,
                 band: tuple = R2_DATA_BAND, warm: int = R2_DATA_WARM):
        import numpy as np
        self.tables = DataRuleTables(tokenizer)
        self.rule, self.start, self.keep, self.band, self.warm = rule, start, keep, tuple(band), warm
        self.keep_below = int(round(keep * 65536))
        self.phase = 0.0
        self.rows = 0
        self.seconds = {"decide": 0.0, "loader": 0.0}
        self.count = {k: np.zeros((2, 2), dtype=np.int64) for k in
                      ("docs_read", "docs_kept", "docs_dropped", "tokens_read", "tokens_kept", "tokens_trained")}
        if rule == 3:
            self.bigram = np.zeros(1 << self.HASH_BITS, dtype=np.int32)
            self.context = np.zeros(self.tables.vocab, dtype=np.int64)
            self.unigram = np.zeros(self.tables.vocab, dtype=np.int64)
            self.ring = np.zeros(self.RING, dtype=np.float64)
            self.scored = 0

    def question_answer_tail(self, xs):
        """Per document (ids without the BOS): a question token and an answer token, each followed by a colon in the
        same document, both at or after token floor(3n / 4) of its n."""
        import numpy as np
        t = self.tables
        d = len(xs)
        lens = np.fromiter((len(x) for x in xs), dtype=np.int64, count=d)
        if not lens.sum():
            return np.zeros(d, dtype=bool)
        x = np.concatenate(xs)
        doc = np.repeat(np.arange(d), lens)
        pos = np.arange(len(x)) - np.repeat(np.cumsum(lens) - lens, lens)
        marker = np.zeros(len(x), dtype=bool)
        marker[:-1] = t.colon[x[1:]] & (doc[1:] == doc[:-1])
        marker &= pos >= (3 * lens[doc]) // 4
        q = np.bincount(doc[marker & t.question[x]], minlength=d)
        a = np.bincount(doc[marker & t.answer[x]], minlength=d)
        return (q > 0) & (a > 0)

    def fails_quality(self, xs):
        """Rule 1, per document: True when it fails one of the heuristic rules listed at switch 25."""
        import numpy as np
        t = self.tables
        out = np.zeros(len(xs), dtype=bool)
        for j, x in enumerate(xs):
            n = len(x)
            words = t.word[x]
            if n < 4 or int(words.sum()) < 50:
                out[j] = True
                continue
            mean_word = float(t.word_bytes[x][words].mean())
            fail = bool(mean_word < 3 or mean_word > 10 or t.symbol[x].mean() > 0.10 or t.digit[x].mean() > 0.20
                        or t.alpha[x].mean() < 0.70 or t.stop[x].mean() < 0.02 or t.non_ascii[x].mean() > 0.30)
            if not fail and n >= 16:
                w = np.ascontiguousarray(np.lib.stride_tricks.sliding_window_view(x, 8))
                distinct = len(np.unique(w.view(np.dtype((np.void, 8 * w.itemsize))).ravel()))
                fail = 1.0 - distinct / len(w) > 0.20
            if not fail:
                cut = np.flatnonzero(t.newline[x]) + 1
                cut = cut[cut < n]
                starts = np.concatenate(([0], cut))
                ends = np.concatenate((cut, [n]))
                fail = bool(t.bullet[x[starts]].mean() > 0.90 or t.ellipsis_end[x[ends - 1]].mean() > 0.30)
                lines = [x[s:e].tobytes() for s, e in zip(starts, ends) if e - s >= 3] if len(starts) >= 2 else []
                if not fail and lines:
                    fail = 1.0 - len(set(lines)) / len(lines) > 0.30
            out[j] = fail
        return out

    def surprisal(self, xs):
        """Rule 3, per document: mean surprisal (nats a token) under this rank's hashed bigram counts, add-4 smoothed
        against the add-1 unigram, each document's first token following the BOS; then the counts learn the documents
        (scored first, so a document never scores against its own counts). NaN for a document with no tokens."""
        import numpy as np
        t = self.tables
        d = len(xs)
        lens = np.fromiter((len(x) for x in xs), dtype=np.int64, count=d)
        if not lens.sum():
            return np.full(d, np.nan)
        x = np.concatenate(xs)
        prev = np.empty_like(x)
        prev[1:] = x[:-1]
        prev[(np.cumsum(lens) - lens)[lens > 0]] = t.bos
        h = ((prev.astype(np.uint64) * np.uint64(2654435761) + x.astype(np.uint64))
             * np.uint64(0x9E3779B97F4A7C15)) >> np.uint64(64 - self.HASH_BITS)
        h = h.astype(np.int64)
        unigram_p = (self.unigram + 1.0) / (self.unigram.sum() + t.vocab)
        p = (self.bigram[h] + 4.0 * unigram_p[x]) / (self.context[prev] + 4.0)
        doc = np.repeat(np.arange(d), lens)
        total = np.bincount(doc, weights=-np.log(p), minlength=d)
        with np.errstate(invalid="ignore", divide="ignore"):
            s = total / lens
        np.add.at(self.bigram, h, 1)
        np.add.at(self.context, prev, 1)
        np.add.at(self.unigram, x, 1)
        return s

    def decide(self, token_lists):
        import numpy as np
        import zlib
        t0 = time.perf_counter()
        xs = [np.asarray(ids[1:], dtype=np.int64) for ids in token_lists]
        cls = self.question_answer_tail(xs)
        acting = self.phase >= self.start
        keep = np.ones(len(xs), dtype=bool)
        if self.rule == 1 and acting:
            keep = ~self.fails_quality(xs)
        elif self.rule == 2 and acting:
            # A draw per document from its first 32 ids: the same verdict on every rank and in every batching.
            draw = np.fromiter((zlib.crc32(np.asarray(ids[1:33], dtype="<i4").tobytes()) & 0xFFFF
                                for ids in token_lists), dtype=np.int64, count=len(token_lists))
            keep = cls | (draw < self.keep_below)
        elif self.rule == 3:
            s = self.surprisal(xs)
            if acting and self.scored >= self.warm:
                lo, hi = np.quantile(self.ring[:min(self.scored, self.RING)], self.band)
                keep = (s >= lo) & (s <= hi)            # a document with no tokens (NaN) is outside
            s = s[np.isfinite(s)]
            self.ring[(self.scored + np.arange(len(s))) % self.RING] = s
            self.scored += len(s)
        b = int(acting)
        c = cls.astype(np.int64)
        n = np.fromiter((len(ids) for ids in token_lists), dtype=np.int64, count=len(token_lists))
        np.add.at(self.count["docs_read"][b], c, 1)
        np.add.at(self.count["tokens_read"][b], c, n)
        np.add.at(self.count["docs_kept"][b], c[keep], 1)
        np.add.at(self.count["tokens_kept"][b], c[keep], n[keep])
        np.add.at(self.count["docs_dropped"][b], c[~keep], 1)
        self.seconds["decide"] += time.perf_counter() - t0
        return keep.tolist(), c.tolist()

    def trained(self, cls: int, n: int) -> None:
        self.count["tokens_trained"][int(self.phase >= self.start), cls] += n

    def counters(self) -> dict:
        return {k: v.tolist() for k, v in self.count.items()} | {"rows": self.rows}

    def record(self) -> dict:
        """For the checkpoint's meta: the settings and this rank's counters ([before, from R2_DATA_FROM][other,
        question-answer])."""
        return {"rule": self.rule, "from": self.start, "keep": self.keep, "band": list(self.band), "warm": self.warm,
                "counters": self.counters()}

    def line(self, head: str, wait_seconds, steps: int) -> str:
        c = self.count
        r, k, dr, tr = c["docs_read"], c["docs_kept"], c["docs_dropped"], c["tokens_trained"]
        share = lambda a, b: f"{a / b:.4f}" if b else "nan"  # noqa: E731
        return (f"data_rule {head}: rule={self.rule} from={self.start:g} keep={self.keep:g} phase={self.phase:.4f} "
                f"rows={self.rows} docs_read={int(r.sum())} docs_kept={int(k.sum())} docs_dropped={int(dr.sum())} "
                f"pre_read={int(r[0].sum())} pre_qa_read={int(r[0, 1])} "
                f"act_read={int(r[1].sum())} act_dropped={int(dr[1].sum())} "
                f"act_dropped_share={share(int(dr[1].sum()), int(r[1].sum()))} "
                f"act_qa_read={int(r[1, 1])} act_qa_kept={int(k[1, 1])} "
                f"act_other_read={int(r[1, 0])} act_other_kept={int(k[1, 0])} "
                f"tokens_read={int(c['tokens_read'].sum())} tokens_kept={int(c['tokens_kept'].sum())} "
                f"tokens_trained={int(tr.sum())} pre_trained={int(tr[0].sum())} act_trained={int(tr[1].sum())} "
                f"pre_trained_qa_share={share(int(tr[0, 1]), int(tr[0].sum()))} "
                f"act_trained_qa_share={share(int(tr[1, 1]), int(tr[1].sum()))} "
                f"loader_ms={1000 * self.seconds['loader'] / max(1, self.rows):.2f} "
                f"decide_ms={1000 * self.seconds['decide'] / max(1, self.rows):.2f}"
                + (f" main_wait_ms={1000 * wait_seconds / max(1, steps):.2f}" if wait_seconds is not None else ""))


